    'proposed',
    'active',
    'completed',
    'cancelled'
);



CREATE TYPE public.interest_status AS ENUM (
    'pending',
    'accepted',
    'declined',
    'withdrawn'
);



CREATE TYPE public.match_suggestion_status AS ENUM (
    'suggested',
    'dismissed',
    'introduced',
    'archived'
);



CREATE TYPE public.mpgf_progress_visibility AS ENUM (
    'exact_amount',
    'progress_range',
    'threshold_status_only',
    'sealed_progress'
);



CREATE TYPE public.mpgf_threshold_visibility AS ENUM (
    'public_exact'
);



CREATE TYPE public.offer_mode AS ENUM (
    'pledge',
