);



CREATE TYPE public.wish_entry_type AS ENUM (
    'wish',
    'offer',
    'ask'
);



CREATE FUNCTION moral_trade_private.activate_confirmed_trade_milestones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  agreement_row public.agreements%rowtype;
  participant_confirmation_count integer;
begin
  select agreement.*
  into agreement_row
  from public.trade_agreement_versions version
  join public.agreements agreement on agreement.id = version.agreement_id
  where version.id = new.agreement_version_id
  for update of agreement;

  if not found or agreement_row.current_version_id <> new.agreement_version_id then
    return new;
  end if;

  select count(distinct confirmation.user_id)
  into participant_confirmation_count
  from public.trade_agreement_confirmations confirmation
  where confirmation.agreement_version_id = new.agreement_version_id
    and confirmation.user_id in (agreement_row.proposer_id, agreement_row.responder_id);

  if participant_confirmation_count = 2 then
    update public.trade_agreement_milestones milestone
    set status = 'evidence_due',
        updated_at = now()
    where milestone.agreement_version_id = new.agreement_version_id
      and milestone.agreement_id = agreement_row.id
      and milestone.status = 'terms';
  end if;

  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.bind_trade_confirmation_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or new.user_id is distinct from auth.uid() then
    raise exception 'A confirmation must belong to the authenticated participant.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_milestone_v1(p_milestone_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      p_actor_id in (agreement.proposer_id, agreement.responder_id)
      or milestone.assigned_reviewer_id = p_actor_id
      or exists (
        select 1
        from public.trade_milestone_appeals appeal
        where appeal.milestone_id = milestone.id
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or exists (
        select 1
        from public.trade_milestone_payouts payout
        join public.trade_payment_review_cases review_case
          on review_case.payout_id = payout.id
        where payout.milestone_id = milestone.id
          and review_case.assigned_reviewer_id = p_actor_id
      )
      or exists (
        select 1
        from public.trade_milestone_payouts payout
        join public.trade_payment_review_cases review_case
          on review_case.payout_id = payout.id
        join public.trade_payment_appeals appeal
          on appeal.case_id = review_case.id
        where payout.milestone_id = milestone.id
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or moral_trade_private.current_actor_has_trade_role('administrator')
    )
  from public.trade_agreement_milestones milestone
  join public.agreements agreement on agreement.id = milestone.agreement_id
  where milestone.id = p_milestone_id;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_payment_appeal_v1(p_appeal_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      appeal.assigned_reviewer_id = p_actor_id
      or moral_trade_private.is_trade_payment_case_participant_v1(
        appeal.case_id,
        p_actor_id
      )
    )
  from public.trade_payment_appeals appeal
  where appeal.id = p_appeal_id;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_payment_case_v1(p_case_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      p_actor_id in (payout.payer_id, payout.payee_id)
      or review_case.assigned_reviewer_id = p_actor_id
      or exists (
        select 1
        from public.trade_payment_appeals appeal
        where appeal.case_id = review_case.id
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or moral_trade_private.current_actor_has_trade_role('administrator')
    )
  from public.trade_payment_review_cases review_case
  join public.trade_milestone_payouts payout
    on payout.id = review_case.payout_id
  where review_case.id = p_case_id;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_payment_decision_v1(p_decision_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      decision.reviewer_id = p_actor_id
      or moral_trade_private.can_read_trade_payment_case_v1(
        decision.case_id,
        p_actor_id
      )
    )
  from public.trade_payment_review_decisions decision
  where decision.id = p_decision_id;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_payout_v1(p_payout_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      p_actor_id in (payout.payer_id, payout.payee_id)
      or milestone.assigned_reviewer_id = p_actor_id
      or exists (
        select 1
        from public.trade_milestone_appeals appeal
        where appeal.milestone_id = milestone.id
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or exists (
        select 1
        from public.trade_payment_review_cases review_case
        where review_case.payout_id = payout.id
          and review_case.assigned_reviewer_id = p_actor_id
      )
      or exists (
        select 1
        from public.trade_payment_review_cases review_case
        join public.trade_payment_appeals appeal
          on appeal.case_id = review_case.id
        where review_case.payout_id = payout.id
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or moral_trade_private.current_actor_has_trade_role('administrator')
    )
  from public.trade_milestone_payouts payout
  join public.trade_agreement_milestones milestone
    on milestone.id = payout.milestone_id
  where payout.id = p_payout_id;
$$;



CREATE FUNCTION moral_trade_private.can_read_trade_receipt_v1(p_receipt_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      p_actor_id in (payout.payer_id, payout.payee_id)
      or exists (
        select 1
        from public.trade_payment_review_cases review_case
        where review_case.payout_id = receipt.payout_id
          and review_case.payment_cycle = receipt.payment_cycle
          and review_case.assigned_reviewer_id = p_actor_id
      )
      or exists (
        select 1
        from public.trade_payment_review_cases review_case
        join public.trade_payment_appeals appeal
          on appeal.case_id = review_case.id
        where review_case.payout_id = receipt.payout_id
          and review_case.payment_cycle = receipt.payment_cycle
          and appeal.assigned_reviewer_id = p_actor_id
      )
      or moral_trade_private.current_actor_has_trade_role('administrator')
    )
  from public.trade_external_payment_receipts receipt
  join public.trade_milestone_payouts payout
    on payout.id = receipt.payout_id
  where receipt.id = p_receipt_id;
$$;



CREATE FUNCTION moral_trade_private.current_actor_has_trade_role(p_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    auth.uid() is not null
    and coalesce(auth.jwt() ->> 'aal', '') = 'aal2'
    and exists (
      select 1
      from public.trade_review_role_grants grant_row
      where grant_row.profile_id = auth.uid()
        and grant_row.role = p_role
        and grant_row.active
        and grant_row.revoked_at is null
    );
$$;



CREATE FUNCTION moral_trade_private.ensure_trade_payment_review_case(p_payout_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payout_row public.trade_milestone_payouts%rowtype;
  receipt_row public.trade_external_payment_receipts%rowtype;
  existing_case public.trade_payment_review_cases%rowtype;
  opened_at_value timestamptz;
  case_id_value uuid;
begin
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = p_payout_id
  for update;

  select *
  into existing_case
  from public.trade_payment_review_cases review_case
  where review_case.payout_id = p_payout_id
    and review_case.status <> 'resolved'
  order by review_case.payment_cycle desc
  limit 1
  for update;
  if found then
    return existing_case.id;
  end if;

  select *
  into receipt_row
  from public.trade_external_payment_receipts receipt
  where receipt.payout_id = p_payout_id
    and receipt.attempt_number = 1
    and not exists (
      select 1
      from public.trade_payment_review_cases prior_case
      where prior_case.initial_receipt_id = receipt.id
    )
  order by receipt.payment_cycle desc
  limit 1
  for update;

  if payout_row.id is null
     or receipt_row.id is null
     or not (
       receipt_row.response_outcome = 'disputed'
       or (
         receipt_row.status = 'reported'
         and receipt_row.response_outcome = 'none'
         and receipt_row.response_deadline_at <= now()
       )
     ) then
    raise exception 'Neutral payment review is unavailable before a dispute or unanswered deadline.';
  end if;

  if receipt_row.response_outcome = 'none' then
    update public.trade_external_payment_receipts
    set status = 'under_review',
        response_outcome = 'unanswered',
        responded_at = coalesce(responded_at, response_deadline_at),
        updated_at = now()
    where id = receipt_row.id;
    opened_at_value := receipt_row.response_deadline_at;
  else
    update public.trade_external_payment_receipts
    set status = 'under_review',
        updated_at = now()
    where id = receipt_row.id;
    opened_at_value := coalesce(receipt_row.responded_at, now());
  end if;

  insert into public.trade_payment_review_cases (
    payout_id,
    payment_cycle,
    initial_receipt_id,
    reviewer_selection_opened_at,
    reviewer_selection_deadline_at
  ) values (
    payout_row.id,
    receipt_row.payment_cycle,
    receipt_row.id,
    opened_at_value,
    opened_at_value + interval '7 days'
  )
  returning id into case_id_value;

  update public.trade_milestone_payouts
  set status = 'payment_review_pending',
      updated_at = now()
  where id = payout_row.id;

  return case_id_value;
end;
$$;



CREATE FUNCTION moral_trade_private.guard_counterproposal_milestone_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.milestone_terms is distinct from old.milestone_terms then
    raise exception 'Counterproposal milestone terms are immutable; create a new proposal round.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.guard_frozen_trade_milestone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  version_id uuid := coalesce(new.agreement_version_id, old.agreement_version_id);
  version_hash text;
begin
  select v.milestone_manifest_hash
  into version_hash
  from public.trade_agreement_versions v
  where v.id = version_id
  for update;

  if (
    version_hash is not null
    or exists (
       select 1
       from public.trade_agreement_confirmations c
       where c.agreement_version_id = version_id
    )
  ) and (
    tg_op <> 'UPDATE'
    or new.agreement_id is distinct from old.agreement_id
    or new.agreement_version_id is distinct from old.agreement_version_id
    or new.position is distinct from old.position
    or new.performer_id is distinct from old.performer_id
    or new.payer_id is distinct from old.payer_id
    or new.action_category is distinct from old.action_category
    or new.description is distinct from old.description
    or new.unit_label is distinct from old.unit_label
    or new.units_total is distinct from old.units_total
    or new.indivisible is distinct from old.indivisible
    or new.maximum_amount_cents is distinct from old.maximum_amount_cents
    or new.currency is distinct from old.currency
    or new.evidence_rule is distinct from old.evidence_rule
  ) then
    raise exception 'Milestone terms are frozen. Create a new agreement version to amend them.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.guard_submitted_evidence_bundle_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bundle_status text;
begin
  select b.status
  into bundle_status
  from public.trade_evidence_bundles b
  where b.id = coalesce(new.bundle_id, old.bundle_id)
  for update;

  if bundle_status is distinct from 'draft' then
    raise exception 'Submitted evidence packets are immutable.';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.invitation_status_is_usable(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select p_status in ('drafted', 'sent', 'opened');
$$;



CREATE FUNCTION moral_trade_private.is_trade_agreement_milestone_complete(p_agreement_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    agreement.current_version_id is not null
    and agreement.lifecycle_status not in ('draft', 'proposed', 'cancelled', 'expired')
    and exists (
      select 1
      from public.trade_agreement_milestones milestone
      where milestone.agreement_id = agreement.id
        and milestone.agreement_version_id = agreement.current_version_id
        and milestone.status <> 'cancelled'
    )
    and not exists (
      select 1
      from public.trade_agreement_milestones milestone
      where milestone.agreement_id = agreement.id
        and milestone.agreement_version_id = agreement.current_version_id
        and milestone.status <> 'cancelled'
        and (
          milestone.final_review_id is null
          or milestone.status not in ('graded', 'paid')
          or not exists (
            select 1
            from public.trade_milestone_payouts payout
            where payout.milestone_id = milestone.id
              and payout.is_final
              and payout.status in (
                'not_due', 'confirmed', 'adjudicated_paid'
              )
          )
        )
    )
  from public.agreements agreement
  where agreement.id = p_agreement_id;
$$;



CREATE FUNCTION moral_trade_private.is_trade_payment_case_participant_v1(p_case_id uuid, p_actor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_actor_id is not null
    and p_actor_id = auth.uid()
    and (
      p_actor_id in (payout.payer_id, payout.payee_id)
      or moral_trade_private.current_actor_has_trade_role('administrator')
    )
  from public.trade_payment_review_cases review_case
  join public.trade_milestone_payouts payout
    on payout.id = review_case.payout_id
  where review_case.id = p_case_id;
$$;



CREATE FUNCTION moral_trade_private.lock_invitation_delivery(p_invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'trade_invitation:' || p_invitation_id::text,
      90211
    )
  );
end;
$$;



CREATE FUNCTION moral_trade_private.lock_pair(p_a uuid, p_b uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      least(p_a::text, p_b::text) || ':' || greatest(p_a::text, p_b::text),
      90210
    )
  );
end;
$$;



CREATE FUNCTION moral_trade_private.offer_is_invitable(p_offer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.offers o
    where o.id = p_offer_id
      and o.workflow_status = 'published'
      and o.status::text = 'open'
      and o.mode::text = 'pledge'
      and o.payment_interval_value is null
      and o.payment_interval_unit is null
      and not exists (
        select 1
        from public.donation_offset_offers d
        where d.offer_id = o.id
      )
      and not exists (
        select 1
        from public.performance_bonds b
        where b.offer_id = o.id
          and b.enabled is true
          and b.status not in ('not_enabled', 'cancelled', 'expired', 'refunded')
      )
  );
$$;



CREATE FUNCTION moral_trade_private.pair_is_blocked(p_a uuid, p_b uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.trade_blocks b
    where (b.blocker_id = p_a and b.blocked_id = p_b)
       or (b.blocker_id = p_b and b.blocked_id = p_a)
  );
$$;





CREATE TABLE public.trade_donation_pool_obligations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    donation_term_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    agreement_version_id uuid NOT NULL,
    payer_user_id uuid NOT NULL,
    environment text NOT NULL,
    provider text DEFAULT 'every_org'::text NOT NULL,
    target_id text NOT NULL,
    target_name text NOT NULL,
    nonprofit_slug text NOT NULL,
    nonprofit_ein text DEFAULT ''::text NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    frequency text DEFAULT 'ONCE'::text NOT NULL,
    condition_hash text NOT NULL,
    status text DEFAULT 'awaiting_funding'::text NOT NULL,
    stripe_livemode boolean NOT NULL,
    stripe_checkout_session_id text,
    stripe_payment_intent_id text,
    stripe_charge_id_hash text DEFAULT ''::text NOT NULL,
    stripe_payload_hash text DEFAULT ''::text NOT NULL,
    bundle_id uuid,
    disclosure_version text NOT NULL,
    disclosures_accepted_at timestamp with time zone NOT NULL,
    checkout_started_at timestamp with time zone,
    funded_at timestamp with time zone,
    refund_requested_at timestamp with time zone,
    refunded_at timestamp with time zone,
    settled_at timestamp with time zone,
    failure_code text DEFAULT ''::text NOT NULL,
    failure_message text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT trade_donation_pool_obligations_amount_cents_check CHECK (((amount_cents >= 100) AND (amount_cents <= 999))),
    CONSTRAINT trade_donation_pool_obligations_condition_hash_check CHECK ((condition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT trade_donation_pool_obligations_currency_check CHECK ((currency = 'USD'::text)),
    CONSTRAINT trade_donation_pool_obligations_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'live'::text]))),
    CONSTRAINT trade_donation_pool_obligations_frequency_check CHECK ((frequency = 'ONCE'::text)),
    CONSTRAINT trade_donation_pool_obligations_provider_check CHECK ((provider = 'every_org'::text)),
    CONSTRAINT trade_donation_pool_obligations_status_check CHECK ((status = ANY (ARRAY['awaiting_funding'::text, 'checkout_started'::text, 'checkout_abandoned'::text, 'payment_failed'::text, 'funded'::text, 'bundled'::text, 'settled'::text, 'refund_pending'::text, 'refunded'::text, 'needs_review'::text, 'disputed'::text, 'cancelled'::text])))
);



CREATE FUNCTION moral_trade_private.post_trade_donation_pool_funding_journal(p_obligation public.trade_donation_pool_obligations, p_event_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  journal_id_value uuid;
begin
  insert into public.trade_donation_pool_ledger_journals(
    event_key,
    journal_type,
    obligation_id,
    currency,
    status,
    description
  ) values (
    p_event_key,
    'participant_funding',
    p_obligation.id,
    p_obligation.currency,
    'draft',
    'Participant funding reserved for a pooled charitable settlement.'
  )
  on conflict (event_key) do nothing
  returning id into journal_id_value;

  if journal_id_value is null then
    select id into journal_id_value
    from public.trade_donation_pool_ledger_journals
    where event_key = p_event_key;
    return journal_id_value;
  end if;

  insert into public.trade_donation_pool_ledger_lines(
    journal_id, account_code, entry_side, amount_cents, currency,
    profile_id, obligation_id
  ) values
    (
      journal_id_value, 'platform_cash_asset', 'debit', p_obligation.amount_cents,
      p_obligation.currency, p_obligation.payer_user_id, p_obligation.id
    ),
    (
      journal_id_value, 'participant_settlement_liability', 'credit', p_obligation.amount_cents,
      p_obligation.currency, p_obligation.payer_user_id, p_obligation.id
    );

  update public.trade_donation_pool_ledger_journals
  set status = 'posted', posted_at = timezone('utc', now())
  where id = journal_id_value;

  return journal_id_value;
end;
$$;



CREATE FUNCTION moral_trade_private.post_trade_donation_pool_refund_journal(p_obligation public.trade_donation_pool_obligations, p_event_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  journal_id_value uuid;
begin
  insert into public.trade_donation_pool_ledger_journals(
    event_key, journal_type, obligation_id, currency, status, description
  ) values (
    p_event_key,
    'participant_refund',
    p_obligation.id,
    p_obligation.currency,
    'draft',
    'Participant contribution refunded before pooled settlement.'
  )
  on conflict (event_key) do nothing
  returning id into journal_id_value;

  if journal_id_value is null then
    select id into journal_id_value
    from public.trade_donation_pool_ledger_journals
    where event_key = p_event_key;
    return journal_id_value;
  end if;

  insert into public.trade_donation_pool_ledger_lines(
    journal_id, account_code, entry_side, amount_cents, currency,
    profile_id, obligation_id
  ) values
    (
      journal_id_value, 'participant_settlement_liability', 'debit', p_obligation.amount_cents,
      p_obligation.currency, p_obligation.payer_user_id, p_obligation.id
    ),
    (
      journal_id_value, 'platform_cash_asset', 'credit', p_obligation.amount_cents,
      p_obligation.currency, p_obligation.payer_user_id, p_obligation.id
    );

  update public.trade_donation_pool_ledger_journals
  set status = 'posted', posted_at = timezone('utc', now())
  where id = journal_id_value;

  return journal_id_value;
end;
$$;



CREATE FUNCTION moral_trade_private.recompute_trade_agreement_completion(p_agreement_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  agreement_row public.agreements%rowtype;
begin
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = p_agreement_id
  for update;

  if not found
     or agreement_row.lifecycle_status in ('draft', 'proposed', 'cancelled', 'expired')
     or not moral_trade_private.is_trade_agreement_milestone_complete(
       agreement_row.id
     ) then
    return false;
  end if;

  update public.agreements
  set lifecycle_status = 'completed',
      status = 'completed',
      completion_state = 'reviewed_complete',
      completed_at = coalesce(completed_at, now()),
      future_obligations_paused_at = null,
      future_obligations_pause_reason = '',
      updated_at = now()
  where id = agreement_row.id
    and lifecycle_status <> 'completed';

  return true;
end;
$$;



CREATE FUNCTION moral_trade_private.recompute_trade_completion_from_milestone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.recompute_trade_agreement_completion(
    new.agreement_id
  );
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.recompute_trade_completion_from_payout() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  agreement_id_value uuid;
begin
  select milestone.agreement_id
  into agreement_id_value
  from public.trade_agreement_milestones milestone
  where milestone.id = new.milestone_id;

  if agreement_id_value is not null then
    perform moral_trade_private.recompute_trade_agreement_completion(
      agreement_id_value
    );
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.require_bound_trade_actor(p_actor_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or p_actor_id is distinct from auth.uid() then
    raise exception 'The actor must match the authenticated profile.';
  end if;
end;
$$;



CREATE FUNCTION moral_trade_private.require_final_trade_milestone_manifest() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  version_row public.trade_agreement_versions%rowtype;
  actual_hash text;
  actual_complete_hash text;
begin
  select *
  into version_row
  from public.trade_agreement_versions v
  where v.id = new.agreement_version_id
  for update;

  if version_row.requires_milestone_manifest then
    actual_hash := public.trade_milestone_manifest_hash_v1(new.agreement_version_id);
    actual_complete_hash := encode(
      extensions.digest(
        convert_to(version_row.terms_hash || chr(31) || actual_hash, 'UTF8'),
        'sha256'
      ),
      'hex'
    );
    if version_row.milestone_manifest_hash is null
       or version_row.milestone_manifest_hash <> actual_hash
       or version_row.complete_terms_hash is null
       or version_row.complete_terms_hash <> actual_complete_hash then
      raise exception 'Finalize and review the milestone manifest before confirming this agreement version.';
    end if;
  end if;
  return new;
end;
$$;



CREATE FUNCTION moral_trade_private.revoke_offer_invitations(p_offer_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  invitation_id_value uuid;
  invitation_row public.trade_invitations%rowtype;
begin
  for invitation_id_value in
    select i.id
    from public.trade_invitations i
    where i.offer_id = p_offer_id
      and moral_trade_private.invitation_status_is_usable(i.status)
    order by i.id
  loop
    perform moral_trade_private.lock_invitation_delivery(invitation_id_value);

    select * into invitation_row
    from public.trade_invitations i
    where i.id = invitation_id_value
    for update;

    if not found
       or not moral_trade_private.invitation_status_is_usable(invitation_row.status) then
      continue;
    end if;
    if exists (
      select 1
      from public.email_outbox e
      where e.source_kind = 'trade_invitation'
        and e.source_id = invitation_id_value::text
        and e.status = 'processing'
        and e.locked_at >= now() - interval '10 minutes'
    ) then
      raise exception 'An invitation email is currently being delivered. Retry this change shortly.';
    end if;

    update public.trade_invitations
    set
      status = 'revoked',
      revoked_at = now(),
      revocation_reason = left(coalesce(p_reason, 'Offer is no longer eligible.'), 500),
      updated_at = now()
    where id = invitation_id_value;

    perform moral_trade_private.suppress_invitation_email(
      invitation_id_value,
      left(coalesce(p_reason, 'Offer is no longer eligible.'), 500)
    );
  end loop;
end;
$$;



CREATE FUNCTION moral_trade_private.suppress_invitation_email(p_invitation_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  update public.email_outbox
  set
    status = 'suppressed',
    body = '[private invitation link removed]',
    last_error = left(coalesce(p_reason, 'Invitation is no longer deliverable.'), 500),
    suppressed_at = now(),
    locked_at = null,
    lock_token = null
  where source_kind = 'trade_invitation'
    and source_id = p_invitation_id::text
    and (
      status in ('queued', 'retry')
      or (status = 'processing' and locked_at < now() - interval '10 minutes')
    );
end;
$$;



CREATE FUNCTION moral_trade_private.trade_donation_pool_bundle_key(p_environment text, p_nonprofit_slug text, p_nonprofit_ein text, p_currency text, p_frequency text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select lower(trim(p_environment)) || '|' || lower(trim(p_nonprofit_slug)) || '|' ||
    regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g') || '|' ||
    upper(trim(p_currency)) || '|' || upper(trim(p_frequency));
$$;



CREATE FUNCTION moral_trade_private.try_freeze_trade_donation_pool_bundle(p_environment text, p_nonprofit_slug text, p_nonprofit_ein text, p_currency text, p_frequency text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  bundle_key_value text;
  bundle_id_value uuid := gen_random_uuid();
  total_cents integer := 0;
  manifest_items jsonb;
  manifest_value jsonb;
  manifest_hash_value text;
begin
  bundle_key_value := moral_trade_private.trade_donation_pool_bundle_key(
    p_environment,
    p_nonprofit_slug,
    p_nonprofit_ein,
    p_currency,
    p_frequency
  );
  perform pg_advisory_xact_lock(hashtextextended(bundle_key_value, 0));

  with eligible as (
    select
      o.*,
      row_number() over (order by o.funded_at, o.id) as position,
      sum(o.amount_cents) over (order by o.funded_at, o.id rows unbounded preceding) as cumulative_cents
    from public.trade_donation_pool_obligations o
    join public.agreements a on a.id = o.agreement_id
    join public.trade_donation_terms t on t.id = o.donation_term_id
    where o.status = 'funded'
      and o.bundle_id is null
      and o.environment = p_environment
      and lower(o.nonprofit_slug) = lower(p_nonprofit_slug)
      and regexp_replace(o.nonprofit_ein, '[^0-9]', '', 'g') = regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g')
      and o.currency = upper(p_currency)
      and o.frequency = upper(p_frequency)
      and a.lifecycle_status = 'awaiting_donation'
      and a.current_version_id = o.agreement_version_id
      and t.agreement_version_id = o.agreement_version_id
      and t.amount_cents = o.amount_cents
      and t.nonprofit_slug = o.nonprofit_slug
      and t.currency = o.currency
      and t.frequency = o.frequency
  ), selected as (
    select *
    from eligible
    where cumulative_cents - amount_cents < 1000
  )
  select
    coalesce(sum(amount_cents), 0)::integer,
    jsonb_agg(
      jsonb_build_object(
        'position', position,
        'obligationId', id,
        'agreementId', agreement_id,
        'agreementVersionId', agreement_version_id,
        'donationTermId', donation_term_id,
        'payerUserId', payer_user_id,
        'allocationCents', amount_cents,
        'conditionHash', condition_hash
      ) order by position
    )
  into total_cents, manifest_items
  from selected;

  if total_cents < 1000 or manifest_items is null then
    return null;
  end if;

  manifest_value := jsonb_build_object(
    'schemaVersion', 'moral-trade-pooled-settlement-manifest-v1',
    'bundleId', bundle_id_value,
    'environment', p_environment,
    'provider', 'every_org',
    'recipientSlug', lower(p_nonprofit_slug),
    'recipientEin', regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    'currency', upper(p_currency),
    'frequency', upper(p_frequency),
    'aggregateAmountCents', total_cents,
    'items', manifest_items
  );
  manifest_hash_value := encode(extensions.digest(convert_to(manifest_value::text, 'UTF8'), 'sha256'), 'hex');

  insert into public.trade_donation_pool_bundles(
    id,
    environment,
    provider,
    target_id,
    target_name,
    nonprofit_slug,
    nonprofit_ein,
    amount_cents,
    currency,
    frequency,
    manifest,
    manifest_hash,
    status
  )
  select
    bundle_id_value,
    p_environment,
    'every_org',
    min(o.target_id),
    min(o.target_name),
    lower(p_nonprofit_slug),
    regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    total_cents,
    upper(p_currency),
    upper(p_frequency),
    manifest_value,
    manifest_hash_value,
    'frozen'
  from public.trade_donation_pool_obligations o
  where o.id in (
    select (item->>'obligationId')::uuid
    from jsonb_array_elements(manifest_items) item
  );

  insert into public.trade_donation_pool_bundle_items(
    bundle_id,
    obligation_id,
    agreement_id,
    agreement_version_id,
    donation_term_id,
    payer_user_id,
    allocation_cents,
    position
  )
  select
    bundle_id_value,
    (item->>'obligationId')::uuid,
    (item->>'agreementId')::uuid,
    (item->>'agreementVersionId')::uuid,
    (item->>'donationTermId')::uuid,
    (item->>'payerUserId')::uuid,
    (item->>'allocationCents')::integer,
    (item->>'position')::integer
  from jsonb_array_elements(manifest_items) item;

  update public.trade_donation_pool_obligations
  set status = 'bundled', bundle_id = bundle_id_value, failure_code = '', failure_message = ''
  where id in (
    select obligation_id
    from public.trade_donation_pool_bundle_items
    where bundle_id = bundle_id_value
  )
    and status = 'funded'
    and bundle_id is null;

  if (
    select count(*)
    from public.trade_donation_pool_bundle_items i
    join public.trade_donation_pool_obligations o on o.id = i.obligation_id
    where i.bundle_id = bundle_id_value and o.bundle_id = bundle_id_value and o.status = 'bundled'
  ) <> jsonb_array_length(manifest_items) then
    raise exception 'The pooled-settlement bundle could not lock every component atomically.';
  end if;

  insert into public.trade_donation_pool_audit_events(
    actor_kind, event_type, object_type, object_id, details
  ) values (
    'system',
    'bundle_frozen',
    'bundle',
    bundle_id_value,
    jsonb_build_object('manifestHash', manifest_hash_value, 'amountCents', total_cents)
  );

  return bundle_id_value;
end;
$$;



CREATE FUNCTION public.accept_marketplace_guest_interest_v1(p_guest_interest_id uuid, p_offer_id uuid, p_notes text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  offer_row public.offers%rowtype;
  guest_interest_row public.guest_interests%rowtype;
  existing_agreement public.agreements%rowtype;
  agreement_row public.agreements%rowtype;
  agreement_id_value uuid;
  normalized_notes text := btrim(coalesce(p_notes, ''));
begin
  if actor_id is null then
    raise exception using errcode = '42501', message = 'A signed-in offer owner is required.';
  end if;
  if p_guest_interest_id is null or p_offer_id is null then
    raise exception using errcode = '22023', message = 'Guest response ID and offer ID are required.';
  end if;

  select * into offer_row
  from public.offers
  where id = p_offer_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Offer not found.';
  end if;
  if offer_row.owner_id <> actor_id then
    raise exception using errcode = '42501', message = 'Only the offer owner can accept responses.';
  end if;

  select * into guest_interest_row
  from public.guest_interests
  where id = p_guest_interest_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Guest response not found.';
  end if;
  if guest_interest_row.offer_id <> offer_row.id then
    raise exception using errcode = '23514', message = 'That guest response is not attached to this offer.';
  end if;
  if guest_interest_row.claimed_by_profile_id is null then
    raise exception using errcode = '23514', message = 'The guest respondent must claim the response with an account first.';
  end if;
  if guest_interest_row.claimed_by_profile_id = actor_id then
    raise exception using errcode = '23514', message = 'An offer owner cannot accept their own response.';
  end if;

  select * into existing_agreement
  from public.agreements
  where offer_id = offer_row.id
    and proposer_id = actor_id
    and responder_id = guest_interest_row.claimed_by_profile_id
  order by created_at asc
  limit 1;
  if existing_agreement.id is not null then
    return jsonb_build_object('agreement', to_jsonb(existing_agreement), 'created', false);
  end if;

  if offer_row.status::text <> 'open' or offer_row.workflow_status <> 'published' then
    raise exception using errcode = '23514', message = 'This offer is not open for acceptance.';
  end if;
  if guest_interest_row.status::text <> 'pending' then
    raise exception using errcode = '23514', message = 'Only a pending guest response can be accepted.';
  end if;
  if offer_row.mode::text = 'offset' and exists (
    select 1 from public.donation_offset_offers offset_offer
    where offset_offer.offer_id = offer_row.id
      and offset_offer.participation_mode = 'pool'
  ) then
    raise exception using errcode = '23514', message = 'Pool commitments cannot be accepted one-to-one.';
  end if;
  if offer_row.mode::text = 'pledge' and exists (
    select 1 from public.performance_bonds bond
    where bond.offer_id = offer_row.id
      and bond.side = 'offerer'
      and bond.enabled is true
      and bond.status not in ('not_enabled', 'cancelled', 'expired', 'refunded')
  ) then
    raise exception using errcode = '23514', message = 'Bonded pledge swaps require a signed-in member response.';
  end if;

  update public.guest_interests
  set status = 'accepted', updated_at = now()
  where id = guest_interest_row.id;

  perform set_config('app.core_trade_linking_agreement', '1', true);
  perform set_config('app.core_trade_internal', '1', true);

  insert into public.agreements(
    offer_id,
    interest_id,
    proposer_id,
    responder_id,
    status,
    lifecycle_status,
    notes,
    evidence_due_at,
    created_at,
    updated_at
  ) values (
    offer_row.id,
    null,
    actor_id,
    guest_interest_row.claimed_by_profile_id,
    'proposed',
    'proposed',
    normalized_notes,
    offer_row.evidence_due_date,
    now(),
    now()
  ) returning id into agreement_id_value;

  perform set_config('app.core_trade_linking_agreement', '', true);
  perform set_config('app.core_trade_internal', '', true);

  update public.guest_interests
  set status = 'declined', updated_at = now()
  where offer_id = offer_row.id
    and id <> guest_interest_row.id
    and status::text = 'pending';

  update public.interests
  set status = 'declined', updated_at = now()
  where offer_id = offer_row.id
    and status::text = 'pending';

  update public.offers
  set status = 'matched', workflow_status = 'closed', closed_at = now(), updated_at = now()
  where id = offer_row.id;

  select * into agreement_row
  from public.agreements
  where id = agreement_id_value;
  if agreement_row.id is null or agreement_row.current_version_id is null then
    raise exception 'The agreement could not be linked to one frozen version.';
  end if;

  return jsonb_build_object('agreement', to_jsonb(agreement_row), 'created', true);
end;
$$;



CREATE FUNCTION public.accept_marketplace_interest_v1(p_interest_id uuid, p_offer_id uuid, p_notes text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  offer_row public.offers%rowtype;
  interest_row public.interests%rowtype;
  existing_agreement public.agreements%rowtype;
  agreement_row public.agreements%rowtype;
  agreement_id_value uuid;
  normalized_notes text := btrim(coalesce(p_notes, ''));
begin
  if actor_id is null then
    raise exception using errcode = '42501', message = 'A signed-in offer owner is required.';
  end if;
  if p_interest_id is null or p_offer_id is null then
    raise exception using errcode = '22023', message = 'Interest ID and offer ID are required.';
  end if;

  select * into offer_row
  from public.offers
  where id = p_offer_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Offer not found.';
  end if;
  if offer_row.owner_id <> actor_id then
    raise exception using errcode = '42501', message = 'Only the offer owner can accept interest.';
  end if;

  select * into interest_row
  from public.interests
  where id = p_interest_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Interest not found.';
  end if;
  if interest_row.offer_id <> offer_row.id then
    raise exception using errcode = '23514', message = 'That interest is not attached to this offer.';
  end if;
  if interest_row.user_id = actor_id then
    raise exception using errcode = '23514', message = 'An offer owner cannot accept their own response.';
  end if;

  select * into existing_agreement
  from public.agreements
  where interest_id = interest_row.id
  limit 1;
  if existing_agreement.id is not null then
    if existing_agreement.offer_id is distinct from offer_row.id
       or existing_agreement.proposer_id is distinct from actor_id
       or existing_agreement.responder_id is distinct from interest_row.user_id then
      raise exception using errcode = '23514', message = 'The existing agreement does not match this response.';
    end if;
    return jsonb_build_object('agreement', to_jsonb(existing_agreement), 'created', false);
  end if;

  if offer_row.status::text <> 'open' or offer_row.workflow_status <> 'published' then
    raise exception using errcode = '23514', message = 'This offer is not open for acceptance.';
  end if;
  if interest_row.status::text <> 'pending' then
    raise exception using errcode = '23514', message = 'Only a pending response can be accepted.';
  end if;
  if offer_row.mode::text = 'offset' and exists (
    select 1 from public.donation_offset_offers offset_offer
    where offset_offer.offer_id = offer_row.id
      and offset_offer.participation_mode = 'pool'
  ) then
    raise exception using errcode = '23514', message = 'Pool commitments cannot be accepted one-to-one.';
  end if;

  update public.interests
  set status = 'accepted', updated_at = now()
  where id = interest_row.id;

  perform set_config('app.core_trade_linking_agreement', '1', true);
  perform set_config('app.core_trade_internal', '1', true);

  insert into public.agreements(
    offer_id,
    interest_id,
    proposer_id,
    responder_id,
    status,
    lifecycle_status,
    notes,
    evidence_due_at,
    created_at,
    updated_at
  ) values (
    offer_row.id,
    interest_row.id,
    actor_id,
    interest_row.user_id,
    'proposed',
    'proposed',
    normalized_notes,
    offer_row.evidence_due_date,
    now(),
    now()
  ) returning id into agreement_id_value;

  perform set_config('app.core_trade_linking_agreement', '', true);
  perform set_config('app.core_trade_internal', '', true);

  update public.interests
  set status = 'declined', updated_at = now()
  where offer_id = offer_row.id
    and id <> interest_row.id
    and status::text = 'pending';

  update public.guest_interests
  set status = 'declined', updated_at = now()
  where offer_id = offer_row.id
    and status::text = 'pending';

  update public.offers
  set status = 'matched', workflow_status = 'closed', closed_at = now(), updated_at = now()
  where id = offer_row.id;

  select * into agreement_row
  from public.agreements
  where id = agreement_id_value;
  if agreement_row.id is null or agreement_row.current_version_id is null then
    raise exception 'The agreement could not be linked to one frozen version.';
  end if;

  return jsonb_build_object('agreement', to_jsonb(agreement_row), 'created', true);
end;
$$;



CREATE FUNCTION public.add_trade_evidence_bundle_item_v1(p_bundle_id uuid, p_evidence_type text, p_storage_path text, p_evidence_url text, p_attestation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  bundle_row public.trade_evidence_bundles%rowtype;
  item_id uuid;
  normalized_path text := btrim(coalesce(p_storage_path, ''));
  normalized_url text := btrim(coalesce(p_evidence_url, ''));
  normalized_attestation text := btrim(coalesce(p_attestation, ''));
begin
  select *
  into bundle_row
  from public.trade_evidence_bundles b
  where b.id = p_bundle_id
  for update;

  if actor_id is null
     or not found
     or bundle_row.submitted_by <> actor_id
     or bundle_row.status <> 'draft' then
    raise exception 'This evidence packet cannot be edited.';
  end if;
  if (
    select count(*)
    from public.trade_evidence_bundle_items item
    where item.bundle_id = bundle_row.id
  ) >= 50 then
    raise exception 'An evidence packet may contain at most 50 items.';
  end if;
  if p_evidence_type not in ('file', 'link', 'attestation')
     or length(normalized_path) > 1000
     or length(normalized_url) > 2000
     or length(normalized_attestation) > 10000 then
    raise exception 'Evidence item is invalid or too long.';
  end if;
  if p_evidence_type = 'file'
     and normalized_path not like actor_id::text || '/%' then
    raise exception 'Evidence files must stay in the performer''s private storage prefix.';
  end if;

  insert into public.trade_evidence_bundle_items (
    bundle_id,
    evidence_type,
    storage_path,
    evidence_url,
    attestation
  ) values (
    bundle_row.id,
    p_evidence_type,
    normalized_path,
    normalized_url,
    normalized_attestation
  )
  returning id into item_id;

  return item_id;
end;
$$;



CREATE FUNCTION public.admin_assign_trade_appeal_reviewer_v1(p_appeal_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  appeal_row public.trade_milestone_appeals%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  base_reviewer_id uuid;
begin
  if not moral_trade_private.current_actor_has_trade_role('administrator') then
    raise exception 'Administrator assignment requires an active profile role and AAL2.';
  end if;

  select *
  into appeal_row
  from public.trade_milestone_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = appeal_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select review.reviewer_id
  into base_reviewer_id
  from public.trade_milestone_reviews review
  where review.id = appeal_row.base_review_id;

  if not found
     or appeal_row.status <> 'reviewer_selection'
     or appeal_row.reviewer_selection_deadline_at > now()
     or p_reviewer_id = base_reviewer_id
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Appeal reviewer fallback is unavailable before the seven-day deadline.';
  end if;

  update public.trade_milestone_appeals
  set assigned_reviewer_id = p_reviewer_id,
      status = 'assigned'
  where id = appeal_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values (
    p_reviewer_id,
    'appeal_reviewer_assigned',
    'Appeal review assigned',
    'An administrator assigned you after the participant selection deadline.',
    '/trade-review/' || milestone_row.id::text,
    'appeal_reviewer_assignment:' || appeal_row.id::text,
    now()
  )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'appealId', appeal_row.id,
    'assignedReviewerId', p_reviewer_id,
    'status', 'assigned'
  );
end;
$$;



CREATE FUNCTION public.admin_assign_trade_milestone_reviewer_v1(p_milestone_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
begin
  if not moral_trade_private.current_actor_has_trade_role('administrator') then
    raise exception 'Administrator assignment requires an active profile role and AAL2.';
  end if;

  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;

  if not found
     or milestone_row.assigned_reviewer_id is not null
     or milestone_row.reviewer_selection_opened_at is null
     or milestone_row.reviewer_selection_opened_at + interval '7 days' > now()
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Reviewer fallback is unavailable before the seven-day deadline.';
  end if;

  update public.trade_agreement_milestones
  set assigned_reviewer_id = p_reviewer_id,
      updated_at = now()
  where id = milestone_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values (
    p_reviewer_id,
    'milestone_reviewer_assigned',
    'Neutral review assigned',
    'An administrator assigned you after the participant selection deadline.',
    '/trade-review/' || milestone_row.id::text,
    'milestone_reviewer_assignment:' || milestone_row.id::text,
    now()
  )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'milestoneId', milestone_row.id,
    'assignedReviewerId', p_reviewer_id,
    'status', 'assigned'
  );
end;
$$;



CREATE FUNCTION public.admin_assign_trade_payment_appeal_reviewer_v1(p_appeal_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  appeal_row public.trade_payment_appeals%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  base_decision public.trade_payment_review_decisions%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
begin
  if not moral_trade_private.current_actor_has_trade_role('administrator') then
    raise exception 'Administrator assignment requires an active profile role and AAL2.';
  end if;

  select *
  into appeal_row
  from public.trade_payment_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = appeal_row.case_id
  for update;
  select *
  into base_decision
  from public.trade_payment_review_decisions decision
  where decision.id = appeal_row.base_decision_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;

  if appeal_row.status <> 'reviewer_selection'
     or review_case.status <> 'appeal_pending'
     or appeal_row.reviewer_selection_deadline_at > now()
     or p_reviewer_id = base_decision.reviewer_id
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Payment-appeal reviewer fallback is unavailable before the seven-day deadline.';
  end if;

  update public.trade_payment_appeals
  set assigned_reviewer_id = p_reviewer_id,
      status = 'assigned'
  where id = appeal_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values (
    p_reviewer_id,
    'payment_appeal_reviewer_assigned',
    'External payment appeal assigned',
    'An administrator assigned you after the participant selection deadline.',
    '/trade-review/' || milestone_row.id::text,
    'payment_appeal_assignment:' || appeal_row.id::text,
    now()
  )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'paymentAppealId', appeal_row.id,
    'assignedReviewerId', p_reviewer_id,
    'status', 'assigned'
  );
end;
$$;



