CREATE FUNCTION public.arbitrate_conditional_redirect_offer(p_offer_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_offer public.conditional_redirect_offers%rowtype;
  v_winner uuid;
begin
  select * into v_offer
  from public.conditional_redirect_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception 'conditional redirect offer not found';
  end if;
  if timezone('utc', now()) < v_offer.arbitration_closes_at then
    raise exception 'arbitration window is still open';
  end if;
  if v_offer.status not in ('open', 'arbitrating') then
    return v_offer.winning_candidate_id;
  end if;

  select id into v_winner
  from public.conditional_redirect_candidates
  where offer_id = p_offer_id
    and status = 'eligible'
    and setup_succeeded_at <= v_offer.deadline_at
  order by stripe_event_created_at, setup_succeeded_at, stripe_event_id, id
  limit 1
  for update;

  if v_winner is null then
    update public.conditional_redirect_offers
    set status = 'fallback_settling',
        settlement_started_at = timezone('utc', now())
    where id = p_offer_id;
    return null;
  end if;

  update public.conditional_redirect_candidates
  set status = case when id = v_winner then 'winner' else 'backup' end
  where offer_id = p_offer_id
    and status = 'eligible';

  update public.conditional_redirect_offers
  set status = 'matched_settling',
      winning_candidate_id = v_winner,
      settlement_started_at = timezone('utc', now())
  where id = p_offer_id;
  return v_winner;
end;
$$;



CREATE FUNCTION public.assert_trade_donation_pool_journal_balanced() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  debit_total bigint;
  credit_total bigint;
begin
  if new.status <> 'posted' then
    return new;
  end if;

  select
    coalesce(sum(case when entry_side = 'debit' then amount_cents else 0 end), 0),
    coalesce(sum(case when entry_side = 'credit' then amount_cents else 0 end), 0)
  into debit_total, credit_total
  from public.trade_donation_pool_ledger_lines
  where journal_id = new.id;

  if debit_total <= 0 or debit_total <> credit_total then
    raise exception 'Pooled-settlement journal % is not balanced.', new.id;
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.attach_trade_donation_pool_checkout(p_actor_id uuid, p_obligation_id uuid, p_checkout_session_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  obligation_row public.trade_donation_pool_obligations%rowtype;
begin
  if length(trim(coalesce(p_checkout_session_id, ''))) = 0 then
    raise exception 'A Stripe Checkout Session ID is required.';
  end if;

  select * into obligation_row
  from public.trade_donation_pool_obligations
  where id = p_obligation_id
    and payer_user_id = p_actor_id
  for update;

  if not found then
    raise exception 'Pooled obligation not found or access denied.';
  end if;
  if obligation_row.status not in ('awaiting_funding', 'checkout_abandoned', 'payment_failed') then
    raise exception 'This pooled obligation cannot start another checkout.';
  end if;

  update public.trade_donation_pool_obligations
  set
    status = 'checkout_started',
    stripe_checkout_session_id = p_checkout_session_id,
    checkout_started_at = timezone('utc', now()),
    failure_code = '',
    failure_message = ''
  where id = obligation_row.id
  returning * into obligation_row;

  insert into public.trade_donation_pool_audit_events(
    actor_profile_id, actor_kind, event_type, object_type, object_id, details
  ) values (
    p_actor_id,
    'participant',
    'stripe_checkout_started',
    'obligation',
    obligation_row.id,
    jsonb_build_object('checkoutSessionIdHash', encode(extensions.digest(convert_to(p_checkout_session_id, 'UTF8'), 'sha256'), 'hex'))
  );

  return to_jsonb(obligation_row);
end;
$$;



CREATE FUNCTION public.block_trade_pair_v2(p_actor_id uuid, p_thread_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.block_trade_pair_v2_unbound_legacy(
    p_actor_id, p_thread_id, p_reason
  );
end;
$$;



CREATE FUNCTION public.block_trade_pair_v2_unbound_legacy(p_actor_id uuid, p_thread_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
  counterpart_id uuid;
  invitation_id_value uuid;
  invitation_row public.trade_invitations%rowtype;
begin
  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b);
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;

  counterpart_id := case
    when thread_row.participant_a = p_actor_id then thread_row.participant_b
    else thread_row.participant_a
  end;
  perform moral_trade_private.lock_pair(p_actor_id, counterpart_id);

  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and (
      (participant_a = p_actor_id and participant_b = counterpart_id)
      or
      (participant_a = counterpart_id and participant_b = p_actor_id)
    )
  for update;
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;

  insert into public.trade_blocks(
    thread_id, blocker_id, blocked_id, reason, created_at
  ) values (
    p_thread_id,
    p_actor_id,
    counterpart_id,
    left(btrim(coalesce(p_reason, '')), 1000),
    now()
  )
  on conflict (thread_id, blocker_id, blocked_id)
  do update set reason = excluded.reason;

  update public.trade_threads
  set status = 'blocked', updated_at = now()
  where (
    (participant_a = p_actor_id and participant_b = counterpart_id)
    or
    (participant_a = counterpart_id and participant_b = p_actor_id)
  )
    and status <> 'closed';

  for invitation_id_value in
    select i.id
    from public.trade_invitations i
    where (
      (i.sender_id = p_actor_id and i.recipient_user_id = counterpart_id)
      or
      (i.sender_id = counterpart_id and i.recipient_user_id = p_actor_id)
    )
      and moral_trade_private.invitation_status_is_usable(i.status)
    order by i.id
  loop
    perform moral_trade_private.lock_invitation_delivery(invitation_id_value);
    select * into invitation_row
    from public.trade_invitations i
    where i.id = invitation_id_value
    for update;

    if found
       and moral_trade_private.invitation_status_is_usable(invitation_row.status) then
      update public.trade_invitations
      set
        status = 'revoked',
        revoked_at = now(),
        revocation_reason = 'Invitation revoked because this participant pair is blocked.',
        updated_at = now()
      where id = invitation_id_value;
      perform moral_trade_private.suppress_invitation_email(
        invitation_id_value,
        'Participant pair is blocked.'
      );
    end if;
  end loop;
  return true;
end;
$$;



CREATE FUNCTION public.bridge_core_agreement_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  offer_row public.offers%rowtype;
  thread_id_value uuid;
  proposal_row public.trade_counterproposals%rowtype;
  version_id_value uuid;
  terms_hash_value text;
  proposer_email text;
  responder_email text;
begin
  if new.notes = 'Created from an accepted structured counterproposal. Both parties must confirm the same immutable version.' then
    return new;
  end if;

  select * into offer_row
  from public.offers
  where id = new.offer_id;

  if not found or offer_row.workflow_status <> 'published' then
    return new;
  end if;

  select id into thread_id_value
  from public.trade_threads
  where offer_id = new.offer_id
    and status <> 'closed'
    and (
      (participant_a = new.proposer_id and participant_b = new.responder_id)
      or
      (participant_a = new.responder_id and participant_b = new.proposer_id)
    )
  order by created_at asc
  limit 1;

  if thread_id_value is null then
    insert into public.trade_threads(
      offer_id,
      agreement_id,
      participant_a,
      participant_b,
      status,
      last_message_at,
      created_at,
      updated_at
    ) values (
      new.offer_id,
      new.id,
      new.proposer_id,
      new.responder_id,
      'active',
      now(),
      now(),
      now()
    )
    on conflict do nothing
    returning id into thread_id_value;

    if thread_id_value is null then
      select id into thread_id_value
      from public.trade_threads
      where offer_id = new.offer_id
        and status <> 'closed'
        and (
          (participant_a = new.proposer_id and participant_b = new.responder_id)
          or
          (participant_a = new.responder_id and participant_b = new.proposer_id)
        )
      order by created_at asc
      limit 1;
    end if;
  end if;

  if thread_id_value is null then
    raise exception 'Unable to create or locate a private thread for agreement %', new.id;
  end if;

  select * into proposal_row
  from public.trade_counterproposals
  where thread_id = thread_id_value
  order by version desc, created_at desc
  limit 1;

  if proposal_row.id is null then
    terms_hash_value := public.core_trade_terms_hash(
      offer_row.offer_action,
      offer_row.request_action,
      offer_row.duration,
      offer_row.start_date,
      offer_row.verification,
      offer_row.evidence_due_date,
      offer_row.exit_conditions,
      offer_row.maximum_burden,
      offer_row.privacy_scope,
      offer_row.no_trade_baseline
    );

    insert into public.trade_agreement_versions(
      agreement_id,
      version,
      proposed_by,
      proposed_action,
      requested_action,
      duration,
      start_date,
      evidence_rule,
      evidence_due_date,
      exit_conditions,
      maximum_burden,
      privacy_scope,
      no_trade_baseline,
      terms_hash,
      created_at
    ) values (
      new.id,
      1,
      new.responder_id,
      offer_row.offer_action,
      offer_row.request_action,
      offer_row.duration,
      offer_row.start_date,
      offer_row.verification,
      offer_row.evidence_due_date,
      offer_row.exit_conditions,
      offer_row.maximum_burden,
      offer_row.privacy_scope,
      offer_row.no_trade_baseline,
      terms_hash_value,
      now()
    )
    returning id into version_id_value;
  else
    insert into public.trade_agreement_versions(
      agreement_id,
      version,
      proposed_by,
      proposed_action,
      requested_action,
      duration,
      start_date,
      evidence_rule,
      evidence_due_date,
      exit_conditions,
      maximum_burden,
      privacy_scope,
      no_trade_baseline,
      terms_hash,
      created_at
    ) values (
      new.id,
      1,
      proposal_row.proposer_id,
      proposal_row.proposed_action,
      proposal_row.requested_action,
      proposal_row.duration,
      proposal_row.start_date,
      proposal_row.evidence_rule,
      proposal_row.evidence_due_date,
      proposal_row.exit_conditions,
      proposal_row.maximum_burden,
      proposal_row.privacy_scope,
      proposal_row.no_trade_baseline,
      proposal_row.terms_hash,
      now()
    )
    returning id into version_id_value;
  end if;

  update public.agreements
  set
    status = 'proposed'::public.agreement_status,
    lifecycle_status = 'proposed',
    current_version_id = version_id_value,
    evidence_due_at = coalesce(proposal_row.evidence_due_date, offer_row.evidence_due_date),
    activated_at = null,
    updated_at = now()
  where id = new.id;

  update public.trade_threads
  set agreement_id = new.id, updated_at = now(), last_message_at = now()
  where id = thread_id_value;

  insert into public.trade_messages(
    thread_id,
    sender_id,
    message_type,
    body,
    metadata,
    created_at
  ) values (
    thread_id_value,
    null,
    'system',
    'The response was accepted, but the agreement remains proposed. Both participants must confirm the same frozen version before it becomes active.',
    jsonb_build_object('agreementId', new.id, 'source', 'legacy_acceptance_bridge'),
    now()
  );

  insert into public.trade_notifications(
    user_id,
    notification_type,
    title,
    body,
    href,
    dedupe_key,
    created_at
  ) values
    (
      new.proposer_id,
      'final_confirmation_required',
      'Final confirmation required',
      'Review and confirm the frozen agreement version. It is not active until both participants confirm.',
      '/trade-agreements/' || new.id::text,
      'legacy_final_confirmation:' || new.id::text || ':' || new.proposer_id::text,
      now()
    ),
    (
      new.responder_id,
      'final_confirmation_required',
      'Final confirmation required',
      'Review and confirm the frozen agreement version. It is not active until both participants confirm.',
      '/trade-agreements/' || new.id::text,
      'legacy_final_confirmation:' || new.id::text || ':' || new.responder_id::text,
      now()
    )
  on conflict (dedupe_key) do nothing;

  select email into proposer_email from public.profiles where id = new.proposer_id;
  select email into responder_email from public.profiles where id = new.responder_id;

  if coalesce(trim(proposer_email), '') <> '' then
    insert into public.email_outbox(
      profile_id, recipient_email, subject, body, status, provider, created_at
    ) values (
      new.proposer_id,
      proposer_email,
      'Moral Trade: final confirmation required',
      'A proposed agreement needs your confirmation. Sign in at https://www.moraltrade.org/trade-agreements/' || new.id::text || '. The agreement is not active until both participants confirm the same version.',
      'queued',
      'core_trade_bridge',
      now()
    );
  end if;

  if coalesce(trim(responder_email), '') <> '' then
    insert into public.email_outbox(
      profile_id, recipient_email, subject, body, status, provider, created_at
    ) values (
      new.responder_id,
      responder_email,
      'Moral Trade: final confirmation required',
      'A proposed agreement needs your confirmation. Sign in at https://www.moraltrade.org/trade-agreements/' || new.id::text || '. The agreement is not active until both participants confirm the same version.',
      'queued',
      'core_trade_bridge',
      now()
    );
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.bridge_core_interest_to_thread() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  offer_row public.offers%rowtype;
  thread_id_value uuid;
  proposal_id_value uuid;
  notification_id_value uuid;
  owner_email text;
  terms_hash_value text;
begin
  select * into offer_row
  from public.offers
  where id = new.offer_id;

  if not found
     or offer_row.workflow_status <> 'published'
     or new.user_id = offer_row.owner_id
     or new.status::text not in ('pending', 'accepted') then
    return new;
  end if;

  select id into thread_id_value
  from public.trade_threads
  where offer_id = new.offer_id
    and status <> 'closed'
    and (
      (participant_a = offer_row.owner_id and participant_b = new.user_id)
      or
      (participant_a = new.user_id and participant_b = offer_row.owner_id)
    )
  order by created_at asc
  limit 1;

  if thread_id_value is null then
    insert into public.trade_threads(
      offer_id,
      participant_a,
      participant_b,
      status,
      last_message_at,
      created_at,
      updated_at
    ) values (
      new.offer_id,
      offer_row.owner_id,
      new.user_id,
      'active',
      now(),
      now(),
      now()
    )
    on conflict do nothing
    returning id into thread_id_value;

    if thread_id_value is null then
      select id into thread_id_value
      from public.trade_threads
      where offer_id = new.offer_id
        and status <> 'closed'
        and (
          (participant_a = offer_row.owner_id and participant_b = new.user_id)
          or
          (participant_a = new.user_id and participant_b = offer_row.owner_id)
        )
      order by created_at asc
      limit 1;
    end if;
  end if;

  if thread_id_value is null then
    raise exception 'Unable to create a private trade thread for interest %', new.id;
  end if;

  terms_hash_value := public.core_trade_terms_hash(
    offer_row.offer_action,
    offer_row.request_action,
    offer_row.duration,
    offer_row.start_date,
    offer_row.verification,
    offer_row.evidence_due_date,
    offer_row.exit_conditions,
    offer_row.maximum_burden,
    offer_row.privacy_scope,
    offer_row.no_trade_baseline
  );

  insert into public.trade_counterproposals(
    thread_id,
    offer_id,
    proposer_id,
    version,
    status,
    proposed_action,
    requested_action,
    duration,
    start_date,
    evidence_rule,
    evidence_due_date,
    exit_conditions,
    maximum_burden,
    privacy_scope,
    no_trade_baseline,
    terms_hash,
    created_at
  )
  select
    thread_id_value,
    offer_row.id,
    new.user_id,
    1,
    'proposed',
    offer_row.offer_action,
    offer_row.request_action,
    offer_row.duration,
    offer_row.start_date,
    offer_row.verification,
    offer_row.evidence_due_date,
    offer_row.exit_conditions,
    offer_row.maximum_burden,
    offer_row.privacy_scope,
    offer_row.no_trade_baseline,
    terms_hash_value,
    now()
  where not exists (
    select 1
    from public.trade_counterproposals
    where thread_id = thread_id_value
  )
  on conflict do nothing
  returning id into proposal_id_value;

  if proposal_id_value is not null then
    insert into public.trade_messages(
      thread_id,
      sender_id,
      message_type,
      body,
      metadata,
      created_at
    ) values (
      thread_id_value,
      null,
      'system',
      'A participant responded from the public offer page. Review the bounded terms before accepting or counterproposing.',
      jsonb_build_object('interestId', new.id, 'source', 'legacy_public_offer'),
      now()
    );

    update public.trade_threads
    set last_message_at = now(), updated_at = now()
    where id = thread_id_value;
  end if;

  insert into public.core_loop_events(
    profile_id,
    event_type,
    entity_type,
    entity_id,
    idempotency_key,
    metadata,
    created_at
  ) values (
    new.user_id,
    'response_sent',
    'interest',
    new.id,
    'response_sent:' || new.user_id::text || ':interest:' || new.id::text,
    jsonb_build_object('source', 'legacy_public_offer'),
    now()
  )
  on conflict (idempotency_key) do nothing;

  insert into public.trade_notifications(
    user_id,
    notification_type,
    title,
    body,
    href,
    dedupe_key,
    created_at
  ) values (
    offer_row.owner_id,
    'response_sent',
    'New response',
    'A participant responded to your published proposal. Review the private thread and the current terms.',
    '/messages/' || thread_id_value::text,
    'legacy_response:' || new.id::text || ':' || offer_row.owner_id::text,
    now()
  )
  on conflict (dedupe_key) do nothing
  returning id into notification_id_value;

  if notification_id_value is not null then
    select email into owner_email
    from public.profiles
    where id = offer_row.owner_id;

    if coalesce(trim(owner_email), '') <> '' then
      insert into public.email_outbox(
        profile_id,
        recipient_email,
        subject,
        body,
        status,
        provider,
        created_at
      ) values (
        offer_row.owner_id,
        owner_email,
        'Moral Trade: new response',
        'A private Moral Trade response is ready. Sign in at https://www.moraltrade.org/messages/' || thread_id_value::text || '. This email omits private terms, contact details, payments, and evidence.',
        'queued',
        'core_trade_bridge',
        now()
      );
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.can_mutate_private_trade_evidence_object_v1(p_bucket_id text, p_object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    auth.uid() is not null
    and p_bucket_id = 'trade-evidence'
    and (storage.foldername(p_object_name))[1] = auth.uid()::text
    and not exists (
      select 1
      from public.trade_evidence_bundle_items item
      join public.trade_evidence_bundles bundle on bundle.id = item.bundle_id
      where item.storage_path = p_object_name
        and bundle.status <> 'draft'
    )
    and not exists (
      select 1
      from public.trade_external_payment_receipts receipt
      where receipt.receipt_storage_path = p_object_name
    )
    and not exists (
      select 1
      from public.trade_evidence_items item
      where item.storage_path = p_object_name
    );
$$;



CREATE FUNCTION public.can_read_private_trade_evidence_object_v1(p_bucket_id text, p_object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    auth.uid() is not null
    and p_bucket_id = 'trade-evidence'
    and (
      (storage.foldername(p_object_name))[1] = auth.uid()::text
      or exists (
        select 1
        from public.trade_evidence_bundle_items item
        join public.trade_evidence_bundles bundle on bundle.id = item.bundle_id
        join public.trade_agreement_milestones milestone on milestone.id = bundle.milestone_id
        join public.agreements agreement on agreement.id = milestone.agreement_id
        where item.storage_path = p_object_name
          and bundle.status <> 'draft'
          and (
            auth.uid() in (agreement.proposer_id, agreement.responder_id)
            or milestone.assigned_reviewer_id = auth.uid()
            or exists (
              select 1
              from public.trade_milestone_appeals appeal
              where appeal.milestone_id = milestone.id
                and appeal.assigned_reviewer_id = auth.uid()
            )
            or moral_trade_private.current_actor_has_trade_role('administrator')
          )
      )
      or exists (
        select 1
        from public.trade_evidence_items item
        join public.agreements agreement on agreement.id = item.agreement_id
        where item.storage_path = p_object_name
          and auth.uid() in (agreement.proposer_id, agreement.responder_id)
      )
      or exists (
        select 1
        from public.trade_external_payment_receipts receipt
        join public.trade_milestone_payouts payout on payout.id = receipt.payout_id
        where receipt.receipt_storage_path = p_object_name
          and (
            auth.uid() in (payout.payer_id, payout.payee_id)
            or moral_trade_private.current_actor_has_trade_role('administrator')
          )
      )
    );
$$;



CREATE FUNCTION public.can_read_public_trade_evidence_object_v1(target_bucket_id text, target_object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    target_bucket_id = 'trade-evidence'
    and coalesce(target_object_name, '') <> ''
    and exists (
      select 1
      from public.trade_evidence_items e
      join public.agreements a on a.id = e.agreement_id
      where a.public_evidence_enabled is true
        and e.public_visibility = 'public'
        and e.public_published_at is not null
        and e.redaction_status in ('redacted', 'not_required')
        and e.public_storage_path <> ''
        and e.public_storage_path = target_object_name
    );
$$;



CREATE FUNCTION public.cancel_mpgf_phase_one_pledge(p_round_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select private.cancel_mpgf_phase_one_pledge($1, $2);
$_$;



CREATE FUNCTION public.cancel_trade_donation_waiting(p_agreement_id uuid, p_actor_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_agreement public.agreements%rowtype;
  current_intent public.trade_donation_intents%rowtype;
begin
  select a.*
  into current_agreement
  from public.agreements a
  where a.id = p_agreement_id
  for update;

  if not found then
    return 'not_found';
  end if;
  if p_actor_id not in (current_agreement.proposer_id, current_agreement.responder_id) then
    return 'forbidden';
  end if;
  if current_agreement.lifecycle_status <> 'awaiting_donation' then
    return 'invalid_state';
  end if;

  select i.*
  into current_intent
  from public.trade_donation_intents i
  where i.agreement_id = current_agreement.id
    and i.agreement_version_id = current_agreement.current_version_id
  for update;

  if found and current_intent.status = 'completed' then
    return 'already_completed';
  end if;
  if found and current_intent.checkout_started_at is not null then
    return 'checkout_in_progress';
  end if;

  update public.trade_donation_intents
  set
    status = 'cancelled',
    failure_code = 'agreement_cancelled_before_verification',
    failure_message = 'The agreement was cancelled before a verified provider donation.'
  where agreement_id = current_agreement.id
    and agreement_version_id = current_agreement.current_version_id
    and status in ('created', 'checkout_started');

  update public.agreements
  set
    status = 'cancelled',
    lifecycle_status = 'cancelled',
    cancelled_at = timezone('utc', now()),
    exit_requested_by = p_actor_id,
    exit_reason = 'Cancelled before the required donation was verified.',
    updated_at = timezone('utc', now())
  where id = current_agreement.id;

  return 'cancelled';
end;
$$;



CREATE FUNCTION public.claim_conditional_settlement_batch(p_batch_id uuid, p_processing_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  affected_rows integer := 0;
begin
  update public.conditional_settlement_batches
  set
    status = 'charging',
    processing_token = p_processing_token,
    processing_started_at = timezone('utc', now()),
    started_at = coalesce(started_at, timezone('utc', now())),
    failure_code = null,
    failure_message = null
  where id = p_batch_id
    and (
      status in (
        'pending_authorizations',
        'ready',
        'requires_action',
        'failed',
        'refunded'
      )
      or (
        status in ('charging', 'transferring')
        and processing_started_at < timezone('utc', now()) - interval '10 minutes'
      )
    )
    and (next_retry_at is null or next_retry_at <= timezone('utc', now()));

  get diagnostics affected_rows = row_count;
  return affected_rows = 1;
end;
$$;



CREATE TABLE public.email_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid,
    recipient_email text NOT NULL,
    subject text NOT NULL,
    body text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    provider text DEFAULT 'manual'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    sent_at timestamp with time zone,
    dedupe_key text,
    source_kind text,
    source_id text,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    lock_token uuid,
    idempotency_key text,
    provider_message_id text,
    suppressed_at timestamp with time zone,
    CONSTRAINT email_outbox_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT email_outbox_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'retry'::text, 'sent'::text, 'failed'::text, 'suppressed'::text])))
);



CREATE FUNCTION public.claim_email_outbox_v2(p_worker_token uuid, p_limit integer DEFAULT 25) RETURNS SETOF public.email_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  candidate public.email_outbox%rowtype;
  locked_email public.email_outbox%rowtype;
  invitation_id_value uuid;
  invitation_row public.trade_invitations%rowtype;
  invitation_usable boolean;
  claimed public.email_outbox%rowtype;
begin
  if p_worker_token is null then
    raise exception 'Worker token is required.';
  end if;

  for candidate in
    select e.*
    from public.email_outbox e
    where (
      (e.status in ('queued', 'retry') and e.available_at <= now())
      or
      (e.status = 'processing' and e.locked_at < now() - interval '10 minutes')
    )
      and e.attempt_count < 5
      and btrim(e.recipient_email) <> ''
    order by e.created_at
    limit greatest(1, least(coalesce(p_limit, 25), 50))
  loop
    invitation_usable := true;

    if candidate.source_kind = 'trade_invitation' then
      invitation_usable := false;
      if candidate.source_id is null
         or candidate.source_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        select * into locked_email
        from public.email_outbox e
        where e.id = candidate.id
          and (
            (e.status in ('queued', 'retry') and e.available_at <= now())
            or
            (e.status = 'processing' and e.locked_at < now() - interval '10 minutes')
          )
          and e.attempt_count < 5
        for update skip locked;
        if not found then
          continue;
        end if;
        update public.email_outbox
        set
          status = 'suppressed',
          body = '[private invitation link removed]',
          last_error = 'Invitation source identifier is invalid.',
          suppressed_at = now(),
          locked_at = null,
          lock_token = null
        where id = locked_email.id;
        continue;
      end if;

      invitation_id_value := candidate.source_id::uuid;
      if not pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'trade_invitation:' || invitation_id_value::text,
          90211
        )
      ) then
        continue;
      end if;

      select * into invitation_row
      from public.trade_invitations i
      where i.id = invitation_id_value
      for update;

      invitation_usable := found
        and moral_trade_private.invitation_status_is_usable(invitation_row.status)
        and invitation_row.expires_at > now();
    end if;

    select * into locked_email
    from public.email_outbox e
    where e.id = candidate.id
      and (
        (e.status in ('queued', 'retry') and e.available_at <= now())
        or
        (e.status = 'processing' and e.locked_at < now() - interval '10 minutes')
      )
      and e.attempt_count < 5
      and btrim(e.recipient_email) <> ''
    for update skip locked;
    if not found then
      continue;
    end if;

    if not invitation_usable then
      update public.email_outbox
      set
        status = 'suppressed',
        body = '[private invitation link removed]',
        last_error = 'Invitation is no longer deliverable.',
        suppressed_at = now(),
        locked_at = null,
        lock_token = null
      where id = locked_email.id;
      continue;
    end if;

    update public.email_outbox
    set
      status = 'processing',
      locked_at = now(),
      lock_token = p_worker_token,
      attempt_count = attempt_count + 1,
      last_error = ''
    where id = locked_email.id
    returning * into claimed;
    return next claimed;
  end loop;
  return;
end;
$_$;



CREATE FUNCTION public.claim_recommendation_training_slot(p_slot_key text, p_scheduled_for timestamp with time zone, p_project_id text, p_deployment_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  claimed_row public.recommendation_training_slots%rowtype;
begin
  if p_project_id <> 'prj_Em3j7Uj7RatX2R1ZYhla3XSHRde7' then
    raise exception 'Only the canonical Moral Trade Vercel project may claim an A1 training slot.';
  end if;

  insert into public.recommendation_training_slots (
    slot_key,
    scheduled_for,
    status,
    canonical_project_id,
    claimed_by_project_id,
    claimed_by_deployment_id
  ) values (
    p_slot_key,
    p_scheduled_for,
    'claimed',
    'prj_Em3j7Uj7RatX2R1ZYhla3XSHRde7',
    p_project_id,
    p_deployment_id
  )
  on conflict (slot_key) do update
    set status = 'claimed',
        claimed_by_project_id = excluded.claimed_by_project_id,
        claimed_by_deployment_id = excluded.claimed_by_deployment_id,
        attempt_count = public.recommendation_training_slots.attempt_count + 1,
        claimed_at = now(),
        completed_at = null,
        last_error = '',
        updated_at = now()
    where public.recommendation_training_slots.status = 'failed'
  returning * into claimed_row;

  if claimed_row.slot_key is not null then
    return jsonb_build_object(
      'claimed', true,
      'slotKey', claimed_row.slot_key,
      'status', claimed_row.status,
      'attemptCount', claimed_row.attempt_count,
      'existingRunId', claimed_row.run_id,
      'existingModelId', claimed_row.model_version_id
    );
  end if;

  select * into claimed_row
  from public.recommendation_training_slots
  where slot_key = p_slot_key;

  return jsonb_build_object(
    'claimed', false,
    'slotKey', claimed_row.slot_key,
    'status', claimed_row.status,
    'attemptCount', claimed_row.attempt_count,
    'existingRunId', claimed_row.run_id,
    'existingModelId', claimed_row.model_version_id
  );
end;
$$;



CREATE FUNCTION public.complete_email_outbox_v2(p_email_id uuid, p_worker_token uuid, p_provider_message_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  update public.email_outbox
  set
    status = 'sent',
    provider = 'resend',
    provider_message_id = left(coalesce(p_provider_message_id, ''), 500),
    sent_at = now(),
    last_error = '',
    body = case
      when source_kind = 'trade_invitation' then '[private invitation link removed after delivery]'
      else body
    end,
    locked_at = null,
    lock_token = null
  where id = p_email_id
    and status = 'processing'
    and lock_token = p_worker_token;
  return found;
end;
$$;



CREATE FUNCTION public.complete_every_org_trade_donation(p_intent_id uuid, p_provider_charge_id_hash text, p_provider_payload_hash text, p_provider_amount_cents integer, p_provider_currency text, p_provider_nonprofit_slug text, p_provider_nonprofit_ein text, p_provider_donation_date timestamp with time zone, p_provider_payment_method text, p_is_valid boolean, p_failure_code text DEFAULT ''::text, p_failure_message text DEFAULT ''::text) RETURNS TABLE(outcome text, agreement_id uuid, payer_user_id uuid, proposer_id uuid, responder_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  current_intent public.trade_donation_intents%rowtype;
  current_term public.trade_donation_terms%rowtype;
  current_agreement public.agreements%rowtype;
  effective_failure_code text;
  effective_failure_message text;
begin
  select i.*
  into current_intent
  from public.trade_donation_intents i
  where i.id = p_intent_id
  for update;

  if not found then
    return query select 'not_found'::text, null::uuid, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select t.*
  into current_term
  from public.trade_donation_terms t
  where t.id = current_intent.donation_term_id;

  select a.*
  into current_agreement
  from public.agreements a
  where a.id = current_intent.agreement_id
  for update;

  if current_term.id is null or current_agreement.id is null then
    return query select
      'orphaned_intent'::text,
      current_intent.agreement_id,
      current_intent.payer_user_id,
      null::uuid,
      null::uuid;
    return;
  end if;

  if current_intent.status = 'completed' then
    return query select
      'duplicate'::text,
      current_intent.agreement_id,
      current_intent.payer_user_id,
      current_agreement.proposer_id,
      current_agreement.responder_id;
    return;
  end if;

  if p_provider_charge_id_hash <> '' and exists (
    select 1
    from public.trade_donation_intents other_intent
    where other_intent.provider = 'every_org'
      and other_intent.provider_charge_id_hash = p_provider_charge_id_hash
      and other_intent.id <> current_intent.id
  ) then
    p_is_valid := false;
    p_failure_code := 'provider_charge_reused';
    p_failure_message := 'The provider charge was already associated with another donation intent.';
    p_provider_charge_id_hash := '';
  end if;

  if not p_is_valid then
    effective_failure_code := coalesce(nullif(p_failure_code, ''), 'provider_payload_mismatch');
    effective_failure_message := coalesce(nullif(p_failure_message, ''), 'The provider payload did not match the frozen donation terms.');

    update public.trade_donation_intents
    set
      status = 'needs_review',
      provider_charge_id_hash = coalesce(p_provider_charge_id_hash, ''),
      provider_payload_hash = coalesce(p_provider_payload_hash, ''),
      provider_amount_cents = p_provider_amount_cents,
      provider_currency = coalesce(p_provider_currency, ''),
      provider_nonprofit_slug = coalesce(p_provider_nonprofit_slug, ''),
      provider_nonprofit_ein = coalesce(p_provider_nonprofit_ein, ''),
      provider_donation_date = p_provider_donation_date,
      provider_payment_method = coalesce(p_provider_payment_method, ''),
      failure_code = effective_failure_code,
      failure_message = effective_failure_message
    where id = current_intent.id;

    return query select
      'needs_review'::text,
      current_intent.agreement_id,
      current_intent.payer_user_id,
      current_agreement.proposer_id,
      current_agreement.responder_id;
    return;
  end if;

  if current_intent.status = 'cancelled'
    or current_agreement.lifecycle_status <> 'awaiting_donation'
    or current_agreement.current_version_id <> current_term.agreement_version_id then
    update public.trade_donation_intents
    set
      status = 'needs_review',
      provider_charge_id_hash = coalesce(p_provider_charge_id_hash, ''),
      provider_payload_hash = coalesce(p_provider_payload_hash, ''),
      provider_amount_cents = p_provider_amount_cents,
      provider_currency = coalesce(p_provider_currency, ''),
      provider_nonprofit_slug = coalesce(p_provider_nonprofit_slug, ''),
      provider_nonprofit_ein = coalesce(p_provider_nonprofit_ein, ''),
      provider_donation_date = p_provider_donation_date,
      provider_payment_method = coalesce(p_provider_payment_method, ''),
      failure_code = 'agreement_not_awaiting_donation',
      failure_message = 'A provider donation arrived after the agreement or version stopped awaiting it.'
    where id = current_intent.id;

    return query select
      'needs_review'::text,
      current_intent.agreement_id,
      current_intent.payer_user_id,
      current_agreement.proposer_id,
      current_agreement.responder_id;
    return;
  end if;

  update public.trade_donation_intents
  set
    status = 'completed',
    provider_charge_id_hash = p_provider_charge_id_hash,
    provider_payload_hash = p_provider_payload_hash,
    provider_amount_cents = p_provider_amount_cents,
    provider_currency = p_provider_currency,
    provider_nonprofit_slug = p_provider_nonprofit_slug,
    provider_nonprofit_ein = p_provider_nonprofit_ein,
    provider_donation_date = p_provider_donation_date,
    provider_payment_method = coalesce(p_provider_payment_method, ''),
    failure_code = '',
    failure_message = '',
    completed_at = timezone('utc', now())
  where id = current_intent.id;

  insert into public.trade_evidence_items (
    agreement_id,
    submitted_by,
    evidence_type,
    evidence_url,
    attestation,
    status,
    public_title,
    public_summary,
    public_visibility,
    redaction_status,
    public_redaction_note,
    public_mime_type,
    challenge_window_ends_at,
    reviewed_at,
    provider,
    provider_reference_hash,
    provider_metadata
  ) values (
    current_intent.agreement_id,
    current_intent.payer_user_id,
    'provider_donation',
    '',
    format(
      'Every.org reported a one-time $%s USD donation to %s before the reciprocal action activated.',
      to_char(current_term.amount_cents / 100.0, 'FM999999990.00'),
      current_term.target_name
    ),
    'accepted',
    'Provider-confirmed donation',
    format(
      'Every.org confirmed a one-time $%s USD donation to %s. The provider receipt activates the reciprocal action but does not prove that action was performed.',
      to_char(current_term.amount_cents / 100.0, 'FM999999990.00'),
      current_term.target_name
    ),
    'public',
    'not_required',
    'Every.org supplied the completed-donation event. Moral Trade stores no donor contact information, raw payment payload, or card data in this evidence record.',
    'application/json',
    timezone('utc', now()),
    timezone('utc', now()),
    'every_org',
    p_provider_charge_id_hash,
    jsonb_build_object(
      'schemaVersion', 'moral-trade-provider-donation-evidence-v1',
      'donationIntentId', current_intent.id,
      'donationTermId', current_term.id,
      'providerPayloadHash', p_provider_payload_hash,
      'amountCents', current_term.amount_cents,
      'currency', current_term.currency,
      'recipientSlug', current_term.nonprofit_slug,
      'recipientEin', current_term.nonprofit_ein,
      'donationDate', p_provider_donation_date,
      'paymentMethod', coalesce(p_provider_payment_method, '')
    )
  )
  on conflict (provider, provider_reference_hash)
    where provider <> '' and provider_reference_hash <> ''
  do nothing;

  update public.agreements
  set
    status = 'active',
    lifecycle_status = 'active',
    activated_at = coalesce(activated_at, timezone('utc', now())),
    updated_at = timezone('utc', now())
  where id = current_agreement.id
    and current_version_id = current_term.agreement_version_id
    and lifecycle_status = 'awaiting_donation';

  return query select
    'activated'::text,
    current_intent.agreement_id,
    current_intent.payer_user_id,
    current_agreement.proposer_id,
    current_agreement.responder_id;
end;
$_$;



CREATE FUNCTION public.complete_every_org_trade_donation_pool_bundle(p_bundle_id uuid, p_manifest_hash text, p_provider_charge_id_hash text, p_provider_payload_hash text, p_provider_amount_cents integer, p_provider_currency text, p_provider_nonprofit_slug text, p_provider_nonprofit_ein text, p_provider_donation_date timestamp with time zone, p_provider_payment_method text, p_is_valid boolean, p_failure_code text, p_failure_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  bundle_row public.trade_donation_pool_bundles%rowtype;
  item_row record;
  invalid_component_count integer;
  manifest_item_count integer;
  manifest_mismatch_count integer;
  item_count integer;
  allocation_total integer;
  manifest_header_valid boolean;
  recomputed_manifest_hash text;
  activated_count integer := 0;
  journal_id_value uuid;
  evidence_reference_hash text;
  effective_failure_code text;
  effective_failure_message text;
begin
  select * into bundle_row
  from public.trade_donation_pool_bundles
  where id = p_bundle_id
  for update;

  if not found then
    return jsonb_build_object('outcome', 'unknown_bundle');
  end if;
  if bundle_row.status = 'completed'
     and bundle_row.provider_charge_id_hash = p_provider_charge_id_hash then
    return jsonb_build_object('outcome', 'already_completed', 'bundleId', bundle_row.id);
  end if;

  if exists (
    select 1 from public.trade_donation_pool_bundles b
    where b.id <> bundle_row.id
      and b.provider = 'every_org'
      and b.provider_charge_id_hash = p_provider_charge_id_hash
      and p_provider_charge_id_hash <> ''
  ) then
    p_is_valid := false;
    p_failure_code := 'provider_charge_reused';
    p_failure_message := 'The Every.org charge was already allocated to another bundle.';
    p_provider_charge_id_hash := '';
  end if;

  if not p_is_valid
     or bundle_row.status <> 'checkout_started'
     or bundle_row.manifest_hash <> p_manifest_hash
     or p_provider_charge_id_hash !~ '^[0-9a-f]{64}$'
     or p_provider_payload_hash !~ '^[0-9a-f]{64}$'
     or p_provider_amount_cents <> bundle_row.amount_cents
     or upper(p_provider_currency) <> bundle_row.currency
     or lower(p_provider_nonprofit_slug) <> lower(bundle_row.nonprofit_slug)
     or (
       bundle_row.nonprofit_ein <> ''
       and regexp_replace(coalesce(p_provider_nonprofit_ein, ''), '[^0-9]', '', 'g') <> bundle_row.nonprofit_ein
     )
     or p_provider_donation_date is null then
    effective_failure_code := coalesce(nullif(p_failure_code, ''), 'provider_bundle_mismatch');
    effective_failure_message := coalesce(nullif(p_failure_message, ''), 'The Every.org payload did not match the frozen pooled-settlement bundle.');
    update public.trade_donation_pool_bundles
    set
      status = 'needs_review',
      provider_charge_id_hash = case when p_provider_charge_id_hash ~ '^[0-9a-f]{64}$' then p_provider_charge_id_hash else '' end,
      provider_payload_hash = case when p_provider_payload_hash ~ '^[0-9a-f]{64}$' then p_provider_payload_hash else '' end,
      provider_amount_cents = p_provider_amount_cents,
      provider_currency = upper(coalesce(p_provider_currency, '')),
      provider_nonprofit_slug = lower(coalesce(p_provider_nonprofit_slug, '')),
      provider_nonprofit_ein = regexp_replace(coalesce(p_provider_nonprofit_ein, ''), '[^0-9]', '', 'g'),
      provider_donation_date = p_provider_donation_date,
      provider_payment_method = left(coalesce(p_provider_payment_method, ''), 120),
      failure_code = effective_failure_code,
      failure_message = left(effective_failure_message, 500)
    where id = bundle_row.id;
    update public.trade_donation_pool_obligations
    set status = 'needs_review', failure_code = effective_failure_code,
        failure_message = left(effective_failure_message, 500)
    where bundle_id = bundle_row.id and status = 'bundled';
    return jsonb_build_object('outcome', 'needs_review', 'bundleId', bundle_row.id);
  end if;

  select count(*), coalesce(sum(i.allocation_cents), 0)
  into item_count, allocation_total
  from public.trade_donation_pool_bundle_items i
  where i.bundle_id = bundle_row.id;

  manifest_header_valid := coalesce(
    jsonb_typeof(bundle_row.manifest) = 'object'
    and bundle_row.manifest->>'schemaVersion' = 'moral-trade-pooled-settlement-manifest-v1'
    and bundle_row.manifest->>'bundleId' = bundle_row.id::text
    and bundle_row.manifest->>'environment' = bundle_row.environment
    and bundle_row.manifest->>'provider' = bundle_row.provider
    and lower(bundle_row.manifest->>'recipientSlug') = lower(bundle_row.nonprofit_slug)
    and regexp_replace(coalesce(bundle_row.manifest->>'recipientEin', ''), '[^0-9]', '', 'g') = bundle_row.nonprofit_ein
    and upper(bundle_row.manifest->>'currency') = bundle_row.currency
    and upper(bundle_row.manifest->>'frequency') = bundle_row.frequency
    and bundle_row.manifest->>'aggregateAmountCents' = bundle_row.amount_cents::text
    and jsonb_typeof(bundle_row.manifest->'items') = 'array',
    false
  );

  manifest_item_count := case
    when jsonb_typeof(bundle_row.manifest->'items') = 'array'
      then jsonb_array_length(bundle_row.manifest->'items')
    else 0
  end;

  select count(*) into manifest_mismatch_count
  from jsonb_array_elements(
    case
      when jsonb_typeof(bundle_row.manifest->'items') = 'array'
        then bundle_row.manifest->'items'
      else '[]'::jsonb
    end
  ) as manifest_item(item)
  left join public.trade_donation_pool_bundle_items i
    on i.bundle_id = bundle_row.id
   and i.position::text = coalesce(manifest_item.item->>'position', '')
  left join public.trade_donation_pool_obligations o on o.id = i.obligation_id
  where i.obligation_id is null
     or i.obligation_id::text is distinct from manifest_item.item->>'obligationId'
     or i.agreement_id::text is distinct from manifest_item.item->>'agreementId'
     or i.agreement_version_id::text is distinct from manifest_item.item->>'agreementVersionId'
     or i.donation_term_id::text is distinct from manifest_item.item->>'donationTermId'
     or i.payer_user_id::text is distinct from manifest_item.item->>'payerUserId'
     or i.allocation_cents::text is distinct from manifest_item.item->>'allocationCents'
     or o.condition_hash is distinct from manifest_item.item->>'conditionHash';

  recomputed_manifest_hash := encode(
    extensions.digest(convert_to(bundle_row.manifest::text, 'UTF8'), 'sha256'),
    'hex'
  );

  select count(*) into invalid_component_count
  from public.trade_donation_pool_bundle_items i
  join public.trade_donation_pool_obligations o on o.id = i.obligation_id
  join public.agreements a on a.id = i.agreement_id
  join public.trade_donation_terms t on t.id = i.donation_term_id
  where i.bundle_id = bundle_row.id
    and (
      o.status <> 'bundled'
      or o.bundle_id <> bundle_row.id
      or o.agreement_id <> i.agreement_id
      or o.agreement_version_id <> i.agreement_version_id
      or o.donation_term_id <> i.donation_term_id
      or o.payer_user_id <> i.payer_user_id
      or o.amount_cents <> i.allocation_cents
      or a.lifecycle_status <> 'awaiting_donation'
      or a.current_version_id <> i.agreement_version_id
      or t.agreement_version_id <> i.agreement_version_id
      or t.amount_cents <> i.allocation_cents
      or lower(t.nonprofit_slug) <> lower(bundle_row.nonprofit_slug)
      or t.currency <> bundle_row.currency
      or t.frequency <> bundle_row.frequency
    );

  if not manifest_header_valid
     or recomputed_manifest_hash <> bundle_row.manifest_hash
     or item_count = 0
     or item_count <> manifest_item_count
     or allocation_total <> bundle_row.amount_cents
     or manifest_mismatch_count > 0
     or invalid_component_count > 0 then
    update public.trade_donation_pool_bundles
    set status = 'needs_review', failure_code = 'bundle_manifest_component_mismatch',
        failure_message = 'At least one component no longer matches the frozen bundle manifest.'
    where id = bundle_row.id;
    update public.trade_donation_pool_obligations
    set status = 'needs_review', failure_code = 'bundle_manifest_component_mismatch',
        failure_message = 'The component could not be atomically allocated from the provider donation.'
    where bundle_id = bundle_row.id and status = 'bundled';
    return jsonb_build_object('outcome', 'needs_review', 'bundleId', bundle_row.id);
  end if;

  perform set_config('app.core_trade_internal', '1', true);

  for item_row in
    select i.*, o.target_name, o.nonprofit_slug, o.nonprofit_ein, o.currency,
           a.proposer_id, a.responder_id
    from public.trade_donation_pool_bundle_items i
    join public.trade_donation_pool_obligations o on o.id = i.obligation_id
    join public.agreements a on a.id = i.agreement_id
    where i.bundle_id = bundle_row.id
    order by i.position
  loop
    evidence_reference_hash := encode(
      extensions.digest(convert_to(p_provider_charge_id_hash || ':' || item_row.obligation_id::text, 'UTF8'), 'sha256'),
      'hex'
    );

    insert into public.trade_evidence_items(
      agreement_id,
      submitted_by,
      evidence_type,
      evidence_url,
      attestation,
      status,
      public_title,
      public_summary,
      public_visibility,
      redaction_status,
      public_redaction_note,
      public_mime_type,
      challenge_window_ends_at,
      reviewed_at,
      provider,
      provider_reference_hash,
      provider_metadata
    ) values (
      item_row.agreement_id,
      item_row.payer_user_id,
      'provider_donation',
      '',
      format(
        'Moral Trade allocated $%s USD of a consolidated Every.org donation to %s to this frozen obligation.',
        to_char(item_row.allocation_cents / 100.0, 'FM999999990.00'),
        item_row.target_name
      ),
      'accepted',
      'Provider-confirmed pooled donation allocation',
      format(
        'Every.org confirmed a consolidated donation and Moral Trade atomically allocated $%s USD to this agreement. Moral Trade, not the participant, was the provider-facing payer and presumptive donor of record.',
        to_char(item_row.allocation_cents / 100.0, 'FM999999990.00')
      ),
      'public',
      'not_required',
      'The public record omits participant payment credentials, contact information, raw Stripe and Every.org payloads, and other bundle participants.',
      'application/json',
      timezone('utc', now()),
      timezone('utc', now()),
      'every_org',
      evidence_reference_hash,
      jsonb_build_object(
        'schemaVersion', 'moral-trade-pooled-provider-donation-evidence-v1',
        'bundleId', bundle_row.id,
        'bundleManifestHash', bundle_row.manifest_hash,
        'obligationId', item_row.obligation_id,
        'allocationCents', item_row.allocation_cents,
        'aggregateAmountCents', bundle_row.amount_cents,
        'currency', bundle_row.currency,
        'recipientSlug', bundle_row.nonprofit_slug,
        'recipientEin', bundle_row.nonprofit_ein,
        'donationDate', p_provider_donation_date,
        'paymentMethod', left(coalesce(p_provider_payment_method, ''), 120),
        'participantWasDirectEveryOrgDonor', false
      )
    )
    on conflict (provider, provider_reference_hash)
      where provider <> '' and provider_reference_hash <> ''
    do nothing;

    update public.agreements
    set
      status = 'active',
      lifecycle_status = 'active',
      activated_at = coalesce(activated_at, timezone('utc', now())),
      updated_at = timezone('utc', now())
    where id = item_row.agreement_id
      and current_version_id = item_row.agreement_version_id
      and lifecycle_status = 'awaiting_donation';

    if not found then
      raise exception 'Atomic activation failed for agreement %.', item_row.agreement_id;
    end if;
    activated_count := activated_count + 1;
  end loop;

  insert into public.trade_donation_pool_ledger_journals(
    event_key, journal_type, bundle_id, currency, status, description
  ) values (
    'every-org-bundle-settlement:' || p_provider_charge_id_hash,
    'bundle_settlement',
    bundle_row.id,
    bundle_row.currency,
    'draft',
    'Consolidated Every.org donation settled every component liability atomically.'
  )
  returning id into journal_id_value;

  insert into public.trade_donation_pool_ledger_lines(
    journal_id, account_code, entry_side, amount_cents, currency,
    profile_id, obligation_id, bundle_id
  )
  select
    journal_id_value,
    'participant_settlement_liability',
    'debit',
    i.allocation_cents,
    bundle_row.currency,
    i.payer_user_id,
    i.obligation_id,
    bundle_row.id
  from public.trade_donation_pool_bundle_items i
  where i.bundle_id = bundle_row.id;

  insert into public.trade_donation_pool_ledger_lines(
    journal_id, account_code, entry_side, amount_cents, currency, bundle_id
  ) values (
    journal_id_value,
    'platform_cash_asset',
    'credit',
    bundle_row.amount_cents,
    bundle_row.currency,
    bundle_row.id
  );

  update public.trade_donation_pool_ledger_journals
  set status = 'posted', posted_at = timezone('utc', now())
  where id = journal_id_value;

  update public.trade_donation_pool_obligations
  set status = 'settled', settled_at = timezone('utc', now()), failure_code = '', failure_message = ''
  where bundle_id = bundle_row.id and status = 'bundled';

  update public.trade_donation_pool_bundles
  set
    status = 'completed',
    provider_charge_id_hash = p_provider_charge_id_hash,
    provider_payload_hash = p_provider_payload_hash,
    provider_amount_cents = p_provider_amount_cents,
    provider_currency = upper(p_provider_currency),
    provider_nonprofit_slug = lower(p_provider_nonprofit_slug),
    provider_nonprofit_ein = regexp_replace(coalesce(p_provider_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    provider_donation_date = p_provider_donation_date,
    provider_payment_method = left(coalesce(p_provider_payment_method, ''), 120),
    failure_code = '',
    failure_message = '',
    completed_at = timezone('utc', now())
  where id = bundle_row.id;

  insert into public.trade_notifications(
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select distinct
    participant_id,
    'pooled_donation_verified',
    'Pooled donation verified; agreement active',
    format(
      'Every.org confirmed the consolidated donation and Moral Trade allocated $%s USD to this agreement. The reciprocal action is now active.',
      to_char(i.allocation_cents / 100.0, 'FM999999990.00')
    ),
    '/trade-agreements/' || i.agreement_id::text,
    'pooled_donation_verified:' || bundle_row.id::text || ':' || i.agreement_id::text || ':' || participant_id::text,
    timezone('utc', now())
  from public.trade_donation_pool_bundle_items i
  join public.agreements a on a.id = i.agreement_id
  cross join lateral (values (a.proposer_id), (a.responder_id)) participants(participant_id)
  where i.bundle_id = bundle_row.id
  on conflict (dedupe_key) do nothing;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, created_at
  )
  select
    t.id,
    null,
    'system',
    format(
      'Every.org verified the consolidated donation. Moral Trade allocated $%s USD to this agreement, and the reciprocal action is now active.',
      to_char(i.allocation_cents / 100.0, 'FM999999990.00')
    ),
    jsonb_build_object(
      'source', 'every_org_pooled_settlement',
      'bundleId', bundle_row.id,
      'obligationId', i.obligation_id,
      'allocationCents', i.allocation_cents
    ),
    timezone('utc', now())
  from public.trade_donation_pool_bundle_items i
  join public.trade_threads t on t.agreement_id = i.agreement_id and t.status = 'active'
  where i.bundle_id = bundle_row.id;

  insert into public.trade_donation_pool_audit_events(
    actor_kind, event_type, object_type, object_id, details
  ) values (
    'every_org',
    'bundle_completed_and_allocated',
    'bundle',
    bundle_row.id,
    jsonb_build_object('activatedAgreementCount', activated_count, 'manifestHash', bundle_row.manifest_hash)
  );

  return jsonb_build_object(
    'outcome', 'activated',
    'bundleId', bundle_row.id,
    'activatedAgreementCount', activated_count
  );
end;
$_$;



CREATE FUNCTION public.complete_recommendation_training_slot(p_slot_key text, p_run_id uuid, p_model_id uuid, p_project_id text, p_deployment_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  model_trained_at timestamptz;
  guardrail_id uuid;
begin
  if p_project_id <> 'prj_Em3j7Uj7RatX2R1ZYhla3XSHRde7' then
    raise exception 'Only the canonical Moral Trade Vercel project may complete an A1 training slot.';
  end if;

  update public.recommendation_training_runs
  set scheduled_slot = p_slot_key,
      source_project_id = p_project_id,
      source_deployment_id = p_deployment_id,
      execution_class = 'canonical',
      duplicate_of = null,
      provenance_note = 'Canonical natural Vercel cron execution protected by the durable scheduled-slot claim.'
  where id = p_run_id;

  if not found then
    raise exception 'Training run % was not found while completing slot %.', p_run_id, p_slot_key;
  end if;

  update public.recommendation_model_versions
  set source_run_id = p_run_id,
      source_project_id = p_project_id,
      source_deployment_id = p_deployment_id,
      execution_class = 'canonical',
      duplicate_of = null,
      provenance_note = 'Produced by the canonical natural Vercel cron execution.'
  where id = p_model_id
  returning trained_at into model_trained_at;

  if model_trained_at is null then
    raise exception 'Model % was not found while completing slot %.', p_model_id, p_slot_key;
  end if;

  select id into guardrail_id
  from public.recommendation_guardrail_snapshots
  where measured_at between model_trained_at - interval '15 seconds'
                        and model_trained_at + interval '15 seconds'
    and training_run_id is null
  order by abs(extract(epoch from (measured_at - model_trained_at)))
  limit 1;

  if guardrail_id is not null then
    update public.recommendation_guardrail_snapshots
    set training_run_id = p_run_id,
        source_project_id = p_project_id,
        source_deployment_id = p_deployment_id,
        execution_class = 'canonical',
        duplicate_of = null,
        provenance_note = 'Produced by the canonical natural Vercel cron execution.'
    where id = guardrail_id;
  end if;

  update public.recommendation_training_slots
  set status = 'succeeded',
      run_id = p_run_id,
      model_version_id = p_model_id,
      completed_at = now(),
      last_error = '',
      updated_at = now()
  where slot_key = p_slot_key
    and status = 'claimed'
    and claimed_by_project_id = p_project_id;

  if not found then
    raise exception 'Slot % was not in a claimable completion state.', p_slot_key;
  end if;

  return jsonb_build_object(
    'slotKey', p_slot_key,
    'status', 'succeeded',
    'runId', p_run_id,
    'modelId', p_model_id,
    'guardrailId', guardrail_id
  );
end;
$$;



