CREATE FUNCTION public.configure_trade_donation_terms(p_agreement_id uuid, p_actor_id uuid, p_payer_role text, p_target_id text, p_target_name text, p_nonprofit_slug text, p_nonprofit_ein text, p_amount_cents integer, p_connector_terms_hash text, p_source_label text, p_source_url text, p_source_checked_at date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  current_agreement public.agreements%rowtype;
  current_version public.trade_agreement_versions%rowtype;
  existing_term public.trade_donation_terms%rowtype;
  next_version integer;
  new_version_id uuid;
begin
  select a.*
  into current_agreement
  from public.agreements a
  where a.id = p_agreement_id
  for update;

  if not found then
    raise exception 'Agreement not found.';
  end if;
  if p_actor_id not in (current_agreement.proposer_id, current_agreement.responder_id) then
    raise exception 'Only a participant can configure the donation leg.';
  end if;
  if current_agreement.lifecycle_status <> 'proposed' then
    raise exception 'Donation terms can only change before bilateral confirmation.';
  end if;
  if not exists (
    select 1
    from public.offers o
    where o.id = current_agreement.offer_id
      and o.mode = 'pledge'
  ) then
    raise exception 'The Every.org connector is available only for pledge agreements.';
  end if;
  if p_payer_role not in ('proposer', 'responder') then
    raise exception 'Invalid payer role.';
  end if;
  if p_amount_cents < 100 or p_amount_cents > 50000 then
    raise exception 'Donation amount is outside the supported range.';
  end if;
  if length(trim(p_target_id)) = 0 or length(trim(p_target_name)) = 0 or length(trim(p_nonprofit_slug)) = 0 then
    raise exception 'A complete donation destination is required.';
  end if;
  if coalesce(p_connector_terms_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'A valid connector terms hash is required.';
  end if;
  if length(trim(coalesce(p_source_label, ''))) = 0
    or coalesce(p_source_url, '') !~ '^https://'
    or p_source_checked_at is null then
    raise exception 'Complete research-source provenance is required.';
  end if;

  select v.*
  into current_version
  from public.trade_agreement_versions v
  where v.id = current_agreement.current_version_id
    and v.agreement_id = current_agreement.id;

  if not found then
    raise exception 'Current agreement version not found.';
  end if;

  select t.*
  into existing_term
  from public.trade_donation_terms t
  where t.agreement_version_id = current_version.id;

  if found and existing_term.connector_terms_hash = p_connector_terms_hash then
    return current_version.id;
  end if;

  select coalesce(max(v.version), 0) + 1
  into next_version
  from public.trade_agreement_versions v
  where v.agreement_id = current_agreement.id;

  insert into public.trade_agreement_versions (
    agreement_id,
    version,
    proposed_by,
    proposed_action,
    requested_action,
    duration,
    start_date,
    evidence_rule,
    evidence_due_date,
    exit_conditions,
    maximum_burden,
    privacy_scope,
    no_trade_baseline,
    terms_hash
  ) values (
    current_agreement.id,
    next_version,
    p_actor_id,
    current_version.proposed_action,
    current_version.requested_action,
    current_version.duration,
    current_version.start_date,
    current_version.evidence_rule,
    current_version.evidence_due_date,
    current_version.exit_conditions,
    current_version.maximum_burden,
    current_version.privacy_scope,
    current_version.no_trade_baseline,
    p_connector_terms_hash
  )
  returning id into new_version_id;

  insert into public.trade_donation_terms (
    agreement_id,
    agreement_version_id,
    payer_role,
    provider,
    target_id,
    target_name,
    nonprofit_slug,
    nonprofit_ein,
    amount_cents,
    currency,
    frequency,
    connector_terms_hash,
    source_label,
    source_url,
    source_checked_at,
    created_by
  ) values (
    current_agreement.id,
    new_version_id,
    p_payer_role,
    'every_org',
    trim(p_target_id),
    trim(p_target_name),
    lower(trim(p_nonprofit_slug)),
    regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    p_amount_cents,
    'USD',
    'ONCE',
    p_connector_terms_hash,
    trim(p_source_label),
    trim(p_source_url),
    p_source_checked_at,
    p_actor_id
  );

  update public.agreements
  set
    current_version_id = new_version_id,
    lifecycle_status = 'proposed',
    status = 'proposed',
    activated_at = null,
    updated_at = timezone('utc', now())
  where id = current_agreement.id;

  return new_version_id;
end;
$_$;



CREATE FUNCTION public.confirm_agreement_version_v2(p_actor_id uuid, p_agreement_id uuid, p_agreement_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.confirm_agreement_version_v2_unbound_legacy(
    p_actor_id, p_agreement_id, p_agreement_version_id
  );
end;
$$;



CREATE FUNCTION public.confirm_agreement_version_v2_unbound_legacy(p_actor_id uuid, p_agreement_id uuid, p_agreement_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  version_row public.trade_agreement_versions%rowtype;
  offer_row public.offers%rowtype;
  confirmation_count integer;
  counterpart_id uuid;
  loser record;
begin
  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id);

  if not found
     or agreement_row.lifecycle_status <> 'proposed'
     or agreement_row.current_version_id is null then
    raise exception 'Agreement is unavailable or can no longer be confirmed.';
  end if;

  perform moral_trade_private.lock_pair(
    agreement_row.proposer_id,
    agreement_row.responder_id
  );

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;

  if not found
     or agreement_row.lifecycle_status <> 'proposed'
     or agreement_row.current_version_id is null then
    raise exception 'Agreement is unavailable or can no longer be confirmed.';
  end if;
  if agreement_row.current_version_id <> p_agreement_version_id then
    raise exception 'The agreement changed after you reviewed it. Review the current frozen version.';
  end if;

  select * into version_row
  from public.trade_agreement_versions
  where id = p_agreement_version_id
    and agreement_id = p_agreement_id;
  if not found then
    raise exception 'Frozen agreement version not found.';
  end if;

  select * into offer_row
  from public.offers
  where id = agreement_row.offer_id
  for update;
  if not found or (
    not moral_trade_private.offer_is_invitable(offer_row.id)
    and not (
      offer_row.status::text = 'matched'
      and offer_row.workflow_status = 'closed'
      and offer_row.closed_at is not null
      and agreement_row.lifecycle_status = 'proposed'
      and (
        exists (
          select 1
          from public.interests accepted_interest
          where accepted_interest.id = agreement_row.interest_id
            and accepted_interest.offer_id = agreement_row.offer_id
            and accepted_interest.user_id = agreement_row.responder_id
            and accepted_interest.status::text = 'accepted'
        )
        or (
          agreement_row.interest_id is null
          and exists (
            select 1
            from public.guest_interests accepted_guest
            where accepted_guest.offer_id = agreement_row.offer_id
              and accepted_guest.claimed_by_profile_id = agreement_row.responder_id
              and accepted_guest.status::text = 'accepted'
          )
        )
      )
    )
  ) then
    raise exception 'The offer is no longer eligible for this non-financial agreement.';
  end if;

  if moral_trade_private.pair_is_blocked(
    agreement_row.proposer_id,
    agreement_row.responder_id
  ) then
    raise exception 'This interaction is blocked.';
  end if;

  insert into public.trade_agreement_confirmations(
    agreement_version_id, user_id, confirmed_at
  ) values (
    p_agreement_version_id, p_actor_id, now()
  )
  on conflict (agreement_version_id, user_id) do nothing;

  select count(distinct c.user_id) into confirmation_count
  from public.trade_agreement_confirmations c
  where c.agreement_version_id = p_agreement_version_id
    and c.user_id in (agreement_row.proposer_id, agreement_row.responder_id);

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;

  if confirmation_count < 2 then
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'final_confirmation_required',
      'Your confirmation is required',
      'The other participant confirmed the frozen agreement version.',
      '/trade-agreements/' || p_agreement_id::text,
      'confirmation_waiting:' || p_agreement_version_id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
    return jsonb_build_object(
      'status', 'proposed',
      'confirmationCount', confirmation_count,
      'active', false
    );
  end if;

  if exists (
    select 1
    from public.agreements a
    where a.offer_id = agreement_row.offer_id
      and a.id <> agreement_row.id
      and a.lifecycle_status in ('active', 'evidence_due', 'disputed', 'completed')
  ) then
    raise exception 'Another agreement already activated for this offer.';
  end if;

  perform set_config('app.core_trade_internal', '1', true);
  for loser in
    update public.agreements
    set
      status = 'cancelled',
      lifecycle_status = 'cancelled',
      cancelled_at = now(),
      exit_reason = 'Superseded when another agreement activated for the same offer.',
      updated_at = now()
    where offer_id = agreement_row.offer_id
      and id <> agreement_row.id
      and lifecycle_status = 'proposed'
    returning id
  loop
    update public.trade_threads
    set status = 'closed', updated_at = now()
    where agreement_id = loser.id;
  end loop;

  update public.agreements
  set
    status = 'active',
    lifecycle_status = 'active',
    activated_at = now(),
    evidence_due_at = version_row.evidence_due_date,
    updated_at = now()
  where id = agreement_row.id;

  update public.offers
  set
    status = 'matched',
    workflow_status = 'closed',
    closed_at = coalesce(closed_at, now()),
    updated_at = now()
  where id = agreement_row.offer_id;

  perform moral_trade_private.revoke_offer_invitations(
    agreement_row.offer_id,
    'Another invitation for this offer reached bilateral confirmation.'
  );

  insert into public.trade_notifications(
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values
    (
      agreement_row.proposer_id,
      'agreement_active',
      'Agreement active',
      'Both participants confirmed the frozen terms. Evidence and exit rules are now active.',
      '/trade-agreements/' || p_agreement_id::text,
      'agreement_active:' || p_agreement_id::text || ':' || agreement_row.proposer_id::text,
      now()
    ),
    (
      agreement_row.responder_id,
      'agreement_active',
      'Agreement active',
      'Both participants confirmed the frozen terms. Evidence and exit rules are now active.',
      '/trade-agreements/' || p_agreement_id::text,
      'agreement_active:' || p_agreement_id::text || ':' || agreement_row.responder_id::text,
      now()
    )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'status', 'active',
    'confirmationCount', confirmation_count,
    'active', true
  );
end;
$$;



CREATE FUNCTION public.confirm_mpgf_phase_one_external_checkout(p_round_id uuid, p_project_id uuid, p_amount_cents bigint, p_result_hash text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE sql
