    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select private.confirm_mpgf_phase_one_pledge($1, $2, $3);
$_$;



CREATE FUNCTION public.confirm_trade_completion_v3(p_actor_id uuid, p_agreement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  confirmation_count integer;
  counterpart_id uuid;
begin
  if p_actor_id is null or p_agreement_id is null then
    raise exception 'A signed-in agreement participant is required.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;
  if agreement_row.lifecycle_status = 'completed' then
    return jsonb_build_object(
      'agreementId', agreement_row.id,
      'confirmationCount', 2,
      'lifecycleStatus', 'completed',
      'completed', true,
      'idempotent', true
    );
  end if;
  if agreement_row.lifecycle_status not in ('active', 'evidence_due') then
    raise exception 'Completion cannot be confirmed in the current state.';
  end if;
  if not exists (
    select 1
    from public.trade_evidence_items evidence
    where evidence.agreement_id = agreement_row.id
      and evidence.status = 'accepted'
  ) then
    raise exception 'Accepted evidence is required before completion.';
  end if;

  insert into public.trade_completion_confirmations(
    agreement_id, user_id, confirmed_at
  ) values (
    agreement_row.id, p_actor_id, now()
  )
  on conflict (agreement_id, user_id) do nothing;

  select count(distinct user_id) into confirmation_count
  from public.trade_completion_confirmations
  where agreement_id = agreement_row.id
    and user_id in (agreement_row.proposer_id, agreement_row.responder_id);

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;

  if confirmation_count < 2 then
    begin
      insert into public.trade_notifications(
        user_id, notification_type, title, body, href, dedupe_key, created_at
      ) values (
        counterpart_id,
        'completion_confirmation_required',
        'Completion confirmation required',
        'The other participant confirmed completion. Review the accepted evidence and confirm or challenge.',
        '/trade-agreements/' || agreement_row.id::text,
        'completion_confirmation:' || agreement_row.id::text || ':' || counterpart_id::text,
        now()
      )
      on conflict (dedupe_key) do nothing;
    exception when others then
      null;
    end;

    return jsonb_build_object(
      'agreementId', agreement_row.id,
      'confirmationCount', confirmation_count,
      'lifecycleStatus', agreement_row.lifecycle_status,
      'completed', false,
      'idempotent', false
    );
  end if;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set lifecycle_status = 'completed',
      status = 'completed',
      completed_at = coalesce(completed_at, now()),
      updated_at = now(),
      public_evidence_updated_at = now()
  where id = agreement_row.id;
  update public.trade_threads
  set status = 'closed', updated_at = now()
  where agreement_id = agreement_row.id;

  begin
    insert into public.core_loop_events(
      profile_id, event_type, entity_type, entity_id, idempotency_key, metadata, created_at
    ) values
      (
        agreement_row.proposer_id,
        'agreement_completed',
        'agreement',
        agreement_row.id,
        'agreement_completed:' || agreement_row.proposer_id::text || ':agreement:' || agreement_row.id::text,
        '{}'::jsonb,
        now()
      ),
      (
        agreement_row.responder_id,
        'agreement_completed',
        'agreement',
        agreement_row.id,
        'agreement_completed:' || agreement_row.responder_id::text || ':agreement:' || agreement_row.id::text,
        '{}'::jsonb,
        now()
      )
    on conflict (idempotency_key) do nothing;
  exception when others then
    null;
  end;

  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values
      (
        agreement_row.proposer_id,
        'agreement_completed',
        'Agreement completed',
        'Both participants confirmed completion. The final Deal Receipt is available.',
        '/trade-agreements/' || agreement_row.id::text,
        'agreement_completed:' || agreement_row.id::text || ':' || agreement_row.proposer_id::text,
        now()
      ),
      (
        agreement_row.responder_id,
        'agreement_completed',
        'Agreement completed',
        'Both participants confirmed completion. The final Deal Receipt is available.',
        '/trade-agreements/' || agreement_row.id::text,
        'agreement_completed:' || agreement_row.id::text || ':' || agreement_row.responder_id::text,
        now()
      )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'agreementId', agreement_row.id,
    'confirmationCount', confirmation_count,
    'lifecycleStatus', 'completed',
    'completed', true,
    'idempotent', false
  );
end;
$$;



CREATE FUNCTION public.confirm_trade_donation_version_v2(p_actor_id uuid, p_agreement_id uuid, p_agreement_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  version_row public.trade_agreement_versions%rowtype;
  donation_term_row public.trade_donation_terms%rowtype;
  offer_row public.offers%rowtype;
  confirmation_count integer;
  counterpart_id uuid;
  loser record;
begin
  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id);

  if not found
     or agreement_row.lifecycle_status <> 'proposed'
     or agreement_row.current_version_id is null then
    raise exception 'Agreement is unavailable or can no longer be confirmed.';
  end if;

  perform moral_trade_private.lock_pair(
    agreement_row.proposer_id,
    agreement_row.responder_id
  );

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;

  if not found
     or agreement_row.lifecycle_status <> 'proposed'
     or agreement_row.current_version_id is null then
    raise exception 'Agreement is unavailable or can no longer be confirmed.';
  end if;
  if agreement_row.current_version_id <> p_agreement_version_id then
    raise exception 'The agreement changed after you reviewed it. Review the current frozen version.';
  end if;

  select * into version_row
  from public.trade_agreement_versions
  where id = p_agreement_version_id
    and agreement_id = p_agreement_id;
  if not found then
    raise exception 'Frozen agreement version not found.';
  end if;

  select * into donation_term_row
  from public.trade_donation_terms
  where agreement_id = p_agreement_id
    and agreement_version_id = p_agreement_version_id;
  if not found then
    raise exception 'Frozen donation terms were not found for this agreement version.';
  end if;

  select * into offer_row
  from public.offers
  where id = agreement_row.offer_id
  for update;
  if not found
     or offer_row.mode::text <> 'pledge'
     or offer_row.workflow_status <> 'published'
     or offer_row.status::text <> 'open' then
    raise exception 'The offer is no longer eligible for confirmation.';
  end if;

  if moral_trade_private.pair_is_blocked(
    agreement_row.proposer_id,
    agreement_row.responder_id
  ) then
    raise exception 'This interaction is blocked.';
  end if;

  insert into public.trade_agreement_confirmations(
    agreement_version_id, user_id, confirmed_at
  ) values (
    p_agreement_version_id, p_actor_id, now()
  )
  on conflict (agreement_version_id, user_id) do nothing;

  select count(distinct c.user_id) into confirmation_count
  from public.trade_agreement_confirmations c
  where c.agreement_version_id = p_agreement_version_id
    and c.user_id in (agreement_row.proposer_id, agreement_row.responder_id);

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;

  if confirmation_count < 2 then
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'final_confirmation_required',
      'Your confirmation is required',
      'The other participant confirmed the frozen donation-backed agreement version.',
      '/trade-agreements/' || p_agreement_id::text,
      'pledge_donation_confirmation_waiting:'
        || p_agreement_version_id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;

    return jsonb_build_object(
      'status', 'proposed',
      'confirmationCount', confirmation_count,
      'awaitingDonation', false
    );
  end if;

  if exists (
    select 1
    from public.agreements a
    where a.offer_id = agreement_row.offer_id
      and a.id <> agreement_row.id
      and a.lifecycle_status in (
        'confirmed',
        'awaiting_donation',
        'active',
        'evidence_due',
        'disputed',
        'completed'
      )
  ) then
    raise exception 'Another agreement already activated for this offer.';
  end if;

  perform set_config('app.core_trade_internal', '1', true);
  for loser in
    update public.agreements
    set
      status = 'cancelled',
      lifecycle_status = 'cancelled',
      cancelled_at = now(),
      exit_reason = 'Superseded when another agreement reached bilateral confirmation for the same offer.',
      updated_at = now()
    where offer_id = agreement_row.offer_id
      and id <> agreement_row.id
      and lifecycle_status = 'proposed'
    returning id
  loop
    update public.trade_threads
    set status = 'closed', updated_at = now()
    where agreement_id = loser.id;
  end loop;

  update public.agreements
  set
    status = 'proposed',
    lifecycle_status = 'awaiting_donation',
    activated_at = null,
    evidence_due_at = version_row.evidence_due_date,
    updated_at = now()
  where id = agreement_row.id;

  update public.offers
  set
    status = 'matched',
    workflow_status = 'closed',
    closed_at = now(),
    updated_at = now()
  where id = agreement_row.offer_id;

  perform moral_trade_private.revoke_offer_invitations(
    agreement_row.offer_id,
    'A donation-backed agreement for this offer reached bilateral confirmation.'
  );

  insert into public.trade_notifications(
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values
    (
      agreement_row.proposer_id,
      'pledge_donation_required',
      'Donation required before activation',
      'Both parties confirmed. The frozen Every.org donation must be completed before the reciprocal action starts.',
      '/trade-agreements/' || p_agreement_id::text,
      'pledge_donation_required:' || p_agreement_id::text
        || ':' || agreement_row.proposer_id::text
        || ':' || donation_term_row.id::text,
      now()
    ),
    (
      agreement_row.responder_id,
      'pledge_donation_required',
      'Donation required before activation',
      'Both parties confirmed. The frozen Every.org donation must be completed before the reciprocal action starts.',
      '/trade-agreements/' || p_agreement_id::text,
      'pledge_donation_required:' || p_agreement_id::text
        || ':' || agreement_row.responder_id::text
        || ':' || donation_term_row.id::text,
      now()
    )
  on conflict (dedupe_key) do nothing;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, created_at
  )
  select
    t.id,
    null,
    'system',
    'Both participants confirmed the frozen donation-backed agreement. The reciprocal action remains inactive until Every.org confirms the exact donation.',
    jsonb_build_object('source', 'every_org_pledge_donation'),
    now()
  from public.trade_threads t
  where t.agreement_id = agreement_row.id
    and t.status = 'active';

  update public.trade_threads
  set last_message_at = now(), updated_at = now()
  where agreement_id = agreement_row.id
    and status = 'active';

  return jsonb_build_object(
    'status', 'awaiting_donation',
    'confirmationCount', confirmation_count,
    'awaitingDonation', true
  );
end;
$$;



CREATE FUNCTION public.core_trade_terms_hash(proposed_action text, requested_action text, duration_value text, start_date_value date, evidence_rule_value text, evidence_due_date_value date, exit_conditions_value text, maximum_burden_value text, privacy_scope_value text, no_trade_baseline_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(
    digest(
      concat_ws(
        E'\x1f',
        lower(trim(coalesce(proposed_action, ''))),
        lower(trim(coalesce(requested_action, ''))),
        lower(trim(coalesce(duration_value, ''))),
        coalesce(start_date_value::text, ''),
        lower(trim(coalesce(evidence_rule_value, ''))),
        coalesce(evidence_due_date_value::text, ''),
        lower(trim(coalesce(exit_conditions_value, ''))),
        lower(trim(coalesce(maximum_burden_value, ''))),
        lower(trim(coalesce(privacy_scope_value, ''))),
        lower(trim(coalesce(no_trade_baseline_value, '')))
      ),
      'sha256'
    ),
    'hex'
  );
$$;



CREATE FUNCTION public.create_counterproposal_v3(p_actor_id uuid, p_thread_id uuid, p_submission_key text, p_proposed_action text, p_requested_action text, p_duration text, p_start_date date, p_evidence_rule text, p_evidence_due_date date, p_exit_conditions text, p_maximum_burden text, p_privacy_scope text, p_no_trade_baseline text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
  proposal_row public.trade_counterproposals%rowtype;
  next_version integer;
  counterpart_id uuid;
  terms_hash_value text;
  normalized_key text := btrim(coalesce(p_submission_key, ''));
begin
  if p_actor_id is null or p_thread_id is null then
    raise exception 'A signed-in participant and thread are required.';
  end if;
  if normalized_key = '' or length(normalized_key) > 200 then
    raise exception 'A bounded counterproposal submission key is required.';
  end if;
  if greatest(
    length(btrim(coalesce(p_proposed_action, ''))),
    length(btrim(coalesce(p_requested_action, ''))),
    length(btrim(coalesce(p_duration, ''))),
    length(btrim(coalesce(p_evidence_rule, ''))),
    length(btrim(coalesce(p_exit_conditions, ''))),
    length(btrim(coalesce(p_maximum_burden, ''))),
    length(btrim(coalesce(p_privacy_scope, ''))),
    length(btrim(coalesce(p_no_trade_baseline, '')))
  ) > 5000
  or btrim(coalesce(p_proposed_action, '')) = ''
  or btrim(coalesce(p_requested_action, '')) = ''
  or btrim(coalesce(p_duration, '')) = ''
  or btrim(coalesce(p_evidence_rule, '')) = ''
  or btrim(coalesce(p_exit_conditions, '')) = ''
  or btrim(coalesce(p_maximum_burden, '')) = ''
  or btrim(coalesce(p_privacy_scope, '')) = ''
  or btrim(coalesce(p_no_trade_baseline, '')) = '' then
    raise exception 'Complete every bounded counterproposal term.';
  end if;

  select * into proposal_row
  from public.trade_counterproposals
  where proposer_id = p_actor_id and submission_key = normalized_key
  limit 1;
  if proposal_row.id is not null then
    if proposal_row.thread_id <> p_thread_id then
      raise exception 'Counterproposal submission key belongs to another thread.';
    end if;
    return jsonb_build_object(
      'counterproposalId', proposal_row.id,
      'version', proposal_row.version,
      'created', false
    );
  end if;

  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b);
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;
  perform moral_trade_private.lock_pair(thread_row.participant_a, thread_row.participant_b);
  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b)
  for update;
  if not found or thread_row.status <> 'active' or thread_row.agreement_id is not null then
    raise exception 'This thread is not open for counterproposals.';
  end if;
  if moral_trade_private.pair_is_blocked(thread_row.participant_a, thread_row.participant_b) then
    raise exception 'This interaction is blocked.';
  end if;

  terms_hash_value := public.core_trade_terms_hash(
    btrim(p_proposed_action),
    btrim(p_requested_action),
    btrim(p_duration),
    p_start_date,
    btrim(p_evidence_rule),
    p_evidence_due_date,
    btrim(p_exit_conditions),
    btrim(p_maximum_burden),
    btrim(p_privacy_scope),
    btrim(p_no_trade_baseline)
  );

  select coalesce(max(version), 0) + 1 into next_version
  from public.trade_counterproposals
  where thread_id = p_thread_id;

  update public.trade_counterproposals
  set status = 'superseded', responded_at = now()
  where thread_id = p_thread_id and status = 'proposed';

  insert into public.trade_counterproposals(
    thread_id, offer_id, proposer_id, version, status,
    proposed_action, requested_action, duration, start_date,
    evidence_rule, evidence_due_date, exit_conditions, maximum_burden,
    privacy_scope, no_trade_baseline, terms_hash, submission_key, created_at
  ) values (
    p_thread_id, thread_row.offer_id, p_actor_id, next_version, 'proposed',
    btrim(p_proposed_action), btrim(p_requested_action), btrim(p_duration), p_start_date,
    btrim(p_evidence_rule), p_evidence_due_date, btrim(p_exit_conditions),
    btrim(p_maximum_burden), btrim(p_privacy_scope), btrim(p_no_trade_baseline),
    terms_hash_value, normalized_key, now()
  ) returning * into proposal_row;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, created_at
  ) values (
    thread_row.id,
    null,
    'system',
    'Counterproposal v' || proposal_row.version::text || ' was submitted.',
    jsonb_build_object('counterproposalId', proposal_row.id, 'version', proposal_row.version),
    now()
  );
  update public.trade_threads
  set last_message_at = now(), updated_at = now()
  where id = thread_row.id;

  counterpart_id := case
    when thread_row.participant_a = p_actor_id then thread_row.participant_b
    else thread_row.participant_a
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'counterproposal_sent',
      'Counterproposal received',
      'A participant proposed a new immutable version of the terms.',
      '/messages/' || thread_row.id::text,
      'counterproposal_sent:' || proposal_row.id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'counterproposalId', proposal_row.id,
    'version', proposal_row.version,
    'created', true
  );
end;
$$;



CREATE FUNCTION public.create_trade_agreement_milestone_v1(p_agreement_version_id uuid, p_position integer, p_performer_id uuid, p_payer_id uuid, p_action_category text, p_description text, p_unit_label text, p_units_total numeric, p_indivisible boolean, p_maximum_amount_cents bigint, p_currency text, p_evidence_rule text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor_id uuid := auth.uid();
  version_row public.trade_agreement_versions%rowtype;
  agreement_row public.agreements%rowtype;
  milestone_id uuid;
  position_value integer;
begin
  if actor_id is null then
    raise exception 'Sign in before defining milestone terms.';
  end if;

  select *
  into version_row
  from public.trade_agreement_versions v
  where v.id = p_agreement_version_id;
  if not found then
    raise exception 'Agreement version not found.';
  end if;

  select *
  into agreement_row
  from public.agreements a
  where a.id = version_row.agreement_id
  for update;

  select *
  into version_row
  from public.trade_agreement_versions v
  where v.id = p_agreement_version_id
    and v.agreement_id = agreement_row.id
  for update;

  if not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or agreement_row.current_version_id <> version_row.id
     or agreement_row.lifecycle_status <> 'proposed' then
    raise exception 'Milestone terms may be added only to the current proposed version by a participant.';
  end if;
  if version_row.milestone_manifest_hash is not null
     or exists (
       select 1
       from public.trade_agreement_confirmations c
       where c.agreement_version_id = version_row.id
     ) then
    raise exception 'Milestone terms are already frozen.';
  end if;
  if p_performer_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or p_payer_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or p_performer_id = p_payer_id then
    raise exception 'The performer and payer must be the two distinct agreement participants.';
  end if;
  position_value := coalesce(
    p_position,
    (
      select coalesce(max(m.position), 0) + 1
      from public.trade_agreement_milestones m
      where m.agreement_version_id = version_row.id
    )
  );

  if position_value not between 1 and 100
     or p_units_total is null
     or p_units_total <= 0
     or (coalesce(p_indivisible, true) and p_units_total <> 1)
     or p_maximum_amount_cents is null
     or p_maximum_amount_cents < 0
     or upper(btrim(coalesce(p_currency, ''))) !~ '^[A-Z]{3}$'
     or lower(btrim(coalesce(p_action_category, ''))) not in (
       'donation', 'service', 'advocacy', 'research', 'lifestyle', 'other'
     )
     or length(btrim(coalesce(p_description, ''))) not between 1 and 5000
     or length(btrim(coalesce(p_unit_label, ''))) not between 1 and 120
     or length(btrim(coalesce(p_evidence_rule, ''))) not between 1 and 5000 then
    raise exception 'Complete every bounded milestone term.';
  end if;

  insert into public.trade_agreement_milestones (
    agreement_id,
    agreement_version_id,
    position,
    performer_id,
    payer_id,
    action_category,
    description,
    unit_label,
    units_total,
    indivisible,
    maximum_amount_cents,
    currency,
    evidence_rule
  ) values (
    agreement_row.id,
    version_row.id,
    position_value,
    p_performer_id,
    p_payer_id,
    lower(btrim(p_action_category)),
    btrim(p_description),
    btrim(p_unit_label),
    p_units_total,
    coalesce(p_indivisible, true),
    p_maximum_amount_cents,
    upper(btrim(p_currency)),
    btrim(p_evidence_rule)
  )
  returning id into milestone_id;

  update public.trade_agreement_versions
  set requires_milestone_manifest = true
  where id = version_row.id;

  return milestone_id;
end;
$_$;



CREATE FUNCTION public.create_trade_donation_pool_obligation(p_actor_id uuid, p_agreement_id uuid, p_agreement_version_id uuid, p_environment text, p_condition_hash text, p_disclosure_version text, p_disclosures_accepted boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  agreement_row public.agreements%rowtype;
  term_row public.trade_donation_terms%rowtype;
  payer_id_value uuid;
  obligation_row public.trade_donation_pool_obligations%rowtype;
  livemode_value boolean;
begin
  if p_environment not in ('test', 'live') then
    raise exception 'Invalid pooled-settlement environment.';
  end if;
  if not p_disclosures_accepted or length(trim(coalesce(p_disclosure_version, ''))) = 0 then
    raise exception 'Pooled-settlement custody and donor-of-record disclosures must be accepted.';
  end if;
  if coalesce(p_condition_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'A valid pooled-settlement condition hash is required.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;

  if not found
     or agreement_row.lifecycle_status <> 'awaiting_donation'
     or agreement_row.current_version_id <> p_agreement_version_id then
    raise exception 'The exact agreement version is not awaiting a donation.';
  end if;

  select * into term_row
  from public.trade_donation_terms
  where agreement_id = p_agreement_id
    and agreement_version_id = p_agreement_version_id;

  if not found or term_row.provider <> 'every_org' or term_row.amount_cents >= 1000 then
    raise exception 'Only sub-$10 Every.org obligations use pooled settlement.';
  end if;

  payer_id_value := case
    when term_row.payer_role = 'proposer' then agreement_row.proposer_id
    else agreement_row.responder_id
  end;
  if p_actor_id <> payer_id_value then
    raise exception 'Only the designated payer can fund this pooled obligation.';
  end if;
  livemode_value := p_environment = 'live';

  select * into obligation_row
  from public.trade_donation_pool_obligations
  where donation_term_id = term_row.id
  for update;

  if found then
    if obligation_row.condition_hash <> p_condition_hash
       or obligation_row.agreement_version_id <> p_agreement_version_id
       or obligation_row.payer_user_id <> payer_id_value
       or obligation_row.environment <> p_environment then
      raise exception 'An existing pooled obligation is bound to different immutable terms.';
    end if;
    return to_jsonb(obligation_row);
  end if;

  insert into public.trade_donation_pool_obligations(
    donation_term_id,
    agreement_id,
    agreement_version_id,
    payer_user_id,
    environment,
    provider,
    target_id,
    target_name,
    nonprofit_slug,
    nonprofit_ein,
    amount_cents,
    currency,
    frequency,
    condition_hash,
    status,
    stripe_livemode,
    disclosure_version,
    disclosures_accepted_at
  ) values (
    term_row.id,
    agreement_row.id,
    p_agreement_version_id,
    payer_id_value,
    p_environment,
    'every_org',
    term_row.target_id,
    term_row.target_name,
    lower(term_row.nonprofit_slug),
    regexp_replace(term_row.nonprofit_ein, '[^0-9]', '', 'g'),
    term_row.amount_cents,
    term_row.currency,
    term_row.frequency,
    p_condition_hash,
    'awaiting_funding',
    livemode_value,
    p_disclosure_version,
    timezone('utc', now())
  )
  returning * into obligation_row;

  insert into public.trade_donation_pool_audit_events(
    actor_profile_id, actor_kind, event_type, object_type, object_id, details
  ) values (
    p_actor_id,
    'participant',
    'obligation_created',
    'obligation',
    obligation_row.id,
    jsonb_build_object('conditionHash', p_condition_hash, 'amountCents', obligation_row.amount_cents)
  );

  return to_jsonb(obligation_row);
end;
$_$;



CREATE FUNCTION public.create_trade_invitation_v2(p_actor_id uuid, p_offer_id uuid, p_invitation_id uuid, p_token_hash text, p_token_ciphertext text, p_recipient_email text, p_message text, p_email_subject text, p_email_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.create_trade_invitation_v2_unbound_legacy(
    p_actor_id, p_offer_id, p_invitation_id, p_token_hash,
    p_token_ciphertext, p_recipient_email, p_message,
    p_email_subject, p_email_body
  );
end;
$$;



CREATE FUNCTION public.create_trade_invitation_v2_unbound_legacy(p_actor_id uuid, p_offer_id uuid, p_invitation_id uuid, p_token_hash text, p_token_ciphertext text, p_recipient_email text, p_message text, p_email_subject text, p_email_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  offer_row public.offers%rowtype;
  normalized_email text := lower(btrim(coalesce(p_recipient_email, '')));
  normalized_message text := btrim(coalesce(p_message, ''));
  recipient_id uuid;
  actor_email text;
  invitation_status text;
  invitation_terms_hash text;
  expires_value timestamptz := now() + interval '14 days';
begin
  if p_actor_id is null or p_invitation_id is null or p_offer_id is null then
    raise exception 'Invitation identity is required.';
  end if;
  if p_token_hash !~ '^[0-9a-f]{64}$' or length(coalesce(p_token_ciphertext, '')) < 40 then
    raise exception 'A secure invitation token is required.';
  end if;
  if length(normalized_email) > 320
     or (normalized_email <> '' and normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
    raise exception 'Enter a valid recipient email address.';
  end if;
  if length(normalized_message) > 4000 then
    raise exception 'Invitation notes must be 4,000 characters or fewer.';
  end if;

  if (
    select count(*)
    from public.trade_invitations i
    where i.sender_id = p_actor_id
      and i.created_at >= now() - interval '24 hours'
  ) >= 20 then
    raise exception 'Daily invitation limit reached. Try again after the oldest invitation is 24 hours old.';
  end if;

  select lower(email) into actor_email
  from auth.users
  where id = p_actor_id;

  if normalized_email <> '' and normalized_email = actor_email then
    raise exception 'You cannot invite your own account.';
  end if;

  if normalized_email <> '' then
    select u.id into recipient_id
    from auth.users u
    join public.profiles p on p.id = u.id
    where lower(u.email) = normalized_email
      and u.email_confirmed_at is not null
    order by u.created_at
    limit 1;
  end if;
  if recipient_id is not null then
    perform moral_trade_private.lock_pair(p_actor_id, recipient_id);
    if moral_trade_private.pair_is_blocked(p_actor_id, recipient_id) then
      raise exception 'This interaction is blocked.';
    end if;
  end if;

  select * into offer_row
  from public.offers
  where id = p_offer_id
  for update;

  if not found or offer_row.owner_id <> p_actor_id then
    raise exception 'Offer not found or access denied.';
  end if;
  if not moral_trade_private.offer_is_invitable(p_offer_id) then
    raise exception 'Only published, bounded, non-financial pledge proposals can be invited.';
  end if;

  invitation_status := case when normalized_email = '' then 'drafted' else 'sent' end;
  invitation_terms_hash := public.core_trade_terms_hash(
    offer_row.offer_action,
    offer_row.request_action,
    offer_row.duration,
    offer_row.start_date,
    offer_row.verification,
    offer_row.evidence_due_date,
    offer_row.exit_conditions,
    offer_row.maximum_burden,
    offer_row.privacy_scope,
    offer_row.no_trade_baseline
  );

  insert into public.trade_invitations(
    id,
    offer_id,
    sender_id,
    recipient_user_id,
    recipient_email,
    token,
    token_hash,
    token_ciphertext,
    delivery_kind,
    message,
    status,
    terms_version,
    terms_hash,
    expires_at,
    created_at,
    updated_at
  ) values (
    p_invitation_id,
    p_offer_id,
    p_actor_id,
    recipient_id,
    normalized_email,
    null,
    p_token_hash,
    p_token_ciphertext,
    case when normalized_email = '' then 'share_link' else 'email' end,
    normalized_message,
    invitation_status,
    offer_row.terms_version,
    invitation_terms_hash,
    expires_value,
    now(),
    now()
  );

  if normalized_email <> '' then
    if btrim(coalesce(p_email_subject, '')) = ''
       or btrim(coalesce(p_email_body, '')) = '' then
      raise exception 'Invitation email delivery could not be prepared.';
    end if;

    insert into public.email_outbox(
      profile_id,
      recipient_email,
      subject,
      body,
      status,
      provider,
      attempt_count,
      dedupe_key,
      idempotency_key,
      source_kind,
      source_id,
      available_at,
      created_at
    ) values (
      recipient_id,
      normalized_email,
      left(p_email_subject, 160),
      p_email_body,
      'queued',
      'core_trade_invitation',
      0,
      'trade-invitation:' || p_invitation_id::text,
      'trade-invitation:' || p_invitation_id::text,
      'trade_invitation',
      p_invitation_id::text,
      now(),
      now()
    );
  end if;

  insert into public.core_loop_events(
    profile_id,
    event_type,
    entity_type,
    entity_id,
    idempotency_key,
    metadata,
    created_at
  ) values (
    p_actor_id,
    'invitation_sent',
    'invitation',
    p_invitation_id,
    'invitation_sent:' || p_actor_id::text || ':invitation:' || p_invitation_id::text,
    jsonb_build_object(
      'delivery', case when normalized_email = '' then 'share_link' else 'email' end,
      'termsVersion', offer_row.terms_version
    ),
    now()
  )
  on conflict (idempotency_key) do nothing;

  return jsonb_build_object(
    'invitationId', p_invitation_id,
    'status', invitation_status,
    'expiresAt', expires_value
  );
end;
$_$;



CREATE FUNCTION public.credibility_category_for_offer_mode(target_mode public.offer_mode) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case target_mode
    when 'pledge'::public.offer_mode then 'behavioral_pledge'
    when 'offset'::public.offer_mode then 'donation'
    when 'payment'::public.offer_mode then 'paid_action'
    else 'other'
  end;
$$;



CREATE FUNCTION public.credibility_proof_weight(target_quality text, target_model jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((target_model ->> target_quality)::numeric, 0.2);
$$;



CREATE FUNCTION public.credibility_stake_weight(target_stake numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select least(2::numeric, 1::numeric + ln(1::numeric + least(greatest(coalesce(target_stake, 0), 0), 1000000::numeric)) / ln(101::numeric));
$$;



CREATE FUNCTION public.decide_counterproposal_v2(p_actor_id uuid, p_thread_id uuid, p_proposal_id uuid, p_decision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.decide_counterproposal_v2_unbound_legacy(
    p_actor_id, p_thread_id, p_proposal_id, p_decision
  );
end;
$$;



CREATE FUNCTION public.decide_counterproposal_v2_unbound_legacy(p_actor_id uuid, p_thread_id uuid, p_proposal_id uuid, p_decision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
  proposal_row public.trade_counterproposals%rowtype;
  offer_row public.offers%rowtype;
  agreement_id_value uuid;
  agreement_version_id uuid;
begin
  if p_decision not in ('accept', 'reject') then
    raise exception 'Choose accept or reject.';
  end if;

  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b);
  if not found or thread_row.status <> 'active' then
    raise exception 'Thread not found or unavailable.';
  end if;

  perform moral_trade_private.lock_pair(thread_row.participant_a, thread_row.participant_b);

  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b)
  for update;
  if not found or thread_row.status <> 'active' then
    raise exception 'Thread not found or unavailable.';
  end if;

  select * into offer_row
  from public.offers
  where id = thread_row.offer_id
  for update;
  if not found then
    raise exception 'Offer not found.';
  end if;

  if moral_trade_private.pair_is_blocked(thread_row.participant_a, thread_row.participant_b) then
    raise exception 'This interaction is blocked.';
  end if;

  select * into proposal_row
  from public.trade_counterproposals
  where id = p_proposal_id
    and thread_id = p_thread_id
    and status = 'proposed'
  for update;
  if not found then
    raise exception 'The proposal is no longer awaiting a decision.';
  end if;
  if proposal_row.proposer_id = p_actor_id then
    raise exception 'The proposer cannot decide their own proposal.';
  end if;

  if p_decision = 'reject' then
    update public.trade_counterproposals
    set status = 'rejected', responded_at = now()
    where id = proposal_row.id;
    insert into public.trade_messages(
      thread_id, sender_id, message_type, body, metadata, created_at
    ) values (
      thread_row.id, null, 'system',
      'Counterproposal v' || proposal_row.version::text || ' was rejected.',
      jsonb_build_object('counterproposalId', proposal_row.id),
      now()
    );
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      proposal_row.proposer_id,
      'proposal_rejected',
      'Proposal rejected',
      'The current counterproposal was rejected. The private thread remains available.',
      '/messages/' || thread_row.id::text,
      'proposal_rejected:' || proposal_row.id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
    return jsonb_build_object('status', 'rejected', 'threadId', thread_row.id);
  end if;

  if thread_row.agreement_id is not null
     or exists (
       select 1
       from public.agreements a
       where a.offer_id = thread_row.offer_id
         and (
           (a.proposer_id = thread_row.participant_a and a.responder_id = thread_row.participant_b)
           or
           (a.proposer_id = thread_row.participant_b and a.responder_id = thread_row.participant_a)
         )
         and a.lifecycle_status not in ('cancelled', 'expired')
     ) then
    raise exception 'An agreement already exists for this participant pair.';
  end if;
  if not moral_trade_private.offer_is_invitable(offer_row.id) then
    raise exception 'This proposal is no longer eligible for a non-financial agreement.';
  end if;

  perform set_config('app.core_trade_accepting', '1', true);
  update public.trade_counterproposals
  set status = 'accepted', responded_at = now()
  where id = proposal_row.id;

  insert into public.agreements(
    offer_id, interest_id, proposer_id, responder_id, status,
    lifecycle_status, notes, evidence_due_at, created_at, updated_at
  ) values (
    offer_row.id,
    null,
    offer_row.owner_id,
    case
      when offer_row.owner_id = thread_row.participant_a then thread_row.participant_b
      else thread_row.participant_a
    end,
    'proposed',
    'proposed',
    'Created from an accepted structured counterproposal. Both parties must confirm the same immutable version.',
    proposal_row.evidence_due_date,
    now(),
    now()
  )
  returning id into agreement_id_value;

  perform set_config('app.core_trade_linking_agreement', '1', true);
  insert into public.trade_agreement_versions(
    agreement_id, version, proposed_by, proposed_action, requested_action,
    duration, start_date, evidence_rule, evidence_due_date, exit_conditions,
    maximum_burden, privacy_scope, no_trade_baseline, terms_hash, created_at
  ) values (
    agreement_id_value, 1, proposal_row.proposer_id,
    proposal_row.proposed_action, proposal_row.requested_action,
    proposal_row.duration, proposal_row.start_date, proposal_row.evidence_rule,
    proposal_row.evidence_due_date, proposal_row.exit_conditions,
    proposal_row.maximum_burden, proposal_row.privacy_scope,
    proposal_row.no_trade_baseline, proposal_row.terms_hash, now()
  )
  returning id into agreement_version_id;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set current_version_id = agreement_version_id,
      evidence_due_at = proposal_row.evidence_due_date,
      status = 'proposed',
      lifecycle_status = 'proposed',
      updated_at = now()
  where id = agreement_id_value;
  update public.trade_threads
  set agreement_id = agreement_id_value, updated_at = now(), last_message_at = now()
  where id = thread_row.id;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, created_at
  ) values (
    thread_row.id,
    null,
    'system',
    'The counterproposal was accepted. Both participants must confirm the same frozen agreement version before activation.',
    jsonb_build_object(
      'counterproposalId', proposal_row.id,
      'agreementId', agreement_id_value,
      'agreementVersionId', agreement_version_id
    ),
    now()
  );

  insert into public.trade_notifications(
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values
    (
      thread_row.participant_a,
      'final_confirmation_required',
      'Final confirmation required',
      'Review the frozen agreement version. It is not active until both participants confirm it.',
      '/trade-agreements/' || agreement_id_value::text,
      'counter_confirmation:' || agreement_id_value::text || ':' || thread_row.participant_a::text,
      now()
    ),
    (
      thread_row.participant_b,
      'final_confirmation_required',
      'Final confirmation required',
      'Review the frozen agreement version. It is not active until both participants confirm it.',
      '/trade-agreements/' || agreement_id_value::text,
      'counter_confirmation:' || agreement_id_value::text || ':' || thread_row.participant_b::text,
      now()
    )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'status', 'accepted',
    'threadId', thread_row.id,
    'agreementId', agreement_id_value,
    'agreementVersionId', agreement_version_id
  );
end;
$$;



CREATE FUNCTION public.decline_proposed_agreement_v3(p_actor_id uuid, p_agreement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  counterpart_id uuid;
begin
  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;
  if agreement_row.lifecycle_status = 'cancelled' then
    return jsonb_build_object('agreementId', p_agreement_id, 'status', 'cancelled', 'idempotent', true);
  end if;
  if agreement_row.lifecycle_status <> 'proposed' then
    raise exception 'Use the published exit workflow after activation.';
  end if;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set lifecycle_status = 'cancelled',
      status = 'cancelled',
      cancelled_at = coalesce(cancelled_at, now()),
      exit_requested_by = p_actor_id,
      exit_reason = 'Declined before bilateral activation.',
      updated_at = now()
  where id = p_agreement_id;
  update public.trade_threads
  set status = 'closed', updated_at = now()
  where agreement_id = p_agreement_id;

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'agreement_declined',
      'Agreement declined',
      'The proposed agreement was declined before activation. No obligation was created.',
      '/trade-agreements/' || p_agreement_id::text,
      'agreement_declined:' || p_agreement_id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object('agreementId', p_agreement_id, 'status', 'cancelled', 'idempotent', false);
end;
$$;



CREATE FUNCTION public.enforce_global_pair_block_on_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
begin
  if new.sender_id is null then
    return new;
  end if;
  select * into thread_row
  from public.trade_threads
  where id = new.thread_id;
  if not found
     or new.sender_id not in (thread_row.participant_a, thread_row.participant_b) then
    raise exception 'Only thread participants may send private messages.';
  end if;
  if thread_row.status <> 'active'
     or moral_trade_private.pair_is_blocked(
       thread_row.participant_a,
       thread_row.participant_b
     ) then
    raise exception 'This private interaction is blocked.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.enforce_global_pair_block_on_thread() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.status = 'active'
     and moral_trade_private.pair_is_blocked(new.participant_a, new.participant_b) then
    raise exception 'This participant pair is blocked.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.enforce_private_source_evidence_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.evidence_type = 'file' then
    -- A participant certification is useful context, but it is not an
    -- independent redaction review. Never expose the original source upload.
    new.redaction_status := 'pending_review';
    new.public_storage_path := '';
    new.public_url := '';
    new.public_redaction_note :=
      'The uploaded source remains private until a separate redaction review approves a public-safe copy.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.ensure_email_outbox_idempotency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.idempotency_key := coalesce(
    nullif(btrim(new.idempotency_key), ''),
    nullif(btrim(new.dedupe_key), ''),
    'email-outbox:' || new.id::text
  );
  new.available_at := coalesce(new.available_at, now());
  return new;
end;
$$;



CREATE FUNCTION public.fail_recommendation_training_slot(p_slot_key text, p_project_id text, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.recommendation_training_slots
  set status = 'failed',
      completed_at = now(),
      last_error = left(coalesce(p_error, 'unknown training error'), 1000),
      updated_at = now()
  where slot_key = p_slot_key
    and status = 'claimed'
    and claimed_by_project_id = p_project_id;
end;
$$;



CREATE FUNCTION public.finalize_donation_offset_settlement(p_batch_id uuid, p_processing_token uuid, p_match_id uuid, p_offer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  affected_rows integer := 0;
begin
  update public.conditional_settlement_batches
  set
    status = 'transferred',
    completed_at = timezone('utc', now()),
    processing_token = null,
    processing_started_at = null,
    failure_code = null,
    failure_message = null
  where id = p_batch_id
    and processing_token = p_processing_token
    and status = 'transferring';

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    return false;
  end if;

  update public.donation_offset_matches
  set status = 'completed'
  where id = p_match_id
    and offer_id = p_offer_id
    and status = 'matched';

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception 'Donation-offset match could not be finalized from matched state.';
  end if;

  update public.offers
  set status = 'closed'
  where id = p_offer_id
    and status in ('open', 'matched');

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception 'Donation-offset offer could not be closed during settlement finalization.';
  end if;

  return true;
end;
$$;



CREATE FUNCTION public.finalize_test_donation_offset_settlement(p_batch_id uuid, p_processing_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  affected_rows integer := 0;
begin
  update public.conditional_settlement_batches
  set
    status = 'transferred',
    completed_at = timezone('utc', now()),
    processing_token = null,
    processing_started_at = null,
    failure_code = null,
    failure_message = null
  where id = p_batch_id
    and processing_token = p_processing_token
    and status = 'transferring'
    and livemode = false
    and purpose = 'donation_offset'
    and subject_type = 'donation_offset_match';

  get diagnostics affected_rows = row_count;
  return affected_rows = 1;
end;
$$;



CREATE FUNCTION public.finalize_trade_milestone_manifest_v1(p_agreement_version_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  version_row public.trade_agreement_versions%rowtype;
  agreement_row public.agreements%rowtype;
  manifest_hash text;
  complete_hash text;
begin
  if actor_id is null then
    raise exception 'Sign in before finalizing milestone terms.';
  end if;

  select *
  into version_row
  from public.trade_agreement_versions v
  where v.id = p_agreement_version_id;

  select *
  into agreement_row
  from public.agreements a
  where a.id = version_row.agreement_id
  for update;

  select *
  into version_row
  from public.trade_agreement_versions v
  where v.id = p_agreement_version_id
    and v.agreement_id = agreement_row.id
  for update;

  if not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or agreement_row.current_version_id <> version_row.id
     or agreement_row.lifecycle_status <> 'proposed' then
    raise exception 'Only a participant may finalize the current proposed version.';
  end if;
  if exists (
    select 1
    from public.trade_agreement_confirmations c
    where c.agreement_version_id = version_row.id
  ) then
    raise exception 'A confirmed version cannot be changed.';
  end if;
  if not exists (
    select 1
    from public.trade_agreement_milestones m
    where m.agreement_version_id = version_row.id
  ) then
    raise exception 'Add at least one independently priced milestone.';
  end if;

  manifest_hash := public.trade_milestone_manifest_hash_v1(version_row.id);
  complete_hash := encode(
    extensions.digest(
      convert_to(version_row.terms_hash || chr(31) || manifest_hash, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  update public.trade_agreement_versions
  set requires_milestone_manifest = true,
      milestone_manifest_hash = manifest_hash,
      complete_terms_hash = complete_hash
  where id = version_row.id;

  return complete_hash;
end;
$$;



CREATE FUNCTION public.finalize_trade_milestone_review_v1(p_milestone_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  review_row public.trade_milestone_reviews%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
begin
  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.milestone_id = milestone_row.id
  for update;
  select *
  into review_row
  from public.trade_milestone_reviews review
  where review.id = payout_row.review_id
  for update;

  if actor_id is null
     or not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or payout_row.is_final
     or review_row.appeal_deadline_at > now()
     or exists (
       select 1
       from public.trade_milestone_appeals appeal
       where appeal.milestone_id = milestone_row.id
     )
     or (
       review_row.outcome = 'rejected'
       and not milestone_row.replacement_packet_used
       and milestone_row.replacement_deadline_at > now()
     ) then
    raise exception 'The review is not ready for finality.';
  end if;

  update public.trade_milestone_reviews
  set is_final = true,
      finalized_at = now()
  where id = review_row.id;

  update public.trade_milestone_payouts
  set is_final = true,
      status = case when amount_due_cents = 0 then 'not_due' else 'due' end,
      finalized_at = now(),
      updated_at = now()
  where id = payout_row.id
  returning * into payout_row;

  update public.trade_agreement_milestones
  set final_review_id = review_row.id,
      status = case when review_row.outcome = 'rejected' then 'evidence_due' else 'graded' end,
      replacement_deadline_at = null,
      replacement_seconds_remaining = null,
      updated_at = now()
  where id = milestone_row.id;

  if review_row.outcome = 'graded'
     and not exists (
       select 1
       from public.trade_agreement_milestones other
       where other.agreement_id = agreement_row.id
         and other.id <> milestone_row.id
         and other.status in ('replacement_due', 'appeal_pending', 'evidence_due')
     ) then
    update public.agreements
    set lifecycle_status = case
          when lifecycle_status = 'evidence_due' then 'active'
          else lifecycle_status
        end,
        future_obligations_paused_at = null,
        future_obligations_pause_reason = '',
        updated_at = now()
    where id = agreement_row.id;
  end if;

  return jsonb_build_object(
    'milestoneId', milestone_row.id,
    'reviewId', review_row.id,
    'payoutId', payout_row.id,
    'status', payout_row.status,
    'isFinal', true
  );
end;
$$;



CREATE FUNCTION public.finalize_trade_payment_review_v1(p_case_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  review_case public.trade_payment_review_cases%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  decision_row public.trade_payment_review_decisions%rowtype;
  receipt_row public.trade_external_payment_receipts%rowtype;
  payout_status_value text;
begin
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = p_case_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select *
  into decision_row
  from public.trade_payment_review_decisions decision
  where decision.id = review_case.final_decision_id
  for update;
  select *
  into receipt_row
  from public.trade_external_payment_receipts receipt
  where receipt.id = decision_row.receipt_id
  for update;

  if actor_id is null
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or review_case.status <> 'decision_pending'
     or decision_row.is_final
     or decision_row.outcome not in ('confirm_paid', 'still_due')
     or decision_row.appeal_deadline_at is null
     or decision_row.appeal_deadline_at > now()
     or exists (
       select 1
       from public.trade_payment_appeals appeal
       where appeal.case_id = review_case.id
     ) then
    raise exception 'The payment decision is not ready for finality.';
  end if;

  payout_status_value := case
    when decision_row.outcome = 'confirm_paid' then 'adjudicated_paid'
    else 'still_due'
  end;

  update public.trade_payment_review_decisions
  set is_final = true,
      finalized_at = now()
  where id = decision_row.id;
  update public.trade_payment_review_cases
  set status = 'resolved',
      updated_at = now()
  where id = review_case.id;
  update public.trade_external_payment_receipts
  set status = case
        when decision_row.outcome = 'confirm_paid'
          then 'adjudicated_paid'
        else 'adjudicated_still_due'
      end,
      updated_at = now()
  where id = receipt_row.id;
  update public.trade_milestone_payouts
  set status = payout_status_value,
      updated_at = now()
  where id = payout_row.id;
  update public.trade_agreement_milestones
  set status = case
        when decision_row.outcome = 'confirm_paid' then 'paid'
        else 'graded'
      end,
      updated_at = now()
  where id = milestone_row.id;

  return jsonb_build_object(
    'paymentReviewCaseId', review_case.id,
    'decisionId', decision_row.id,
    'outcome', decision_row.outcome,
    'status', payout_status_value,
    'isFinal', true
  );
end;
$$;



CREATE FUNCTION public.get_core_release_health_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  with required_tables(name) as (
    values
      ('public.profiles'),
      ('public.offers'),
      ('public.trade_invitations'),
      ('public.trade_threads'),
      ('public.trade_messages'),
      ('public.trade_counterproposals'),
      ('public.agreements'),
      ('public.trade_agreement_versions'),
      ('public.trade_agreement_confirmations'),
      ('public.trade_evidence_items'),
      ('public.trade_completion_confirmations'),
      ('public.trade_exit_requests')
  ), required_functions(name) as (
    values
      ('create_trade_invitation_v2'),
      ('respond_trade_invitation_v2'),
      ('decide_counterproposal_v2'),
      ('confirm_agreement_version_v2'),
      ('send_trade_message_v3'),
      ('create_counterproposal_v3'),
      ('propose_agreement_version_v3'),
      ('register_trade_evidence_v3'),
      ('review_trade_evidence_v3'),
      ('confirm_trade_completion_v3'),
      ('request_trade_exit_v3')
  ), table_check as (
    select bool_and(to_regclass(name) is not null) as ready
    from required_tables
  ), function_check as (
    select bool_and(exists (
      select 1
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = required_functions.name
    )) as ready
    from required_functions
  ), rls_check as (
    select bool_and(c.relrowsecurity) as ready
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname in (
        'offers','trade_invitations','trade_threads','trade_messages',
        'trade_counterproposals','agreements','trade_agreement_versions',
        'trade_agreement_confirmations','trade_evidence_items',
        'trade_completion_confirmations','trade_exit_requests'
      )
  ), storage_check as (
    select exists (
      select 1 from storage.buckets b
      where b.id = 'trade-evidence' and b.public = false
    ) as ready
  )
  select jsonb_build_object(
    'ready', coalesce(table_check.ready, false)
      and coalesce(function_check.ready, false)
      and coalesce(rls_check.ready, false)
      and coalesce(storage_check.ready, false),
    'tablesReady', coalesce(table_check.ready, false),
    'functionsReady', coalesce(function_check.ready, false),
    'rlsReady', coalesce(rls_check.ready, false),
    'storageReady', coalesce(storage_check.ready, false)
  )
  from table_check, function_check, rls_check, storage_check;
$$;



