CREATE FUNCTION public.get_public_group_buying_snapshot() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
with
live_cycles as (
  select
    id,
    label,
    mode,
    currency,
    status,
    ballot_closes_at,
    summary_published_at,
    created_at
  from public.mpgf_cycles
  where mode in ('real_money', 'pledge_only')
    and concat_ws(' ', id, label, mode) !~* '(^|[[:space:]_:-])(demo|test|sandbox|simulated)([[:space:]_:-]|$)'
    and status !~* '(closed|cancelled|canceled|expired|archived|completed|complete)'
),
route_payload as (
  select
    p.title as sort_title,
    jsonb_build_object(
      'id', p.id::text,
      'publicKey', a.id,
      'title', p.title,
      'summary', coalesce(nullif(p.summary, ''), a.description),
      'causeArea', coalesce(nullif(p.cause_area, ''), a.cause_area),
      'recipientName', coalesce(nullif(p.proposed_recipient_name, ''), a.recipient_name),
      'intervention', p.intervention,
      'verificationSummary', coalesce(nullif(p.outcome_units_summary, ''), a.outcome_unit),
      'expectedEffect', p.expected_effect_vs_funding,
      'timeline', p.timeline,
      'statusLabel', case
        when c.mode = 'real_money' then 'Live real-money cycle'
        else 'Live pledge-only cycle'
      end,
      'statusSentence', concat(
        'Approved candidate in ',
        c.label,
        '. ',
        case
          when c.mode = 'real_money' then 'Financial activity is read from live payment records.'
          else 'This route records real participant intent but does not move money.'
        end
      ),
      'fundingMode', c.mode,
      'currency', upper(c.currency),
      'minimumFundingCents', coalesce(p.minimum_viable_funding_cents, 0),
      'targetFundingCents', p.requested_maximum_funding_cents,
      'deadlineAt', coalesce(c.ballot_closes_at, c.summary_published_at),
      'failureBehavior', 'If the cycle or its review conditions do not clear, no live settlement is created for this route.',
      'href', '/contact'
    ) as route
  from public.mpgf_pool_proposals p
  join public.mpgf_candidate_alternatives a
    on a.id = p.candidate_alternative_id
  join live_cycles c
    on c.id = a.cycle_id
  where p.status = 'approved_as_candidate'
    and a.status <> 'approved_demo'
    and concat_ws(
      ' ',
      p.title,
      p.summary,
      p.proposed_recipient_name,
      a.id,
      a.name,
      a.recipient_name,
      a.status
    ) !~* '(^|[[:space:]_:-])(demo|test|sandbox|simulated)([[:space:]_:-]|$)'
),
route_summary as (
  select coalesce(jsonb_agg(route order by sort_title), '[]'::jsonb) as routes
  from route_payload
),
live_mandates as (
  select
    id,
    amount_cents,
    currency,
    status,
    created_at,
    updated_at
  from public.conditional_payment_mandates
  where purpose = 'public_goods_pool'
    and livemode = true
),
live_attempts as (
  select
    a.amount_cents,
    a.currency,
    a.status,
    a.refunded_amount_cents,
    a.created_at,
    a.updated_at
  from public.conditional_payment_attempts a
  join live_mandates m
    on m.id = a.mandate_id
),
live_transfers as (
  select
    t.amount_cents,
    t.currency,
    t.status,
    t.created_at,
    t.updated_at
  from public.conditional_settlement_transfers t
  join live_mandates m
    on m.id = t.mandate_id
),
live_recurring as (
  select
    amount_cents,
    currency,
    status,
    next_scheduled_at,
    created_at,
    paused_at,
    cancelled_at
  from public.mpgf_recurring_contribution_commitments
  where mode = 'real_money'
),
financial_activity as (
  select updated_at as activity_at from live_mandates
  union all
  select updated_at as activity_at from live_attempts
  union all
  select updated_at as activity_at from live_transfers
  union all
  select coalesce(cancelled_at, paused_at, next_scheduled_at, created_at) as activity_at
  from live_recurring
),
financial_summary as (
  select jsonb_build_object(
    'currency', upper(coalesce(
      (select currency from live_mandates order by created_at desc limit 1),
      (select currency from live_attempts order by created_at desc limit 1),
      (select currency from live_transfers order by created_at desc limit 1),
      (select currency from live_recurring order by created_at desc limit 1),
      (select currency from live_cycles order by created_at desc limit 1),
      'USD'
    )),
    'liveMandateCount', (select count(*) from live_mandates),
    'openMandateCount', (
      select count(*)
      from live_mandates
      where status in ('setup_pending', 'ready', 'charge_pending', 'requires_action')
    ),
    'openConditionalExposureCents', (
      select coalesce(sum(amount_cents), 0)
      from live_mandates
      where status in ('setup_pending', 'ready', 'charge_pending', 'requires_action')
    ),
    'grossChargedCents', (
      select coalesce(sum(amount_cents), 0)
      from live_attempts
      where status in ('succeeded', 'refunded', 'disputed')
    ),
    'refundedCents', (
      select coalesce(sum(refunded_amount_cents), 0)
      from live_attempts
      where status in ('succeeded', 'refunded', 'disputed')
    ),
    'netChargedCents', greatest(
      (
        select coalesce(sum(amount_cents), 0)
        from live_attempts
        where status in ('succeeded', 'refunded', 'disputed')
      ) - (
        select coalesce(sum(refunded_amount_cents), 0)
        from live_attempts
        where status in ('succeeded', 'refunded', 'disputed')
      ),
      0
    ),
    'transferredCents', (
      select coalesce(sum(amount_cents), 0)
      from live_transfers
      where status = 'transferred'
    ),
    'activeRecurringCommitmentCount', (
      select count(*)
      from live_recurring
      where status in ('active', 'provider_action_required')
    ),
    'activeRecurringMonthlyCents', (
      select coalesce(sum(amount_cents), 0)
      from live_recurring
      where status in ('active', 'provider_action_required')
    ),
    'latestFinancialActivityAt', (select max(activity_at) from financial_activity)
  ) as financial
),
gate_payload as (
  select
    case gate_key
      when 'destination_approved' then 'Live recipient destination'
      when 'legal_terms_approved' then 'Legal terms'
      when 'operator_runbook_approved' then 'Operator runbook'
      when 'payout_profile_approved' then 'Payout profile'
      when 'recipient_compliance_policy_approved' then 'Recipient compliance'
      when 'refund_policy_approved' then 'Refund policy'
      when 'stripe_account_ready' then 'Stripe account'
      when 'stripe_live_keys_configured' then 'Stripe live keys'
      when 'stripe_webhook_configured' then 'Stripe webhook'
      when 'terms_approved' then 'Participant terms'
      when 'webhook_signature' then 'Signed webhook'
      else replace(gate_key, '_', ' ')
    end as sort_label,
    status,
    jsonb_build_object(
      'key', gate_key,
      'label', case gate_key
        when 'destination_approved' then 'Live recipient destination'
        when 'legal_terms_approved' then 'Legal terms'
        when 'operator_runbook_approved' then 'Operator runbook'
        when 'payout_profile_approved' then 'Payout profile'
        when 'recipient_compliance_policy_approved' then 'Recipient compliance'
        when 'refund_policy_approved' then 'Refund policy'
        when 'stripe_account_ready' then 'Stripe account'
        when 'stripe_live_keys_configured' then 'Stripe live keys'
        when 'stripe_webhook_configured' then 'Stripe webhook'
        when 'terms_approved' then 'Participant terms'
        when 'webhook_signature' then 'Signed webhook'
        else replace(gate_key, '_', ' ')
      end,
      'status', case
        when status in ('passed', 'pending', 'blocked') then status
        else 'unknown'
      end,
      'updatedAt', updated_at
    ) as gate
  from public.conditional_payment_gate_status
  where environment = 'live'
),
gate_summary as (
  select
    count(*) filter (where status = 'passed') as passed_count,
    count(*) filter (where status = 'pending') as pending_count,
    count(*) filter (where status = 'blocked') as blocked_count,
    count(*) as total_count,
    coalesce(jsonb_agg(gate order by sort_label), '[]'::jsonb) as gates
  from gate_payload
)
select jsonb_build_object(
  'sourceStatus', 'live',
  'checkedAt', statement_timestamp(),
  'routes', route_summary.routes,
  'openCycleCount', (select count(*) from live_cycles),
  'financial', financial_summary.financial,
  'paymentReadiness', jsonb_build_object(
    'status', case
      when gate_summary.total_count = 0 then 'unavailable'
      when gate_summary.blocked_count > 0 then 'blocked'
      when gate_summary.pending_count > 0
        or gate_summary.passed_count <> gate_summary.total_count then 'pending'
      else 'ready'
    end,
    'passedGateCount', gate_summary.passed_count,
    'pendingGateCount', gate_summary.pending_count,
    'blockedGateCount', gate_summary.blocked_count,
    'totalGateCount', gate_summary.total_count,
    'gates', gate_summary.gates
  )
)
from route_summary
cross join financial_summary
cross join gate_summary;
$_$;



CREATE FUNCTION public.get_public_moral_trade_evidence_v1(p_record_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', a.id,
    'isExample', false,
    'accessScope', 'public',
    'lifecycle', a.lifecycle_status,
    'offeredCause', coalesce(nullif(o.offered_cause, ''), 'Moral priority'),
    'requestedCause', coalesce(nullif(o.requested_cause, ''), 'Counterparty priority'),
    'proposedAction', coalesce(nullif(v.proposed_action, ''), 'Action recorded in the agreement.'),
    'requestedAction', coalesce(nullif(v.requested_action, ''), 'Reciprocal action recorded in the agreement.'),
    'evidenceRule', coalesce(nullif(v.evidence_rule, ''), 'Evidence is evaluated against the frozen agreement.'),
    'duration', coalesce(nullif(v.duration, ''), 'Duration recorded in the agreement.'),
    'privacyScope', coalesce(nullif(v.privacy_scope, ''), 'Public-safe evidence only.'),
    'proposer', coalesce(nullif(proposer.display_name, ''), 'Proposer'),
    'responder', coalesce(nullif(responder.display_name, ''), 'Responder'),
    'createdAt', a.created_at,
    'activatedAt', a.activated_at,
    'completedAt', a.completed_at,
    'updatedAt', a.public_evidence_updated_at,
    'evidenceTotalCount', evidence.item_count,
    'evidence', evidence.items,
    'completionConfirmations', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'confirmed_at', confirmation.confirmed_at,
            'actor_display_name', case
              when confirmation.user_id = a.proposer_id
                then coalesce(nullif(proposer.display_name, ''), 'Proposer')
              when confirmation.user_id = a.responder_id
                then coalesce(nullif(responder.display_name, ''), 'Responder')
              else 'Participant'
            end
          )
          order by confirmation.confirmed_at
        )
        from public.trade_completion_confirmations confirmation
        where confirmation.agreement_id = a.id
      ),
      '[]'::jsonb
    )
  )
  from public.agreements a
  left join public.offers o on o.id = a.offer_id
  left join public.trade_agreement_versions v on v.id = a.current_version_id
  left join public.profiles proposer on proposer.id = a.proposer_id
  left join public.profiles responder on responder.id = a.responder_id
  join lateral (
    select
      count(*)::bigint as item_count,
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', e.id,
            'title', coalesce(nullif(e.public_title, ''), 'Published evidence'),
            'summary', coalesce(nullif(e.public_summary, ''), 'Evidence submitted under the frozen agreement.'),
            'evidenceType', e.evidence_type,
            'mimeType', nullif(e.public_mime_type, ''),
            'state', e.status,
            'submittedBy', coalesce(nullif(submitter.display_name, ''), 'Participant'),
            'submittedAt', e.created_at,
            'reviewedAt', e.reviewed_at,
            'challengeWindowEndsAt', e.challenge_window_ends_at,
            'redactionState', e.redaction_status,
            'redactionNote', coalesce(nullif(e.public_redaction_note, ''), 'Only the public-safe evidence record is available.'),
            'fileName', case
              when e.redaction_status in ('redacted', 'not_required')
                then nullif(e.public_original_filename, '')
              else null
            end,
            'publicUrl', case
              when e.redaction_status in ('redacted', 'not_required')
                and nullif(e.public_url, '') ~* '^https?://'
                then e.public_url
              else null
            end,
            'publicObjectPath', case
              when e.evidence_type = 'file'
                and e.redaction_status in ('redacted', 'not_required')
                then nullif(e.public_storage_path, '')
              else null
            end
          )
        )
        order by e.created_at, e.id
      ) as items
    from public.trade_evidence_items e
    left join public.profiles submitter on submitter.id = e.submitted_by
    where e.agreement_id = a.id
      and e.public_visibility = 'public'
      and e.public_published_at is not null
      and e.redaction_status <> 'withheld'
  ) evidence on evidence.item_count > 0
  where a.id = p_record_id
    and a.public_evidence_enabled is true;
$$;



CREATE FUNCTION public.get_safe_profile_labels_v1(p_profile_ids uuid[]) RETURNS TABLE(id uuid, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    profile.id,
    coalesce(nullif(btrim(profile.display_name), ''), 'Moral Trade participant')
  from public.profiles profile
  join (
    select distinct candidate.profile_id
    from unnest(coalesce(p_profile_ids, array[]::uuid[])) as candidate(profile_id)
    limit 100
  ) requested on requested.profile_id = profile.id
  where cardinality(coalesce(p_profile_ids, array[]::uuid[])) <= 100
  order by profile.id;
$$;



CREATE FUNCTION public.grade_trade_milestone_v1(p_milestone_id uuid, p_bundle_id uuid, p_completion_units numeric, p_confidence_band smallint, p_outcome text, p_private_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  bundle_row public.trade_evidence_bundles%rowtype;
  completion_value numeric(20, 6);
  band_value smallint;
  basis_points_value integer;
  amount_due_value bigint;
  review_kind_value text;
  appeal_already_used boolean;
  final_value boolean;
  review_id uuid;
begin
  if not moral_trade_private.current_actor_has_trade_role('reviewer') then
    raise exception 'Neutral review requires an active profile role and AAL2.';
  end if;

  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;
  select *
  into bundle_row
  from public.trade_evidence_bundles b
  where b.id = p_bundle_id
    and b.milestone_id = milestone_row.id
  for update;

  if not found
     or actor_id <> milestone_row.assigned_reviewer_id
     or actor_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or milestone_row.current_bundle_id <> bundle_row.id
     or milestone_row.status <> 'under_review'
     or bundle_row.status <> 'submitted'
     or p_outcome not in ('graded', 'rejected')
     or p_confidence_band not in (0, 25, 50, 75, 100)
     or length(btrim(coalesce(p_private_reason, ''))) not between 1 and 4000 then
    raise exception 'This evidence packet cannot be graded.';
  end if;

  if p_outcome = 'rejected' then
    completion_value := 0;
    band_value := 0;
  else
    completion_value := p_completion_units;
    band_value := p_confidence_band;
    if completion_value is null
       or completion_value < 0
       or completion_value > milestone_row.units_total
       or (
         milestone_row.indivisible
         and completion_value not in (0, milestone_row.units_total)
       ) then
      raise exception 'Completion must follow the pre-agreed milestone units.';
    end if;
  end if;

  select calculation.payout_basis_points, calculation.amount_due_cents
  into basis_points_value, amount_due_value
  from public.trade_milestone_payout_v1(
    milestone_row.maximum_amount_cents,
    completion_value,
    milestone_row.units_total,
    band_value
  ) calculation;

  review_kind_value := case
    when bundle_row.bundle_kind = 'replacement' then 'replacement'
    else 'initial'
  end;
  appeal_already_used := exists (
    select 1
    from public.trade_milestone_appeals appeal
    where appeal.milestone_id = milestone_row.id
  );
  final_value := appeal_already_used;

  insert into public.trade_milestone_reviews (
    milestone_id,
    bundle_id,
    reviewer_id,
    review_kind,
    outcome,
    completion_units,
    confidence_band,
    payout_basis_points,
    amount_due_cents,
    private_reason,
    appeal_deadline_at,
    is_final,
    finalized_at
  ) values (
    milestone_row.id,
    bundle_row.id,
    actor_id,
    review_kind_value,
    p_outcome,
    completion_value,
    band_value,
    basis_points_value,
    amount_due_value,
    btrim(p_private_reason),
    now() + interval '7 days',
    final_value,
    case when final_value then now() else null end
  )
  returning id into review_id;

  update public.trade_evidence_bundles
  set status = case when p_outcome = 'rejected' then 'invalid' else 'accepted' end,
      reviewed_at = now()
  where id = bundle_row.id;

  insert into public.trade_milestone_payouts (
    milestone_id,
    review_id,
    payer_id,
    payee_id,
    maximum_amount_cents,
    completion_units,
    units_total,
    confidence_band,
    payout_basis_points,
    amount_due_cents,
    currency,
    is_final,
    status,
    finalized_at
  ) values (
    milestone_row.id,
    review_id,
    milestone_row.payer_id,
    milestone_row.performer_id,
    milestone_row.maximum_amount_cents,
    completion_value,
    milestone_row.units_total,
    band_value,
    basis_points_value,
    amount_due_value,
    milestone_row.currency,
    final_value,
    case
      when not final_value then 'provisional'
      when amount_due_value = 0 then 'not_due'
      else 'due'
    end,
    case when final_value then now() else null end
  )
  on conflict (milestone_id) do update
  set review_id = excluded.review_id,
      completion_units = excluded.completion_units,
      confidence_band = excluded.confidence_band,
      payout_basis_points = excluded.payout_basis_points,
      amount_due_cents = excluded.amount_due_cents,
      is_final = excluded.is_final,
      status = excluded.status,
      finalized_at = excluded.finalized_at,
      updated_at = now();

  if p_outcome = 'rejected' then
    update public.trade_agreement_milestones
    set status = case when final_value then 'evidence_due' else 'replacement_due' end,
        final_review_id = case when final_value then review_id else null end,
        replacement_deadline_at = case
          when final_value or replacement_packet_used then null
          else now() + interval '7 days'
        end,
        replacement_seconds_remaining = case
          when final_value or replacement_packet_used then null
          else 604800
        end,
        updated_at = now()
    where id = milestone_row.id;

    update public.agreements
    set lifecycle_status = 'evidence_due',
        future_obligations_paused_at = coalesce(future_obligations_paused_at, now()),
        future_obligations_pause_reason = 'Evidence was rejected; replacement evidence or prospective exit is required.',
        updated_at = now()
    where id = agreement_row.id;
  else
    update public.trade_agreement_milestones
    set status = 'graded',
        final_review_id = case when final_value then review_id else null end,
        replacement_deadline_at = null,
        replacement_seconds_remaining = null,
        updated_at = now()
    where id = milestone_row.id;

    if final_value
       and not exists (
         select 1
         from public.trade_agreement_milestones other
         where other.agreement_id = agreement_row.id
           and other.id <> milestone_row.id
           and other.status in ('replacement_due', 'appeal_pending', 'evidence_due')
       ) then
      update public.agreements
      set lifecycle_status = case
            when lifecycle_status = 'evidence_due' then 'active'
            else lifecycle_status
          end,
          future_obligations_paused_at = null,
          future_obligations_pause_reason = '',
          updated_at = now()
      where id = agreement_row.id;
    end if;
  end if;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    participant_id,
    'milestone_reviewed',
    'Milestone review recorded',
    case
      when p_outcome = 'rejected'
        then 'Evidence was rejected. Replacement and appeal rules are now active.'
      else 'A neutral reviewer recorded the pre-agreed completion and confidence band.'
    end,
    '/trade-agreements/' || agreement_row.id::text,
    'milestone_reviewed:' || review_id::text || ':' || participant_id::text,
    now()
  from unnest(
    array[agreement_row.proposer_id, agreement_row.responder_id]
  ) as participants(participant_id)
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'reviewId', review_id,
    'milestoneId', milestone_row.id,
    'outcome', p_outcome,
    'completionUnits', completion_value,
    'confidenceBand', band_value,
    'payoutBasisPoints', basis_points_value,
    'amountDueCents', amount_due_value,
    'currency', milestone_row.currency,
    'isFinal', final_value,
    'appealDeadlineAt', now() + interval '7 days'
  );
end;
$$;



CREATE FUNCTION public.guard_conditional_destination_request_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Destination requests are retained as an audit record.';
  end if;
  if new.requester_profile_id <> old.requester_profile_id
     or new.environment <> old.environment
     or new.provider <> old.provider
     or new.provider_nonprofit_id <> old.provider_nonprofit_id
     or new.nonprofit_slug <> old.nonprofit_slug
     or new.display_name <> old.display_name
     or new.nonprofit_ein <> old.nonprofit_ein
     or new.country_code <> old.country_code
     or new.website_url <> old.website_url
     or new.identity_snapshot <> old.identity_snapshot
     or new.identity_hash <> old.identity_hash
     or new.created_at <> old.created_at then
    raise exception 'Destination request identity is immutable.';
  end if;
  if old.status <> 'pending' and (
    new.status <> old.status
    or new.reviewed_by is distinct from old.reviewed_by
    or new.reviewed_at is distinct from old.reviewed_at
    or new.review_notes <> old.review_notes
    or new.destination_id is distinct from old.destination_id
  ) then
    raise exception 'A reviewed destination request is immutable.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_core_agreement_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  offer_workflow_status text;
  confirmation_count integer;
  completion_count integer;
  authorized_exit_count integer;
begin
  select offer.workflow_status
  into offer_workflow_status
  from public.offers offer
  where offer.id = new.offer_id;

  if offer_workflow_status <> 'published' and old.current_version_id is null then
    return new;
  end if;

  if (
    (new.status::text = 'active' and old.status::text <> 'active')
    or
    (new.lifecycle_status = 'active' and old.lifecycle_status <> 'active')
  ) then
    if new.current_version_id is null then
      raise exception 'A frozen agreement version is required before activation.';
    end if;

    select count(*)
    into confirmation_count
    from public.trade_agreement_confirmations confirmation
    where confirmation.agreement_version_id = new.current_version_id
      and confirmation.user_id in (new.proposer_id, new.responder_id);

    if confirmation_count < 2 then
      raise exception 'Both participants must confirm the same frozen agreement version before activation.';
    end if;
  end if;

  if (
    (new.status::text = 'completed' and old.status::text <> 'completed')
    or
    (new.lifecycle_status = 'completed' and old.lifecycle_status <> 'completed')
  ) and not moral_trade_private.is_trade_agreement_milestone_complete(new.id) then
    select count(*)
    into completion_count
    from public.trade_completion_confirmations confirmation
    where confirmation.agreement_id = new.id
      and confirmation.user_id in (new.proposer_id, new.responder_id);

    if completion_count < 2 then
      raise exception 'Completion requires final milestone grading and payment or both participant confirmations.';
    end if;
  end if;

  if (
    (new.status::text = 'cancelled' and old.status::text <> 'cancelled')
    or
    (new.lifecycle_status = 'cancelled' and old.lifecycle_status <> 'cancelled')
  ) and old.lifecycle_status in (
    'active', 'evidence_due', 'disputed', 'confirmed'
  ) then
    select count(*)
    into authorized_exit_count
    from public.trade_exit_requests request
    where request.agreement_id = new.id
      and request.status in ('accepted', 'executed');

    if authorized_exit_count < 1 then
      raise exception 'Active agreements may be cancelled only through an accepted mutual cancellation or an executed unilateral exit.';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.guard_core_agreement_version_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  expected_version integer;
  is_participant boolean;
begin
  select coalesce(max(v.version), 0) + 1
  into expected_version
  from public.trade_agreement_versions v
  where v.agreement_id = new.agreement_id;

  select exists (
    select 1 from public.agreements a
    where a.id = new.agreement_id
      and actor in (a.proposer_id, a.responder_id)
      and a.lifecycle_status = 'proposed'
  ) into is_participant;

  if actor is not null
     and coalesce(current_setting('app.core_trade_linking_agreement', true), '') <> '1' then
    if not is_participant or new.proposed_by <> actor then
      raise exception 'Only a participant may propose a new agreement version.';
    end if;
  end if;
  if new.version <> expected_version then
    raise exception 'Agreement versions must be sequential.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_core_counterproposal_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  participant boolean;
begin
  select exists (
    select 1 from public.trade_threads t
    where t.id = coalesce(new.thread_id, old.thread_id)
      and actor in (t.participant_a, t.participant_b)
  ) into participant;

  if actor is not null and not participant then
    raise exception 'Only thread participants may change counterproposals.';
  end if;

  if tg_op = 'INSERT' then
    if actor is not null and new.proposer_id <> actor then
      raise exception 'The proposer must be the signed-in participant.';
    end if;
    if new.version <= 0 or btrim(new.terms_hash) = '' then
      raise exception 'A positive version and terms hash are required.';
    end if;
    return new;
  end if;

  if new.thread_id <> old.thread_id
     or new.offer_id <> old.offer_id
     or new.proposer_id <> old.proposer_id
     or new.version <> old.version
     or new.proposed_action <> old.proposed_action
     or new.requested_action <> old.requested_action
     or new.duration <> old.duration
     or new.start_date is distinct from old.start_date
     or new.evidence_rule <> old.evidence_rule
     or new.evidence_due_date is distinct from old.evidence_due_date
     or new.exit_conditions <> old.exit_conditions
     or new.maximum_burden <> old.maximum_burden
     or new.privacy_scope <> old.privacy_scope
     or new.no_trade_baseline <> old.no_trade_baseline
     or new.terms_hash <> old.terms_hash then
    raise exception 'Counterproposal terms are immutable.';
  end if;

  if new.status = 'accepted'
     and coalesce(current_setting('app.core_trade_accepting', true), '') <> '1' then
    raise exception 'Acceptance must use the atomic acceptance workflow.';
  end if;
  if actor is not null and new.status = 'rejected' and actor = old.proposer_id then
    raise exception 'A proposer cannot reject their own proposal.';
  end if;
  if actor is not null and new.status = 'withdrawn' and actor <> old.proposer_id then
    raise exception 'Only the proposer may withdraw a proposal.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_core_evidence_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  actor uuid := auth.uid();
  is_participant boolean;
  is_counterparty boolean;
begin
  select
    exists (
      select 1 from public.agreements a
      where a.id = coalesce(new.agreement_id, old.agreement_id)
        and actor in (a.proposer_id, a.responder_id)
        and a.lifecycle_status in ('active', 'evidence_due', 'disputed')
    ),
    exists (
      select 1 from public.agreements a
      where a.id = coalesce(new.agreement_id, old.agreement_id)
        and actor in (a.proposer_id, a.responder_id)
        and actor <> coalesce(new.submitted_by, old.submitted_by)
    )
  into is_participant, is_counterparty;

  if actor is not null and not is_participant then
    raise exception 'Evidence may be changed only by an active agreement participant.';
  end if;

  if tg_op = 'INSERT' then
    if actor is not null and new.submitted_by <> actor then
      raise exception 'The evidence submitter must be the signed-in participant.';
    end if;
    if new.replaces_evidence_id is not null and not exists (
      select 1 from public.trade_evidence_items prior
      where prior.id = new.replaces_evidence_id
        and prior.agreement_id = new.agreement_id
        and prior.submitted_by = new.submitted_by
        and prior.status in ('submitted', 'challenged')
    ) then
      raise exception 'Replacement evidence must reference an open item from the same submitter and agreement.';
    end if;
    return new;
  end if;

  if new.agreement_id <> old.agreement_id
     or new.submitted_by <> old.submitted_by
     or new.evidence_type <> old.evidence_type
     or new.storage_path <> old.storage_path
     or new.evidence_url <> old.evidence_url
     or new.attestation <> old.attestation
     or new.replaces_evidence_id is distinct from old.replaces_evidence_id
     or new.created_at <> old.created_at then
    raise exception 'Submitted evidence source data is immutable.';
  end if;

  if actor is not null
     and actor <> old.submitted_by
     and (
       new.public_title is distinct from old.public_title
       or new.public_summary is distinct from old.public_summary
       or new.public_url is distinct from old.public_url
       or new.public_storage_path is distinct from old.public_storage_path
       or new.public_visibility is distinct from old.public_visibility
       or new.redaction_status is distinct from old.redaction_status
       or new.public_redaction_note is distinct from old.public_redaction_note
       or new.public_mime_type is distinct from old.public_mime_type
       or new.public_original_filename is distinct from old.public_original_filename
       or new.public_published_at is distinct from old.public_published_at
       or new.withdrawal_reason is distinct from old.withdrawal_reason
       or new.withdrawn_at is distinct from old.withdrawn_at
       or new.replaced_at is distinct from old.replaced_at
     ) then
    raise exception 'Only the submitter may change evidence publication or withdrawal fields.';
  end if;

  if new.status is distinct from old.status then
    if new.status in ('accepted', 'challenged') then
      if old.status <> 'submitted' or (actor is not null and not is_counterparty) then
        raise exception 'Only the counterparty may accept or challenge submitted evidence.';
      end if;
    elsif new.status in ('withdrawn', 'replaced') then
      if old.status not in ('submitted', 'challenged')
         or (actor is not null and actor <> old.submitted_by) then
        raise exception 'Only the submitter may withdraw or replace open evidence.';
      end if;
      new.public_visibility := 'private';
      new.public_title := '';
      new.public_summary := '';
      new.redaction_status := 'withheld';
      new.public_url := '';
      new.public_storage_path := '';
      new.public_original_filename := '';
      new.public_mime_type := '';
      new.public_redaction_note := '';
      new.public_published_at := null;
    else
      raise exception 'Unsupported evidence status transition.';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.guard_core_exit_request_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  is_participant boolean;
begin
  select exists (
    select 1 from public.agreements a
    where a.id = coalesce(new.agreement_id, old.agreement_id)
      and actor in (a.proposer_id, a.responder_id)
      and a.lifecycle_status not in ('completed', 'cancelled', 'expired')
  ) into is_participant;
  if actor is not null and not is_participant then
    raise exception 'Only an active agreement participant may use the exit workflow.';
  end if;

  if tg_op = 'INSERT' then
    if actor is not null and new.requested_by <> actor then
      raise exception 'The exit requester must be the signed-in participant.';
    end if;
    if new.request_type = 'unilateral_exit' and new.status <> 'executed' then
      raise exception 'A unilateral exit executes immediately.';
    end if;
    if new.request_type = 'mutual_cancel' and new.status <> 'pending' then
      raise exception 'A mutual cancellation begins pending.';
    end if;
    return new;
  end if;

  if new.agreement_id <> old.agreement_id
     or new.requested_by <> old.requested_by
     or new.request_type <> old.request_type
     or new.reason <> old.reason
     or new.created_at <> old.created_at then
    raise exception 'Exit request source data is immutable.';
  end if;
  if old.status <> 'pending' or new.status not in ('accepted', 'declined') then
    raise exception 'Only pending mutual cancellation requests may be decided.';
  end if;
  if actor is not null and actor = old.requested_by then
    raise exception 'The requester cannot decide their own cancellation request.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_core_offer_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  internal_write boolean := coalesce(current_setting('app.core_trade_internal', true), '') = '1';
  terms_changed boolean := false;
begin
  if actor is not null and not internal_write then
    if new.owner_id <> actor then
      raise exception 'Offers may be changed only by their owner.';
    end if;
    if tg_op = 'INSERT' then
      if new.mode::text <> 'pledge'
         or new.payment_interval_value is not null
         or new.payment_interval_unit is not null then
        raise exception 'The self-service launch route supports non-financial pledge offers only.';
      end if;
    elsif old.mode::text = 'pledge' then
      if new.mode::text <> 'pledge'
         or new.payment_interval_value is not null
         or new.payment_interval_unit is not null then
        raise exception 'The self-service launch route does not support money movement.';
      end if;
    end if;
  end if;

  if tg_op = 'UPDATE' then
    if new.owner_id <> old.owner_id then
      raise exception 'Offer ownership is immutable.';
    end if;
    if old.workflow_status in ('closed', 'deleted')
       and new.workflow_status not in ('closed', 'deleted')
       and actor is not null then
      raise exception 'Closed or deleted offers cannot be reopened.';
    end if;

    terms_changed :=
      new.offered_cause is distinct from old.offered_cause or
      new.requested_cause is distinct from old.requested_cause or
      new.offer_action is distinct from old.offer_action or
      new.request_action is distinct from old.request_action or
      new.verification is distinct from old.verification or
      new.duration is distinct from old.duration or
      new.no_trade_baseline is distinct from old.no_trade_baseline or
      new.start_date is distinct from old.start_date or
      new.exit_conditions is distinct from old.exit_conditions or
      new.maximum_burden is distinct from old.maximum_burden or
      new.privacy_scope is distinct from old.privacy_scope or
      new.evidence_due_date is distinct from old.evidence_due_date;

    if actor is not null and not internal_write and old.mode::text <> 'pledge' then
      if terms_changed
         or new.mode is distinct from old.mode
         or new.payment_interval_value is distinct from old.payment_interval_value
         or new.payment_interval_unit is distinct from old.payment_interval_unit then
        raise exception 'Legacy financial offers are read-only except for pausing or closing them.';
      end if;
    end if;
    if actor is not null and old.workflow_status = 'published' and terms_changed then
      raise exception 'Pause a published offer before changing its terms.';
    end if;
    if terms_changed and new.terms_version <= old.terms_version then
      raise exception 'Material offer changes must increment terms_version.';
    end if;
  end if;

  if new.workflow_status = 'published' then
    if new.status::text <> 'open' then
      raise exception 'Published offers must be open.';
    end if;
    if btrim(coalesce(new.offered_cause, '')) = ''
       or btrim(coalesce(new.requested_cause, '')) = ''
       or btrim(coalesce(new.offer_action, '')) = ''
       or btrim(coalesce(new.request_action, '')) = ''
       or btrim(coalesce(new.verification, '')) = ''
       or btrim(coalesce(new.duration, '')) = ''
       or btrim(coalesce(new.no_trade_baseline, '')) = ''
       or btrim(coalesce(new.exit_conditions, '')) = ''
       or btrim(coalesce(new.maximum_burden, '')) = ''
       or btrim(coalesce(new.privacy_scope, '')) = '' then
      raise exception 'Published offers require complete bounded terms.';
    end if;
    if concat_ws(' ', new.offered_cause, new.requested_cause, new.offer_action,
                 new.request_action, new.verification, new.duration,
                 new.no_trade_baseline, new.exit_conditions,
                 new.maximum_burden, new.privacy_scope) like '%[Replace:%' then
      raise exception 'Published offers cannot contain unresolved template prompts.';
    end if;
    new.submitted_at := coalesce(new.submitted_at, now());
    new.published_at := coalesce(new.published_at, now());
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_core_thread_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
begin
  if actor is not null and actor not in (new.participant_a, new.participant_b) then
    raise exception 'Only thread participants may change the thread.';
  end if;
  if tg_op = 'UPDATE' then
    if new.offer_id <> old.offer_id
       or new.participant_a <> old.participant_a
       or new.participant_b <> old.participant_b
       or new.invitation_id is distinct from old.invitation_id then
      raise exception 'Thread participants, offer, and invitation are immutable.';
    end if;
    if new.agreement_id is distinct from old.agreement_id
       and coalesce(current_setting('app.core_trade_linking_agreement', true), '') <> '1' then
      raise exception 'Agreement links may be added only by the atomic acceptance workflow.';
    end if;
    if old.status = 'closed' and new.status <> 'closed' then
      raise exception 'Closed threads cannot be reopened.';
    end if;
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_financial_attachment_against_trade() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  target_offer_id uuid := new.offer_id;
  attachment_is_active boolean := true;
begin
  if tg_table_name = 'performance_bonds' then
    attachment_is_active := new.enabled is true
      and new.status not in ('not_enabled', 'cancelled', 'expired', 'refunded');
  end if;
  if not attachment_is_active then
    return new;
  end if;

  perform 1
  from public.offers
  where id = target_offer_id
  for update;

  if exists (
    select 1
    from public.trade_threads t
    where t.offer_id = target_offer_id
      and t.status <> 'closed'
  ) or exists (
    select 1
    from public.agreements a
    where a.offer_id = target_offer_id
      and a.lifecycle_status not in ('cancelled', 'expired')
  ) or exists (
    select 1
    from public.trade_invitations i
    where i.offer_id = target_offer_id
      and i.status in ('accepted', 'countered', 'responded')
  ) then
    raise exception 'Financial attachments cannot be added after a trade negotiation begins.';
  end if;

  perform moral_trade_private.revoke_offer_invitations(
    target_offer_id,
    'A financial attachment was added to the offer.'
  );
  return new;
end;
$$;



CREATE FUNCTION public.guard_trade_donation_pool_bundle_manifest() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Pooled-settlement bundles are retained as an audit record.';
  end if;
  if new.environment <> old.environment
     or new.provider <> old.provider
     or new.target_id <> old.target_id
     or new.target_name <> old.target_name
     or new.nonprofit_slug <> old.nonprofit_slug
     or new.nonprofit_ein <> old.nonprofit_ein
     or new.amount_cents <> old.amount_cents
     or new.currency <> old.currency
     or new.frequency <> old.frequency
     or new.manifest <> old.manifest
     or new.manifest_hash <> old.manifest_hash
     or new.frozen_at <> old.frozen_at
     or new.created_at <> old.created_at then
    raise exception 'Pooled-settlement bundle manifests are immutable.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_trade_donation_pool_ledger_journal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Pooled-settlement ledger journals are immutable.';
  end if;
  if old.status = 'posted' then
    raise exception 'Posted pooled-settlement ledger journals are immutable.';
  end if;
  if new.event_key <> old.event_key
     or new.journal_type <> old.journal_type
     or new.obligation_id is distinct from old.obligation_id
     or new.bundle_id is distinct from old.bundle_id
     or new.currency <> old.currency
     or new.description <> old.description
     or new.created_at <> old.created_at
     or new.status <> 'posted'
     or new.posted_at is null then
    raise exception 'A draft pooled-settlement journal may only transition once to posted.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.guard_trade_donation_pool_obligation_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Pooled-settlement obligations are retained as an audit record.';
  end if;
  if new.donation_term_id <> old.donation_term_id
     or new.agreement_id <> old.agreement_id
     or new.agreement_version_id <> old.agreement_version_id
     or new.payer_user_id <> old.payer_user_id
     or new.environment <> old.environment
     or new.provider <> old.provider
     or new.target_id <> old.target_id
     or new.target_name <> old.target_name
     or new.nonprofit_slug <> old.nonprofit_slug
     or new.nonprofit_ein <> old.nonprofit_ein
     or new.amount_cents <> old.amount_cents
     or new.currency <> old.currency
     or new.frequency <> old.frequency
     or new.condition_hash <> old.condition_hash
     or new.stripe_livemode <> old.stripe_livemode
     or new.disclosure_version <> old.disclosure_version
     or new.disclosures_accepted_at <> old.disclosures_accepted_at
     or new.created_at <> old.created_at then
    raise exception 'Pooled-settlement obligation terms are immutable.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.handle_agreement_rating_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.refresh_profile_rating_summary(new.rated_user_id);
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform public.refresh_profile_rating_summary(old.rated_user_id);
    return old;
  end if;

  if old.rated_user_id is distinct from new.rated_user_id then
    perform public.refresh_profile_rating_summary(old.rated_user_id);
  end if;

  perform public.refresh_profile_rating_summary(new.rated_user_id);
  return new;
end;
$$;



CREATE FUNCTION public.handle_auth_profile_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  insert into public.profiles (id, email, display_name, city, region, bio)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1)),
    nullif(new.raw_user_meta_data ->> 'city', ''),
    nullif(new.raw_user_meta_data ->> 'region', ''),
    coalesce(new.raw_user_meta_data ->> 'bio', '')
  )
  on conflict (id) do update
    set email = excluded.email,
        display_name = coalesce(excluded.display_name, public.profiles.display_name),
        city = coalesce(excluded.city, public.profiles.city),
        region = coalesce(excluded.region, public.profiles.region),
        bio = case
          when excluded.bio <> '' then excluded.bio
          else public.profiles.bio
        end;

  return new;
end;
$$;



CREATE FUNCTION public.handle_comment_vote_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  target_author_id uuid;
  karma_delta integer;
begin
  if tg_op = 'INSERT' then
    select author_id into target_author_id
    from public.offer_comments
    where id = new.comment_id;

    karma_delta := new.value;
  elsif tg_op = 'UPDATE' then
    select author_id into target_author_id
    from public.offer_comments
    where id = new.comment_id;

    karma_delta := new.value - old.value;
  else
    select author_id into target_author_id
    from public.offer_comments
    where id = old.comment_id;

    karma_delta := -old.value;
  end if;

  if target_author_id is not null and karma_delta <> 0 then
    update public.profiles
    set karma = greatest(karma + karma_delta, 0)
    where id = target_author_id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.handle_completed_agreement_credibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  offer_category text;
begin
  if new.status <> 'completed'::public.agreement_status then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status is not distinct from new.status then
    return new;
  end if;

  select public.credibility_category_for_offer_mode(offer_record.mode)
    into offer_category
    from public.offers offer_record
    where offer_record.id = new.offer_id;

    offer_category := coalesce(offer_category, 'other');

    insert into public.credibility_events (
      profile_id, agreement_id, counterparty_id, role, category, dimension,
      outcome, evidence_quality, source_type, source_id, reason_code, occurred_at
    )
    values
      (
        new.proposer_id, new.id, new.responder_id, 'committer', offer_category, 'fulfilment',
        1, 'platform_verified', 'agreement_transition', new.id::text || ':proposer:completed',
        'agreement_completed', coalesce(new.updated_at, now())
      ),
      (
        new.responder_id, new.id, new.proposer_id, 'counterparty', offer_category, 'fulfilment',
        1, 'bilateral', 'agreement_transition', new.id::text || ':responder:completed',
        'agreement_completed', coalesce(new.updated_at, now())
      )
    on conflict do nothing;

  return new;
end;
$$;



CREATE FUNCTION public.handle_credibility_event_refresh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_profile_credibility(old.profile_id);
    return old;
  end if;

  perform public.refresh_profile_credibility(new.profile_id);
  if tg_op = 'UPDATE' and old.profile_id <> new.profile_id then
    perform public.refresh_profile_credibility(old.profile_id);
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.handle_credibility_restriction_refresh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_profile_credibility_status(old.profile_id);
    return old;
  end if;

  perform public.refresh_profile_credibility_status(new.profile_id);
  if tg_op = 'UPDATE' and old.profile_id <> new.profile_id then
    perform public.refresh_profile_credibility_status(old.profile_id);
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.handle_offer_comment_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.profiles
    set
      comment_count = comment_count + 1,
      karma = karma + 1
    where id = new.author_id;

    return new;
  end if;

  update public.profiles
  set
    comment_count = greatest(comment_count - 1, 0),
    karma = greatest(karma - 1, 0)
  where id = old.author_id;

  return old;
end;
$$;



CREATE FUNCTION public.handle_offer_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'open' then
      update public.profiles
      set offer_count = offer_count + 1
      where id = new.owner_id;
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status = 'open' then
      update public.profiles
      set offer_count = greatest(offer_count - 1, 0)
      where id = old.owner_id;
    end if;

    return old;
  end if;

  if old.owner_id = new.owner_id then
    if old.status <> 'open' and new.status = 'open' then
      update public.profiles
      set offer_count = offer_count + 1
      where id = new.owner_id;
    elsif old.status = 'open' and new.status <> 'open' then
      update public.profiles
      set offer_count = greatest(offer_count - 1, 0)
      where id = new.owner_id;
    end if;
  else
    if old.status = 'open' then
      update public.profiles
      set offer_count = greatest(offer_count - 1, 0)
      where id = old.owner_id;
    end if;

    if new.status = 'open' then
      update public.profiles
      set offer_count = offer_count + 1
      where id = new.owner_id;
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.handle_paid_agreement_payment_credibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  offer_category text;
begin
  if new.status <> 'paid' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status is not distinct from new.status then
    return new;
  end if;

  select public.credibility_category_for_offer_mode(offer_record.mode)
    into offer_category
    from public.agreements agreement_record
    join public.offers offer_record on offer_record.id = agreement_record.offer_id
    where agreement_record.id = new.agreement_id;

    insert into public.credibility_events (
      profile_id, agreement_id, counterparty_id, role, category, dimension,
      outcome, evidence_quality, stake_units, source_type, source_id, reason_code, occurred_at
    )
    values (
      new.payer_id, new.agreement_id, new.payee_id, 'funder', coalesce(offer_category, 'paid_action'), 'settlement',
      1, 'platform_verified', new.amount_cents::numeric / 100::numeric,
      'payment_transition', new.id::text || ':paid', 'payment_settled', coalesce(new.paid_at, new.updated_at, now())
    )
    on conflict do nothing;

  return new;
end;
$$;



CREATE FUNCTION public.handle_user_follow_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.profiles
    set following_count = following_count + 1
    where id = new.follower_id;

    update public.profiles
    set follower_count = follower_count + 1
    where id = new.followed_id;

    return new;
  end if;

  update public.profiles
  set following_count = greatest(following_count - 1, 0)
  where id = old.follower_id;

  update public.profiles
  set follower_count = greatest(follower_count - 1, 0)
  where id = old.followed_id;

  return old;
end;
$$;



CREATE FUNCTION public.initialize_public_trade_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.public_title := btrim(coalesce(new.public_title, ''));
  new.public_summary := btrim(coalesce(new.public_summary, ''));
  new.public_url := btrim(coalesce(new.public_url, ''));
  new.public_storage_path := btrim(coalesce(new.public_storage_path, ''));
  new.public_original_filename := btrim(coalesce(new.public_original_filename, ''));
  new.public_mime_type := btrim(coalesce(new.public_mime_type, ''));
  new.public_redaction_note := btrim(coalesce(new.public_redaction_note, ''));

  if coalesce(new.public_visibility, 'private') <> 'public' then
    new.public_visibility := 'private';
    new.redaction_status := 'withheld';
    new.public_url := '';
    new.public_storage_path := '';
    new.public_original_filename := '';
    new.public_mime_type := '';
    new.public_redaction_note := '';
    new.public_published_at := null;
    return new;
  end if;

  if new.status in ('withdrawn', 'replaced') then
    raise exception 'Withdrawn or replaced evidence cannot be published.';
  end if;

  new.public_published_at := coalesce(new.public_published_at, now());
  new.public_title := coalesce(
    nullif(new.public_title, ''),
    case new.evidence_type
      when 'attestation' then 'Participant attestation'
      when 'link' then 'External evidence link'
      else 'Published evidence file'
    end
  );
  new.public_summary := coalesce(
    nullif(new.public_summary, ''),
    case
      when new.evidence_type = 'attestation' then nullif(btrim(new.attestation), '')
      else null
    end,
    'A participant explicitly published this redacted evidence record under the frozen agreement.'
  );

  if new.evidence_type = 'file' then
    if new.public_storage_path = '' then
      raise exception 'A separate redacted public file is required for file publication.';
    end if;
    if new.public_storage_path = coalesce(new.storage_path, '') then
      raise exception 'The private source file cannot be reused as the public evidence copy.';
    end if;
    if new.redaction_status not in ('redacted', 'not_required') then
      raise exception 'A public evidence file must be marked redacted or not_required.';
    end if;
    new.public_url := '';
  elsif new.evidence_type = 'link' then
    if new.public_url !~* '^https?://' then
      raise exception 'A public evidence link must use http or https.';
    end if;
    new.public_storage_path := '';
    new.redaction_status := 'not_required';
  else
    new.public_url := '';
    new.public_storage_path := '';
    new.redaction_status := 'not_required';
  end if;

  new.public_redaction_note := coalesce(
    nullif(new.public_redaction_note, ''),
    'The submitting participant explicitly published this redacted record. Publication is not independent verification.'
  );
  return new;
end;
$$;



CREATE FUNCTION public.list_public_moral_trade_evidence_v1(p_limit integer DEFAULT 24, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with eligible as (
    select a.id, a.public_evidence_updated_at
    from public.agreements a
    where a.public_evidence_enabled is true
      and exists (
        select 1
        from public.trade_evidence_items e
        where e.agreement_id = a.id
          and e.public_visibility = 'public'
          and e.public_published_at is not null
          and e.redaction_status <> 'withheld'
      )
  ),
  evidence_page as (
    select eligible.id, eligible.public_evidence_updated_at
    from eligible
    order by eligible.public_evidence_updated_at desc, eligible.id desc
    limit least(greatest(coalesce(p_limit, 24), 1), 50)
    offset least(greatest(coalesce(p_offset, 0), 0), 100000)
  )
  select jsonb_build_object(
    'totalRecords', (select count(*) from eligible),
    'records', coalesce(
      (
        select jsonb_agg(
          public.get_public_moral_trade_evidence_v1(evidence_page.id)
          order by evidence_page.public_evidence_updated_at desc, evidence_page.id desc
        )
        from evidence_page
      ),
      '[]'::jsonb
    )
  );
$$;



CREATE FUNCTION public.list_public_moral_trade_outcomes_v2(p_limit integer DEFAULT 24, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with eligible as (
    select
      milestone.action_category,
      case
        when payout.status in ('confirmed', 'adjudicated_paid') then 'paid'
        when payout.status = 'still_due' then 'payment_due'
        when payout.status in ('reported_paid', 'corrected_reported')
          then 'payment_reported'
        when payout.status in (
          'payment_review_pending',
          'correction_due',
          'payment_decision_pending',
          'payment_appeal_pending'
        ) then 'payment_review'
        when review.outcome = 'rejected' then 'evidence_due'
        else 'graded'
      end as lifecycle_status,
      review.confidence_band,
      round(review.completion_units / milestone.units_total, 6)
        as completion_fraction,
      (review.payout_basis_points::numeric / 100)::numeric(7, 2)
        as payout_percentage,
      review.finalized_at::date as outcome_date,
      review.finalized_at,
      milestone.id
    from public.trade_agreement_milestones milestone
    join public.trade_milestone_reviews review
      on review.id = milestone.final_review_id
     and review.is_final
     and review.finalized_at is not null
    join public.trade_milestone_payouts payout
      on payout.milestone_id = milestone.id
     and payout.review_id = review.id
     and payout.is_final
    where milestone.status in ('graded', 'paid', 'evidence_due')
       or (
         milestone.status = 'replacement_due'
         and milestone.replacement_deadline_at <= now()
       )
  ),
  outcome_page as (
    select *
    from eligible
    order by finalized_at desc, id desc
    limit least(greatest(coalesce(p_limit, 24), 1), 50)
    offset least(greatest(coalesce(p_offset, 0), 0), 100000)
  )
  select jsonb_build_object(
    'totalRecords', (select count(*) from eligible),
    'records', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'actionCategory', outcome_page.action_category,
            'lifecycleStatus', outcome_page.lifecycle_status,
            'confidenceBand', outcome_page.confidence_band,
            'completionFraction', outcome_page.completion_fraction,
            'payoutPercentage', outcome_page.payout_percentage,
            'date', outcome_page.outcome_date
          )
          order by outcome_page.finalized_at desc, outcome_page.id desc
        )
        from outcome_page
      ),
      '[]'::jsonb
    )
  );
$$;



CREATE FUNCTION public.list_trade_reviewer_candidates_v1() RETURNS TABLE(profile_id uuid, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    grant_row.profile_id,
    coalesce(nullif(btrim(profile.display_name), ''), 'Neutral reviewer') as display_name
  from public.trade_review_role_grants grant_row
  join public.profiles profile on profile.id = grant_row.profile_id
  where auth.uid() is not null
    and grant_row.role = 'reviewer'
    and grant_row.active
    and grant_row.revoked_at is null
    and grant_row.profile_id <> auth.uid()
  order by lower(coalesce(profile.display_name, '')), grant_row.profile_id
  limit 100;
$$;



CREATE FUNCTION public.mark_trade_donation_pool_component_stale() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if coalesce(current_setting('app.core_trade_internal', true), '') = '1' then
    return new;
  end if;

  if new.current_version_id is distinct from old.current_version_id
     or (
       old.lifecycle_status = 'awaiting_donation'
       and new.lifecycle_status <> 'awaiting_donation'
     ) then
    update public.trade_donation_pool_obligations
    set
      status = 'needs_review',
      failure_code = 'agreement_component_changed',
      failure_message = 'The agreement version or lifecycle changed after pooled funding began.'
    where agreement_id = new.id
      and status in ('checkout_started', 'funded', 'bundled', 'refund_pending');

    update public.trade_donation_pool_bundles b
    set
      status = 'needs_review',
      failure_code = 'component_changed_after_bundle',
      failure_message = 'A component agreement changed after the bundle became immutable.'
    where exists (
      select 1
      from public.trade_donation_pool_bundle_items i
      where i.bundle_id = b.id and i.agreement_id = new.id
    )
      and b.status in ('frozen', 'checkout_started');
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_create_pool_terms_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  accepted_at timestamptz;
begin
  select first_accepted_pledge_at
  into accepted_at
  from public.mpgf_pool_proposals
  where id = old.pool_proposal_id;

  if accepted_at is not null then
    raise exception using
      errcode = '23514',
      message = 'Create-interface pool terms are immutable after the first accepted pledge.';
  end if;

  if old.review_status = 'approved' then
    raise exception using
      errcode = '23514',
      message = 'Approved Create-interface pool terms are immutable.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_create_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_create_submit_service(p_actor_id uuid, p_submission_key text, p_submission_kind text, p_source_payload jsonb, p_payload_hash text, p_cause_area text, p_request_kind text, p_requested_action text, p_offered_summary text, p_offered_terms jsonb, p_pool_terms jsonb, p_target_fields jsonb) RETURNS TABLE(submission_id uuid, target_type text, target_id uuid, submission_status text, canonical_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  actor_id uuid := p_actor_id;
  actor_alias text;
  existing_submission public.moral_trade_create_submissions%rowtype;
  new_submission_id uuid := gen_random_uuid();
  new_target_id uuid;
  canonical text := '/create/submissions/' || new_submission_id::text;
  mode_value public.offer_mode;
  first_threshold_cents bigint;
  final_threshold_cents bigint;
  deadline_value timestamptz;
  progress_value public.mpgf_progress_visibility;
  threshold_milestones jsonb;
begin
  if actor_id is null then
    raise exception using errcode = '42501', message = 'A valid authenticated actor is required to submit a Create record.';
  end if;

  if p_submission_kind not in ('pledge_swap', 'donation_redirect', 'pool_create', 'existing_pool_contribution') then
    raise exception using errcode = '22023', message = 'Unsupported Create submission kind.';
  end if;
  if p_request_kind not in ('commitment', 'skill', 'fund') then
    raise exception using errcode = '22023', message = 'Unsupported request kind.';
  end if;
  if nullif(btrim(p_submission_key), '') is null
     or length(p_submission_key) > 120
     or p_submission_key !~ '^[A-Za-z0-9:_-]+$' then
    raise exception using errcode = '22023', message = 'Submission key is invalid.';
  end if;
  if p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Payload hash is invalid.';
  end if;
  if jsonb_typeof(p_source_payload) <> 'object'
     or octet_length(p_source_payload::text) > 180000 then
    raise exception using errcode = '22023', message = 'Source payload is invalid or too large.';
  end if;
  if jsonb_typeof(p_offered_terms) <> 'array' then
    raise exception using errcode = '22023', message = 'Contribution terms must be an array.';
  end if;
  if nullif(btrim(p_cause_area), '') is null or nullif(btrim(p_requested_action), '') is null then
    raise exception using errcode = '22023', message = 'Cause and requested action are required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(actor_id::text || ':create-key:' || p_submission_key, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended(actor_id::text || ':create-hash:' || p_payload_hash, 0)
  );

  select * into existing_submission
  from public.moral_trade_create_submissions
  where owner_profile_id = actor_id
    and submission_key = p_submission_key
  limit 1;

  if existing_submission.id is not null then
    if existing_submission.source_payload_hash <> p_payload_hash
       or existing_submission.source_payload_json is distinct from p_source_payload then
      raise exception using
        errcode = '23514',
        message = 'This Create submission key was already used for different terms.';
    end if;

    return query select
      existing_submission.id,
      existing_submission.target_type,
      existing_submission.target_id,
      existing_submission.status,
      existing_submission.canonical_path;
    return;
  end if;

  select * into existing_submission
  from public.moral_trade_create_submissions
  where owner_profile_id = actor_id
    and source_payload_hash = p_payload_hash
  limit 1;

  if existing_submission.id is not null then
    if existing_submission.source_payload_json is distinct from p_source_payload then
      raise exception using
        errcode = '23514',
        message = 'A Create payload hash collision was detected.';
    end if;

    return query select
      existing_submission.id,
      existing_submission.target_type,
      existing_submission.target_id,
      existing_submission.status,
      existing_submission.canonical_path;
    return;
  end if;

  if p_source_payload ->> 'interfaceVersion' <> 'moral_trade_create_v1'
     or p_source_payload ->> 'submissionKey' <> p_submission_key
     or btrim(coalesce(p_source_payload ->> 'cause', '')) <> btrim(p_cause_area)
     or p_source_payload ->> 'requestKind' <> p_request_kind
     or btrim(coalesce(p_source_payload ->> 'requestAction', '')) <> btrim(p_requested_action)
     or coalesce(p_source_payload -> 'offers', '[]'::jsonb) is distinct from p_offered_terms then
    raise exception using
      errcode = '23514',
      message = 'The Create payload does not match its validated persistence fields.';
  end if;

  if jsonb_typeof(p_target_fields) <> 'object' then
    raise exception using errcode = '22023', message = 'Create target fields must be an object.';
  end if;
  if p_submission_kind = 'pool_create' and jsonb_typeof(p_pool_terms) <> 'object' then
    raise exception using errcode = '22023', message = 'Direct pool submissions require validated pool terms.';
  end if;
  if p_submission_kind <> 'pool_create' and p_pool_terms is not null then
    raise exception using errcode = '22023', message = 'Only direct pool submissions may include pool terms.';
  end if;

  select coalesce(nullif(btrim(display_name), ''), nullif(btrim(email), ''), 'Moral Trade participant')
  into actor_alias
  from public.profiles
  where id = actor_id;
  if actor_alias is null then
    raise exception using errcode = '23503', message = 'A Moral Trade profile is required before submission.';
  end if;

  insert into public.moral_trade_create_submissions (
    id,
    owner_profile_id,
    submission_key,
    interface_version,
    submission_kind,
    cause_area,
    request_kind,
    requested_action,
    offered_terms_json,
    pool_terms_json,
    source_payload_json,
    source_payload_hash,
    status,
    canonical_path
  ) values (
    new_submission_id,
    actor_id,
    p_submission_key,
    'moral_trade_create_v1',
    p_submission_kind,
    btrim(p_cause_area),
    p_request_kind,
    btrim(p_requested_action),
    p_offered_terms,
    p_pool_terms,
    p_source_payload,
    p_payload_hash,
    'pending_review',
    canonical
  );

  if p_submission_kind in ('pledge_swap', 'donation_redirect', 'existing_pool_contribution') then
    mode_value := case when p_submission_kind = 'donation_redirect' then 'offset' else 'pledge' end;
    new_target_id := gen_random_uuid();

    insert into public.offers (
      id,
      owner_id,
      owner_alias,
      mode,
      offered_cause,
      requested_cause,
      offer_action,
      request_action,
      compromise_cause,
      offer_impact,
      min_counterparty_impact,
      verification,
      duration,
      payment_interval_value,
      payment_interval_unit,
      trust_level,
      notes,
      discount_note,
      status,
      workflow_status,
      moderation_reason,
      submission_key,
      fingerprint,
      no_trade_baseline,
      exit_conditions,
      maximum_burden,
      privacy_scope,
      submitted_at,
      terms_version
    ) values (
      new_target_id,
      actor_id,
      actor_alias,
      mode_value,
      'Creator-defined contribution options',
      btrim(p_cause_area),
      left(btrim(p_offered_summary), 2000),
      btrim(p_requested_action),
      case when p_submission_kind = 'donation_redirect' then btrim(p_cause_area) else 'Not applicable' end,
      1,
      1,
      'Evidence terms must be agreed before any binding trade.',
      'As specified in the selected contribution option.',
      null,
      null,
      1,
      'Created through Moral Trade Create v1. Exact structured terms are stored in the linked Create submission.',
      '',
      'paused',
      'pending_review',
      '',
      'create:' || p_submission_key,
      p_payload_hash,
      'If no proposal is accepted, neither party incurs an obligation.',
      'No commitment exists until both parties confirm final terms.',
      left(btrim(p_offered_summary), 2000),
      'Listing terms may become public after review; private negotiation and sensitive evidence remain private.',
      timezone('utc', now()),
      1
    );

    insert into public.moral_trade_create_offer_terms (
      offer_id,
      create_submission_id,
      request_kind,
      exact_requested_action,
      contribution_options_json,
      existing_pool_reference,
      existing_pool_amount_cents,
      existing_pool_currency
    ) values (
      new_target_id,
      new_submission_id,
      p_request_kind,
      btrim(p_requested_action),
      p_offered_terms,
      nullif(p_target_fields ->> 'existingPoolReference', ''),
      case
        when p_target_fields ? 'existingPoolAmountCents'
        then (p_target_fields ->> 'existingPoolAmountCents')::bigint
        else null
      end,
      nullif(p_target_fields ->> 'existingPoolCurrency', '')
    );

    if p_submission_kind = 'donation_redirect' then
      insert into public.moral_trade_donation_redirect_proposals (
        offer_id,
        create_submission_id,
        owner_profile_id,
        requested_redirect_terms,
        cause_area,
        contribution_options_json
      ) values (
        new_target_id,
        new_submission_id,
        actor_id,
        btrim(p_requested_action),
        btrim(p_cause_area),
        p_offered_terms
      );
    end if;

    update public.moral_trade_create_submissions
    set target_type = 'offer', target_id = new_target_id
    where id = new_submission_id;

    return query select new_submission_id, 'offer'::text, new_target_id, 'pending_review'::text, canonical;
    return;
  end if;

  if p_submission_kind = 'pool_create' then
    if jsonb_typeof(p_pool_terms) <> 'object'
       or jsonb_typeof(p_pool_terms -> 'thresholdAmountsCents') <> 'array'
       or jsonb_array_length(p_pool_terms -> 'thresholdAmountsCents') not between 1 and 10 then
      raise exception using errcode = '22023', message = 'Direct pool terms require one to ten thresholds.';
    end if;

    first_threshold_cents := (p_pool_terms -> 'thresholdAmountsCents' ->> 0)::bigint;
    final_threshold_cents := (
      p_pool_terms -> 'thresholdAmountsCents' ->>
      (jsonb_array_length(p_pool_terms -> 'thresholdAmountsCents') - 1)
    )::bigint;
    deadline_value := (p_pool_terms ->> 'deadlineAt')::timestamptz;
    progress_value := (p_pool_terms ->> 'progressVisibility')::public.mpgf_progress_visibility;

    if first_threshold_cents <= 0 or final_threshold_cents < first_threshold_cents then
      raise exception using errcode = '22023', message = 'Pool threshold amounts are invalid.';
    end if;
    if deadline_value <= timezone('utc', now()) + interval '30 minutes' then
      raise exception using errcode = '22023', message = 'Pool deadline must be at least 30 minutes in the future.';
    end if;

    select jsonb_agg(
      jsonb_build_object(
        'label', format('Cumulative threshold %s', ordinality),
        'amountCents', value::bigint
      ) order by ordinality
    )
    into threshold_milestones
    from jsonb_array_elements_text(p_pool_terms -> 'thresholdAmountsCents') with ordinality;

    new_target_id := gen_random_uuid();
    insert into public.mpgf_pool_proposals (
      id,
      proposer_id,
      title,
      problem,
      intervention,
      moral_public_good_rationale,
      proposed_recipient_name,
      status,
      summary,
      cause_area,
      requested_maximum_funding_cents,
      minimum_viable_funding_cents,
      outcome_units_summary,
      expected_effect_vs_funding,
      timeline,
      milestones_json,
      risks_json,
      misuse_pathways,
      implementing_team_json,
      submitted_at,
      public_goods_destination_type,
      public_goods_destination_ref,
      public_goods_threshold_amount_cents,
      public_goods_threshold_supporters,
      public_goods_deadline_at,
      public_goods_verification_method,
      public_goods_baseline_rule,
      public_goods_exit_rule,
      public_goods_base_match_ratio,
      public_goods_qf_enabled,
      public_goods_qf_cap_multiple,
      public_goods_payout_method,
      threshold_visibility,
      progress_visibility,
      public_goods_failure_bonus_enabled,
      public_goods_success_premium_included_in_net_threshold
    ) values (
      new_target_id,
      actor_id,
      left(btrim(p_requested_action), 240),
      'The creator proposes funding the named moral public good under the exact threshold terms stored with this submission.',
      btrim(p_requested_action),
      'The creator selected ' || btrim(p_cause_area) || ' as the cause to improve. No additional impact claim is inferred.',
      null,
      'submitted',
      'A reviewable multi-threshold moral-public-good pool submitted through Moral Trade Create v1.',
      btrim(p_cause_area),
      final_threshold_cents,
      first_threshold_cents,
      'Unit: one cumulatively cleared funding threshold. Exact amounts are stored in the linked Create terms.',
      'No impact estimate is invented by the adapter. Funding, implementation, and any failure-bonus reserve remain subject to review.',
      'Pledge deadline: ' || deadline_value::text,
      coalesce(threshold_milestones, '[]'::jsonb),
      '[{"risk":"No live-money capability, reserve backing, recipient verification, or payout is authorized by submission alone."}]'::jsonb,
      'The pool remains pending review. Unsupported or unsafe recipient, payout, formula, or activation terms must be revised or rejected before pledges open.',
      jsonb_build_object('summary', 'Implementing team and recipient to be confirmed during review.'),
      timezone('utc', now()),
      'external_charity',
      null,
      first_threshold_cents,
      null,
      deadline_value,
      'Moral Trade ledger plus recipient and implementation evidence required before clearance.',
      'Without an approved and cleared pool, no contribution is charged and no public good is treated as funded.',
      'No pledge is binding before review; post-acceptance exits and settlement follow the approved pool terms.',
      0,
      false,
      1.5,
      'external_handoff',
      'public_exact',
      progress_value,
      false,
      false
    );

    insert into public.moral_trade_create_pool_terms (
      pool_proposal_id,
      create_submission_id,
      threshold_amounts_cents_json,
      deadline_at,
      failure_bonus_base_type,
      failure_bonus_base_terms_json,
      failure_bonus_timing_mode,
      failure_bonus_timing_terms_json,
      formula_source,
      formula_ast_json,
      formula_language_version,
      formula_hash,
      formula_variables_json,
      continuation_mode,
      threshold_visibility,
      progress_visibility,
      moral_trade_failure_bonus_share_bps,
      additional_activation_rule,
      reserve_quote_status,
      review_status
    ) values (
      new_target_id,
      new_submission_id,
      p_pool_terms -> 'thresholdAmountsCents',
      deadline_value,
      p_pool_terms ->> 'failureBonusType',
      p_pool_terms -> 'failureBonusTerms',
      p_pool_terms ->> 'failureTimingMode',
      p_pool_terms -> 'failureTimingTerms',
      p_pool_terms -> 'formula' ->> 'source',
      p_pool_terms -> 'formula' -> 'ast',
      p_pool_terms -> 'formula' ->> 'languageVersion',
      p_pool_terms -> 'formula' ->> 'hash',
      p_pool_terms -> 'formula' -> 'variables',
      p_pool_terms ->> 'continuation',
      'public_exact',
      progress_value,
      (p_pool_terms ->> 'moralTradeBonusShareBps')::integer,
      coalesce(p_pool_terms ->> 'activationRule', ''),
      case when p_pool_terms ->> 'failureBonusType' = 'none' then 'not_applicable' else 'pending_underwriting' end,
      'pending_review'
    );

    update public.moral_trade_create_submissions
    set target_type = 'mpgf_pool_proposal', target_id = new_target_id
    where id = new_submission_id;

    return query select new_submission_id, 'mpgf_pool_proposal'::text, new_target_id, 'pending_review'::text, canonical;
    return;
  end if;

  raise exception using errcode = '22023', message = 'Unsupported Create submission kind.';
end;
$_$;



CREATE FUNCTION public.moral_trade_feed_create_deliver_service(p_reviewer_id uuid, p_derived_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  link_row public.moral_trade_feed_create_links%rowtype;
  derived_row public.offers%rowtype;
  source_row public.offers%rowtype;
  thread_row public.trade_threads%rowtype;
  proposal_row public.trade_counterproposals%rowtype;
  next_version integer;
  now_value timestamptz := timezone('utc', now());
  proposal_key text;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'service_role_required';
  end if;
  if p_reviewer_id is null or p_derived_offer_id is null then
    raise exception using errcode = '22023', message = 'Reviewer and derived offer are required.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('feed-create-delivery:' || p_derived_offer_id::text, 0));

  select * into link_row
  from public.moral_trade_feed_create_links
  where derived_offer_id = p_derived_offer_id
  for update;
  if link_row.id is null then
    raise exception using errcode = 'P0002', message = 'Feed-derived proposal link not found.';
  end if;

  if link_row.delivered_counterproposal_id is not null then
    return jsonb_build_object(
      'created', false,
      'threadId', link_row.delivered_thread_id,
      'counterproposalId', link_row.delivered_counterproposal_id
    );
  end if;

  select * into derived_row from public.offers where id = p_derived_offer_id for update;
  select * into source_row from public.offers where id = link_row.source_offer_id for update;

  if derived_row.id is null
     or derived_row.owner_id <> link_row.creator_profile_id
     or derived_row.mode::text <> 'pledge'
     or derived_row.workflow_status <> 'pending_review'
     or derived_row.status::text <> 'paused'
     or derived_row.published_at is not null
     or derived_row.deleted_at is not null then
    raise exception using errcode = '23514', message = 'The Feed-derived proposal is not awaiting operator review.';
  end if;

  if source_row.id is null
     or source_row.owner_id <> link_row.source_owner_profile_id
     or source_row.owner_id <> link_row.counterparty_profile_id
     or source_row.owner_id = link_row.creator_profile_id
     or source_row.mode::text <> 'pledge'
     or source_row.status::text <> 'open'
     or source_row.workflow_status <> 'published'
     or source_row.published_at is null
     or source_row.closed_at is not null
     or source_row.deleted_at is not null
     or source_row.terms_version <> link_row.source_terms_version then
    raise exception using errcode = '23514', message = 'The original Feed opportunity changed or closed. Review cannot deliver a stale counterproposal.';
  end if;

  if moral_trade_private.pair_is_blocked(link_row.creator_profile_id, link_row.source_owner_profile_id) then
    raise exception using errcode = '42501', message = 'This interaction is blocked.';
  end if;

  perform moral_trade_private.lock_pair(link_row.creator_profile_id, link_row.source_owner_profile_id);

  select * into thread_row
  from public.trade_threads
  where offer_id = source_row.id
    and status <> 'closed'
    and least(participant_a, participant_b) = least(link_row.creator_profile_id, link_row.source_owner_profile_id)
    and greatest(participant_a, participant_b) = greatest(link_row.creator_profile_id, link_row.source_owner_profile_id)
  order by created_at asc
  limit 1
  for update;

  if thread_row.id is null then
    insert into public.trade_threads(
      offer_id, participant_a, participant_b, status, last_message_at, created_at, updated_at
    ) values (
      source_row.id,
      source_row.owner_id,
      link_row.creator_profile_id,
      'active',
      now_value,
      now_value,
      now_value
    ) returning * into thread_row;
  end if;

  update public.trade_counterproposals
  set status = 'superseded', responded_at = now_value
  where thread_id = thread_row.id and status = 'proposed';

  select coalesce(max(version), 0) + 1 into next_version
  from public.trade_counterproposals
  where thread_id = thread_row.id;

  proposal_key := 'feed-create-private-delivery:' || link_row.id::text;

  insert into public.trade_counterproposals(
    thread_id,
    offer_id,
    proposer_id,
    version,
    status,
    proposed_action,
    requested_action,
    duration,
    start_date,
    evidence_rule,
    evidence_due_date,
    exit_conditions,
    maximum_burden,
    privacy_scope,
    no_trade_baseline,
    terms_hash,
    created_at,
    submission_key,
    milestone_terms
  ) values (
    thread_row.id,
    source_row.id,
    link_row.creator_profile_id,
    next_version,
    'proposed',
    derived_row.offer_action,
    derived_row.request_action,
    derived_row.duration,
    derived_row.start_date,
    derived_row.verification,
    derived_row.evidence_due_date,
    derived_row.exit_conditions,
    derived_row.maximum_burden,
    derived_row.privacy_scope,
    derived_row.no_trade_baseline,
    public.core_trade_terms_hash(
      derived_row.offer_action,
      derived_row.request_action,
      derived_row.duration,
      derived_row.start_date,
      derived_row.verification,
      derived_row.evidence_due_date,
      derived_row.exit_conditions,
      derived_row.maximum_burden,
      derived_row.privacy_scope,
      derived_row.no_trade_baseline
    ),
    now_value,
    proposal_key,
    '[]'::jsonb
  ) returning * into proposal_row;

  update public.trade_threads
  set last_message_at = now_value, updated_at = now_value
  where id = thread_row.id;

  perform set_config('app.feed_create_private_delivery', '1', true);
  update public.offers
  set
    status = 'closed',
    workflow_status = 'closed',
    moderation_reason = 'Approved and delivered privately as a source-bound counterproposal.',
    published_at = null,
    closed_at = now_value,
    updated_at = now_value
  where id = derived_row.id;
  perform set_config('app.feed_create_private_delivery', '', true);

  update public.moral_trade_feed_create_links
  set
    delivered_thread_id = thread_row.id,
    delivered_counterproposal_id = proposal_row.id,
    delivered_at = now_value,
    reviewed_by = p_reviewer_id,
    updated_at = now_value
  where id = link_row.id;

  insert into public.trade_review_events(offer_id, reviewer_id, action, reason, metadata)
  values (
    derived_row.id,
    p_reviewer_id,
    'approved_private_delivery',
    'Approved and delivered to the exact Feed counterparty without public publication.',
    jsonb_build_object(
      'sourceOfferId', source_row.id,
      'feedCreateLinkId', link_row.id,
      'threadId', thread_row.id,
      'counterproposalId', proposal_row.id,
      'sourceTermsVersion', link_row.source_terms_version
    )
  );

  insert into public.core_loop_events(profile_id, event_type, entity_type, entity_id, idempotency_key, metadata)
  values (
    link_row.creator_profile_id,
    'counterproposal_sent',
    'trade_counterproposal',
    proposal_row.id,
    'feed_create_counterproposal_sent:' || link_row.id::text,
    jsonb_build_object('source', 'feed_create_v1', 'sourceOfferId', source_row.id, 'threadId', thread_row.id)
  ) on conflict (idempotency_key) do nothing;

  insert into public.trade_notifications(user_id, notification_type, title, body, href, dedupe_key, created_at)
  values
    (
      source_row.owner_id,
      'counterproposal_received',
      'New counterproposal',
      'A participant responded to your published offer with reviewed private terms.',
      '/messages/' || thread_row.id::text,
      'feed_create_counterproposal_received:' || proposal_row.id::text || ':' || source_row.owner_id::text,
      now_value
    ),
    (
      link_row.creator_profile_id,
      'counterproposal_delivered',
      'Counterproposal delivered',
      'Operator review passed. Your proposal was delivered privately to the exact counterparty and was not published as a separate public offer.',
      '/messages/' || thread_row.id::text,
      'feed_create_counterproposal_delivered:' || proposal_row.id::text || ':' || link_row.creator_profile_id::text,
      now_value
    )
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'created', true,
    'threadId', thread_row.id,
    'counterproposalId', proposal_row.id,
    'sourceOfferId', source_row.id
  );
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_guard_offer_relation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  guarded_offer_id uuid;
begin
  guarded_offer_id := new.offer_id;
  if guarded_offer_id is not null and exists (
    select 1 from public.moral_trade_feed_create_links where derived_offer_id = guarded_offer_id
  ) then
    raise exception using errcode = '42501', message = 'Feed-derived counteroffers cannot create invitations, responses, threads, or agreements in Phase 1.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_guard_offer_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.moral_trade_feed_create_links%rowtype;
  source_row public.offers%rowtype;
begin
  select * into link_row
  from public.moral_trade_feed_create_links
  where derived_offer_id = old.id
  limit 1;
  if link_row.id is null then
    return new;
  end if;

  if new.owner_id is distinct from old.owner_id or new.mode::text <> 'pledge' then
    raise exception using errcode = '23514', message = 'A Feed-derived counteroffer cannot change its creator or trade mode.';
  end if;

  if current_setting('app.feed_create_private_delivery', true) = '1' then
    return new;
  end if;

  if new.workflow_status = 'published' or new.status::text = 'open' or new.published_at is not null then
    raise exception using errcode = '42501', message = 'Feed-derived counteroffers are delivered privately through review; they are never published as public inventory.';
  end if;

  if new.workflow_status = 'pending_review' then
    select * into source_row from public.offers where id = link_row.source_offer_id;
    if source_row.id is null
       or source_row.owner_id <> link_row.source_owner_profile_id
       or source_row.mode::text <> 'pledge'
       or source_row.status::text <> 'open'
       or source_row.workflow_status <> 'published'
       or source_row.closed_at is not null
       or source_row.deleted_at is not null
       or source_row.terms_version <> link_row.source_terms_version then
      raise exception using errcode = '23514', message = 'The original Feed offer changed or closed. This counteroffer cannot be resubmitted from the stale source revision.';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_record_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  link_row public.moral_trade_feed_create_links%rowtype;
begin
  if new.offer_id is null then
    return new;
  end if;
  if not (
    new.lifecycle_status = 'completed'
    or new.completion_state = 'reviewed_complete'
  ) then
    return new;
  end if;

  select * into link_row
  from public.moral_trade_feed_create_links
  where derived_offer_id = new.offer_id
  limit 1;
  if link_row.id is null then
    return new;
  end if;

  perform public.moral_trade_feed_create_record_event_service(
    link_row.creator_profile_id,
    'trade_completed',
    link_row.source_opportunity_type,
    link_row.source_offer_id,
    link_row.exposure_request_id,
    link_row.source_terms_version,
    link_row.derived_offer_id,
    new.id
  );
  return new;
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_record_event_authenticated(p_expected_actor_id uuid, p_event_type text, p_source_opportunity_type text, p_source_opportunity_id uuid, p_exposure_request_id uuid, p_source_terms_version integer, p_derived_offer_id uuid DEFAULT NULL::uuid, p_agreement_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then
    raise exception using errcode = '42501', message = 'An authenticated actor is required.';
  end if;
  if p_expected_actor_id is null or p_expected_actor_id is distinct from actor_id then
    raise exception using errcode = '42501', message = 'The expected Feed-to-Create actor does not match the authenticated session.';
  end if;

  return public.moral_trade_feed_create_record_event_service(
    actor_id,
    p_event_type,
    p_source_opportunity_type,
    p_source_opportunity_id,
    p_exposure_request_id,
    p_source_terms_version,
    p_derived_offer_id,
    p_agreement_id
  );
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_record_event_service(p_actor_id uuid, p_event_type text, p_source_opportunity_type text, p_source_opportunity_id uuid, p_exposure_request_id uuid, p_source_terms_version integer, p_derived_offer_id uuid DEFAULT NULL::uuid, p_agreement_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  exposure_row public.recommendation_exposures%rowtype;
  source_row public.offers%rowtype;
  link_row public.moral_trade_feed_create_links%rowtype;
  event_id uuid;
  event_key text;
begin
  if p_actor_id is null then
    raise exception using errcode = '42501', message = 'An authenticated actor is required.';
  end if;
  if p_event_type not in (
    'action_shown', 'action_clicked', 'create_opened',
    'draft_saved', 'proposal_submitted', 'trade_completed'
  ) then
    raise exception using errcode = '22023', message = 'Unsupported Feed-to-Create event type.';
  end if;
  if p_source_opportunity_type <> 'offer' then
    raise exception using errcode = '22023', message = 'Only bilateral offers may enter Feed-to-Create Phase 1.';
  end if;

  select * into exposure_row
  from public.recommendation_exposures
  where profile_id = p_actor_id
    and request_id = p_exposure_request_id
    and opportunity_type = p_source_opportunity_type
    and opportunity_id = p_source_opportunity_id::text
    and was_shown = true
  limit 1;

  if exposure_row.id is null then
    raise exception using errcode = '42501', message = 'The Feed exposure receipt is missing or does not belong to this user.';
  end if;

  select * into source_row
  from public.offers
  where id = p_source_opportunity_id
  limit 1;

  if p_event_type <> 'trade_completed' and (
    source_row.id is null
    or source_row.owner_id is distinct from exposure_row.owner_id
    or source_row.owner_id = p_actor_id
    or source_row.mode::text <> 'pledge'
    or source_row.status::text <> 'open'
    or source_row.workflow_status <> 'published'
    or source_row.published_at is null
    or source_row.closed_at is not null
    or source_row.deleted_at is not null
    or source_row.terms_version <> p_source_terms_version
  ) then
    raise exception using errcode = '23514', message = 'The Feed source is no longer an eligible open bilateral offer at the shown revision.';
  end if;

  if p_event_type in ('draft_saved', 'proposal_submitted', 'trade_completed') then
    select * into link_row
    from public.moral_trade_feed_create_links
    where creator_profile_id = p_actor_id
      and derived_offer_id = p_derived_offer_id
      and source_exposure_id = exposure_row.id
      and source_offer_id = p_source_opportunity_id
    limit 1;
    if link_row.id is null then
      raise exception using errcode = '42501', message = 'The derived offer is not linked to this authenticated Feed source.';
    end if;
  end if;

  if p_event_type = 'trade_completed' then
    if p_agreement_id is null or not exists (
      select 1 from public.agreements
      where id = p_agreement_id
        and offer_id = p_derived_offer_id
        and (
          lifecycle_status = 'completed'
          or completion_state = 'reviewed_complete'
        )
    ) then
      raise exception using errcode = '23514', message = 'A completed linked agreement is required for the completion event.';
    end if;
  elsif p_agreement_id is not null then
    raise exception using errcode = '22023', message = 'Only completion events may reference an agreement.';
  end if;

  event_key := concat_ws(':',
    'feed-create-v1',
    p_actor_id::text,
    p_event_type,
    exposure_row.id::text,
    coalesce(p_derived_offer_id::text, ''),
    coalesce(p_agreement_id::text, '')
  );

  insert into public.moral_trade_feed_create_events (
    profile_id,
    source_exposure_id,
    source_opportunity_type,
    source_opportunity_id,
    exposure_request_id,
    event_type,
    rank,
    derived_offer_id,
    agreement_id,
    idempotency_key
  ) values (
    p_actor_id,
    exposure_row.id,
    p_source_opportunity_type,
    p_source_opportunity_id,
    p_exposure_request_id,
    p_event_type,
    exposure_row.rank,
    p_derived_offer_id,
    p_agreement_id,
    event_key
  )
  on conflict (idempotency_key) do update
    set occurred_at = public.moral_trade_feed_create_events.occurred_at
  returning id into event_id;

  if event_id is null then
    select id into event_id
    from public.moral_trade_feed_create_events
    where idempotency_key = event_key;
  end if;

  return event_id;
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_save_authenticated(p_expected_actor_id uuid, p_intent text, p_submission_key text, p_source_opportunity_type text, p_source_opportunity_id uuid, p_exposure_request_id uuid, p_source_terms_version integer, p_imported_field_reviews jsonb, p_duplicate_acknowledged boolean, p_offered_cause text, p_requested_cause text, p_proposed_action text, p_requested_action text, p_no_trade_baseline text, p_duration text, p_start_date date, p_evidence_due_date date, p_evidence_rule text, p_maximum_burden text, p_privacy_scope text, p_exit_conditions text, p_notes text) RETURNS TABLE(derived_offer_id uuid, link_id uuid, workflow_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then
    raise exception using errcode = '42501', message = 'An authenticated actor is required.';
  end if;
  if p_expected_actor_id is null or p_expected_actor_id is distinct from actor_id then
    raise exception using errcode = '42501', message = 'The expected Feed-to-Create actor does not match the authenticated session.';
  end if;

  return query
  select saved.derived_offer_id, saved.link_id, saved.workflow_status
  from public.moral_trade_feed_create_save_service(
    actor_id,
    p_intent,
    p_submission_key,
    p_source_opportunity_type,
    p_source_opportunity_id,
    p_exposure_request_id,
    p_source_terms_version,
    p_imported_field_reviews,
    p_duplicate_acknowledged,
    p_offered_cause,
    p_requested_cause,
    p_proposed_action,
    p_requested_action,
    p_no_trade_baseline,
    p_duration,
    p_start_date,
    p_evidence_due_date,
    p_evidence_rule,
    p_maximum_burden,
    p_privacy_scope,
    p_exit_conditions,
    p_notes
  ) as saved;
end;
$$;



CREATE FUNCTION public.moral_trade_feed_create_save_service(p_actor_id uuid, p_intent text, p_submission_key text, p_source_opportunity_type text, p_source_opportunity_id uuid, p_exposure_request_id uuid, p_source_terms_version integer, p_imported_field_reviews jsonb, p_duplicate_acknowledged boolean, p_offered_cause text, p_requested_cause text, p_proposed_action text, p_requested_action text, p_no_trade_baseline text, p_duration text, p_start_date date, p_evidence_due_date date, p_evidence_rule text, p_maximum_burden text, p_privacy_scope text, p_exit_conditions text, p_notes text) RETURNS TABLE(derived_offer_id uuid, link_id uuid, workflow_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  exposure_row public.recommendation_exposures%rowtype;
  source_row public.offers%rowtype;
  existing_offer public.offers%rowtype;
  existing_link public.moral_trade_feed_create_links%rowtype;
  actor_alias text;
  active_duplicate_count integer;
  new_offer_id uuid := gen_random_uuid();
  new_link_id uuid := gen_random_uuid();
  now_value timestamptz := timezone('utc', now());
  workflow_value text;
  source_snapshot jsonb;
  source_snapshot_hash text;
  fingerprint_value text;
  review_key text;
  required_reviews text[] := array[
    'counterparty',
    'offered_cause',
    'requested_cause',
    'proposed_action',
    'requested_action',
    'duration',
    'evidence_rule'
  ];
begin
  if p_actor_id is null then
    raise exception using errcode = '42501', message = 'An authenticated actor is required.';
  end if;
  if p_intent not in ('draft', 'submit') then
    raise exception using errcode = '22023', message = 'Feed-to-Create intent must be draft or submit.';
  end if;
  if p_source_opportunity_type <> 'offer' then
    raise exception using errcode = '22023', message = 'Only bilateral offers may enter Feed-to-Create Phase 1.';
  end if;
  if nullif(btrim(p_submission_key), '') is null
     or length(p_submission_key) > 120
     or p_submission_key !~ '^[A-Za-z0-9:_-]+$' then
    raise exception using errcode = '22023', message = 'Submission key is invalid.';
  end if;
  if jsonb_typeof(p_imported_field_reviews) <> 'object'
     or p_imported_field_reviews - required_reviews <> '{}'::jsonb then
    raise exception using errcode = '22023', message = 'Imported-field review receipts contain unsupported fields.';
  end if;
  foreach review_key in array required_reviews loop
    if coalesce(p_imported_field_reviews ->> review_key, '') <> 'true' then
      raise exception using errcode = '23514', message = 'Review every imported material field before saving.';
    end if;
  end loop;

  if nullif(btrim(p_offered_cause), '') is null
     or nullif(btrim(p_requested_cause), '') is null
     or nullif(btrim(p_proposed_action), '') is null
     or nullif(btrim(p_requested_action), '') is null
     or nullif(btrim(p_no_trade_baseline), '') is null
     or nullif(btrim(p_duration), '') is null
     or nullif(btrim(p_evidence_rule), '') is null
     or nullif(btrim(p_maximum_burden), '') is null
     or nullif(btrim(p_privacy_scope), '') is null
     or nullif(btrim(p_exit_conditions), '') is null then
    raise exception using errcode = '22023', message = 'Complete every required counteroffer field before saving.';
  end if;
  if greatest(
    length(p_offered_cause), length(p_requested_cause), length(p_proposed_action),
    length(p_requested_action), length(p_no_trade_baseline), length(p_duration),
    length(p_evidence_rule), length(p_maximum_burden), length(p_privacy_scope),
    length(p_exit_conditions), length(coalesce(p_notes, ''))
  ) > 5000 then
    raise exception using errcode = '22023', message = 'A Feed-derived counteroffer field is too long.';
  end if;
  if p_start_date is not null and p_start_date < current_date then
    raise exception using errcode = '22023', message = 'The start date cannot be in the past.';
  end if;
  if p_evidence_due_date is not null and p_evidence_due_date < current_date then
    raise exception using errcode = '22023', message = 'The evidence due date cannot be in the past.';
  end if;
  if p_start_date is not null and p_evidence_due_date is not null and p_evidence_due_date < p_start_date then
    raise exception using errcode = '22023', message = 'Evidence cannot be due before the commitment starts.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_actor_id::text || ':feed-create:' || p_source_opportunity_id::text, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended(p_actor_id::text || ':feed-create-key:' || p_submission_key, 0)
  );

  select * into exposure_row
  from public.recommendation_exposures
  where profile_id = p_actor_id
    and request_id = p_exposure_request_id
    and opportunity_type = p_source_opportunity_type
    and opportunity_id = p_source_opportunity_id::text
    and was_shown = true
  limit 1;

  if exposure_row.id is null then
    raise exception using errcode = '42501', message = 'The Feed exposure receipt is missing or does not belong to this user.';
  end if;

  select * into source_row
  from public.offers
  where id = p_source_opportunity_id
  for share;

  if source_row.id is null
     or source_row.owner_id is distinct from exposure_row.owner_id
     or source_row.owner_id = p_actor_id
     or source_row.mode::text <> 'pledge'
     or source_row.status::text <> 'open'
     or source_row.workflow_status <> 'published'
     or source_row.published_at is null
     or source_row.closed_at is not null
     or source_row.deleted_at is not null
     or source_row.terms_version <> p_source_terms_version
     or nullif(btrim(source_row.offered_cause), '') is null
     or nullif(btrim(source_row.requested_cause), '') is null
     or nullif(btrim(source_row.offer_action), '') is null
     or nullif(btrim(source_row.request_action), '') is null
     or nullif(btrim(source_row.verification), '') is null
     or nullif(btrim(source_row.duration), '') is null then
    raise exception using errcode = '23514', message = 'The Feed source is no longer an eligible open bilateral offer at the shown revision.';
  end if;

  select coalesce(nullif(btrim(display_name), ''), nullif(btrim(email), ''), 'Moral Trade participant')
  into actor_alias
  from public.profiles
  where id = p_actor_id;
  if actor_alias is null then
    raise exception using errcode = '23503', message = 'A Moral Trade profile is required before saving.';
  end if;

  select * into existing_offer
  from public.offers
  where owner_id = p_actor_id
    and submission_key = p_submission_key
  limit 1;

  if existing_offer.id is not null then
    select * into existing_link
    from public.moral_trade_feed_create_links as existing_feed_link
    where existing_feed_link.derived_offer_id = existing_offer.id
      and existing_feed_link.creator_profile_id = p_actor_id
      and existing_feed_link.source_exposure_id = exposure_row.id
      and existing_feed_link.source_offer_id = source_row.id
      and existing_feed_link.source_terms_version = p_source_terms_version
    limit 1;
    if existing_link.id is null then
      raise exception using errcode = '23514', message = 'This submission key was already used for a different proposal.';
    end if;
    return query select existing_offer.id, existing_link.id, existing_offer.workflow_status;
    return;
  end if;

  select count(*)::integer into active_duplicate_count
  from public.moral_trade_feed_create_links link
  join public.offers derived on derived.id = link.derived_offer_id
  where link.creator_profile_id = p_actor_id
    and link.source_offer_id = p_source_opportunity_id
    and derived.status::text <> 'closed'
    and derived.workflow_status not in ('closed', 'deleted', 'rejected');

  if active_duplicate_count > 0 and coalesce(p_duplicate_acknowledged, false) = false then
    raise exception using errcode = '23514', message = 'An active draft already exists for this Feed opportunity. Acknowledge the duplicate before creating another.';
  end if;

  source_snapshot := jsonb_build_object(
    'ownerAlias', source_row.owner_alias,
    'offeredCause', source_row.offered_cause,
    'requestedCause', source_row.requested_cause,
    'offerAction', source_row.offer_action,
    'requestAction', source_row.request_action,
    'verification', source_row.verification,
    'duration', source_row.duration,
    'termsVersion', source_row.terms_version,
    'publishedAt', source_row.published_at
  );
  source_snapshot_hash := encode(
    extensions.digest(convert_to(source_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );
  fingerprint_value := encode(
    extensions.digest(convert_to(concat_ws(chr(31),
      lower(btrim(p_offered_cause)), lower(btrim(p_requested_cause)),
      lower(btrim(p_proposed_action)), lower(btrim(p_requested_action)),
      lower(btrim(p_no_trade_baseline)), lower(btrim(p_duration)),
      lower(btrim(p_evidence_rule)), lower(btrim(p_maximum_burden)),
      lower(btrim(p_privacy_scope)), lower(btrim(p_exit_conditions)),
      p_source_opportunity_id::text, p_submission_key
    ), 'UTF8'), 'sha256'),
    'hex'
  );
  workflow_value := case when p_intent = 'submit' then 'pending_review' else 'draft' end;

  insert into public.offers (
    id,
    owner_id,
    owner_alias,
    mode,
    offered_cause,
    requested_cause,
    offer_action,
    request_action,
    compromise_cause,
    offer_impact,
    min_counterparty_impact,
    verification,
    duration,
    trust_level,
    notes,
    discount_note,
    status,
    workflow_status,
    moderation_reason,
    submission_key,
    fingerprint,
    no_trade_baseline,
    start_date,
    exit_conditions,
    maximum_burden,
    privacy_scope,
    evidence_due_date,
    submitted_at,
    terms_version
  ) values (
    new_offer_id,
    p_actor_id,
    actor_alias,
    'pledge',
    btrim(p_offered_cause),
    btrim(p_requested_cause),
    btrim(p_proposed_action),
    btrim(p_requested_action),
    'Not needed',
    5,
    5,
    btrim(p_evidence_rule),
    btrim(p_duration),
    1,
    left(coalesce(p_notes, ''), 5000),
    '',
    'paused',
    workflow_value,
    '',
    p_submission_key,
    fingerprint_value,
    btrim(p_no_trade_baseline),
    p_start_date,
    btrim(p_exit_conditions),
    btrim(p_maximum_burden),
    btrim(p_privacy_scope),
    p_evidence_due_date,
    case when p_intent = 'submit' then now_value else null end,
    1
  );

  insert into public.moral_trade_feed_create_links (
    id,
    creator_profile_id,
    derived_offer_id,
    source_exposure_id,
    exposure_request_id,
    source_opportunity_type,
    source_offer_id,
    source_owner_profile_id,
    counterparty_profile_id,
    source_terms_version,
    derivation_mode,
    source_snapshot_json,
    source_snapshot_hash,
    imported_field_reviews,
    duplicate_acknowledged,
    submitted_at
  ) values (
    new_link_id,
    p_actor_id,
    new_offer_id,
    exposure_row.id,
    p_exposure_request_id,
    p_source_opportunity_type,
    source_row.id,
    source_row.owner_id,
    source_row.owner_id,
    p_source_terms_version,
    'counteroffer',
    source_snapshot,
    source_snapshot_hash,
    p_imported_field_reviews,
    coalesce(p_duplicate_acknowledged, false),
    case when p_intent = 'submit' then now_value else null end
  );

  insert into public.core_loop_events (
    profile_id,
    event_type,
    entity_type,
    entity_id,
    idempotency_key,
    metadata
  ) values (
    p_actor_id,
    'offer_draft_saved',
    'offer',
    new_offer_id,
    'offer_draft_saved:' || p_actor_id::text || ':offer:' || new_offer_id::text,
    jsonb_build_object('source', 'feed_create_v1', 'derivationMode', 'counteroffer')
  ) on conflict (idempotency_key) do nothing;

  perform public.moral_trade_feed_create_record_event_service(
    p_actor_id,
    'draft_saved',
    p_source_opportunity_type,
    p_source_opportunity_id,
    p_exposure_request_id,
    p_source_terms_version,
    new_offer_id,
    null
  );

  if p_intent = 'submit' then
    insert into public.trade_review_events (
      offer_id,
      reviewer_id,
      action,
      reason,
      metadata
    ) values (
      new_offer_id,
      null,
      'submitted',
      'Feed-derived source-bound counteroffer submitted for Phase-1 operator review.',
      jsonb_build_object('feedCreateLinkId', new_link_id, 'deliveryBlocked', true)
    );

    insert into public.core_loop_events (
      profile_id,
      event_type,
      entity_type,
      entity_id,
      idempotency_key,
      metadata
    ) values (
      p_actor_id,
      'offer_submitted',
      'offer',
      new_offer_id,
      'offer_submitted:' || p_actor_id::text || ':offer:' || new_offer_id::text,
      jsonb_build_object('source', 'feed_create_v1', 'derivationMode', 'counteroffer', 'deliveryBlocked', true)
    ) on conflict (idempotency_key) do nothing;

    perform public.moral_trade_feed_create_record_event_service(
      p_actor_id,
      'proposal_submitted',
      p_source_opportunity_type,
      p_source_opportunity_id,
      p_exposure_request_id,
      p_source_terms_version,
      new_offer_id,
      null
    );
  end if;

  return query select new_offer_id, new_link_id, workflow_value;
end;
$_$;



CREATE FUNCTION public.moral_trade_feed_create_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$$;



CREATE FUNCTION public.mpgf_approve_and_freeze_pool_proposal(p_proposal_id uuid, p_reviewer_id uuid, p_reason text) RETURNS TABLE(proposal_id uuid, terms_version integer, terms_sha256 text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  recorded_hash text;
  current_hash text;
  create_terms_row public.moral_trade_create_pool_terms%rowtype;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'An approval rationale is required.';
  end if;
  perform public.mpgf_assert_authorized_pool_reviewer(p_reviewer_id, p_proposal_id);

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id
  for update;
  if proposal_row.status <> 'under_review' then
    raise exception using errcode = '23514', message = 'Only a pool proposal under review can be approved.';
  end if;

  select * into create_terms_row
  from public.moral_trade_create_pool_terms
  where pool_proposal_id = p_proposal_id
  for update;

  if create_terms_row.pool_proposal_id is not null
     and create_terms_row.reserve_quote_status not in ('not_applicable', 'approved') then
    raise exception using errcode = '23514', message = 'Pool reserve underwriting must be approved before proposal approval.';
  end if;
  if proposal_row.public_goods_failure_bonus_enabled = true
     and proposal_row.public_goods_failure_bonus_schedule_status <> 'approved' then
    raise exception using errcode = '23514', message = 'Failure-bonus schedule approval is required before proposal approval.';
  end if;

  select proposal_version.terms_sha256 into recorded_hash
  from public.mpgf_pool_proposal_versions as proposal_version
  where proposal_version.proposal_id = p_proposal_id
    and proposal_version.terms_version = proposal_row.terms_version;
  current_hash := public.mpgf_pool_proposal_terms_sha256(p_proposal_id);

  if recorded_hash is null or recorded_hash <> current_hash then
    raise exception using errcode = '23514', message = 'Pool terms changed after review began; submit a new proposal revision.';
  end if;

  perform set_config('app.mpgf_pool_review_transition', p_proposal_id::text, true);
  update public.mpgf_pool_proposals
  set status = 'approved_as_candidate',
      approved_terms_version = proposal_row.terms_version,
      operative_terms_sha256 = current_hash,
      terms_locked_at = timezone('utc', now()),
      reviewed_by = p_reviewer_id,
      reviewed_at = timezone('utc', now()),
      review_reason = btrim(p_reason)
  where id = p_proposal_id;
  perform set_config('app.mpgf_pool_review_transition', '', true);

  update public.moral_trade_create_pool_terms
  set review_status = 'approved',
      terms_locked_at = timezone('utc', now())
  where pool_proposal_id = p_proposal_id;

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id, terms_version, event_type, actor_user_id,
    from_status, to_status, terms_sha256, reason
  ) values (
    p_proposal_id, proposal_row.terms_version, 'terms_approved_and_frozen', p_reviewer_id,
    'under_review', 'approved_as_candidate', current_hash, btrim(p_reason)
  );

  return query select p_proposal_id, proposal_row.terms_version, current_hash, 'approved_as_candidate'::text;
end;
$$;



CREATE FUNCTION public.mpgf_approve_failure_bonus_premium_schedule(proposal_id_input uuid, reviewer_id_input uuid, rationale_input text) RETURNS TABLE(pool_proposal_id uuid, approved_threshold_count integer, approved_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  threshold_item jsonb;
  quote_row public.mpgf_failure_bonus_premium_quotes%rowtype;
  approved_schedule jsonb;
  approved_thresholds jsonb;
  threshold_count integer;
  approved_timestamp timestamptz := timezone('utc', now());
  operator_rationale text := btrim(rationale_input);
begin
  if reviewer_id_input is null
     or not exists (select 1 from public.profiles where id = reviewer_id_input) then
    raise exception using errcode = '23503', message = 'A valid operator profile is required.';
  end if;
  if operator_rationale = '' then
    raise exception using errcode = '22023', message = 'Operator approval requires a rationale.';
  end if;

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = proposal_id_input
  for update;

  if proposal_row.id is null then
    raise exception using errcode = 'P0002', message = 'Failure-bonus proposal was not found.';
  end if;
  if proposal_row.status <> 'submitted'
     or proposal_row.public_goods_failure_bonus_enabled <> true
     or proposal_row.public_goods_failure_bonus_schedule_status <> 'pending_review'
     or proposal_row.public_goods_success_premium_provisional <> true then
    raise exception using errcode = '23514', message = 'Only a submitted proposal with a complete pending failure-bonus schedule can be approved.';
  end if;
  if proposal_row.first_accepted_pledge_at is not null then
    raise exception using errcode = '23514', message = 'A failure-bonus schedule must be approved before the first accepted pledge.';
  end if;

  threshold_count := jsonb_array_length(
    proposal_row.public_goods_threshold_schedule_json -> 'thresholds'
  );

  if (
    select count(*)
    from public.mpgf_failure_bonus_premium_quotes pending_quote
    where pending_quote.pool_proposal_id = proposal_row.id
      and pending_quote.status = 'pending_review'
  ) <> threshold_count then
    raise exception using errcode = '23514', message = 'The pending quote set does not match the complete threshold schedule.';
  end if;

  for threshold_item in
    select value
    from jsonb_array_elements(
      proposal_row.public_goods_threshold_schedule_json -> 'thresholds'
    )
  loop
    select * into quote_row
    from public.mpgf_failure_bonus_premium_quotes quote_candidate
    where quote_candidate.pool_proposal_id = proposal_row.id
      and quote_candidate.threshold_index = (threshold_item ->> 'thresholdIndex')::integer
      and quote_candidate.status = 'pending_review'
    for update;

    if quote_row.id is null
       or quote_row.threshold_id <> threshold_item ->> 'thresholdId'
       or quote_row.cumulative_net_recipient_threshold_cents <>
          (threshold_item ->> 'cumulativeNetRecipientThresholdCents')::bigint
       or quote_row.incremental_net_recipient_cents <>
          (threshold_item ->> 'incrementalNetRecipientCents')::bigint
       or quote_row.premium_rate_bps <> (threshold_item ->> 'premiumRateBps')::integer
       or quote_row.success_premium_cents <> (threshold_item ->> 'successPremiumCents')::bigint
       or quote_row.cumulative_success_premium_cents <>
          (threshold_item ->> 'cumulativeSuccessPremiumCents')::bigint
       or quote_row.gross_success_requirement_cents <>
          (threshold_item ->> 'grossSuccessRequirementCents')::bigint
       or quote_row.incremental_failure_bonus_exposure_cents <>
          (threshold_item ->> 'incrementalFailureBonusExposureCents')::bigint
       or quote_row.maximum_failure_bonus_exposure_cents <>
          (threshold_item ->> 'maximumFailureBonusExposureCents')::bigint
       or quote_row.pricing_json is distinct from threshold_item -> 'assumptions'
       or quote_row.eligibility_json is distinct from
          proposal_row.public_goods_failure_bonus_eligibility_json then
      raise exception using errcode = '23514', message = 'A pending threshold quote differs from the current proposal schedule.';
    end if;
  end loop;

  select jsonb_agg(
    (value - 'provisional' - 'rationale') || jsonb_build_object(
      'provisional', false,
      'rationale', operator_rationale
    )
    order by (value ->> 'thresholdIndex')::integer
  ) into approved_thresholds
  from jsonb_array_elements(
    proposal_row.public_goods_threshold_schedule_json -> 'thresholds'
  );

  approved_schedule := jsonb_set(
    proposal_row.public_goods_threshold_schedule_json,
    '{thresholds}',
    approved_thresholds,
    false
  );

  perform set_config(
    'app.mpgf_failure_bonus_schedule_approval',
    proposal_row.id::text,
    true
  );

  update public.mpgf_pool_proposals
  set public_goods_threshold_schedule_json = approved_schedule,
      public_goods_failure_bonus_schedule_status = 'approved',
      public_goods_success_premium_provisional = false
  where id = proposal_row.id;

  update public.mpgf_failure_bonus_premium_quotes approved_quote
  set status = 'approved',
      provisional = false,
      rationale = operator_rationale,
      approved_by = reviewer_id_input,
      approved_at = approved_timestamp
  where approved_quote.pool_proposal_id = proposal_row.id
    and approved_quote.status = 'pending_review';

  if not found then
    raise exception using errcode = '23514', message = 'No pending threshold quotes were approved.';
  end if;

  return query select proposal_row.id, threshold_count, approved_timestamp;
end;
$$;



CREATE FUNCTION public.mpgf_assert_authorized_pool_reviewer(p_reviewer_id uuid, p_proposal_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_reviewer_id is null
     or not exists (
       select 1
       from public.mpgf_pool_reviewers reviewer
       where reviewer.reviewer_id = p_reviewer_id
         and reviewer.active = true
         and (reviewer.expires_at is null or reviewer.expires_at > timezone('utc', now()))
     ) then
    raise exception using errcode = '42501', message = 'An active authorized pool reviewer is required.';
  end if;

  if exists (
    select 1
    from public.mpgf_pool_proposals proposal
    where proposal.id = p_proposal_id
      and proposal.proposer_id = p_reviewer_id
  ) then
    raise exception using errcode = '42501', message = 'A pool proposer cannot review their own proposal.';
  end if;
end;
$$;



CREATE FUNCTION public.mpgf_assert_failure_bonus_reserve_solvency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  reserve_status text;
  current_cash_cents bigint;
  current_exposure_cents bigint;
  next_cash_cents bigint;
  next_exposure_cents bigint;
  current_pool_exposure_cents bigint;
  next_pool_exposure_cents bigint;
  quote_row public.mpgf_failure_bonus_premium_quotes%rowtype;
begin
  if new.status <> 'posted' then
    return new;
  end if;

  select status
  into reserve_status
  from public.mpgf_failure_bonus_reserves
  where id = new.reserve_id
  for update;

  if reserve_status is null then
    raise exception 'Failure-bonus reserve is missing.';
  end if;

  if reserve_status in ('simulation_only', 'closed') then
    raise exception 'Reserve status % does not permit posted accounting entries.', reserve_status
      using errcode = '23514';
  end if;

  if reserve_status = 'paused'
     and new.event_type = 'bonus_exposure_allocation' then
    raise exception 'Paused reserves cannot accept new bonus exposure; existing claims and releases remain settleable.'
      using errcode = '23514';
  end if;

  if new.event_type = 'success_premium_credit' then
    select *
    into quote_row
    from public.mpgf_failure_bonus_premium_quotes
    where id = new.premium_quote_id;

    if quote_row.id is null
       or quote_row.status <> 'approved'
       or quote_row.provisional <> false
       or quote_row.reserve_id <> new.reserve_id
       or quote_row.pool_proposal_id <> new.pool_proposal_id
       or quote_row.threshold_index <> new.threshold_index
       or quote_row.success_premium_cents <> new.cash_delta_cents then
      raise exception 'Success-premium credits must exactly match a final approved quote.'
        using errcode = '23514';
    end if;
  end if;

  select
    coalesce(sum(cash_delta_cents), 0),
    coalesce(sum(exposure_delta_cents), 0)
  into current_cash_cents, current_exposure_cents
  from public.mpgf_failure_bonus_reserve_entries
  where reserve_id = new.reserve_id
    and status = 'posted'
    and id <> new.id;

  next_cash_cents := current_cash_cents + new.cash_delta_cents;
  next_exposure_cents := current_exposure_cents + new.exposure_delta_cents;

  if next_cash_cents < 0 then
    raise exception 'Failure-bonus reserve cash balance cannot become negative.'
      using errcode = '23514';
  end if;

  if next_exposure_cents < 0 then
    raise exception 'Failure-bonus reserve open exposure cannot become negative.'
      using errcode = '23514';
  end if;

  if next_cash_cents - next_exposure_cents < 0 then
    raise exception 'Failure-bonus reserve cannot allocate more exposure than posted cash backing.'
      using errcode = '23514';
  end if;

  if new.exposure_delta_cents <> 0 then
    select coalesce(sum(exposure_delta_cents), 0)
    into current_pool_exposure_cents
    from public.mpgf_failure_bonus_reserve_entries
    where reserve_id = new.reserve_id
      and pool_proposal_id = new.pool_proposal_id
      and threshold_index = new.threshold_index
      and status = 'posted'
      and id <> new.id;

    next_pool_exposure_cents := current_pool_exposure_cents + new.exposure_delta_cents;

    if next_pool_exposure_cents < 0 then
      raise exception 'A pool threshold cannot release or debit another pool threshold''s bonus exposure.'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_begin_pool_proposal_review(p_proposal_id uuid, p_reviewer_id uuid, p_reason text) RETURNS TABLE(proposal_id uuid, terms_version integer, terms_sha256 text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  terms_hash text;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A review rationale is required.';
  end if;
  perform public.mpgf_assert_authorized_pool_reviewer(p_reviewer_id, p_proposal_id);

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id
  for update;

  if proposal_row.status <> 'submitted' then
    raise exception using errcode = '23514', message = 'Only a submitted pool proposal can enter review.';
  end if;

  terms_hash := public.mpgf_record_pool_proposal_version(
    p_proposal_id,
    p_reviewer_id,
    'review_started: ' || btrim(p_reason)
  );

  perform set_config('app.mpgf_pool_review_transition', p_proposal_id::text, true);
  update public.mpgf_pool_proposals
  set status = 'under_review',
      reviewed_by = p_reviewer_id,
      reviewed_at = timezone('utc', now()),
      review_reason = btrim(p_reason)
  where id = p_proposal_id;
  perform set_config('app.mpgf_pool_review_transition', '', true);

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id, terms_version, event_type, actor_user_id,
    from_status, to_status, terms_sha256, reason
  ) values (
    p_proposal_id, proposal_row.terms_version, 'review_started', p_reviewer_id,
    'submitted', 'under_review', terms_hash, btrim(p_reason)
  );

  return query select p_proposal_id, proposal_row.terms_version, terms_hash, 'under_review'::text;
end;
$$;



CREATE FUNCTION public.mpgf_create_dac_pledge(p_campaign_id text, p_amount_cents bigint, p_visibility_mode text, p_supporter_reason text, p_idempotency_key text) RETURNS TABLE(pledge_intent_id uuid, pledge_id uuid, campaign_id text, pool_proposal_id uuid, terms_version integer, terms_sha256 text, amount_cents bigint, currency text, eligibility_state text, pledge_status text, accepted_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  campaign_id_value text := btrim(coalesce(p_campaign_id, ''));
  campaign_row public.mpgf_public_goods_campaigns%rowtype;
  proposal_row public.mpgf_pool_proposals%rowtype;
  existing_intent public.mpgf_dac_pledge_intents%rowtype;
  existing_pledge public.mpgf_public_goods_pledges%rowtype;
  intent_id_value uuid := gen_random_uuid();
  pledge_id_value uuid := gen_random_uuid();
  accepted_at_value timestamptz := timezone('utc', now());
  supporter_reason_value text := nullif(btrim(coalesce(p_supporter_reason, '')), '');
  idempotency_hash_value text;
  consent_value jsonb;
  consent_hash_value text;
  event_value jsonb;
begin
  if actor_id is null then
    raise exception using
      errcode = '42501',
      message = 'Sign in to create a DAC pledge.';
  end if;
  if not exists (
    select 1 from public.profiles as profile where profile.id = actor_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A Moral Trade profile is required before pledging.';
  end if;
  if campaign_id_value = '' then
    raise exception using errcode = '22023', message = 'A campaign is required.';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception using errcode = '22023', message = 'Pledge amount must be a positive number of cents.';
  end if;
  if p_visibility_mode is null
     or p_visibility_mode not in ('private_amount', 'public_supporter', 'public_reason') then
    raise exception using errcode = '22023', message = 'Pledge visibility is invalid.';
  end if;
  if p_visibility_mode = 'public_reason' and supporter_reason_value is null then
    raise exception using errcode = '22023', message = 'A public supporter reason is required for public-reason visibility.';
  end if;
  if supporter_reason_value is not null and char_length(supporter_reason_value) > 500 then
    raise exception using errcode = '22023', message = 'Supporter reason is too long.';
  end if;
  if btrim(coalesce(p_idempotency_key, '')) = ''
     or char_length(p_idempotency_key) > 256 then
    raise exception using errcode = '22023', message = 'A stable idempotency key of at most 256 characters is required.';
  end if;

  idempotency_hash_value :=
    'sha256:' ||
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(btrim(p_idempotency_key), 'UTF8'),
        'sha256'
      ),
      'hex'
    );

  perform pg_advisory_xact_lock(
    hashtextextended(actor_id::text || ':' || idempotency_hash_value, 0)
  );

  select * into existing_intent
  from public.mpgf_dac_pledge_intents as intent
  where intent.profile_id = actor_id
    and intent.idempotency_key_hash = idempotency_hash_value;

  if existing_intent.id is not null then
    select * into existing_pledge
    from public.mpgf_public_goods_pledges as pledge
    where pledge.pledge_intent_id = existing_intent.id;

    if existing_pledge.id is null then
      raise exception using
        errcode = '23514',
        message = 'The existing pledge intent is missing its canonical pledge row.';
    end if;
    if existing_intent.campaign_id is distinct from campaign_id_value
       or existing_intent.amount_cents is distinct from p_amount_cents
       or existing_intent.visibility_mode is distinct from p_visibility_mode
       or existing_intent.supporter_reason is distinct from supporter_reason_value then
      raise exception using
        errcode = '23505',
        message = 'The idempotency key was already used for different DAC pledge terms.';
    end if;

    return query select
      existing_intent.id,
      existing_pledge.id,
      existing_intent.campaign_id,
      existing_intent.pool_proposal_id,
      existing_intent.terms_version,
      existing_intent.terms_sha256,
      existing_intent.amount_cents,
      existing_intent.currency,
      existing_pledge.eligibility_state,
      existing_pledge.status,
      existing_intent.accepted_at,
      existing_pledge.expires_at;
    return;
  end if;

  select * into campaign_row
  from public.mpgf_public_goods_campaigns as campaign
  where campaign.id = campaign_id_value
  for share;

  if campaign_row.id is null
     or campaign_row.review_status not in ('approved', 'finalized')
     or campaign_row.pool_proposal_id is null
     or campaign_row.published_terms_version is null
     or campaign_row.published_terms_sha256 is null
     or campaign_row.published_at is null
     or campaign_row.deadline_at <= accepted_at_value then
    raise exception using
      errcode = '23514',
      message = 'Only a live, approved, published campaign can accept a DAC pledge.';
  end if;

  select * into proposal_row
  from public.mpgf_pool_proposals as proposal
  where proposal.id = campaign_row.pool_proposal_id
  for share;

  if proposal_row.id is null
     or proposal_row.status <> 'approved_as_candidate'
     or proposal_row.approved_terms_version is null
     or proposal_row.approved_terms_version <> campaign_row.published_terms_version
     or proposal_row.operative_terms_sha256 is null
     or proposal_row.operative_terms_sha256 <> campaign_row.published_terms_sha256
     or proposal_row.terms_locked_at is null
     or proposal_row.public_goods_deadline_at is distinct from campaign_row.deadline_at then
    raise exception using
      errcode = '23514',
      message = 'The published campaign no longer matches its approved frozen proposal version.';
  end if;

  if proposal_row.public_goods_failure_bonus_enabled is distinct from true
     or proposal_row.public_goods_failure_bonus_schedule_status <> 'approved'
     or proposal_row.public_goods_success_premium_provisional is distinct from false
     or proposal_row.public_goods_threshold_schedule_json is null
     or proposal_row.public_goods_failure_bonus_eligibility_json is null then
    raise exception using
      errcode = '23514',
      message = 'This pledge path is restricted to reviewed dominant assurance contracts.';
  end if;

  if not exists (
    select 1
    from public.mpgf_pool_proposal_versions as proposal_version
    where proposal_version.proposal_id = proposal_row.id
      and proposal_version.terms_version = campaign_row.published_terms_version
      and proposal_version.terms_sha256 = campaign_row.published_terms_sha256
  ) then
    raise exception using
      errcode = '23514',
      message = 'The published campaign is missing its immutable approved proposal version.';
  end if;

  consent_value := jsonb_build_object(
    'schemaVersion', 'mpgf_dac_pledge_consent_v1',
    'mechanism', 'dominant_assurance_contract',
    'pledgeMode', 'pledge_only',
    'profileId', actor_id,
    'campaignId', campaign_row.id,
    'poolProposalId', proposal_row.id,
    'termsVersion', campaign_row.published_terms_version,
    'termsSha256', campaign_row.published_terms_sha256,
    'amountCents', p_amount_cents,
    'currency', 'usd',
    'visibilityMode', p_visibility_mode,
    'supporterReason', supporter_reason_value,
    'acceptedAt', accepted_at_value,
    'expiresAt', campaign_row.deadline_at,
    'threshold', jsonb_build_object(
      'netRecipientAmountCents', campaign_row.threshold_amount_cents,
      'minimumSupporters', campaign_row.threshold_supporters,
      'deadlineAt', campaign_row.deadline_at
    ),
    'failureBonus', jsonb_build_object(
      'enabled', true,
      'rateBps', proposal_row.public_goods_failure_bonus_rate_bps,
      'eligibility', proposal_row.public_goods_failure_bonus_eligibility_json,
      'maxParticipants', proposal_row.public_goods_failure_bonus_max_participants,
      'maxPerParticipantCents', proposal_row.public_goods_failure_bonus_max_per_participant_cents,
      'thresholdSchedule', proposal_row.public_goods_threshold_schedule_json,
      'scheduleStatus', proposal_row.public_goods_failure_bonus_schedule_status
    ),
    'payment', jsonb_build_object(
      'authorized', false,
      'mandateCreated', false,
      'charged', false,
      'captureMode', 'signed_intent'
    )
  );
  consent_hash_value := public.mpgf_dac_json_sha256(consent_value);

  insert into public.mpgf_dac_pledge_intents (
    id,
    campaign_id,
    pool_proposal_id,
    terms_version,
    terms_sha256,
    profile_id,
    idempotency_key_hash,
    amount_cents,
    currency,
    visibility_mode,
    supporter_reason,
    consent_json,
    consent_sha256,
    accepted_at
  ) values (
    intent_id_value,
    campaign_row.id,
    proposal_row.id,
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    actor_id,
    idempotency_hash_value,
    p_amount_cents,
    'usd',
    p_visibility_mode,
    supporter_reason_value,
    consent_value,
    consent_hash_value,
    accepted_at_value
  );

  perform set_config('app.mpgf_dac_internal_write', intent_id_value::text, true);

  insert into public.mpgf_public_goods_pledges (
    id,
    campaign_id,
    profile_id,
    user_ref,
    amount_cents,
    currency,
    visibility_mode,
    is_recurring,
    capture_mode,
    eligibility_state,
    human_score_bps,
    status,
    supporter_reason,
    payment_intent_ref,
    pledge_intent_id,
    pool_proposal_id,
    terms_version,
    terms_sha256,
    accepted_at,
    expires_at
  ) values (
    pledge_id_value,
    campaign_row.id,
    actor_id,
    'profile:' || actor_id::text,
    p_amount_cents,
    'usd',
    p_visibility_mode,
    false,
    'signed_intent',
    'pending_review',
    0,
    'pledged',
    supporter_reason_value,
    null,
    intent_id_value,
    proposal_row.id,
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    accepted_at_value,
    campaign_row.deadline_at
  );

  event_value := jsonb_build_object(
    'schemaVersion', 'mpgf_dac_pledge_event_v1',
    'eventType', 'pledge_created',
    'pledgeIntentId', intent_id_value,
    'pledgeId', pledge_id_value,
    'campaignId', campaign_row.id,
    'poolProposalId', proposal_row.id,
    'profileId', actor_id,
    'termsVersion', campaign_row.published_terms_version,
    'termsSha256', campaign_row.published_terms_sha256,
    'amountCents', p_amount_cents,
    'currency', 'usd',
    'eligibilityState', 'pending_review',
    'pledgeStatus', 'pledged',
    'paymentAuthorized', false,
    'createdAt', accepted_at_value
  );

  insert into public.mpgf_dac_pledge_events (
    pledge_intent_id,
    pledge_id,
    campaign_id,
    pool_proposal_id,
    profile_id,
    event_type,
    terms_version,
    terms_sha256,
    amount_cents,
    currency,
    event_json,
    event_sha256,
    created_at
  ) values (
    intent_id_value,
    pledge_id_value,
    campaign_row.id,
    proposal_row.id,
    actor_id,
    'pledge_created',
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    p_amount_cents,
    'usd',
    event_value,
    public.mpgf_dac_json_sha256(event_value),
    accepted_at_value
  );

  perform set_config('app.mpgf_dac_internal_write', '', true);

  return query select
    intent_id_value,
    pledge_id_value,
    campaign_row.id,
    proposal_row.id,
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    p_amount_cents,
    'usd'::text,
    'pending_review'::text,
    'pledged'::text,
    accepted_at_value,
    campaign_row.deadline_at;
end;
$$;



CREATE FUNCTION public.mpgf_dac_immutable_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  raise exception using
    errcode = '23514',
    message = 'DAC pledge consent and audit records are immutable.';
end;
$$;



CREATE FUNCTION public.mpgf_dac_json_sha256(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select 'sha256:' ||
    pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(p_value::text, 'UTF8'), 'sha256'),
      'hex'
    );
$$;



CREATE FUNCTION public.mpgf_enforce_pool_visibility_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.threshold_visibility::text <> 'public_exact' then
    raise exception using
      errcode = '23514',
      message = 'Pool thresholds must remain public and exact.',
      detail = format('Attempted threshold_visibility: %s', new.threshold_visibility::text),
      hint = 'Use threshold_visibility = public_exact.';
  end if;

  if old.first_accepted_pledge_at is not null
     and new.first_accepted_pledge_at is distinct from old.first_accepted_pledge_at then
    raise exception using
      errcode = '23514',
      message = 'first_accepted_pledge_at is immutable once set.';
  end if;

  if old.first_accepted_pledge_at is not null
     and public.mpgf_progress_visibility_rank(new.progress_visibility)
       < public.mpgf_progress_visibility_rank(old.progress_visibility) then
    raise exception using
      errcode = '23514',
      message = 'Progress visibility cannot become less transparent after the first accepted pledge.',
      detail = format(
        'Attempted change from %s to %s after first accepted pledge at %s.',
        old.progress_visibility::text,
        new.progress_visibility::text,
        old.first_accepted_pledge_at
      ),
      hint = 'Keep the current setting or choose a more transparent progress-visibility mode.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_approved_quote_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.status = 'approved' then
    if tg_op = 'DELETE' then
      raise exception 'Approved failure-bonus premium quotes are immutable.'
        using errcode = '23514';
    end if;

    if new is distinct from old then
      raise exception 'Approved failure-bonus premium quotes are immutable.'
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_eligibility_policy_valid(eligibility_json jsonb, max_participants integer, max_bonus_per_participant_cents bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  json_max_participants integer;
  json_max_bonus_per_participant_cents bigint;
  aggregate_cap numeric;
begin
  if jsonb_typeof(eligibility_json) <> 'object'
     or eligibility_json ->> 'policyVersion' <> 'mpgf_failure_bonus_eligibility_v0_1'
     or eligibility_json ->> 'contributorIdentityRule' <> 'verified_unique_person'
     or eligibility_json ->> 'contributionTimingRule' <> 'captured_before_deadline'
     or eligibility_json ->> 'relatedPartyRule' <> 'exclude_creator_and_related_parties'
     or eligibility_json ->> 'paymentIntegrityRule' <> 'exclude_duplicate_reversed_disputed_or_fraudulent'
     or eligibility_json ->> 'bonusBasis' <> 'eligible_contribution'
     or jsonb_typeof(eligibility_json -> 'maxParticipants') <> 'number'
     or jsonb_typeof(eligibility_json -> 'maxBonusPerParticipantCents') <> 'number' then
    return false;
  end if;

  json_max_participants := (eligibility_json ->> 'maxParticipants')::integer;
  json_max_bonus_per_participant_cents :=
    (eligibility_json ->> 'maxBonusPerParticipantCents')::bigint;

  if json_max_participants <> max_participants
     or json_max_bonus_per_participant_cents <> max_bonus_per_participant_cents
     or max_participants < 1
     or max_bonus_per_participant_cents < 1 then
    return false;
  end if;

  aggregate_cap := max_participants::numeric * max_bonus_per_participant_cents::numeric;
  return aggregate_cap <= 9007199254740991::numeric;
exception
  when others then
    return false;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_provisional_pricing_valid(pricing_json jsonb, failure_bonus_rate_bps integer, success_premium_rate_bps integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  success_probability_bps integer;
  pricing_failure_bonus_rate_bps integer;
  expected_eligible_failure_fill_bps integer;
  expense_load_bps integer;
  reserve_risk_margin_bps integer;
  expected_claims_rate_bps bigint;
  denominator bigint;
begin
  if jsonb_typeof(pricing_json) <> 'object'
     or jsonb_typeof(pricing_json -> 'successProbabilityBps') <> 'number'
     or jsonb_typeof(pricing_json -> 'failureBonusRateBps') <> 'number'
     or jsonb_typeof(pricing_json -> 'expectedEligibleFailureFillBps') <> 'number'
     or jsonb_typeof(pricing_json -> 'expenseLoadBps') <> 'number'
     or jsonb_typeof(pricing_json -> 'reserveRiskMarginBps') <> 'number' then
    return false;
  end if;

  success_probability_bps := (pricing_json ->> 'successProbabilityBps')::integer;
  pricing_failure_bonus_rate_bps := (pricing_json ->> 'failureBonusRateBps')::integer;
  expected_eligible_failure_fill_bps :=
    (pricing_json ->> 'expectedEligibleFailureFillBps')::integer;
  expense_load_bps := (pricing_json ->> 'expenseLoadBps')::integer;
  reserve_risk_margin_bps := (pricing_json ->> 'reserveRiskMarginBps')::integer;

  if success_probability_bps < 1
     or success_probability_bps > 7500
     or pricing_failure_bonus_rate_bps <> failure_bonus_rate_bps
     or expected_eligible_failure_fill_bps < 4000
     or expected_eligible_failure_fill_bps > 10000
     or expense_load_bps <> 25
     or reserve_risk_margin_bps <> 42 then
    return false;
  end if;

  denominator := success_probability_bps::bigint * 10000;
  expected_claims_rate_bps := (
    ((10000 - success_probability_bps)::bigint
      * pricing_failure_bonus_rate_bps::bigint
      * expected_eligible_failure_fill_bps::bigint)
    + denominator - 1
  ) / denominator;

  return success_premium_rate_bps =
    expected_claims_rate_bps + expense_load_bps + reserve_risk_margin_bps;
exception
  when others then
    return false;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_quote_approval_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status = 'approved'
     and old.status is distinct from 'approved'
     and current_setting('app.mpgf_failure_bonus_schedule_approval', true)
       is distinct from new.pool_proposal_id::text then
    raise exception using
      errcode = '42501',
      message = 'Failure-bonus threshold quotes must be approved as one atomic schedule.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_reserve_entry_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Failure-bonus reserve entries are append-only; post a reversing entry instead.'
      using errcode = '23514';
  end if;

  if old.status = 'posted' and new is distinct from old then
    raise exception 'Posted failure-bonus reserve entries are immutable.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_schedule_approval_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if old.public_goods_failure_bonus_schedule_status = 'approved'
     and new.public_goods_failure_bonus_schedule_status is distinct from 'approved' then
    raise exception using
      errcode = '23514',
      message = 'An approved failure-bonus schedule cannot return to a provisional state.';
  end if;

  if new.public_goods_failure_bonus_schedule_status = 'approved'
     and old.public_goods_failure_bonus_schedule_status is distinct from 'approved'
     and current_setting('app.mpgf_failure_bonus_schedule_approval', true) is distinct from new.id::text then
    raise exception using
      errcode = '42501',
      message = 'Only the atomic operator schedule-approval function can approve a failure-bonus schedule.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_failure_bonus_threshold_schedule_valid(schedule_json jsonb, eligibility_json jsonb, schedule_status text, failure_bonus_rate_bps integer, threshold_one_cents bigint, threshold_one_premium_rate_bps integer, threshold_one_premium_cents bigint, threshold_one_gross_cents bigint, threshold_one_pricing_json jsonb, requested_maximum_funding_cents bigint, verified_supporter_minimum integer, max_participants integer, max_bonus_per_participant_cents bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  thresholds_json jsonb;
  threshold_item jsonb;
  assumptions_json jsonb;
  threshold_ids text[] := array[]::text[];
  threshold_count integer;
  current_index integer := 0;
  threshold_id text;
  cumulative_net_cents bigint;
  previous_cumulative_net_cents bigint := 0;
  incremental_net_cents bigint;
  premium_rate_bps integer;
  success_premium_cents bigint;
  cumulative_success_premium_cents bigint;
  previous_cumulative_success_premium_cents bigint := 0;
  gross_success_requirement_cents bigint;
  incremental_exposure_cents bigint;
  cumulative_exposure_cents bigint;
  previous_cumulative_exposure_cents bigint := 0;
  uncapped_cumulative_exposure numeric;
  aggregate_cap numeric;
  expected_rationale text;
begin
  if schedule_status not in ('pending_review', 'approved')
     or jsonb_typeof(schedule_json) <> 'object'
     or schedule_json ->> 'policyVersion' <> 'mpgf_failure_bonus_success_premium_v0_1'
     or schedule_json ->> 'premiumPayer' <> 'pool_creator_or_sponsor'
     or jsonb_typeof(schedule_json -> 'premiumIncludedInNetRecipientThreshold') <> 'boolean'
     or (schedule_json ->> 'premiumIncludedInNetRecipientThreshold')::boolean <> false
     or schedule_json -> 'eligibilityPolicy' is distinct from eligibility_json
     or not public.mpgf_failure_bonus_eligibility_policy_valid(
       eligibility_json,
       max_participants,
       max_bonus_per_participant_cents
     )
     or verified_supporter_minimum < 1
     or verified_supporter_minimum > max_participants then
    return false;
  end if;

  thresholds_json := schedule_json -> 'thresholds';
  if jsonb_typeof(thresholds_json) <> 'array' then
    return false;
  end if;

  threshold_count := jsonb_array_length(thresholds_json);
  if threshold_count < 1 or threshold_count > 10 then
    return false;
  end if;

  aggregate_cap := max_participants::numeric * max_bonus_per_participant_cents::numeric;

  for threshold_item in
    select value
    from jsonb_array_elements(thresholds_json)
  loop
    current_index := current_index + 1;

    if jsonb_typeof(threshold_item) <> 'object'
       or jsonb_typeof(threshold_item -> 'thresholdIndex') <> 'number'
       or jsonb_typeof(threshold_item -> 'cumulativeNetRecipientThresholdCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'incrementalNetRecipientCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'premiumRateBps') <> 'number'
       or jsonb_typeof(threshold_item -> 'successPremiumCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'cumulativeSuccessPremiumCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'grossSuccessRequirementCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'provisional') <> 'boolean'
       or jsonb_typeof(threshold_item -> 'incrementalFailureBonusExposureCents') <> 'number'
       or jsonb_typeof(threshold_item -> 'maximumFailureBonusExposureCents') <> 'number' then
      return false;
    end if;

    threshold_id := threshold_item ->> 'thresholdId';
    if threshold_id is null
       or threshold_id = ''
       or threshold_id <> btrim(threshold_id)
       or threshold_id = any(threshold_ids) then
      return false;
    end if;
    threshold_ids := array_append(threshold_ids, threshold_id);

    if (threshold_item ->> 'thresholdIndex')::integer <> current_index
       or threshold_item ->> 'premiumPayer' <> 'pool_creator_or_sponsor'
       or jsonb_typeof(threshold_item -> 'premiumIncludedInNetRecipientThreshold') <> 'boolean'
       or (threshold_item ->> 'premiumIncludedInNetRecipientThreshold')::boolean <> false
       or threshold_item ->> 'pricingMode' <> 'experience_rated' then
      return false;
    end if;

    if schedule_status = 'pending_review' then
      expected_rationale := format(
        'Provisional threshold %s experience-rated quote; operator approval remains required.',
        current_index
      );
      if (threshold_item ->> 'provisional')::boolean <> true
         or threshold_item ->> 'rationale' <> expected_rationale then
        return false;
      end if;
    else
      if (threshold_item ->> 'provisional')::boolean <> false
         or btrim(coalesce(threshold_item ->> 'rationale', '')) = '' then
        return false;
      end if;
    end if;

    cumulative_net_cents :=
      (threshold_item ->> 'cumulativeNetRecipientThresholdCents')::bigint;
    incremental_net_cents :=
      (threshold_item ->> 'incrementalNetRecipientCents')::bigint;
    premium_rate_bps := (threshold_item ->> 'premiumRateBps')::integer;
    success_premium_cents := (threshold_item ->> 'successPremiumCents')::bigint;
    cumulative_success_premium_cents :=
      (threshold_item ->> 'cumulativeSuccessPremiumCents')::bigint;
    gross_success_requirement_cents :=
      (threshold_item ->> 'grossSuccessRequirementCents')::bigint;
    incremental_exposure_cents :=
      (threshold_item ->> 'incrementalFailureBonusExposureCents')::bigint;
    cumulative_exposure_cents :=
      (threshold_item ->> 'maximumFailureBonusExposureCents')::bigint;
    assumptions_json := threshold_item -> 'assumptions';

    if cumulative_net_cents <= previous_cumulative_net_cents
       or cumulative_net_cents > requested_maximum_funding_cents
       or incremental_net_cents <> cumulative_net_cents - previous_cumulative_net_cents
       or not public.mpgf_failure_bonus_provisional_pricing_valid(
         assumptions_json,
         failure_bonus_rate_bps,
         premium_rate_bps
       )
       or (assumptions_json ->> 'failureBonusRateBps')::integer <> failure_bonus_rate_bps
       or success_premium_cents < 1
       or success_premium_cents <>
         ((incremental_net_cents * premium_rate_bps::bigint) + 9999) / 10000
       or cumulative_success_premium_cents <>
         previous_cumulative_success_premium_cents + success_premium_cents
       or gross_success_requirement_cents <>
         cumulative_net_cents + cumulative_success_premium_cents then
      return false;
    end if;

    uncapped_cumulative_exposure :=
      ((cumulative_net_cents::numeric * failure_bonus_rate_bps::numeric) + 9999) / 10000;
    uncapped_cumulative_exposure := trunc(uncapped_cumulative_exposure);

    if cumulative_exposure_cents::numeric <>
         least(uncapped_cumulative_exposure, aggregate_cap)
       or incremental_exposure_cents <>
         cumulative_exposure_cents - previous_cumulative_exposure_cents
       or incremental_exposure_cents < 0 then
      return false;
    end if;

    if current_index = 1 and (
      cumulative_net_cents <> threshold_one_cents
      or premium_rate_bps <> threshold_one_premium_rate_bps
      or success_premium_cents <> threshold_one_premium_cents
      or gross_success_requirement_cents <> threshold_one_gross_cents
      or assumptions_json is distinct from threshold_one_pricing_json
    ) then
      return false;
    end if;

    previous_cumulative_net_cents := cumulative_net_cents;
    previous_cumulative_success_premium_cents := cumulative_success_premium_cents;
    previous_cumulative_exposure_cents := cumulative_exposure_cents;
  end loop;

  return current_index = threshold_count;
exception
  when others then
    return false;
end;
$$;



CREATE FUNCTION public.mpgf_finalize_dac_campaign(p_campaign_id text, p_reviewer_id uuid, p_reason text) RETURNS TABLE(outcome_id uuid, finalized_campaign_id text, finalized_pool_proposal_id uuid, finalized_terms_version integer, finalized_terms_sha256 text, outcome_status text, eligible_amount_cents bigint, eligible_supporter_count integer, threshold_amount_cents bigint, threshold_supporters integer, deadline_at timestamp with time zone, evaluated_at timestamp with time zone, expired_pledge_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  campaign_id_value text := btrim(coalesce(p_campaign_id, ''));
  reason_value text := btrim(coalesce(p_reason, ''));
  evaluated_at_value timestamptz := clock_timestamp();
  campaign_row public.mpgf_public_goods_campaigns%rowtype;
  proposal_row public.mpgf_pool_proposals%rowtype;
  existing_outcome public.mpgf_dac_campaign_outcomes%rowtype;
  pledge_row public.mpgf_public_goods_pledges%rowtype;
  outcome_id_value uuid := gen_random_uuid();
  outcome_status_value text;
  eligible_amount_value bigint := 0;
  eligible_supporter_value integer := 0;
  expired_pledge_count_value integer := 0;
  outcome_value jsonb;
  expiry_event_value jsonb;
begin
  if campaign_id_value = '' then
    raise exception using errcode = '22023', message = 'A DAC campaign is required.';
  end if;
  if reason_value = '' then
    raise exception using
      errcode = '22023',
      message = 'A terminal-outcome rationale is required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(campaign_id_value || ':dac-terminal-outcome', 0)
  );

  select * into campaign_row
  from public.mpgf_public_goods_campaigns as campaign
  where campaign.id = campaign_id_value
  for update;

  if campaign_row.id is null
     or campaign_row.pool_proposal_id is null
     or campaign_row.published_terms_version is null
     or campaign_row.published_terms_sha256 is null
     or campaign_row.published_at is null then
    raise exception using
      errcode = 'P0002',
      message = 'A published proposal-bound DAC campaign was not found.';
  end if;

  select * into proposal_row
  from public.mpgf_pool_proposals as proposal
  where proposal.id = campaign_row.pool_proposal_id
  for update;

  if proposal_row.id is null then
    raise exception using
      errcode = 'P0002',
      message = 'The published DAC proposal was not found.';
  end if;

  perform public.mpgf_assert_authorized_pool_reviewer(
    p_reviewer_id,
    proposal_row.id
  );

  select * into existing_outcome
  from public.mpgf_dac_campaign_outcomes as outcome
  where outcome.campaign_id = campaign_row.id;

  if existing_outcome.id is not null then
    if campaign_row.review_status <> 'finalized'
       or proposal_row.status is distinct from existing_outcome.outcome_status
       or existing_outcome.pool_proposal_id is distinct from proposal_row.id
       or existing_outcome.terms_version is distinct from campaign_row.published_terms_version
       or existing_outcome.terms_sha256 is distinct from campaign_row.published_terms_sha256 then
      raise exception using
        errcode = '23514',
        message = 'The existing DAC outcome disagrees with current terminal campaign state.';
    end if;

    select count(*)::integer into expired_pledge_count_value
    from public.mpgf_public_goods_pledges as pledge
    where pledge.campaign_id = campaign_row.id
      and pledge.pledge_intent_id is not null
      and pledge.status = 'expired';

    return query select
      existing_outcome.id,
      existing_outcome.campaign_id,
      existing_outcome.pool_proposal_id,
      existing_outcome.terms_version,
      existing_outcome.terms_sha256,
      existing_outcome.outcome_status,
      existing_outcome.eligible_amount_cents,
      existing_outcome.eligible_supporter_count,
      existing_outcome.threshold_amount_cents,
      existing_outcome.threshold_supporters,
      existing_outcome.deadline_at,
      existing_outcome.evaluated_at,
      expired_pledge_count_value;
    return;
  end if;

  if campaign_row.review_status <> 'approved'
     or proposal_row.status <> 'approved_as_candidate'
     or proposal_row.public_goods_failure_bonus_enabled is distinct from true
     or proposal_row.public_goods_failure_bonus_schedule_status <> 'approved'
     or proposal_row.public_goods_success_premium_provisional is distinct from false
     or proposal_row.approved_terms_version is distinct from campaign_row.published_terms_version
     or proposal_row.operative_terms_sha256 is distinct from campaign_row.published_terms_sha256
     or proposal_row.terms_locked_at is null
     or proposal_row.public_goods_deadline_at is distinct from campaign_row.deadline_at
     or proposal_row.public_goods_threshold_amount_cents is distinct from campaign_row.threshold_amount_cents
     or proposal_row.public_goods_threshold_supporters is distinct from campaign_row.threshold_supporters then
    raise exception using
      errcode = '23514',
      message = 'Only a live DAC campaign matching its approved frozen proposal can be finalized.';
  end if;

  if not exists (
    select 1
    from public.mpgf_pool_proposal_versions as proposal_version
    where proposal_version.proposal_id = proposal_row.id
      and proposal_version.terms_version = campaign_row.published_terms_version
      and proposal_version.terms_sha256 = campaign_row.published_terms_sha256
  ) then
    raise exception using
      errcode = '23514',
      message = 'The DAC campaign is missing its immutable approved proposal version.';
  end if;

  if exists (
    select 1
    from public.mpgf_public_goods_pledges as pledge
    where pledge.campaign_id = campaign_row.id
      and pledge.pledge_intent_id is not null
      and (
        pledge.pool_proposal_id is distinct from proposal_row.id
        or pledge.terms_version is distinct from campaign_row.published_terms_version
        or pledge.terms_sha256 is distinct from campaign_row.published_terms_sha256
        or pledge.accepted_at is null
        or pledge.accepted_at > campaign_row.deadline_at
        or pledge.expires_at is distinct from campaign_row.deadline_at
        or pledge.capture_mode <> 'signed_intent'
        or pledge.is_recurring
      )
  ) then
    raise exception using
      errcode = '23514',
      message = 'A DAC pledge differs from the exact published campaign terms.';
  end if;

  if exists (
    select 1
    from public.mpgf_public_goods_pledges as pledge
    where pledge.campaign_id = campaign_row.id
      and pledge.pledge_intent_id is not null
      and (
        pledge.payment_intent_ref is not null
        or pledge.status = 'captured'
      )
  ) then
    raise exception using
      errcode = '23514',
      message = 'This no-payment finalization tranche cannot process a charged or captured DAC pledge.';
  end if;

  if exists (
    select 1
    from public.mpgf_public_goods_pledges as pledge
    left join public.mpgf_dac_pledge_intents as intent
      on intent.id = pledge.pledge_intent_id
    where pledge.campaign_id = campaign_row.id
      and pledge.pledge_intent_id is not null
      and (
        intent.id is null
        or intent.campaign_id is distinct from pledge.campaign_id
        or intent.pool_proposal_id is distinct from pledge.pool_proposal_id
        or intent.terms_version is distinct from pledge.terms_version
        or intent.terms_sha256 is distinct from pledge.terms_sha256
        or intent.profile_id is distinct from pledge.profile_id
        or intent.amount_cents is distinct from pledge.amount_cents
        or intent.currency is distinct from pledge.currency
        or intent.visibility_mode is distinct from pledge.visibility_mode
        or intent.supporter_reason is distinct from pledge.supporter_reason
        or intent.accepted_at is distinct from pledge.accepted_at
        or pledge.eligibility_state = 'pending_review'
        or not exists (
          select 1
          from public.mpgf_dac_pledge_events as eligibility_event
          where eligibility_event.pledge_id = pledge.id
            and eligibility_event.pledge_intent_id = pledge.pledge_intent_id
            and eligibility_event.campaign_id = pledge.campaign_id
            and eligibility_event.pool_proposal_id = pledge.pool_proposal_id
            and eligibility_event.profile_id = pledge.profile_id
            and eligibility_event.event_type = 'eligibility_reviewed'
            and eligibility_event.terms_version = pledge.terms_version
            and eligibility_event.terms_sha256 = pledge.terms_sha256
            and eligibility_event.amount_cents = pledge.amount_cents
            and eligibility_event.currency = pledge.currency
            and eligibility_event.event_sha256 =
              public.mpgf_dac_json_sha256(eligibility_event.event_json)
            and eligibility_event.event_json ->> 'toEligibilityState' =
              pledge.eligibility_state
            and (eligibility_event.event_json ->> 'humanScoreBps')::integer =
              pledge.human_score_bps
        )
      )
  ) then
    raise exception using
      errcode = '23514',
      message = 'Every DAC pledge must have a final audited eligibility decision bound to its immutable consent intent before finalization.';
  end if;

  select
    coalesce(sum(pledge.amount_cents), 0)::bigint,
    count(distinct pledge.profile_id)::integer
  into eligible_amount_value, eligible_supporter_value
  from public.mpgf_public_goods_pledges as pledge
  where pledge.campaign_id = campaign_row.id
    and pledge.pledge_intent_id is not null
    and pledge.pool_proposal_id = proposal_row.id
    and pledge.terms_version = campaign_row.published_terms_version
    and pledge.terms_sha256 = campaign_row.published_terms_sha256
    and pledge.eligibility_state = 'eligible'
    and pledge.status = 'pledged'
    and pledge.accepted_at <= campaign_row.deadline_at
    and pledge.expires_at = campaign_row.deadline_at;

  if eligible_amount_value >= campaign_row.threshold_amount_cents
     and eligible_supporter_value >= campaign_row.threshold_supporters then
    outcome_status_value := 'succeeded';
  elsif evaluated_at_value >= campaign_row.deadline_at then
    outcome_status_value := 'lapsed';
  else
    raise exception using
      errcode = '23514',
      message = 'The DAC threshold is unmet and its deadline has not arrived.';
  end if;

  outcome_value := jsonb_build_object(
    'schemaVersion', 'mpgf_dac_campaign_outcome_v1',
    'mechanism', 'dominant_assurance_contract',
    'outcomeStatus', outcome_status_value,
    'campaignId', campaign_row.id,
    'poolProposalId', proposal_row.id,
    'termsVersion', campaign_row.published_terms_version,
    'termsSha256', campaign_row.published_terms_sha256,
    'eligibleAmountCents', eligible_amount_value,
    'eligibleSupporterCount', eligible_supporter_value,
    'thresholdAmountCents', campaign_row.threshold_amount_cents,
    'thresholdSupporters', campaign_row.threshold_supporters,
    'deadlineAt', campaign_row.deadline_at,
    'evaluatedAt', evaluated_at_value,
    'finalizedBy', p_reviewer_id,
    'reason', reason_value,
    'pledgeDisposition',
      case
        when outcome_status_value = 'lapsed'
          then 'expired_without_payment'
        else 'active_signed_intents_preserved_no_payment'
      end,
    'payment', jsonb_build_object(
      'authorized', false,
      'mandateCreated', false,
      'charged', false,
      'captured', false,
      'settled', false,
      'failureBonusPaid', false
    )
  );

  insert into public.mpgf_dac_campaign_outcomes (
    id,
    campaign_id,
    pool_proposal_id,
    terms_version,
    terms_sha256,
    outcome_status,
    eligible_amount_cents,
    eligible_supporter_count,
    threshold_amount_cents,
    threshold_supporters,
    deadline_at,
    evaluated_at,
    finalized_by,
    reason,
    outcome_json,
    outcome_sha256,
    created_at
  ) values (
    outcome_id_value,
    campaign_row.id,
    proposal_row.id,
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    outcome_status_value,
    eligible_amount_value,
    eligible_supporter_value,
    campaign_row.threshold_amount_cents,
    campaign_row.threshold_supporters,
    campaign_row.deadline_at,
    evaluated_at_value,
    p_reviewer_id,
    reason_value,
    outcome_value,
    public.mpgf_dac_json_sha256(outcome_value),
    evaluated_at_value
  );

  if outcome_status_value = 'lapsed' then
    for pledge_row in
      select *
      from public.mpgf_public_goods_pledges as pledge
      where pledge.campaign_id = campaign_row.id
        and pledge.pledge_intent_id is not null
        and pledge.status = 'pledged'
      order by pledge.id
      for update
    loop
      perform set_config(
        'app.mpgf_dac_internal_write',
        pledge_row.pledge_intent_id::text,
        true
      );

      update public.mpgf_public_goods_pledges
      set status = 'expired'
      where id = pledge_row.id;

      expiry_event_value := jsonb_build_object(
        'schemaVersion', 'mpgf_dac_pledge_event_v1',
        'eventType', 'pledge_expired',
        'pledgeIntentId', pledge_row.pledge_intent_id,
        'pledgeId', pledge_row.id,
        'campaignId', pledge_row.campaign_id,
        'poolProposalId', pledge_row.pool_proposal_id,
        'profileId', pledge_row.profile_id,
        'termsVersion', pledge_row.terms_version,
        'termsSha256', pledge_row.terms_sha256,
        'amountCents', pledge_row.amount_cents,
        'currency', pledge_row.currency,
        'fromPledgeStatus', pledge_row.status,
        'toPledgeStatus', 'expired',
        'outcomeId', outcome_id_value,
        'outcomeStatus', outcome_status_value,
        'reason', reason_value,
        'paymentAuthorized', false,
        'expiredAt', evaluated_at_value
      );

      insert into public.mpgf_dac_pledge_events (
        pledge_intent_id,
        pledge_id,
        campaign_id,
        pool_proposal_id,
        profile_id,
        event_type,
        terms_version,
        terms_sha256,
        amount_cents,
        currency,
        event_json,
        event_sha256,
        created_at
      ) values (
        pledge_row.pledge_intent_id,
        pledge_row.id,
        pledge_row.campaign_id,
        pledge_row.pool_proposal_id,
        pledge_row.profile_id,
        'pledge_expired',
        pledge_row.terms_version,
        pledge_row.terms_sha256,
        pledge_row.amount_cents,
        pledge_row.currency,
        expiry_event_value,
        public.mpgf_dac_json_sha256(expiry_event_value),
        evaluated_at_value
      );

      expired_pledge_count_value := expired_pledge_count_value + 1;
    end loop;

    perform set_config('app.mpgf_dac_internal_write', '', true);
  end if;

  perform set_config(
    'app.mpgf_pool_review_transition',
    proposal_row.id::text,
    true
  );

  update public.mpgf_pool_proposals
  set status = outcome_status_value
  where id = proposal_row.id;

  perform set_config('app.mpgf_pool_review_transition', '', true);

  perform set_config(
    'app.mpgf_dac_campaign_finalization',
    campaign_row.id,
    true
  );

  update public.mpgf_public_goods_campaigns
  set review_status = 'finalized'
  where id = campaign_row.id;

  perform set_config('app.mpgf_dac_campaign_finalization', '', true);

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id,
    terms_version,
    event_type,
    actor_user_id,
    from_status,
    to_status,
    terms_sha256,
    reason,
    metadata_json
  ) values (
    proposal_row.id,
    campaign_row.published_terms_version,
    case
      when outcome_status_value = 'succeeded' then 'pool_succeeded'
      else 'pool_lapsed'
    end,
    p_reviewer_id,
    proposal_row.status,
    outcome_status_value,
    campaign_row.published_terms_sha256,
    reason_value,
    jsonb_build_object(
      'outcomeId', outcome_id_value,
      'campaignId', campaign_row.id,
      'eligibleAmountCents', eligible_amount_value,
      'eligibleSupporterCount', eligible_supporter_value,
      'thresholdAmountCents', campaign_row.threshold_amount_cents,
      'thresholdSupporters', campaign_row.threshold_supporters,
      'deadlineAt', campaign_row.deadline_at,
      'evaluatedAt', evaluated_at_value,
      'expiredPledgeCount', expired_pledge_count_value,
      'paymentAuthorized', false
    )
  );

  return query select
    outcome_id_value,
    campaign_row.id,
    proposal_row.id,
    campaign_row.published_terms_version,
    campaign_row.published_terms_sha256,
    outcome_status_value,
    eligible_amount_value,
    eligible_supporter_value,
    campaign_row.threshold_amount_cents,
    campaign_row.threshold_supporters,
    campaign_row.deadline_at,
    evaluated_at_value,
    expired_pledge_count_value;
end;
$$;



CREATE FUNCTION public.mpgf_freeze_failure_bonus_terms_after_acceptance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if old.first_accepted_pledge_at is not null and (
    new.public_goods_threshold_amount_cents is distinct from old.public_goods_threshold_amount_cents
    or new.public_goods_failure_bonus_enabled is distinct from old.public_goods_failure_bonus_enabled
    or new.public_goods_failure_bonus_rate_bps is distinct from old.public_goods_failure_bonus_rate_bps
    or new.public_goods_threshold_schedule_json is distinct from old.public_goods_threshold_schedule_json
    or new.public_goods_failure_bonus_eligibility_json is distinct from old.public_goods_failure_bonus_eligibility_json
    or new.public_goods_failure_bonus_max_participants is distinct from old.public_goods_failure_bonus_max_participants
    or new.public_goods_failure_bonus_max_per_participant_cents is distinct from old.public_goods_failure_bonus_max_per_participant_cents
    or new.public_goods_failure_bonus_schedule_status is distinct from old.public_goods_failure_bonus_schedule_status
    or new.public_goods_success_premium_rate_bps is distinct from old.public_goods_success_premium_rate_bps
    or new.public_goods_success_premium_cents is distinct from old.public_goods_success_premium_cents
    or new.public_goods_success_premium_payer is distinct from old.public_goods_success_premium_payer
    or new.public_goods_success_premium_policy_version is distinct from old.public_goods_success_premium_policy_version
    or new.public_goods_success_premium_included_in_net_threshold is distinct from old.public_goods_success_premium_included_in_net_threshold
    or new.public_goods_success_premium_provisional is distinct from old.public_goods_success_premium_provisional
    or new.public_goods_gross_success_requirement_cents is distinct from old.public_goods_gross_success_requirement_cents
    or new.public_goods_success_premium_pricing_json is distinct from old.public_goods_success_premium_pricing_json
  ) then
    raise exception using
      errcode = '23514',
      message = 'Failure-bonus formula, eligibility, caps, and thresholds cannot change after the first accepted pledge.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.mpgf_freeze_proposal_with_approved_premium_quote() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new is not distinct from old then
    return new;
  end if;

  if exists (
    select 1
    from public.mpgf_failure_bonus_premium_quotes quote
    where quote.pool_proposal_id = old.id
      and quote.status = 'approved'
  ) then
    raise exception 'Create a new proposal version before changing approved failure-bonus premium terms.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_guard_dac_public_goods_pledge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  campaign_is_dac boolean := false;
  trusted_writer boolean := false;
  internal_write_token text := current_setting('app.mpgf_dac_internal_write', true);
begin
  trusted_writer :=
    auth.role() = 'service_role'
    or (auth.uid() is null and current_user in ('postgres', 'supabase_admin'))
    or (
      tg_op <> 'DELETE'
      and new.pledge_intent_id is not null
      and internal_write_token = new.pledge_intent_id::text
    );

  if tg_op = 'DELETE' then
    if old.pledge_intent_id is not null then
      raise exception using
        errcode = '23514',
        message = 'A DAC pledge cannot be deleted.';
    end if;
    return old;
  end if;

  select coalesce(proposal.public_goods_failure_bonus_enabled, false)
  into campaign_is_dac
  from public.mpgf_public_goods_campaigns as campaign
  join public.mpgf_pool_proposals as proposal
    on proposal.id = campaign.pool_proposal_id
  where campaign.id = new.campaign_id
    and campaign.review_status in ('approved', 'finalized')
    and campaign.published_terms_version is not null
    and campaign.published_terms_sha256 is not null;

  if campaign_is_dac and new.pledge_intent_id is null then
    raise exception using
      errcode = '23514',
      message = 'Published DAC campaigns accept pledges only through an immutable pledge intent.';
  end if;

  if new.pledge_intent_id is not null and not trusted_writer then
    raise exception using
      errcode = '42501',
      message = 'DAC pledge rows can be created or changed only through the authorized lifecycle.';
  end if;

  if tg_op = 'UPDATE' and old.pledge_intent_id is not null then
    if new.pledge_intent_id is distinct from old.pledge_intent_id
       or new.campaign_id is distinct from old.campaign_id
       or new.profile_id is distinct from old.profile_id
       or new.user_ref is distinct from old.user_ref
       or new.amount_cents is distinct from old.amount_cents
       or new.currency is distinct from old.currency
       or new.visibility_mode is distinct from old.visibility_mode
       or new.is_recurring is distinct from old.is_recurring
       or new.capture_mode is distinct from old.capture_mode
       or new.supporter_reason is distinct from old.supporter_reason
       or new.pool_proposal_id is distinct from old.pool_proposal_id
       or new.terms_version is distinct from old.terms_version
       or new.terms_sha256 is distinct from old.terms_sha256
       or new.accepted_at is distinct from old.accepted_at
       or new.expires_at is distinct from old.expires_at then
      raise exception using
        errcode = '23514',
        message = 'A DAC pledge''s identity, amount, consent, campaign, and frozen terms cannot change.';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_guard_pool_review_fields_and_frozen_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  transition_authorized boolean :=
    current_user not in ('anon', 'authenticated')
    and current_setting('app.mpgf_pool_review_transition', true) = old.id::text;
  old_material jsonb;
  new_material jsonb;
begin
  if new.id is distinct from old.id
     or new.proposer_id is distinct from old.proposer_id
     or new.created_at is distinct from old.created_at
     or new.submitted_at is distinct from old.submitted_at then
    raise exception using errcode = '42501', message = 'Pool proposal identity and submission metadata are immutable.';
  end if;

  if current_user in ('anon', 'authenticated') and (
    new.first_accepted_pledge_at is distinct from old.first_accepted_pledge_at
    or new.candidate_alternative_id is distinct from old.candidate_alternative_id
  ) then
    raise exception using errcode = '42501', message = 'Pool system fields may change only through an authorized service path.';
  end if;

  if not transition_authorized and (
    new.status is distinct from old.status
    or new.terms_version is distinct from old.terms_version
    or new.approved_terms_version is distinct from old.approved_terms_version
    or new.operative_terms_sha256 is distinct from old.operative_terms_sha256
    or new.terms_locked_at is distinct from old.terms_locked_at
    or new.reviewed_by is distinct from old.reviewed_by
    or new.reviewed_at is distinct from old.reviewed_at
    or new.review_reason is distinct from old.review_reason
    or new.supersedes_proposal_id is distinct from old.supersedes_proposal_id
  ) then
    raise exception using errcode = '42501', message = 'Pool review state may change only through an authorized lifecycle function.';
  end if;

  if old.status in ('under_review', 'changes_requested', 'approved_as_candidate', 'rejected')
     or old.terms_locked_at is not null then
    old_material := to_jsonb(old)
      - 'status'
      - 'candidate_alternative_id'
      - 'first_accepted_pledge_at'
      - 'progress_visibility'
      - 'reviewed_by'
      - 'reviewed_at'
      - 'review_reason'
      - 'approved_terms_version'
      - 'operative_terms_sha256'
      - 'terms_locked_at';
    new_material := to_jsonb(new)
      - 'status'
      - 'candidate_alternative_id'
      - 'first_accepted_pledge_at'
      - 'progress_visibility'
      - 'reviewed_by'
      - 'reviewed_at'
      - 'review_reason'
      - 'approved_terms_version'
      - 'operative_terms_sha256'
      - 'terms_locked_at';

    if new_material is distinct from old_material then
      raise exception using errcode = '23514', message = 'Pool proposal terms are immutable after review begins; submit a new version instead.';
    end if;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_guard_published_pool_campaign() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  finalization_token text :=
    current_setting('app.mpgf_dac_campaign_finalization', true);
  status_writer boolean := current_user not in ('anon', 'authenticated');
begin
  if tg_op = 'DELETE' then
    if old.pool_proposal_id is not null then
      raise exception using
        errcode = '23514',
        message = 'A published MPGF pool campaign cannot be deleted; use an audited lifecycle status transition.';
    end if;
    return old;
  end if;

  if old.pool_proposal_id is not null and (
    new.id is distinct from old.id
    or new.round_id is distinct from old.round_id
    or new.slug is distinct from old.slug
    or new.pool_alternative_id is distinct from old.pool_alternative_id
    or new.title is distinct from old.title
    or new.destination_type is distinct from old.destination_type
    or new.destination_ref is distinct from old.destination_ref
    or new.cause_tags is distinct from old.cause_tags
    or new.public_summary is distinct from old.public_summary
    or new.threshold_amount_cents is distinct from old.threshold_amount_cents
    or new.threshold_supporters is distinct from old.threshold_supporters
    or new.deadline_at is distinct from old.deadline_at
    or new.verification_method is distinct from old.verification_method
    or new.baseline_rule is distinct from old.baseline_rule
    or new.exit_rule is distinct from old.exit_rule
    or new.pool_proposal_id is distinct from old.pool_proposal_id
    or new.threshold_visibility is distinct from old.threshold_visibility
    or new.published_terms_version is distinct from old.published_terms_version
    or new.published_terms_sha256 is distinct from old.published_terms_sha256
    or new.published_by is distinct from old.published_by
    or new.published_at is distinct from old.published_at
    or new.created_at is distinct from old.created_at
  ) then
    raise exception using
      errcode = '23514',
      message = 'Published MPGF campaign identity and operative terms are immutable.';
  end if;

  if old.pool_proposal_id is not null
     and new.review_status is distinct from old.review_status
     and not status_writer then
    raise exception using
      errcode = '42501',
      message = 'Published pool campaign status may change only through an authorized service lifecycle.';
  end if;

  if old.pool_proposal_id is not null
     and old.review_status = 'finalized'
     and new.review_status is distinct from 'finalized' then
    raise exception using
      errcode = '23514',
      message = 'A finalized DAC campaign cannot return to a nonterminal state.';
  end if;

  if old.pool_proposal_id is not null
     and old.review_status is distinct from 'finalized'
     and new.review_status = 'finalized'
     and finalization_token is distinct from old.id then
    raise exception using
      errcode = '42501',
      message = 'A DAC campaign can be finalized only through the audited terminal-outcome function.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_latch_pool_proposal_accepted_pledge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.pool_proposal_id is not null
     and new.status in ('pledged', 'converted_to_payment_intent') then
    update public.mpgf_pool_proposals
    set first_accepted_pledge_at = coalesce(
      first_accepted_pledge_at,
      new.created_at,
      timezone('utc', now())
    )
    where id = new.pool_proposal_id
      and first_accepted_pledge_at is null;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_latch_public_goods_campaign_accepted_pledge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  accepted_at timestamptz;
begin
  if new.eligibility_state::text <> 'eligible'
     or new.status::text not in ('pledged', 'captured') then
    return new;
  end if;

  if to_regclass('public.mpgf_public_goods_campaigns') is null then
    return new;
  end if;

  accepted_at := coalesce(new.created_at, timezone('utc', now()));

  execute $sql$
    update public.mpgf_public_goods_campaigns
    set first_accepted_pledge_at = coalesce(first_accepted_pledge_at, $2)
    where id = $1
      and first_accepted_pledge_at is null
  $sql$
  using new.campaign_id, accepted_at;

  execute $sql$
    update public.mpgf_pool_proposals proposal
    set first_accepted_pledge_at = coalesce(proposal.first_accepted_pledge_at, $2)
    from public.mpgf_public_goods_campaigns campaign
    where campaign.id = $1
      and proposal.first_accepted_pledge_at is null
      and (
        campaign.pool_proposal_id = proposal.id
        or (
          campaign.pool_proposal_id is null
          and campaign.pool_alternative_id is not null
          and proposal.candidate_alternative_id = campaign.pool_alternative_id
        )
      )
  $sql$
  using new.campaign_id, accepted_at;

  return new;
end;
$_$;



CREATE FUNCTION public.mpgf_link_pool_proposal_revision(p_prior_proposal_id uuid, p_new_proposal_id uuid, p_actor_id uuid, p_reason text) RETURNS TABLE(proposal_id uuid, terms_version integer, terms_sha256 text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  prior_row public.mpgf_pool_proposals%rowtype;
  new_row public.mpgf_pool_proposals%rowtype;
  terms_hash text;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A revision rationale is required.';
  end if;

  select * into prior_row
  from public.mpgf_pool_proposals
  where id = p_prior_proposal_id
  for update;
  select * into new_row
  from public.mpgf_pool_proposals
  where id = p_new_proposal_id
  for update;

  if prior_row.id is null or new_row.id is null then
    raise exception using errcode = 'P0002', message = 'Both prior and new pool proposals are required.';
  end if;
  if prior_row.status <> 'changes_requested'
     or new_row.status <> 'submitted'
     or prior_row.proposer_id <> p_actor_id
     or new_row.proposer_id <> p_actor_id
     or new_row.supersedes_proposal_id is not null
     or prior_row.first_accepted_pledge_at is not null
     or new_row.first_accepted_pledge_at is not null then
    raise exception using errcode = '23514', message = 'Pool proposal revision linkage is not allowed for these records.';
  end if;

  perform set_config('app.mpgf_pool_review_transition', p_new_proposal_id::text, true);
  update public.mpgf_pool_proposals
  set supersedes_proposal_id = p_prior_proposal_id,
      terms_version = prior_row.terms_version + 1
  where id = p_new_proposal_id;
  perform set_config('app.mpgf_pool_review_transition', '', true);

  terms_hash := public.mpgf_record_pool_proposal_version(
    p_new_proposal_id,
    p_actor_id,
    'revision_submitted: ' || btrim(p_reason)
  );

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id, terms_version, event_type, actor_user_id,
    from_status, to_status, terms_sha256, reason,
    metadata_json
  ) values (
    p_new_proposal_id, prior_row.terms_version + 1, 'revision_submitted', p_actor_id,
    'changes_requested', 'submitted', terms_hash, btrim(p_reason),
    jsonb_build_object('supersedesProposalId', p_prior_proposal_id)
  );

  return query select p_new_proposal_id, prior_row.terms_version + 1, terms_hash, 'submitted'::text;
end;
$$;



CREATE FUNCTION public.mpgf_pledge_impact_bundle_at(p_pool_public_key text, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  live_pool_state jsonb;
  live_pool_state_sha256 text;
  latest_snapshot record;
  status_value text;
  release_value jsonb := null;
begin
  live_pool_state := public.mpgf_pledge_impact_live_pool_state(
    p_pool_public_key,
    p_at
  );
  if live_pool_state is null then
    return jsonb_build_object(
      'status', 'pool_not_live',
      'checkedAt', to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'poolPublicKey', p_pool_public_key,
      'poolState', null,
      'poolStateSha256', null,
      'forecastRelease', null
    );
  end if;

  live_pool_state_sha256 := public.mpgf_pledge_impact_sha256(live_pool_state);

  select
    id,
    forecast_version,
    model_version,
    released_at,
    expires_at,
    pool_state_sha256,
    forecast_json
  into latest_snapshot
  from public.mpgf_pledge_impact_forecast_snapshots
  where pool_public_key = p_pool_public_key
    and released_at <= p_at + interval '5 minutes'
  order by released_at desc
  limit 1;

  if not found then
    status_value := 'forecast_not_released';
  elsif latest_snapshot.expires_at <= p_at then
    status_value := 'forecast_stale';
  elsif latest_snapshot.pool_state_sha256 <> live_pool_state_sha256 then
    status_value := 'pool_state_mismatch';
  else
    status_value := 'available';
    release_value := jsonb_build_object(
      'id', latest_snapshot.id,
      'forecastVersion', latest_snapshot.forecast_version,
      'modelVersion', latest_snapshot.model_version,
      'releasedAt', to_char(
        latest_snapshot.released_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
      ),
      'expiresAt', to_char(
        latest_snapshot.expires_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
      ),
      'poolStateSha256', latest_snapshot.pool_state_sha256,
      'forecast', latest_snapshot.forecast_json
    );
  end if;

  return jsonb_build_object(
    'status', status_value,
    'checkedAt', to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'poolPublicKey', p_pool_public_key,
    'poolState', live_pool_state,
    'poolStateSha256', live_pool_state_sha256,
    'forecastRelease', release_value
  );
end;
$$;



CREATE FUNCTION public.mpgf_pledge_impact_contains_personalization(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case jsonb_typeof(value)
    when 'object' then exists (
      select 1
      from jsonb_each(value) as item(key, child)
      where lower(regexp_replace(item.key, '[^a-zA-Z0-9_]', '', 'g')) = any (array[
        'userid', 'user_id', 'profileid', 'profile_id', 'viewerid', 'viewer_id',
        'email', 'demographic', 'demographics', 'paymenthistory', 'payment_history',
        'sharingpropensity', 'sharing_propensity', 'individualhistory', 'individual_history'
      ])
      or public.mpgf_pledge_impact_contains_personalization(item.child)
    )
    when 'array' then exists (
      select 1
      from jsonb_array_elements(value) as item(child)
      where public.mpgf_pledge_impact_contains_personalization(item.child)
    )
    else false
  end;
$$;



CREATE FUNCTION public.mpgf_pledge_impact_forecast_shape_valid(forecast_json jsonb, live_pool_state jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  points_json jsonb;
  point_item jsonb;
  previous_pledge_cents bigint := -1;
  current_pledge_cents bigint;
  expected_threshold_count integer;
begin
  if jsonb_typeof(forecast_json) <> 'object'
     or forecast_json ->> 'schemaVersion' <> 'mpgf_pledge_impact_forecast_v1'
     or forecast_json ->> 'audience' <> 'pool_state'
     or forecast_json ->> 'currency' <> 'USD'
     or jsonb_typeof(forecast_json -> 'experimental') <> 'boolean'
     or (forecast_json ->> 'experimental')::boolean <> true
     or jsonb_typeof(forecast_json -> 'forecastErrorFloorBps') <> 'number'
     or (forecast_json ->> 'forecastErrorFloorBps')::integer not between 0 and 10000
     or jsonb_typeof(forecast_json -> 'followOnEffect') <> 'object'
     or jsonb_typeof(forecast_json -> 'modelPerformance') <> 'object'
     or public.mpgf_pledge_impact_contains_personalization(forecast_json) then
    return false;
  end if;

  points_json := forecast_json -> 'points';
  if jsonb_typeof(points_json) <> 'array'
     or jsonb_array_length(points_json) < 2
     or jsonb_array_length(points_json) > 256 then
    return false;
  end if;

  expected_threshold_count := jsonb_array_length(live_pool_state -> 'thresholds');
  for point_item in select value from jsonb_array_elements(points_json)
  loop
    if jsonb_typeof(point_item) <> 'object'
       or jsonb_typeof(point_item -> 'pledgeCents') <> 'number'
       or jsonb_typeof(point_item -> 'additionalFundingFromOthers') <> 'object'
       or jsonb_typeof(point_item -> 'allocatedFundingCredit') <> 'object'
       or jsonb_typeof(point_item -> 'thresholds') <> 'array'
       or jsonb_array_length(point_item -> 'thresholds') <> expected_threshold_count
       or jsonb_typeof(point_item -> 'decomposition') <> 'object' then
      return false;
    end if;
    current_pledge_cents := (point_item ->> 'pledgeCents')::bigint;
    if current_pledge_cents < 0
       or current_pledge_cents <= previous_pledge_cents then
      return false;
    end if;
    previous_pledge_cents := current_pledge_cents;
  end loop;

  return ((points_json -> 0 ->> 'pledgeCents')::bigint = 0);
exception
  when others then
    return false;
end;
$$;



CREATE FUNCTION public.mpgf_pledge_impact_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'Released pledge-impact forecasts and audit events are immutable.'
    using errcode = '23514';
end;
$$;



CREATE FUNCTION public.mpgf_pledge_impact_live_pool_state(p_pool_public_key text, p_at timestamp with time zone DEFAULT timezone('utc'::text, now())) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  proposal record;
  funded_cents bigint := 0;
  contributor_count integer := 0;
  thresholds_json jsonb;
  failure_bonus_json jsonb;
begin
  if p_pool_public_key is null
     or p_pool_public_key !~ '^(pool|qa-pool)-[a-z0-9-]{3,96}$' then
    return null;
  end if;

  select
    mapping.pool_public_key,
    mapping.pool_proposal_id,
    mapping.release_environment,
    pool.title,
    pool.cause_area,
    pool.status,
    pool.threshold_visibility::text as threshold_visibility,
    pool.progress_visibility::text as progress_visibility,
    pool.public_goods_destination_type,
    pool.public_goods_destination_ref,
    pool.public_goods_threshold_amount_cents,
    pool.public_goods_threshold_supporters,
    pool.public_goods_deadline_at,
    pool.public_goods_failure_bonus_enabled,
    pool.public_goods_failure_bonus_rate_bps,
    pool.public_goods_threshold_schedule_json,
    pool.public_goods_failure_bonus_max_participants,
    pool.public_goods_failure_bonus_max_per_participant_cents,
    pool.public_goods_failure_bonus_schedule_status,
    pool.public_goods_success_premium_rate_bps,
    pool.public_goods_success_premium_cents,
    pool.public_goods_gross_success_requirement_cents
  into proposal
  from public.mpgf_pledge_impact_pool_map as mapping
  join public.mpgf_pool_proposals as pool
    on pool.id = mapping.pool_proposal_id
  where mapping.pool_public_key = p_pool_public_key
    and mapping.active = true;

  if not found
     or proposal.status <> 'approved_as_candidate'
     or proposal.threshold_visibility <> 'public_exact'
     or proposal.progress_visibility <> 'exact_amount'
     or proposal.public_goods_destination_type not in (
       'external_charity', 'fiscal_host', 'signed_sponsor_route'
     )
     or btrim(coalesce(proposal.public_goods_destination_ref, '')) = ''
     or proposal.public_goods_destination_ref ilike '%demo%'
     or proposal.public_goods_threshold_amount_cents is null
     or proposal.public_goods_threshold_amount_cents <= 0
     or proposal.public_goods_threshold_supporters is null
     or proposal.public_goods_threshold_supporters <= 0
     or proposal.public_goods_deadline_at is null
     or proposal.public_goods_deadline_at <= p_at then
    return null;
  end if;

  if proposal.public_goods_failure_bonus_enabled then
    if proposal.public_goods_failure_bonus_schedule_status <> 'approved'
       or jsonb_typeof(proposal.public_goods_threshold_schedule_json) <> 'object'
       or jsonb_typeof(proposal.public_goods_threshold_schedule_json -> 'thresholds') <> 'array'
       or jsonb_array_length(proposal.public_goods_threshold_schedule_json -> 'thresholds') < 1 then
      return null;
    end if;

    select jsonb_agg(
      jsonb_build_object(
        'thresholdIndex', (threshold_item.value ->> 'thresholdIndex')::integer,
        'thresholdId', threshold_item.value ->> 'thresholdId',
        'cumulativeNetRecipientThresholdCents',
          (threshold_item.value ->> 'cumulativeNetRecipientThresholdCents')::bigint,
        'grossSuccessRequirementCents',
          (threshold_item.value ->> 'grossSuccessRequirementCents')::bigint,
        'premiumRateBps', (threshold_item.value ->> 'premiumRateBps')::integer,
        'successPremiumCents',
          (threshold_item.value ->> 'successPremiumCents')::bigint
      )
      order by (threshold_item.value ->> 'thresholdIndex')::integer
    )
    into thresholds_json
    from jsonb_array_elements(
      proposal.public_goods_threshold_schedule_json -> 'thresholds'
    ) as threshold_item(value);

    failure_bonus_json := jsonb_build_object(
      'enabled', true,
      'scheduleStatus', 'approved',
      'rateBps', proposal.public_goods_failure_bonus_rate_bps,
      'maxParticipants', proposal.public_goods_failure_bonus_max_participants,
      'maxPerParticipantCents',
        proposal.public_goods_failure_bonus_max_per_participant_cents
    );
  else
    thresholds_json := jsonb_build_array(
      jsonb_build_object(
        'thresholdIndex', 1,
        'thresholdId', 'threshold-1',
        'cumulativeNetRecipientThresholdCents',
          proposal.public_goods_threshold_amount_cents,
        'grossSuccessRequirementCents',
          proposal.public_goods_threshold_amount_cents,
        'premiumRateBps', 0,
        'successPremiumCents', 0
      )
    );
    failure_bonus_json := jsonb_build_object(
      'enabled', false,
      'scheduleStatus', null,
      'rateBps', null,
      'maxParticipants', null,
      'maxPerParticipantCents', null
    );
  end if;

  select
    coalesce(sum(pledge.amount_cents::bigint), 0),
    count(distinct coalesce(
      pledge.user_id::text,
      pledge.profile_id::text,
      pledge.id::text
    ))::integer
  into funded_cents, contributor_count
  from public.mpgf_pledges as pledge
  where pledge.pool_proposal_id = proposal.pool_proposal_id
    and pledge.status in ('pledged', 'converted_to_payment_intent')
    and pledge.pledge_mode = 'pledge_only'
    and pledge.real_money = false
    and (pledge.expires_at is null or pledge.expires_at > p_at);

  return jsonb_build_object(
    'schemaVersion', 'mpgf_pledge_impact_pool_state_v1',
    'poolPublicKey', proposal.pool_public_key,
    'poolProposalId', proposal.pool_proposal_id,
    'title', proposal.title,
    'causeArea', proposal.cause_area,
    'currency', 'USD',
    'thresholds', thresholds_json,
    'fundedCents', funded_cents,
    'contributorCount', contributor_count,
    'deadlineAt', to_char(
      proposal.public_goods_deadline_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'thresholdSupporters', proposal.public_goods_threshold_supporters,
    'thresholdVisibility', proposal.threshold_visibility,
    'progressVisibility', proposal.progress_visibility,
    'destinationType', proposal.public_goods_destination_type,
    'failureBonus', failure_bonus_json
  );
exception
  when others then
    return null;
end;
$_$;



CREATE FUNCTION public.mpgf_pledge_impact_sha256(value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'sha256:' || encode(extensions.digest(value::text, 'sha256'), 'hex');
$$;



CREATE FUNCTION public.mpgf_pool_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  raise exception using errcode = '23514', message = 'MPGF pool lifecycle versions and events are append-only.';
end;
$$;



CREATE FUNCTION public.mpgf_pool_proposal_terms_sha256(p_proposal_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  select 'sha256:' || encode(
    extensions.digest(
      convert_to(public.mpgf_pool_proposal_terms_snapshot(p_proposal_id)::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;



CREATE FUNCTION public.mpgf_pool_proposal_terms_snapshot(p_proposal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  create_terms_json jsonb;
begin
  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id;

  if proposal_row.id is null then
    raise exception using errcode = 'P0002', message = 'Pool proposal was not found.';
  end if;

  select to_jsonb(pool_terms)
    - 'review_status'
    - 'reserve_quote_status'
    - 'terms_locked_at'
    - 'created_at'
    - 'updated_at'
  into create_terms_json
  from public.moral_trade_create_pool_terms as pool_terms
  where pool_terms.pool_proposal_id = p_proposal_id;

  return jsonb_build_object(
    'proposal',
      to_jsonb(proposal_row)
      - 'status'
      - 'candidate_alternative_id'
      - 'created_at'
      - 'submitted_at'
      - 'first_accepted_pledge_at'
      - 'progress_visibility'
      - 'public_goods_failure_bonus_schedule_status'
      - 'terms_version'
      - 'approved_terms_version'
      - 'operative_terms_sha256'
      - 'terms_locked_at'
      - 'reviewed_by'
      - 'reviewed_at'
      - 'review_reason'
      - 'supersedes_proposal_id',
    'createPoolTerms', create_terms_json
  );
end;
$$;



CREATE FUNCTION public.mpgf_progress_visibility_rank(visibility public.mpgf_progress_visibility) RETURNS smallint
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case visibility::text
    when 'sealed_progress' then 1::smallint
    when 'threshold_status_only' then 2::smallint
    when 'progress_range' then 3::smallint
    when 'exact_amount' then 4::smallint
  end;
$$;



CREATE FUNCTION public.mpgf_public_dac_campaign_terms(p_campaign_id_or_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  identifier_value text := btrim(coalesce(p_campaign_id_or_slug, ''));
  campaign_row record;
  proposal_terms_json jsonb;
  proposal_json jsonb;
  create_pool_terms_json jsonb;
  threshold_schedule_json jsonb;
  eligibility_policy_json jsonb;
  success_premium_pricing_json jsonb;
  threshold_amount_value bigint;
  threshold_supporters_value integer;
  deadline_value timestamptz;
  failure_bonus_rate_value integer;
  failure_bonus_max_participants_value integer;
  failure_bonus_max_per_participant_value bigint;
  success_premium_rate_value integer;
  success_premium_amount_value bigint;
  gross_success_requirement_value bigint;
begin
  if identifier_value = '' then
    return null;
  end if;

  select
    campaign.id,
    campaign.slug,
    campaign.pool_proposal_id,
    campaign.published_terms_version,
    campaign.published_terms_sha256,
    campaign.threshold_amount_cents,
    campaign.threshold_supporters,
    campaign.deadline_at,
    campaign.review_status
  into campaign_row
  from public.mpgf_public_goods_campaigns as campaign
  where (campaign.id = identifier_value or campaign.slug = identifier_value)
    and campaign.pool_proposal_id is not null
    and campaign.published_terms_version is not null
    and campaign.published_terms_sha256 is not null
    and campaign.published_at is not null
    and campaign.review_status in ('approved', 'finalized')
  order by (campaign.id = identifier_value) desc
  limit 1;

  if campaign_row.id is null then
    return null;
  end if;

  select
    version.proposal_terms_json,
    version.create_pool_terms_json
  into
    proposal_terms_json,
    create_pool_terms_json
  from public.mpgf_pool_proposal_versions as version
  where version.proposal_id = campaign_row.pool_proposal_id
    and version.terms_version = campaign_row.published_terms_version
    and version.terms_sha256 = campaign_row.published_terms_sha256;

  if proposal_terms_json is null
     or jsonb_typeof(proposal_terms_json) <> 'object' then
    return null;
  end if;

  proposal_json := proposal_terms_json;
  threshold_schedule_json := proposal_json -> 'public_goods_threshold_schedule_json';
  eligibility_policy_json := proposal_json -> 'public_goods_failure_bonus_eligibility_json';
  success_premium_pricing_json := proposal_json -> 'public_goods_success_premium_pricing_json';

  -- Fail closed before casting or publishing any derived approval claim. The
  -- immutable proposal snapshot deliberately omits mutable review-state fields;
  -- an approved/finalized campaign plus a non-provisional frozen schedule is the
  -- public evidence that the exact published schedule completed review.
  if jsonb_typeof(proposal_json -> 'public_goods_threshold_amount_cents') is distinct from 'number'
     or jsonb_typeof(proposal_json -> 'public_goods_threshold_supporters') is distinct from 'number'
     or jsonb_typeof(proposal_json -> 'public_goods_deadline_at') is distinct from 'string'
     or proposal_json ->> 'public_goods_failure_bonus_enabled' is distinct from 'true'
     or jsonb_typeof(proposal_json -> 'public_goods_failure_bonus_rate_bps') is distinct from 'number'
     or jsonb_typeof(eligibility_policy_json) is distinct from 'object'
     or jsonb_typeof(proposal_json -> 'public_goods_failure_bonus_max_participants') is distinct from 'number'
     or jsonb_typeof(proposal_json -> 'public_goods_failure_bonus_max_per_participant_cents') is distinct from 'number'
     or jsonb_typeof(threshold_schedule_json) is distinct from 'object'
     or jsonb_typeof(threshold_schedule_json -> 'thresholds') is distinct from 'array'
     or jsonb_array_length(threshold_schedule_json -> 'thresholds') < 1
     or exists (
       select 1
       from jsonb_array_elements(threshold_schedule_json -> 'thresholds') as threshold_item(value)
       where threshold_item.value ->> 'provisional' is distinct from 'false'
     )
     or jsonb_typeof(proposal_json -> 'public_goods_success_premium_rate_bps') is distinct from 'number'
     or jsonb_typeof(proposal_json -> 'public_goods_success_premium_cents') is distinct from 'number'
     or proposal_json ->> 'public_goods_success_premium_payer' is distinct from 'pool_creator_or_sponsor'
     or proposal_json ->> 'public_goods_success_premium_included_in_net_threshold' is distinct from 'false'
     or proposal_json ->> 'public_goods_success_premium_provisional' is distinct from 'false'
     or jsonb_typeof(proposal_json -> 'public_goods_gross_success_requirement_cents') is distinct from 'number'
     or jsonb_typeof(success_premium_pricing_json) is distinct from 'object'
     or proposal_json ->> 'public_goods_payout_method' is distinct from 'signed_intent'
     or (create_pool_terms_json is not null and jsonb_typeof(create_pool_terms_json) is distinct from 'object') then
    return null;
  end if;

  threshold_amount_value := (proposal_json ->> 'public_goods_threshold_amount_cents')::bigint;
  threshold_supporters_value := (proposal_json ->> 'public_goods_threshold_supporters')::integer;
  deadline_value := (proposal_json ->> 'public_goods_deadline_at')::timestamptz;
  failure_bonus_rate_value := (proposal_json ->> 'public_goods_failure_bonus_rate_bps')::integer;
  failure_bonus_max_participants_value :=
    (proposal_json ->> 'public_goods_failure_bonus_max_participants')::integer;
  failure_bonus_max_per_participant_value :=
    (proposal_json ->> 'public_goods_failure_bonus_max_per_participant_cents')::bigint;
  success_premium_rate_value := (proposal_json ->> 'public_goods_success_premium_rate_bps')::integer;
  success_premium_amount_value := (proposal_json ->> 'public_goods_success_premium_cents')::bigint;
  gross_success_requirement_value :=
    (proposal_json ->> 'public_goods_gross_success_requirement_cents')::bigint;

  if threshold_amount_value <= 0
     or threshold_supporters_value <= 0
     or failure_bonus_rate_value < 1
     or failure_bonus_rate_value > 10000
     or failure_bonus_max_participants_value <= 0
     or failure_bonus_max_per_participant_value <= 0
     or success_premium_rate_value < 1
     or success_premium_amount_value <= 0
     or gross_success_requirement_value is distinct from
        threshold_amount_value + success_premium_amount_value
     or threshold_amount_value is distinct from campaign_row.threshold_amount_cents
     or threshold_supporters_value is distinct from campaign_row.threshold_supporters
     or deadline_value is distinct from campaign_row.deadline_at then
    return null;
  end if;

  return jsonb_build_object(
    'schemaVersion', 'mpgf_dac_public_terms_v1',
    'mechanism', 'dominant_assurance_contract',
    'campaignId', campaign_row.id,
    'campaignSlug', campaign_row.slug,
    'poolProposalId', campaign_row.pool_proposal_id,
    'termsVersion', campaign_row.published_terms_version,
    'termsSha256', campaign_row.published_terms_sha256,
    'threshold', jsonb_build_object(
      'netRecipientAmountCents', threshold_amount_value,
      'minimumSupporters', threshold_supporters_value,
      'deadlineAt', deadline_value
    ),
    'failureBonus', jsonb_build_object(
      'enabled', true,
      'rateBps', failure_bonus_rate_value,
      'eligibilityPolicy', eligibility_policy_json,
      'maxParticipants', failure_bonus_max_participants_value,
      'maxPerParticipantCents', failure_bonus_max_per_participant_value,
      'thresholdSchedule', threshold_schedule_json,
      'scheduleStatus', 'approved'
    ),
    'successPremium', jsonb_build_object(
      'rateBps', success_premium_rate_value,
      'amountCents', success_premium_amount_value,
      'payer', 'pool_creator_or_sponsor',
      'includedInNetThreshold', false,
      'provisional', false,
      'grossSuccessRequirementCents', gross_success_requirement_value,
      'pricing', success_premium_pricing_json
    ),
    'createPoolTerms', case
      when jsonb_typeof(create_pool_terms_json) = 'object' then jsonb_build_object(
        'thresholdAmountsCents', create_pool_terms_json -> 'threshold_amounts_cents_json',
        'failureBonusBaseType', create_pool_terms_json -> 'failure_bonus_base_type',
        'failureBonusBaseTerms', create_pool_terms_json -> 'failure_bonus_base_terms_json',
        'failureBonusTimingMode', create_pool_terms_json -> 'failure_bonus_timing_mode',
        'failureBonusTimingTerms', create_pool_terms_json -> 'failure_bonus_timing_terms_json',
        'formulaSource', create_pool_terms_json -> 'formula_source',
        'formulaAst', create_pool_terms_json -> 'formula_ast_json',
        'formulaLanguageVersion', create_pool_terms_json -> 'formula_language_version',
        'formulaHash', create_pool_terms_json -> 'formula_hash',
        'formulaVariables', create_pool_terms_json -> 'formula_variables_json',
        'continuationMode', create_pool_terms_json -> 'continuation_mode',
        'moralTradeFailureBonusShareBps', create_pool_terms_json -> 'moral_trade_failure_bonus_share_bps',
        'additionalActivationRule', create_pool_terms_json -> 'additional_activation_rule'
      )
      else null
    end,
    'payoutMethod', proposal_json -> 'public_goods_payout_method',
    'payment', jsonb_build_object(
      'pledgeMode', 'pledge_only',
      'paymentMethodCollected', false,
      'authorized', false,
      'mandateCreated', false,
      'charged', false,
      'captured', false,
      'settled', false,
      'failureBonusPaid', false
    )
  );
end;
$$;



CREATE FUNCTION public.mpgf_publish_pool_proposal(p_proposal_id uuid, p_round_id text, p_slug text, p_publisher_id uuid, p_reason text) RETURNS TABLE(published_proposal_id uuid, public_campaign_id text, public_round_id text, public_slug text, public_terms_version integer, public_terms_sha256 text, public_published_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  round_row public.mpgf_public_goods_rounds%rowtype;
  campaign_row public.mpgf_public_goods_campaigns%rowtype;
  campaign_id_value text;
  slug_value text := lower(btrim(coalesce(p_slug, '')));
  current_hash text;
  recorded_hash text;
  create_review_status text;
  create_terms_locked_at timestamptz;
  has_create_terms boolean := false;
  published_timestamp timestamptz := timezone('utc', now());
begin
  if btrim(coalesce(p_round_id, '')) = '' then
    raise exception using errcode = '22023', message = 'A public-goods round is required for publication.';
  end if;
  if length(slug_value) < 3
     or length(slug_value) > 96
     or slug_value !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then
    raise exception using errcode = '22023', message = 'The public campaign slug is invalid.';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A publication rationale is required.';
  end if;

  perform public.mpgf_assert_authorized_pool_reviewer(p_publisher_id, p_proposal_id);
  perform pg_advisory_xact_lock(hashtextextended(p_proposal_id::text || ':pool-publication', 0));
  perform pg_advisory_xact_lock(hashtextextended(p_round_id || ':' || slug_value, 0));

  select * into proposal_row
  from public.mpgf_pool_proposals as proposal
  where proposal.id = p_proposal_id
  for update;

  if proposal_row.id is null then
    raise exception using errcode = 'P0002', message = 'Pool proposal was not found.';
  end if;
  if proposal_row.status <> 'approved_as_candidate'
     or proposal_row.approved_terms_version is null
     or proposal_row.approved_terms_version <> proposal_row.terms_version
     or proposal_row.operative_terms_sha256 is null
     or proposal_row.terms_locked_at is null
     or proposal_row.reviewed_by is null
     or proposal_row.reviewed_at is null then
    raise exception using
      errcode = '23514',
      message = 'Only an approved proposal with complete frozen terms can be published.';
  end if;
  if proposal_row.first_accepted_pledge_at is not null
     or exists (
       select 1
       from public.mpgf_pledges as pledge
       where pledge.pool_proposal_id = proposal_row.id
         and pledge.status in ('pledged', 'converted_to_payment_intent')
     ) then
    raise exception using
      errcode = '23514',
      message = 'A pool proposal must be published before it accepts any pledge.';
  end if;

  current_hash := public.mpgf_pool_proposal_terms_sha256(proposal_row.id);
  if current_hash <> proposal_row.operative_terms_sha256 then
    raise exception using
      errcode = '23514',
      message = 'Current pool terms differ from the approved frozen version.';
  end if;

  select proposal_version.terms_sha256 into recorded_hash
  from public.mpgf_pool_proposal_versions as proposal_version
  where proposal_version.proposal_id = proposal_row.id
    and proposal_version.terms_version = proposal_row.approved_terms_version;
  if recorded_hash is null or recorded_hash <> current_hash then
    raise exception using
      errcode = '23514',
      message = 'The approved proposal version is missing or differs from current frozen terms.';
  end if;

  select pool_terms.review_status, pool_terms.terms_locked_at
  into create_review_status, create_terms_locked_at
  from public.moral_trade_create_pool_terms as pool_terms
  where pool_terms.pool_proposal_id = proposal_row.id;
  has_create_terms := found;
  if has_create_terms and (
    create_review_status <> 'approved'
    or create_terms_locked_at is null
  ) then
    raise exception using
      errcode = '23514',
      message = 'Linked Create pool terms must be approved and locked before publication.';
  end if;

  if btrim(coalesce(proposal_row.title, '')) = ''
     or btrim(coalesce(proposal_row.summary, '')) = ''
     or btrim(coalesce(proposal_row.cause_area, '')) = ''
     or proposal_row.public_goods_destination_type is null
     or btrim(coalesce(proposal_row.public_goods_destination_ref, '')) = ''
     or proposal_row.public_goods_threshold_amount_cents is null
     or proposal_row.public_goods_threshold_amount_cents <= 0
     or proposal_row.public_goods_threshold_supporters is null
     or proposal_row.public_goods_threshold_supporters <= 0
     or proposal_row.public_goods_deadline_at is null
     or btrim(coalesce(proposal_row.public_goods_verification_method, '')) = ''
     or btrim(coalesce(proposal_row.public_goods_baseline_rule, '')) = ''
     or btrim(coalesce(proposal_row.public_goods_exit_rule, '')) = ''
     or proposal_row.public_goods_payout_method is null then
    raise exception using
      errcode = '23514',
      message = 'Approved pool terms are incomplete for public campaign materialization.';
  end if;
  if proposal_row.threshold_visibility::text <> 'public_exact' then
    raise exception using errcode = '23514', message = 'Published pool thresholds must remain public and exact.';
  end if;
  if proposal_row.public_goods_payout_method not in ('external_handoff', 'signed_intent') then
    raise exception using
      errcode = '23514',
      message = 'This publication tranche supports only non-custodial external-handoff or signed-intent payout terms.';
  end if;
  if proposal_row.public_goods_failure_bonus_enabled = true and (
    proposal_row.public_goods_failure_bonus_schedule_status <> 'approved'
    or proposal_row.public_goods_success_premium_provisional is distinct from false
  ) then
    raise exception using
      errcode = '23514',
      message = 'A failure-bonus pool requires an approved, non-provisional complete schedule before publication.';
  end if;

  select * into round_row
  from public.mpgf_public_goods_rounds as public_round
  where public_round.id = p_round_id
  for update;

  if round_row.id is null then
    raise exception using errcode = 'P0002', message = 'Public-goods round was not found.';
  end if;
  if round_row.status not in ('scheduled', 'open')
     or round_row.ends_at <= published_timestamp
     or not exists (
       select 1
       from public.mpgf_public_goods_match_pools as match_pool
       where match_pool.id = round_row.match_pool_id
         and match_pool.status = 'active'
     ) then
    raise exception using
      errcode = '23514',
      message = 'Pools can be published only into a scheduled or open round with an active match pool that has not ended.';
  end if;
  if proposal_row.public_goods_deadline_at <= published_timestamp
     or proposal_row.public_goods_deadline_at <= round_row.starts_at
     or proposal_row.public_goods_deadline_at > round_row.ends_at then
    raise exception using
      errcode = '23514',
      message = 'The frozen pool deadline must be future-dated and fall inside the selected round.';
  end if;
  if round_row.supporter_gate <> 'demo_self_attestation'
     and proposal_row.public_goods_destination_ref ilike '%demo%' then
    raise exception using
      errcode = '23514',
      message = 'Non-demo rounds cannot publish a demo destination.';
  end if;

  select * into campaign_row
  from public.mpgf_public_goods_campaigns as campaign
  where campaign.pool_proposal_id = proposal_row.id
  for update;

  if campaign_row.id is not null then
    if campaign_row.round_id is distinct from p_round_id
       or campaign_row.slug is distinct from slug_value
       or campaign_row.published_terms_version is distinct from proposal_row.approved_terms_version
       or campaign_row.published_terms_sha256 is distinct from current_hash
       or campaign_row.review_status not in ('approved', 'finalized') then
      raise exception using
        errcode = '23514',
        message = 'This proposal was already materialized with different publication terms.';
    end if;

    return query select
      proposal_row.id,
      campaign_row.id,
      campaign_row.round_id,
      campaign_row.slug,
      campaign_row.published_terms_version,
      campaign_row.published_terms_sha256,
      campaign_row.published_at;
    return;
  end if;

  if exists (
    select 1
    from public.mpgf_public_goods_campaigns as campaign
    where campaign.slug = slug_value
  ) then
    raise exception using errcode = '23505', message = 'The public campaign slug is already in use.';
  end if;

  campaign_id_value := 'campaign-' || replace(proposal_row.id::text, '-', '');
  if exists (
    select 1
    from public.mpgf_public_goods_campaigns as campaign
    where campaign.id = campaign_id_value
  ) then
    raise exception using errcode = '23505', message = 'The deterministic public campaign ID is already in use.';
  end if;

  insert into public.mpgf_public_goods_campaigns (
    id,
    round_id,
    slug,
    pool_alternative_id,
    title,
    destination_type,
    destination_ref,
    cause_tags,
    public_summary,
    threshold_amount_cents,
    threshold_supporters,
    deadline_at,
    verification_method,
    baseline_rule,
    exit_rule,
    review_status,
    challenge_window_ends_at,
    pool_proposal_id,
    threshold_visibility,
    progress_visibility,
    first_accepted_pledge_at,
    published_terms_version,
    published_terms_sha256,
    published_by,
    published_at
  ) values (
    campaign_id_value,
    round_row.id,
    slug_value,
    proposal_row.candidate_alternative_id,
    proposal_row.title,
    proposal_row.public_goods_destination_type,
    proposal_row.public_goods_destination_ref,
    array[proposal_row.cause_area],
    proposal_row.summary,
    proposal_row.public_goods_threshold_amount_cents,
    proposal_row.public_goods_threshold_supporters,
    proposal_row.public_goods_deadline_at,
    proposal_row.public_goods_verification_method,
    proposal_row.public_goods_baseline_rule,
    proposal_row.public_goods_exit_rule,
    'approved',
    null,
    proposal_row.id,
    'public_exact',
    proposal_row.progress_visibility,
    null,
    proposal_row.approved_terms_version,
    current_hash,
    p_publisher_id,
    published_timestamp
  );

  update public.moral_trade_create_submissions as submission
  set status = 'published'
  where submission.target_type = 'mpgf_pool_proposal'
    and submission.target_id = proposal_row.id
    and submission.status = 'pending_review';

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id,
    terms_version,
    event_type,
    actor_user_id,
    from_status,
    to_status,
    terms_sha256,
    reason,
    metadata_json
  ) values (
    proposal_row.id,
    proposal_row.approved_terms_version,
    'pool_published',
    p_publisher_id,
    proposal_row.status,
    'published',
    current_hash,
    btrim(p_reason),
    jsonb_build_object(
      'campaignId', campaign_id_value,
      'roundId', round_row.id,
      'slug', slug_value,
      'publicationMode', 'non_custodial_no_payment_execution'
    )
  );

  return query select
    proposal_row.id,
    campaign_id_value,
    round_row.id,
    slug_value,
    proposal_row.approved_terms_version,
    current_hash,
    published_timestamp;
end;
$_$;



CREATE FUNCTION public.mpgf_record_pool_proposal_version(p_proposal_id uuid, p_actor_id uuid, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  snapshot_json jsonb;
  create_terms_json jsonb;
  terms_hash text;
  existing_hash text;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A version-record reason is required.';
  end if;

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id
  for update;

  if proposal_row.id is null then
    raise exception using errcode = 'P0002', message = 'Pool proposal was not found.';
  end if;

  snapshot_json := public.mpgf_pool_proposal_terms_snapshot(p_proposal_id);
  terms_hash := public.mpgf_pool_proposal_terms_sha256(p_proposal_id);
  create_terms_json := nullif(snapshot_json -> 'createPoolTerms', 'null'::jsonb);

  select terms_sha256 into existing_hash
  from public.mpgf_pool_proposal_versions
  where proposal_id = p_proposal_id
    and terms_version = proposal_row.terms_version;

  if existing_hash is not null then
    if existing_hash <> terms_hash then
      raise exception using
        errcode = '23514',
        message = 'Recorded pool proposal version differs from current terms; create a new proposal revision.';
    end if;
    return existing_hash;
  end if;

  insert into public.mpgf_pool_proposal_versions (
    proposal_id,
    terms_version,
    supersedes_proposal_id,
    terms_sha256,
    proposal_terms_json,
    create_pool_terms_json,
    recorded_by,
    recorded_reason
  ) values (
    p_proposal_id,
    proposal_row.terms_version,
    proposal_row.supersedes_proposal_id,
    terms_hash,
    snapshot_json -> 'proposal',
    create_terms_json,
    p_actor_id,
    btrim(p_reason)
  );

  return terms_hash;
end;
$$;



CREATE FUNCTION public.mpgf_reject_pool_proposal(p_proposal_id uuid, p_reviewer_id uuid, p_reason text) RETURNS TABLE(proposal_id uuid, terms_version integer, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
  terms_hash text;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A rejection rationale is required.';
  end if;
  perform public.mpgf_assert_authorized_pool_reviewer(p_reviewer_id, p_proposal_id);

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id
  for update;
  if proposal_row.status not in ('submitted', 'under_review') then
    raise exception using errcode = '23514', message = 'Only a submitted or under-review pool proposal can be rejected.';
  end if;

  terms_hash := public.mpgf_record_pool_proposal_version(
    p_proposal_id,
    p_reviewer_id,
    'proposal_rejected: ' || btrim(p_reason)
  );

  perform set_config('app.mpgf_pool_review_transition', p_proposal_id::text, true);
  update public.mpgf_pool_proposals
  set status = 'rejected',
      reviewed_by = p_reviewer_id,
      reviewed_at = timezone('utc', now()),
      review_reason = btrim(p_reason)
  where id = p_proposal_id;
  perform set_config('app.mpgf_pool_review_transition', '', true);

  update public.moral_trade_create_pool_terms
  set review_status = 'rejected'
  where pool_proposal_id = p_proposal_id;

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id, terms_version, event_type, actor_user_id,
    from_status, to_status, terms_sha256, reason
  ) values (
    p_proposal_id, proposal_row.terms_version, 'proposal_rejected', p_reviewer_id,
    proposal_row.status, 'rejected',
    terms_hash, btrim(p_reason)
  );

  return query select p_proposal_id, proposal_row.terms_version, 'rejected'::text;
end;
$$;



CREATE FUNCTION public.mpgf_request_pool_proposal_changes(p_proposal_id uuid, p_reviewer_id uuid, p_reason text) RETURNS TABLE(proposal_id uuid, terms_version integer, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
begin
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception using errcode = '22023', message = 'A change request is required.';
  end if;
  perform public.mpgf_assert_authorized_pool_reviewer(p_reviewer_id, p_proposal_id);

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = p_proposal_id
  for update;
  if proposal_row.status <> 'under_review' then
    raise exception using errcode = '23514', message = 'Only a pool proposal under review can receive a change request.';
  end if;

  perform set_config('app.mpgf_pool_review_transition', p_proposal_id::text, true);
  update public.mpgf_pool_proposals
  set status = 'changes_requested',
      reviewed_by = p_reviewer_id,
      reviewed_at = timezone('utc', now()),
      review_reason = btrim(p_reason)
  where id = p_proposal_id;
  perform set_config('app.mpgf_pool_review_transition', '', true);

  update public.moral_trade_create_pool_terms
  set review_status = 'revision_required'
  where pool_proposal_id = p_proposal_id;

  insert into public.mpgf_pool_lifecycle_events (
    proposal_id, terms_version, event_type, actor_user_id,
    from_status, to_status, terms_sha256, reason
  ) values (
    p_proposal_id, proposal_row.terms_version, 'changes_requested', p_reviewer_id,
    'under_review', 'changes_requested',
    public.mpgf_pool_proposal_terms_sha256(p_proposal_id), btrim(p_reason)
  );

  return query select p_proposal_id, proposal_row.terms_version, 'changes_requested'::text;
end;
$$;



CREATE FUNCTION public.mpgf_require_approved_failure_bonus_before_pledge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  proposal_row public.mpgf_pool_proposals%rowtype;
begin
  if new.pool_proposal_id is null
     or new.status not in ('pledged', 'converted_to_payment_intent') then
    return new;
  end if;

  select * into proposal_row
  from public.mpgf_pool_proposals
  where id = new.pool_proposal_id;

  if proposal_row.public_goods_failure_bonus_enabled = true
     and proposal_row.public_goods_failure_bonus_schedule_status <> 'approved' then
    raise exception using
      errcode = '23514',
      message = 'Failure-bonus pledges cannot be accepted until an operator approves the complete threshold schedule.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.mpgf_review_dac_pledge_eligibility(p_pledge_id uuid, p_reviewer_id uuid, p_eligibility_state text, p_human_score_bps integer, p_reason text) RETURNS TABLE(reviewed_pledge_id uuid, reviewed_pledge_intent_id uuid, reviewed_campaign_id text, reviewed_profile_id uuid, eligibility_state text, human_score_bps integer, eligibility_event_id uuid, reviewed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  pledge_row public.mpgf_public_goods_pledges%rowtype;
  intent_row public.mpgf_dac_pledge_intents%rowtype;
  campaign_row public.mpgf_public_goods_campaigns%rowtype;
  existing_event public.mpgf_dac_pledge_events%rowtype;
  event_id_value uuid := gen_random_uuid();
  reviewed_at_value timestamptz := clock_timestamp();
  reason_value text := btrim(coalesce(p_reason, ''));
  event_value jsonb;
begin
  if p_pledge_id is null then
    raise exception using errcode = '22023', message = 'A DAC pledge is required.';
  end if;
  if p_eligibility_state is null
     or p_eligibility_state not in (
       'eligible',
       'duplicate_identity',
       'below_minimum',
       'blocked'
     ) then
    raise exception using
      errcode = '22023',
      message = 'A final DAC eligibility state is required.';
  end if;
  if reason_value = '' then
    raise exception using
      errcode = '22023',
      message = 'An eligibility-review rationale is required.';
  end if;
  if p_eligibility_state = 'eligible' and (
    p_human_score_bps is null
    or p_human_score_bps < 1
    or p_human_score_bps > 10000
  ) then
    raise exception using
      errcode = '22023',
      message = 'An eligible pledge requires a human score from 1 to 10000 basis points.';
  end if;
  if p_eligibility_state <> 'eligible'
     and coalesce(p_human_score_bps, 0) <> 0 then
    raise exception using
      errcode = '22023',
      message = 'An ineligible pledge must have a zero human score.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_pledge_id::text || ':dac-eligibility', 0)
  );

  select * into pledge_row
  from public.mpgf_public_goods_pledges as pledge
  where pledge.id = p_pledge_id;

  if pledge_row.id is null
     or pledge_row.pledge_intent_id is null
     or pledge_row.pool_proposal_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'A proposal-bound DAC pledge was not found.';
  end if;

  select * into intent_row
  from public.mpgf_dac_pledge_intents as intent
  where intent.id = pledge_row.pledge_intent_id;

  if intent_row.id is null
     or intent_row.campaign_id is distinct from pledge_row.campaign_id
     or intent_row.pool_proposal_id is distinct from pledge_row.pool_proposal_id
     or intent_row.terms_version is distinct from pledge_row.terms_version
     or intent_row.terms_sha256 is distinct from pledge_row.terms_sha256
     or intent_row.profile_id is distinct from pledge_row.profile_id
     or intent_row.amount_cents is distinct from pledge_row.amount_cents
     or intent_row.currency is distinct from pledge_row.currency
     or intent_row.visibility_mode is distinct from pledge_row.visibility_mode
     or intent_row.supporter_reason is distinct from pledge_row.supporter_reason
     or intent_row.accepted_at is distinct from pledge_row.accepted_at then
    raise exception using
      errcode = '23514',
      message = 'The canonical DAC pledge differs from its immutable consent intent.';
  end if;

  perform public.mpgf_assert_authorized_pool_reviewer(
    p_reviewer_id,
    pledge_row.pool_proposal_id
  );

  if pledge_row.profile_id = p_reviewer_id then
    raise exception using
      errcode = '42501',
      message = 'A reviewer cannot decide their own DAC pledge eligibility.';
  end if;

  select * into campaign_row
  from public.mpgf_public_goods_campaigns as campaign
  where campaign.id = pledge_row.campaign_id
  for share;

  if campaign_row.id is null
     or campaign_row.review_status <> 'approved'
     or campaign_row.pool_proposal_id is distinct from pledge_row.pool_proposal_id
     or campaign_row.published_terms_version is distinct from pledge_row.terms_version
     or campaign_row.published_terms_sha256 is distinct from pledge_row.terms_sha256
     or exists (
       select 1
       from public.mpgf_dac_campaign_outcomes as outcome
       where outcome.campaign_id = campaign_row.id
     ) then
    raise exception using
      errcode = '23514',
      message = 'Eligibility can be decided only for a live, exact-version DAC campaign.';
  end if;

  select * into pledge_row
  from public.mpgf_public_goods_pledges as pledge
  where pledge.id = p_pledge_id
  for update;

  if pledge_row.campaign_id is distinct from campaign_row.id
     or pledge_row.pool_proposal_id is distinct from campaign_row.pool_proposal_id
     or pledge_row.terms_version is distinct from campaign_row.published_terms_version
     or pledge_row.terms_sha256 is distinct from campaign_row.published_terms_sha256 then
    raise exception using
      errcode = '23514',
      message = 'The DAC pledge changed while eligibility review was starting.';
  end if;

  select * into existing_event
  from public.mpgf_dac_pledge_events as event
  where event.pledge_id = pledge_row.id
    and event.event_type = 'eligibility_reviewed';

  if pledge_row.eligibility_state <> 'pending_review' then
    if pledge_row.eligibility_state = p_eligibility_state
       and pledge_row.human_score_bps = coalesce(p_human_score_bps, 0)
       and existing_event.id is not null then
      return query select
        pledge_row.id,
        pledge_row.pledge_intent_id,
        pledge_row.campaign_id,
        pledge_row.profile_id,
        pledge_row.eligibility_state,
        pledge_row.human_score_bps,
        existing_event.id,
        existing_event.created_at;
      return;
    end if;

    raise exception using
      errcode = '23514',
      message = 'DAC pledge eligibility was already decided and cannot be changed.';
  end if;

  if existing_event.id is not null then
    raise exception using
      errcode = '23514',
      message = 'A pending DAC pledge already has a final eligibility event.';
  end if;

  perform set_config(
    'app.mpgf_dac_internal_write',
    pledge_row.pledge_intent_id::text,
    true
  );

  update public.mpgf_public_goods_pledges
  set eligibility_state = p_eligibility_state,
      human_score_bps = coalesce(p_human_score_bps, 0)
  where id = pledge_row.id;

  event_value := jsonb_build_object(
    'schemaVersion', 'mpgf_dac_pledge_event_v1',
    'eventType', 'eligibility_reviewed',
    'pledgeIntentId', pledge_row.pledge_intent_id,
    'pledgeId', pledge_row.id,
    'campaignId', pledge_row.campaign_id,
    'poolProposalId', pledge_row.pool_proposal_id,
    'profileId', pledge_row.profile_id,
    'reviewerId', p_reviewer_id,
    'termsVersion', pledge_row.terms_version,
    'termsSha256', pledge_row.terms_sha256,
    'amountCents', pledge_row.amount_cents,
    'currency', pledge_row.currency,
    'fromEligibilityState', pledge_row.eligibility_state,
    'toEligibilityState', p_eligibility_state,
    'humanScoreBps', coalesce(p_human_score_bps, 0),
    'reason', reason_value,
    'paymentAuthorized', false,
    'reviewedAt', reviewed_at_value
  );

  insert into public.mpgf_dac_pledge_events (
    id,
    pledge_intent_id,
    pledge_id,
    campaign_id,
    pool_proposal_id,
    profile_id,
    event_type,
    terms_version,
    terms_sha256,
    amount_cents,
    currency,
    event_json,
    event_sha256,
    created_at
  ) values (
    event_id_value,
    pledge_row.pledge_intent_id,
    pledge_row.id,
    pledge_row.campaign_id,
    pledge_row.pool_proposal_id,
    pledge_row.profile_id,
    'eligibility_reviewed',
    pledge_row.terms_version,
    pledge_row.terms_sha256,
    pledge_row.amount_cents,
    pledge_row.currency,
    event_value,
    public.mpgf_dac_json_sha256(event_value),
    reviewed_at_value
  );

  perform set_config('app.mpgf_dac_internal_write', '', true);

  return query select
    pledge_row.id,
    pledge_row.pledge_intent_id,
    pledge_row.campaign_id,
    pledge_row.profile_id,
    p_eligibility_state,
    coalesce(p_human_score_bps, 0),
    event_id_value,
    reviewed_at_value;
end;
$$;



CREATE FUNCTION public.mpgf_sync_failure_bonus_premium_quote() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  reserve_row public.mpgf_failure_bonus_reserves%rowtype;
  threshold_item jsonb;
  quote_hash_value text;
  current_hashes text[] := array[]::text[];
  threshold_count integer;
begin
  select *
  into reserve_row
  from public.mpgf_failure_bonus_reserves
  where reserve_key = 'moral-trade-common-failure-bonus-usd';

  if reserve_row.id is null then
    raise exception 'Common failure-bonus reserve metadata is missing.';
  end if;

  if new.public_goods_failure_bonus_enabled = false then
    update public.mpgf_failure_bonus_premium_quotes
    set status = 'superseded'
    where pool_proposal_id = new.id
      and status = 'pending_review';
    return new;
  end if;

  if new.public_goods_failure_bonus_schedule_status = 'approved' then
    return new;
  end if;

  threshold_count := jsonb_array_length(new.public_goods_threshold_schedule_json -> 'thresholds');

  for threshold_item in
    select value
    from jsonb_array_elements(new.public_goods_threshold_schedule_json -> 'thresholds')
  loop
    quote_hash_value := 'sha256:' || pg_catalog.encode(
      extensions.digest(
        concat_ws(
          '|',
          new.id::text,
          threshold_item::text,
          new.public_goods_failure_bonus_eligibility_json::text,
          new.public_goods_success_premium_policy_version
        ),
        'sha256'
      ),
      'hex'
    );
    current_hashes := array_append(current_hashes, quote_hash_value);

    insert into public.mpgf_failure_bonus_premium_quotes (
      reserve_id,
      pool_proposal_id,
      threshold_id,
      threshold_index,
      cumulative_net_recipient_threshold_cents,
      incremental_net_recipient_cents,
      premium_rate_bps,
      success_premium_cents,
      cumulative_success_premium_cents,
      gross_success_requirement_cents,
      premium_payer,
      premium_included_in_net_recipient_threshold,
      pricing_mode,
      pricing_json,
      policy_version,
      provisional,
      rationale,
      status,
      quote_hash,
      failure_bonus_rate_bps,
      incremental_failure_bonus_exposure_cents,
      maximum_failure_bonus_exposure_cents,
      eligibility_json,
      max_participants,
      max_bonus_per_participant_cents
    ) values (
      reserve_row.id,
      new.id,
      threshold_item ->> 'thresholdId',
      (threshold_item ->> 'thresholdIndex')::integer,
      (threshold_item ->> 'cumulativeNetRecipientThresholdCents')::bigint,
      (threshold_item ->> 'incrementalNetRecipientCents')::bigint,
      (threshold_item ->> 'premiumRateBps')::integer,
      (threshold_item ->> 'successPremiumCents')::bigint,
      (threshold_item ->> 'cumulativeSuccessPremiumCents')::bigint,
      (threshold_item ->> 'grossSuccessRequirementCents')::bigint,
      'pool_creator_or_sponsor',
      false,
      'experience_rated',
      threshold_item -> 'assumptions',
      new.public_goods_success_premium_policy_version,
      true,
      threshold_item ->> 'rationale',
      'pending_review',
      quote_hash_value,
      new.public_goods_failure_bonus_rate_bps,
      (threshold_item ->> 'incrementalFailureBonusExposureCents')::bigint,
      (threshold_item ->> 'maximumFailureBonusExposureCents')::bigint,
      new.public_goods_failure_bonus_eligibility_json,
      new.public_goods_failure_bonus_max_participants,
      new.public_goods_failure_bonus_max_per_participant_cents
    )
    on conflict (quote_hash) do update set
      status = case
        when public.mpgf_failure_bonus_premium_quotes.status = 'approved'
          then public.mpgf_failure_bonus_premium_quotes.status
        else 'pending_review'
      end;
  end loop;

  update public.mpgf_failure_bonus_premium_quotes
  set status = 'superseded'
  where pool_proposal_id = new.id
    and status = 'pending_review'
    and not (quote_hash = any(current_hashes));

  if cardinality(current_hashes) <> threshold_count then
    raise exception 'Premium quote synchronization did not cover every threshold.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.nominate_trade_appeal_reviewer_v1(p_appeal_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  appeal_row public.trade_milestone_appeals%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  base_reviewer_id uuid;
  agreed_reviewer uuid;
begin
  select *
  into appeal_row
  from public.trade_milestone_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = appeal_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select review.reviewer_id
  into base_reviewer_id
  from public.trade_milestone_reviews review
  where review.id = appeal_row.base_review_id;

  if actor_id is null
     or not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or appeal_row.status <> 'reviewer_selection'
     or p_reviewer_id = base_reviewer_id
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Choose a different active neutral appeal reviewer.';
  end if;

  insert into public.trade_appeal_reviewer_nominations (
    appeal_id, nominated_by, reviewer_id
  ) values (
    appeal_row.id, actor_id, p_reviewer_id
  )
  on conflict (appeal_id, nominated_by) do update
  set reviewer_id = excluded.reviewer_id,
      created_at = now();

  select nomination.reviewer_id
  into agreed_reviewer
  from public.trade_appeal_reviewer_nominations nomination
  where nomination.appeal_id = appeal_row.id
    and nomination.nominated_by in (agreement_row.proposer_id, agreement_row.responder_id)
  group by nomination.reviewer_id
  having count(*) = 2
  limit 1;

  if agreed_reviewer is not null then
    update public.trade_milestone_appeals
    set assigned_reviewer_id = agreed_reviewer,
        status = 'assigned'
    where id = appeal_row.id;
  end if;

  return jsonb_build_object(
    'appealId', appeal_row.id,
    'assignedReviewerId', agreed_reviewer,
    'status', case when agreed_reviewer is null then 'awaiting_consensus' else 'assigned' end
  );
end;
$$;



CREATE FUNCTION public.nominate_trade_milestone_reviewer_v1(p_milestone_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  agreed_reviewer uuid;
begin
  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;

  if actor_id is null
     or not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or milestone_row.assigned_reviewer_id is not null then
    raise exception 'Reviewer nomination is unavailable.';
  end if;
  if not exists (
    select 1
    from public.trade_review_role_grants grant_row
    where grant_row.profile_id = p_reviewer_id
      and grant_row.role = 'reviewer'
      and grant_row.active
      and grant_row.revoked_at is null
  ) then
    raise exception 'Choose an active neutral reviewer.';
  end if;

  update public.trade_agreement_milestones
  set reviewer_selection_opened_at = coalesce(reviewer_selection_opened_at, now()),
      updated_at = now()
  where id = milestone_row.id;

  insert into public.trade_milestone_reviewer_nominations (
    milestone_id, nominated_by, reviewer_id
  ) values (
    milestone_row.id, actor_id, p_reviewer_id
  )
  on conflict (milestone_id, nominated_by) do update
  set reviewer_id = excluded.reviewer_id,
      created_at = now();

  select n.reviewer_id
  into agreed_reviewer
  from public.trade_milestone_reviewer_nominations n
  where n.milestone_id = milestone_row.id
    and n.nominated_by in (agreement_row.proposer_id, agreement_row.responder_id)
  group by n.reviewer_id
  having count(*) = 2
  limit 1;

  if agreed_reviewer is not null then
    update public.trade_agreement_milestones
    set assigned_reviewer_id = agreed_reviewer,
        updated_at = now()
    where id = milestone_row.id
      and assigned_reviewer_id is null;
  end if;

  return jsonb_build_object(
    'milestoneId', milestone_row.id,
    'assignedReviewerId', agreed_reviewer,
    'status', case when agreed_reviewer is null then 'awaiting_consensus' else 'assigned' end
  );
end;
$$;



CREATE FUNCTION public.nominate_trade_payment_appeal_reviewer_v1(p_appeal_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  appeal_row public.trade_payment_appeals%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  base_decision public.trade_payment_review_decisions%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  agreed_reviewer uuid;
begin
  select *
  into appeal_row
  from public.trade_payment_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = appeal_row.case_id
  for update;
  select *
  into base_decision
  from public.trade_payment_review_decisions decision
  where decision.id = appeal_row.base_decision_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;

  if actor_id is null
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or appeal_row.status <> 'reviewer_selection'
     or review_case.status <> 'appeal_pending'
     or p_reviewer_id = base_decision.reviewer_id
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Choose a different active neutral payment-appeal reviewer.';
  end if;

  insert into public.trade_payment_appeal_reviewer_nominations (
    appeal_id, nominated_by, reviewer_id
  ) values (
    appeal_row.id, actor_id, p_reviewer_id
  )
  on conflict (appeal_id, nominated_by) do update
  set reviewer_id = excluded.reviewer_id,
      created_at = now();

  select nomination.reviewer_id
  into agreed_reviewer
  from public.trade_payment_appeal_reviewer_nominations nomination
  where nomination.appeal_id = appeal_row.id
    and nomination.nominated_by in (
      agreement_row.proposer_id, agreement_row.responder_id
    )
  group by nomination.reviewer_id
  having count(*) = 2
  limit 1;

  if agreed_reviewer is not null then
    update public.trade_payment_appeals
    set assigned_reviewer_id = agreed_reviewer,
        status = 'assigned'
    where id = appeal_row.id
      and assigned_reviewer_id is null;

    insert into public.trade_notifications (
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      agreed_reviewer,
      'payment_appeal_reviewer_assigned',
      'External payment appeal assigned',
      'The participants selected you to decide a final external-payment appeal.',
      '/trade-review/' || milestone_row.id::text,
      'payment_appeal_assignment:' || appeal_row.id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  end if;

  return jsonb_build_object(
    'paymentAppealId', appeal_row.id,
    'assignedReviewerId', agreed_reviewer,
    'status', case
      when agreed_reviewer is null then 'awaiting_consensus'
      else 'assigned'
    end
  );
end;
$$;



CREATE FUNCTION public.nominate_trade_payment_reviewer_v1(p_payout_id uuid, p_reviewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  agreed_reviewer uuid;
  case_id_value uuid;
begin
  case_id_value := moral_trade_private.ensure_trade_payment_review_case(
    p_payout_id
  );

  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = p_payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = case_id_value
  for update;

  if actor_id is null
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or review_case.status <> 'reviewer_selection'
     or review_case.assigned_reviewer_id is not null
     or p_reviewer_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or not exists (
       select 1
       from public.trade_review_role_grants grant_row
       where grant_row.profile_id = p_reviewer_id
         and grant_row.role = 'reviewer'
         and grant_row.active
         and grant_row.revoked_at is null
     ) then
    raise exception 'Payment-reviewer nomination is unavailable.';
  end if;

  insert into public.trade_payment_reviewer_nominations (
    case_id, nominated_by, reviewer_id
  ) values (
    review_case.id, actor_id, p_reviewer_id
  )
  on conflict (case_id, nominated_by) do update
  set reviewer_id = excluded.reviewer_id,
      created_at = now();

  select nomination.reviewer_id
  into agreed_reviewer
  from public.trade_payment_reviewer_nominations nomination
  where nomination.case_id = review_case.id
    and nomination.nominated_by in (
      agreement_row.proposer_id, agreement_row.responder_id
    )
  group by nomination.reviewer_id
  having count(*) = 2
  limit 1;

  if agreed_reviewer is not null then
    update public.trade_payment_review_cases
    set assigned_reviewer_id = agreed_reviewer,
        status = 'assigned',
        updated_at = now()
    where id = review_case.id
      and assigned_reviewer_id is null;

    insert into public.trade_notifications (
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      agreed_reviewer,
      'payment_reviewer_assigned',
      'External payment review assigned',
      'The participants selected you to review a disputed or unanswered external payment receipt.',
      '/trade-review/' || milestone_row.id::text,
      'payment_reviewer_assignment:' || review_case.id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  end if;

  return jsonb_build_object(
    'paymentReviewCaseId', review_case.id,
    'assignedReviewerId', agreed_reviewer,
    'status', case
      when agreed_reviewer is null then 'awaiting_consensus'
      else 'assigned'
    end
  );
end;
$$;



CREATE FUNCTION public.normalize_profile_username_v1(p_username text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select lower(regexp_replace(btrim(p_username), '^@+', ''));
$$;



CREATE FUNCTION public.open_mpgf_phase_one_ballot(p_round_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_round public.mpgf_phase_one_rounds%rowtype;
  v_eligible_count integer;
  v_candidate_count integer;
begin
  select *
  into v_round
  from public.mpgf_phase_one_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'MPGF phase-one round not found.';
  end if;

  if v_round.status = 'ballot_open' then
    select count(*)
    into v_eligible_count
    from public.mpgf_phase_one_eligible_voters
    where round_id = p_round_id;

    select count(*)
    into v_candidate_count
    from public.mpgf_phase_one_candidate_snapshots
    where round_id = p_round_id;

    return jsonb_build_object(
      'ok', true,
      'replayed', true,
      'roundId', p_round_id,
      'status', 'ballot_open',
      'eligiblePledgerCount', v_eligible_count,
      'approvedProjectCount', v_candidate_count,
      'quorumBps', 5000,
      'ballotPolicy', 'equal_credit_approval_split_v1',
      'resultEffect', 'advisory_external_checkout_confirmation_required'
    );
  end if;

  if v_round.status <> 'pledge_open' then
    raise exception 'MPGF phase-one ballot can open only from pledge_open.';
  end if;

  if v_round.pledge_closes_at is not null
     and timezone('utc', now()) < v_round.pledge_closes_at then
    raise exception 'MPGF pledge window has not closed.';
  end if;

  if v_round.ballot_closes_at is null
     or v_round.ballot_closes_at <= timezone('utc', now()) then
    raise exception 'MPGF ballot close time must be in the future.';
  end if;

  insert into public.mpgf_phase_one_eligible_voters (
    round_id,
    profile_id,
    pledge_id,
    snapshotted_at
  )
  select
    p_round_id,
    pledge.profile_id,
    pledge.id,
    timezone('utc', now())
  from public.mpgf_phase_one_pledges pledge
  where pledge.round_id = p_round_id
    and pledge.status = 'confirmed'
  on conflict (round_id, profile_id) do nothing;

  select count(*)
  into v_eligible_count
  from public.mpgf_phase_one_eligible_voters
  where round_id = p_round_id;

  if v_eligible_count <= 0 then
    raise exception 'MPGF ballot requires at least one confirmed pledger.';
  end if;

  insert into public.mpgf_phase_one_candidate_snapshots (
    round_id,
    project_id,
    title,
    summary,
    recipient_name,
    action_category,
    external_checkout_url_snapshot,
    snapshotted_at
  )
  select
    p_round_id,
    project.id,
    project.title,
    project.summary,
    project.recipient_name,
    project.action_category,
    project.external_checkout_url,
    timezone('utc', now())
  from public.mpgf_phase_one_projects project
  where project.round_id = p_round_id
    and project.status = 'approved'
  on conflict (round_id, project_id) do nothing;

  select count(*)
  into v_candidate_count
  from public.mpgf_phase_one_candidate_snapshots
  where round_id = p_round_id;

  if v_candidate_count <= 0 then
    raise exception 'MPGF ballot requires at least one reviewed approved project.';
  end if;

  update public.mpgf_phase_one_rounds
  set
    status = 'ballot_open',
    ballot_opens_at = coalesce(ballot_opens_at, timezone('utc', now())),
    updated_at = timezone('utc', now())
  where id = p_round_id;

  return jsonb_build_object(
    'ok', true,
    'roundId', p_round_id,
    'status', 'ballot_open',
    'eligiblePledgerCount', v_eligible_count,
    'approvedProjectCount', v_candidate_count,
    'quorumBps', 5000,
    'ballotPolicy', 'equal_credit_approval_split_v1',
    'resultEffect', 'advisory_external_checkout_confirmation_required'
  );
end;
$$;



CREATE FUNCTION public.open_trade_evidence_bundle_v1(p_milestone_id uuid, p_bundle_kind text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  attempt_value smallint;
  bundle_id uuid;
begin
  if actor_id is null or p_bundle_kind not in ('initial', 'replacement') then
    raise exception 'Choose an initial or replacement evidence packet.';
  end if;

  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  if not found or milestone_row.performer_id <> actor_id then
    raise exception 'Only the milestone performer may submit evidence.';
  end if;

  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;
  if agreement_row.current_version_id <> milestone_row.agreement_version_id
     or agreement_row.lifecycle_status not in ('active', 'evidence_due', 'disputed') then
    raise exception 'Evidence is unavailable for this agreement version.';
  end if;

  select b.id
  into bundle_id
  from public.trade_evidence_bundles b
  where b.milestone_id = milestone_row.id
    and b.bundle_kind = p_bundle_kind
    and b.submitted_by = actor_id
    and b.status = 'draft'
  order by b.created_at, b.id
  limit 1;
  if bundle_id is not null then
    return bundle_id;
  end if;

  if p_bundle_kind = 'initial' then
    if exists (
      select 1
      from public.trade_evidence_bundles b
      where b.milestone_id = milestone_row.id
        and b.bundle_kind = 'initial'
    ) then
      raise exception 'The initial evidence packet already exists.';
    end if;
    attempt_value := 1;
  else
    if milestone_row.status <> 'replacement_due'
       or milestone_row.replacement_packet_used
       or milestone_row.replacement_deadline_at is null
       or milestone_row.replacement_deadline_at <= now()
       or exists (
         select 1
         from public.trade_milestone_appeals appeal
         where appeal.milestone_id = milestone_row.id
           and appeal.status <> 'resolved'
       ) then
      raise exception 'The one replacement packet is unavailable or its clock is paused.';
    end if;
    attempt_value := 2;
    update public.trade_agreement_milestones
    set replacement_packet_used = true,
        updated_at = now()
    where id = milestone_row.id;
  end if;

  insert into public.trade_evidence_bundles (
    milestone_id,
    submitted_by,
    bundle_kind,
    attempt_number
  ) values (
    milestone_row.id,
    actor_id,
    p_bundle_kind,
    attempt_value
  )
  returning id into bundle_id;

  return bundle_id;
end;
$$;



CREATE FUNCTION public.open_trade_milestone_appeal_v1(p_milestone_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  review_row public.trade_milestone_reviews%rowtype;
  remaining_seconds integer;
  appeal_id uuid;
begin
  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = p_milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements a
  where a.id = milestone_row.agreement_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.milestone_id = milestone_row.id
  for update;
  select *
  into review_row
  from public.trade_milestone_reviews review
  where review.id = payout_row.review_id
  for update;

  if actor_id is null
     or not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or review_row.is_final
     or review_row.appeal_deadline_at <= now()
     or exists (
       select 1
       from public.trade_milestone_appeals appeal
       where appeal.milestone_id = milestone_row.id
     )
     or exists (
       select 1
       from public.trade_evidence_bundles replacement
       where replacement.milestone_id = milestone_row.id
         and replacement.bundle_kind = 'replacement'
         and replacement.status <> 'draft'
         and replacement.id <> review_row.bundle_id
     )
     or length(btrim(coalesce(p_reason, ''))) not between 1 and 4000 then
    raise exception 'The single appeal is unavailable or its seven-day window has closed.';
  end if;

  remaining_seconds := case
    when milestone_row.replacement_deadline_at is null then null
    else greatest(
      0,
      least(
        604800,
        floor(extract(epoch from milestone_row.replacement_deadline_at - now()))::integer
      )
    )
  end;

  insert into public.trade_milestone_appeals (
    milestone_id,
    base_review_id,
    opened_by,
    reason,
    reviewer_selection_deadline_at,
    replacement_seconds_remaining
  ) values (
    milestone_row.id,
    review_row.id,
    actor_id,
    btrim(p_reason),
    now() + interval '7 days',
    remaining_seconds
  )
  returning id into appeal_id;

  update public.trade_agreement_milestones
  set status = 'appeal_pending',
      replacement_deadline_at = null,
      replacement_seconds_remaining = remaining_seconds,
      updated_at = now()
  where id = milestone_row.id;

  return appeal_id;
end;
$$;



CREATE FUNCTION public.open_trade_payment_appeal_v1(p_case_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  review_case public.trade_payment_review_cases%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  decision_row public.trade_payment_review_decisions%rowtype;
  existing_appeal public.trade_payment_appeals%rowtype;
  normalized_reason text := btrim(coalesce(p_reason, ''));
  appeal_id_value uuid;
begin
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = p_case_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select *
  into decision_row
  from public.trade_payment_review_decisions decision
  where decision.id = review_case.final_decision_id
  for update;
  select *
  into existing_appeal
  from public.trade_payment_appeals appeal
  where appeal.case_id = review_case.id
  for update;

  if existing_appeal.id is not null then
    if existing_appeal.opened_by = actor_id
       and existing_appeal.base_decision_id = decision_row.id
       and existing_appeal.reason = normalized_reason then
      return existing_appeal.id;
    end if;
    raise exception 'The single payment appeal has already been opened.';
  end if;

  if actor_id is null
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or review_case.status <> 'decision_pending'
     or payout_row.status <> 'payment_decision_pending'
     or decision_row.id is null
     or decision_row.is_final
     or decision_row.outcome not in ('confirm_paid', 'still_due')
     or decision_row.appeal_deadline_at is null
     or decision_row.appeal_deadline_at <= now()
     or length(normalized_reason) not between 1 and 4000 then
    raise exception 'The single payment appeal is unavailable or its seven-day window has closed.';
  end if;

  insert into public.trade_payment_appeals (
    case_id,
    base_decision_id,
    opened_by,
    reason,
    reviewer_selection_deadline_at
  ) values (
    review_case.id,
    decision_row.id,
    actor_id,
    normalized_reason,
    now() + interval '7 days'
  )
  returning id into appeal_id_value;

  update public.trade_payment_review_cases
  set status = 'appeal_pending',
      updated_at = now()
  where id = review_case.id;
  update public.trade_milestone_payouts
  set status = 'payment_appeal_pending',
      updated_at = now()
  where id = payout_row.id;

  return appeal_id_value;
end;
$$;



CREATE FUNCTION public.prepare_core_agreement_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  offer_workflow_status text;
begin
  select workflow_status into offer_workflow_status
  from public.offers
  where id = new.offer_id;

  if offer_workflow_status = 'published' then
    new.status := 'proposed'::public.agreement_status;
    new.lifecycle_status := 'proposed';
    new.current_version_id := null;
    new.activated_at := null;
    new.completed_at := null;
    new.cancelled_at := null;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.prepare_profile_username_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  normalized text;
  existing_owner uuid;
begin
  if new.username is null or btrim(new.username) = '' then
    if tg_op = 'UPDATE' and old.username is not null then
      raise exception 'username_cannot_be_cleared' using errcode = '23514';
    end if;
    new.username := null;
    return new;
  end if;
  normalized := public.normalize_profile_username_v1(new.username);
  if char_length(normalized) not between 2 and 32
     or normalized !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'
     or normalized ~ '--'
     or public.profile_username_is_reserved_v1(normalized) then
    raise exception 'invalid_or_reserved_username' using errcode = '23514';
  end if;
  select claim.profile_id
  into existing_owner
  from public.profile_username_claims claim
  where claim.username = normalized;
  if existing_owner is not null and existing_owner <> new.id then
    raise exception 'username_already_claimed_or_reserved' using errcode = '23505';
  end if;
  new.username := normalized;
  return new;
end;
$_$;



CREATE FUNCTION public.prepare_trade_donation_pool_refund(p_actor_id uuid, p_obligation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  obligation_row public.trade_donation_pool_obligations%rowtype;
begin
  select * into obligation_row
  from public.trade_donation_pool_obligations
  where id = p_obligation_id
    and payer_user_id = p_actor_id
  for update;

  if not found then
    raise exception 'Pooled obligation not found or access denied.';
  end if;
  if obligation_row.status = 'refunded' then
    return to_jsonb(obligation_row);
  end if;
  if obligation_row.status <> 'funded' or obligation_row.bundle_id is not null then
    raise exception 'A contribution can be self-service refunded only before bundle freeze.';
  end if;
  if length(obligation_row.stripe_payment_intent_id) = 0 then
    raise exception 'The funded Stripe payment is unavailable for refund.';
  end if;

  update public.trade_donation_pool_obligations
  set status = 'refund_pending', refund_requested_at = timezone('utc', now())
  where id = obligation_row.id
  returning * into obligation_row;

  return to_jsonb(obligation_row);
end;
$$;



CREATE FUNCTION public.preserve_repeatable_catalog_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'matched'::public.offer_status
     and new.workflow_status = 'closed'
     and exists (
       select 1
       from public.offer_catalog_entries catalog
       where catalog.offer_id = new.id
         and catalog.repeatable = true
     )
  then
    new.status := 'open'::public.offer_status;
    new.workflow_status := 'published';
    new.closed_at := null;
  end if;

  return new;
end;
$$;



