CREATE FUNCTION public.preview_trade_invitation_v2(p_token_hash text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  invitation_row public.trade_invitations%rowtype;
  offer_row public.offers%rowtype;
  sender_name text;
  current_terms_hash text;
  response_thread_id uuid;
begin
  if p_token_hash !~ '^[0-9a-f]{64}$' then
    return null;
  end if;

  select * into invitation_row
  from public.trade_invitations
  where token_hash = p_token_hash;

  if not found or invitation_row.status in ('revoked', 'expired') then
    return null;
  end if;

  select * into offer_row
  from public.offers
  where id = invitation_row.offer_id
  for update;

  if not found then
    return null;
  end if;

  perform moral_trade_private.lock_invitation_delivery(invitation_row.id);
  select * into invitation_row
  from public.trade_invitations
  where id = invitation_row.id
    and token_hash = p_token_hash
  for update;

  if not found or invitation_row.status in ('revoked', 'expired') then
    return null;
  end if;

  if invitation_row.expires_at <= now()
     and moral_trade_private.invitation_status_is_usable(invitation_row.status) then
    update public.trade_invitations
    set
      status = 'expired',
      revoked_at = now(),
      revocation_reason = 'Invitation expired after 14 days.',
      updated_at = now()
    where id = invitation_row.id;
    perform moral_trade_private.suppress_invitation_email(
      invitation_row.id,
      'Invitation expired before delivery.'
    );
    return null;
  end if;

  current_terms_hash := public.core_trade_terms_hash(
    offer_row.offer_action,
    offer_row.request_action,
    offer_row.duration,
    offer_row.start_date,
    offer_row.verification,
    offer_row.evidence_due_date,
    offer_row.exit_conditions,
    offer_row.maximum_burden,
    offer_row.privacy_scope,
    offer_row.no_trade_baseline
  );

  if moral_trade_private.invitation_status_is_usable(invitation_row.status)
     and (
       not moral_trade_private.offer_is_invitable(offer_row.id)
       or invitation_row.terms_version <> offer_row.terms_version
       or invitation_row.terms_hash <> current_terms_hash
     ) then
    update public.trade_invitations
    set
      status = 'revoked',
      revoked_at = now(),
      revocation_reason = 'The reviewed offer terms or eligibility changed.',
      updated_at = now()
    where id = invitation_row.id;
    perform moral_trade_private.suppress_invitation_email(
      invitation_row.id,
      'Invitation terms changed before response.'
    );
    return null;
  end if;

  if invitation_row.status in ('drafted', 'sent') then
    update public.trade_invitations
    set
      status = 'opened',
      opened_at = coalesce(opened_at, now()),
      updated_at = now()
    where id = invitation_row.id;
    invitation_row.status := 'opened';
    invitation_row.opened_at := coalesce(invitation_row.opened_at, now());
  end if;

  select p.display_name into sender_name
  from public.profiles p
  where p.id = invitation_row.sender_id;

  if p_actor_id is not null
     and p_actor_id in (invitation_row.sender_id, invitation_row.recipient_user_id) then
    select t.id into response_thread_id
    from public.trade_threads t
    where t.offer_id = invitation_row.offer_id
      and (
        (t.participant_a = invitation_row.sender_id and t.participant_b = p_actor_id)
        or
        (t.participant_b = invitation_row.sender_id and t.participant_a = p_actor_id)
      )
    order by t.created_at desc
    limit 1;
  end if;

  return jsonb_build_object(
    'invitationId', invitation_row.id,
    'status', invitation_row.status,
    'deliveryKind', invitation_row.delivery_kind,
    'message', invitation_row.message,
    'expiresAt', invitation_row.expires_at,
    'openedAt', invitation_row.opened_at,
    'senderDisplayName', coalesce(nullif(sender_name, ''), 'A Moral Trade participant'),
    'threadId', response_thread_id,
    'offer', jsonb_build_object(
      'id', offer_row.id,
      'offeredCause', offer_row.offered_cause,
      'requestedCause', offer_row.requested_cause,
      'offerAction', offer_row.offer_action,
      'requestAction', offer_row.request_action,
      'verification', offer_row.verification,
      'duration', offer_row.duration,
      'noTradeBaseline', offer_row.no_trade_baseline,
      'startDate', offer_row.start_date,
      'exitConditions', offer_row.exit_conditions,
      'maximumBurden', offer_row.maximum_burden,
      'privacyScope', offer_row.privacy_scope,
      'evidenceDueDate', offer_row.evidence_due_date,
      'termsVersion', offer_row.terms_version
    )
  );
end;
$_$;



CREATE FUNCTION public.profile_participates_in_match(target_match_id uuid, target_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    target_profile_id is not null
    and exists (
      select 1
      from public.match_suggestions
      where id = target_match_id
        and (
          profile_a_id = target_profile_id
          or profile_b_id = target_profile_id
        )
    );
$$;



CREATE FUNCTION public.profile_username_is_reserved_v1(p_username text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select public.normalize_profile_username_v1(p_username) = any (array[
    'about','account','admin','administrator','api','app','auth','billing','blog',
    'contact','create','dashboard','discover','docs','help','legal','login','logout',
    'moral-trade','moraltrade','moderator','notifications','people','privacy','profile',
    'root','security','settings','signup','staff','support','system','terms','trade',
    'trades','user','users','verification','www'
  ]::text[]);
$$;



CREATE FUNCTION public.promote_conditional_redirect_backup_or_fallback(p_offer_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_offer public.conditional_redirect_offers%rowtype;
  v_backup uuid;
begin
  select * into v_offer
  from public.conditional_redirect_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception 'conditional redirect offer not found';
  end if;
  if v_offer.status <> 'matcher_recovery' then
    raise exception 'conditional redirect offer is not in matcher recovery';
  end if;
  if v_offer.recovery_ends_at is null
     or timezone('utc', now()) < v_offer.recovery_ends_at then
    raise exception 'matcher recovery window is still open';
  end if;

  update public.conditional_redirect_candidates
  set status = 'declined',
      recovery_ends_at = null
  where id = v_offer.winning_candidate_id
    and status = 'recovery';

  select id into v_backup
  from public.conditional_redirect_candidates
  where offer_id = p_offer_id
    and status = 'backup'
    and setup_succeeded_at <= v_offer.deadline_at
  order by stripe_event_created_at, setup_succeeded_at, stripe_event_id, id
  limit 1
  for update;

  if v_backup is null then
    update public.conditional_redirect_offers
    set status = 'fallback_settling',
        winning_candidate_id = null,
        recovery_ends_at = null,
        settlement_started_at = timezone('utc', now())
    where id = p_offer_id;
    return null;
  end if;

  update public.conditional_redirect_candidates
  set status = 'promoted',
      recovery_ends_at = null
  where id = v_backup;

  update public.conditional_redirect_offers
  set status = 'matched_settling',
      winning_candidate_id = v_backup,
      recovery_ends_at = null,
      settlement_started_at = timezone('utc', now())
  where id = p_offer_id;
  return v_backup;
end;
$$;



CREATE FUNCTION public.propose_agreement_version_v3(p_actor_id uuid, p_agreement_id uuid, p_submission_key text, p_proposed_action text, p_requested_action text, p_duration text, p_start_date date, p_evidence_rule text, p_evidence_due_date date, p_exit_conditions text, p_maximum_burden text, p_privacy_scope text, p_no_trade_baseline text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  version_row public.trade_agreement_versions%rowtype;
  existing_row public.trade_agreement_versions%rowtype;
  next_version integer;
  counterpart_id uuid;
  terms_hash_value text;
  normalized_key text := btrim(coalesce(p_submission_key, ''));
begin
  if normalized_key = '' or length(normalized_key) > 200 then
    raise exception 'A bounded agreement version submission key is required.';
  end if;
  if greatest(
    length(btrim(coalesce(p_proposed_action, ''))),
    length(btrim(coalesce(p_requested_action, ''))),
    length(btrim(coalesce(p_duration, ''))),
    length(btrim(coalesce(p_evidence_rule, ''))),
    length(btrim(coalesce(p_exit_conditions, ''))),
    length(btrim(coalesce(p_maximum_burden, ''))),
    length(btrim(coalesce(p_privacy_scope, ''))),
    length(btrim(coalesce(p_no_trade_baseline, '')))
  ) > 5000
  or btrim(coalesce(p_proposed_action, '')) = ''
  or btrim(coalesce(p_requested_action, '')) = ''
  or btrim(coalesce(p_duration, '')) = ''
  or btrim(coalesce(p_evidence_rule, '')) = ''
  or btrim(coalesce(p_exit_conditions, '')) = ''
  or btrim(coalesce(p_maximum_burden, '')) = ''
  or btrim(coalesce(p_privacy_scope, '')) = ''
  or btrim(coalesce(p_no_trade_baseline, '')) = '' then
    raise exception 'Complete every bounded agreement term.';
  end if;

  select * into existing_row
  from public.trade_agreement_versions
  where proposed_by = p_actor_id and submission_key = normalized_key
  limit 1;
  if existing_row.id is not null then
    if existing_row.agreement_id <> p_agreement_id then
      raise exception 'Agreement version submission key belongs to another agreement.';
    end if;
    return jsonb_build_object(
      'agreementId', existing_row.agreement_id,
      'versionId', existing_row.id,
      'version', existing_row.version,
      'created', false
    );
  end if;

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;
  if agreement_row.lifecycle_status <> 'proposed' then
    raise exception 'Activated agreement terms are immutable. Exit and create a new agreement to change them.';
  end if;

  terms_hash_value := public.core_trade_terms_hash(
    btrim(p_proposed_action), btrim(p_requested_action), btrim(p_duration), p_start_date,
    btrim(p_evidence_rule), p_evidence_due_date, btrim(p_exit_conditions),
    btrim(p_maximum_burden), btrim(p_privacy_scope), btrim(p_no_trade_baseline)
  );

  select * into existing_row
  from public.trade_agreement_versions
  where agreement_id = p_agreement_id and terms_hash = terms_hash_value
  limit 1;
  if existing_row.id is not null then
    if existing_row.id = agreement_row.current_version_id then
      return jsonb_build_object(
        'agreementId', existing_row.agreement_id,
        'versionId', existing_row.id,
        'version', existing_row.version,
        'created', false
      );
    end if;
    raise exception 'These exact terms already exist in the version history. Submit a materially distinct version.';
  end if;

  select coalesce(max(version), 0) + 1 into next_version
  from public.trade_agreement_versions
  where agreement_id = p_agreement_id;

  perform set_config('app.core_trade_linking_agreement', '1', true);
  insert into public.trade_agreement_versions(
    agreement_id, version, proposed_by, proposed_action, requested_action,
    duration, start_date, evidence_rule, evidence_due_date, exit_conditions,
    maximum_burden, privacy_scope, no_trade_baseline, terms_hash, submission_key, created_at
  ) values (
    p_agreement_id, next_version, p_actor_id,
    btrim(p_proposed_action), btrim(p_requested_action), btrim(p_duration), p_start_date,
    btrim(p_evidence_rule), p_evidence_due_date, btrim(p_exit_conditions),
    btrim(p_maximum_burden), btrim(p_privacy_scope), btrim(p_no_trade_baseline),
    terms_hash_value, normalized_key, now()
  ) returning * into version_row;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set current_version_id = version_row.id,
      evidence_due_at = version_row.evidence_due_date,
      lifecycle_status = 'proposed',
      status = 'proposed',
      updated_at = now()
  where id = p_agreement_id;

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'agreement_amendment',
      'Agreement amendment proposed',
      'A new immutable term version is awaiting separate confirmation from both participants.',
      '/trade-agreements/' || p_agreement_id::text,
      'agreement_amendment:' || version_row.id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'agreementId', p_agreement_id,
    'versionId', version_row.id,
    'version', version_row.version,
    'created', true
  );
end;
$$;



CREATE FUNCTION public.publish_mpgf_phase_one_results(p_round_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_round public.mpgf_phase_one_rounds%rowtype;
  v_eligible_count integer;
  v_ballot_count integer;
  v_quorum_required integer;
  v_quorum_met boolean;
  v_result_hash text;
  v_status text;
begin
  select *
  into v_round
  from public.mpgf_phase_one_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'MPGF phase-one round not found.';
  end if;

  if v_round.status in ('results_published', 'quorum_failed', 'closed') then
    select count(*)
    into v_eligible_count
    from public.mpgf_phase_one_eligible_voters
    where round_id = p_round_id;

    select count(*)
    into v_ballot_count
    from public.mpgf_phase_one_ballots
    where round_id = p_round_id
      and status = 'submitted';

    v_quorum_required := (v_eligible_count + 1) / 2;

    return jsonb_build_object(
      'ok', true,
      'replayed', true,
      'roundId', p_round_id,
      'status', v_round.status,
      'eligiblePledgerCount', v_eligible_count,
      'submittedBallotCount', v_ballot_count,
      'quorumRequiredCount', v_quorum_required,
      'quorumMet', v_round.quorum_met,
      'quorumBps', 5000,
      'resultHash', v_round.result_hash,
      'binding', false,
      'externalCheckoutConfirmationRequired', true
    );
  end if;

  if v_round.status <> 'ballot_open' then
    raise exception 'MPGF phase-one results can publish only from ballot_open.';
  end if;

  if v_round.ballot_closes_at is not null
     and timezone('utc', now()) < v_round.ballot_closes_at then
    raise exception 'MPGF ballot window has not closed.';
  end if;

  select count(*)
  into v_eligible_count
  from public.mpgf_phase_one_eligible_voters
  where round_id = p_round_id;

  select count(*)
  into v_ballot_count
  from public.mpgf_phase_one_ballots
  where round_id = p_round_id
    and status = 'submitted';

  v_quorum_required := (v_eligible_count + 1) / 2;
  v_quorum_met := v_eligible_count > 0
    and v_ballot_count >= v_quorum_required;
  v_status := case when v_quorum_met then 'results_published' else 'quorum_failed' end;

  select pg_catalog.encode(
    pg_catalog.sha256(
      pg_catalog.convert_to(
        p_round_id::text
        || '|' || v_eligible_count::text
        || '|' || v_ballot_count::text
        || '|' || v_quorum_required::text
        || '|' || coalesce(
          string_agg(
            score.project_id::text || ':' || score.credit_score::text,
            ',' order by score.project_id
          ),
          ''
        ),
        'UTF8'
      )
    ),
    'hex'
  )
  into v_result_hash
  from (
    select
      candidate.project_id,
      coalesce(
        sum(1::numeric / nullif(ballot.selection_count, 0)::numeric)
          filter (where ballot.status = 'submitted'),
        0::numeric
      ) as credit_score
    from public.mpgf_phase_one_candidate_snapshots candidate
    left join public.mpgf_phase_one_ballot_approvals approval
      on approval.round_id = candidate.round_id
      and approval.project_id = candidate.project_id
    left join public.mpgf_phase_one_ballots ballot
      on ballot.id = approval.ballot_id
      and ballot.round_id = candidate.round_id
    where candidate.round_id = p_round_id
    group by candidate.project_id
  ) score;

  update public.mpgf_phase_one_rounds
  set
    status = v_status,
    result_hash = v_result_hash,
    quorum_met = v_quorum_met,
    results_published_at = timezone('utc', now()),
    updated_at = timezone('utc', now())
  where id = p_round_id;

  return jsonb_build_object(
    'ok', true,
    'roundId', p_round_id,
    'status', v_status,
    'eligiblePledgerCount', v_eligible_count,
    'submittedBallotCount', v_ballot_count,
    'quorumRequiredCount', v_quorum_required,
    'quorumMet', v_quorum_met,
    'quorumBps', 5000,
    'resultHash', v_result_hash,
    'binding', false,
    'externalCheckoutConfirmationRequired', true
  );
end;
$$;



CREATE FUNCTION public.publish_trade_evidence_v3(p_actor_id uuid, p_evidence_id uuid, p_public_title text DEFAULT ''::text, p_public_summary text DEFAULT ''::text, p_public_url text DEFAULT ''::text, p_public_storage_path text DEFAULT ''::text, p_public_original_filename text DEFAULT ''::text, p_public_mime_type text DEFAULT ''::text, p_public_redaction_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  evidence_row public.trade_evidence_items%rowtype;
  agreement_row public.agreements%rowtype;
  normalized_title text := btrim(coalesce(p_public_title, ''));
  normalized_summary text := btrim(coalesce(p_public_summary, ''));
  normalized_url text := btrim(coalesce(p_public_url, ''));
  normalized_storage_path text := btrim(coalesce(p_public_storage_path, ''));
  normalized_filename text := btrim(coalesce(p_public_original_filename, ''));
  normalized_mime_type text := btrim(coalesce(p_public_mime_type, ''));
  normalized_note text := btrim(coalesce(p_public_redaction_note, ''));
  redaction_state text;
begin
  if p_actor_id is null or p_evidence_id is null then
    raise exception 'A signed-in evidence submitter is required.';
  end if;
  if length(normalized_title) > 300
     or length(normalized_summary) > 5000
     or length(normalized_url) > 2000
     or length(normalized_storage_path) > 2000
     or length(normalized_filename) > 500
     or length(normalized_mime_type) > 200
     or length(normalized_note) > 2000 then
    raise exception 'Public evidence fields are too long.';
  end if;
  if normalized_note = '' then
    raise exception 'Describe what was removed or reviewed before publication.';
  end if;

  select * into evidence_row
  from public.trade_evidence_items
  where id = p_evidence_id
  for update;
  if not found or evidence_row.submitted_by <> p_actor_id then
    raise exception 'Evidence not found or access denied.';
  end if;
  if evidence_row.status in ('withdrawn', 'replaced') then
    raise exception 'Withdrawn or replaced evidence cannot be published.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = evidence_row.agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;

  if evidence_row.evidence_type = 'file' then
    if normalized_storage_path = ''
       or normalized_storage_path = evidence_row.storage_path
       or split_part(normalized_storage_path, '/', 1) <> evidence_row.agreement_id::text
       or split_part(normalized_storage_path, '/', 2) <> p_actor_id::text
       or split_part(normalized_storage_path, '/', 3) <> 'public'
       or split_part(normalized_storage_path, '/', 4) = ''
       or normalized_filename = ''
       or normalized_mime_type = '' then
      raise exception 'A separate reviewed public-safe file is required.';
    end if;
    if normalized_url <> '' then
      raise exception 'Publish either a public file or a public URL, not both.';
    end if;
    redaction_state := 'redacted';
  elsif evidence_row.evidence_type = 'link' then
    if normalized_url !~* '^https?://' then
      raise exception 'A public evidence link must use http or https.';
    end if;
    if normalized_storage_path <> '' then
      raise exception 'Publish either a public file or a public URL, not both.';
    end if;
    redaction_state := 'not_required';
  elsif evidence_row.evidence_type = 'attestation' then
    if normalized_summary = '' then
      raise exception 'Write a public-safe summary instead of publishing the private attestation verbatim.';
    end if;
    if normalized_url <> '' or normalized_storage_path <> '' then
      raise exception 'Attestation publication uses the public-safe summary only.';
    end if;
    redaction_state := 'redacted';
  else
    raise exception 'Provider evidence cannot be published through this participant workflow.';
  end if;

  update public.trade_evidence_items
  set public_visibility = 'public',
      public_title = normalized_title,
      public_summary = normalized_summary,
      public_url = normalized_url,
      public_storage_path = normalized_storage_path,
      public_original_filename = normalized_filename,
      public_mime_type = normalized_mime_type,
      public_redaction_note = normalized_note,
      redaction_status = redaction_state,
      public_published_at = now()
  where id = p_evidence_id;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set public_evidence_enabled = true,
      public_evidence_updated_at = now(),
      updated_at = now()
  where id = evidence_row.agreement_id;

  return jsonb_build_object(
    'evidenceId', p_evidence_id,
    'visibility', 'public',
    'redactionStatus', redaction_state,
    'published', true
  );
end;
$$;



CREATE FUNCTION public.record_core_onboarding_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.completed_at is not null or new.status = 'completed' then
    insert into public.core_loop_events(
      profile_id, event_type, entity_type, entity_id, idempotency_key
    ) values (
      new.profile_id,
      'onboarding_completed',
      'profile',
      new.profile_id,
      'onboarding_completed:' || new.profile_id::text
    ) on conflict (idempotency_key) do nothing;
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.record_core_signup_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.core_loop_events(
    profile_id, event_type, entity_type, entity_id, idempotency_key
  ) values (
    new.id, 'signup_completed', 'profile', new.id, 'signup_completed:' || new.id::text
  ) on conflict (idempotency_key) do nothing;
  return new;
end;
$$;



CREATE FUNCTION public.record_profile_username_claim_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if old.username is not distinct from new.username then
      return new;
    end if;
    if old.username is not null then
      update public.profile_username_claims
      set is_current = false,
          superseded_at = coalesce(superseded_at, timezone('utc', now()))
      where username = old.username
        and profile_id = new.id;
    end if;
  elsif new.username is null then
    return new;
  end if;
  if new.username is not null then
    insert into public.profile_username_claims(
      username,
      profile_id,
      is_current,
      claimed_at,
      superseded_at
    ) values (
      new.username,
      new.id,
      true,
      timezone('utc', now()),
      null
    )
    on conflict (username) do update
    set is_current = true,
        superseded_at = null
    where public.profile_username_claims.profile_id = excluded.profile_id;
    if not found then
      raise exception 'username_already_claimed_or_reserved' using errcode = '23505';
    end if;
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.record_trade_donation_pool_refund_or_dispute(p_stripe_event_id text, p_event_type text, p_livemode boolean, p_payload_hash text, p_signature_verified boolean, p_obligation_id uuid, p_is_dispute boolean, p_amount_cents integer, p_failure_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  obligation_row public.trade_donation_pool_obligations%rowtype;
  bundle_row public.trade_donation_pool_bundles%rowtype;
  inserted_count integer := 0;
  journal_id_value uuid;
begin
  insert into public.trade_donation_pool_stripe_events(
    stripe_event_id, event_type, livemode, payload_hash, signature_verified,
    obligation_id, status, details, processed_at
  ) values (
    p_stripe_event_id, p_event_type, p_livemode, p_payload_hash, p_signature_verified,
    p_obligation_id, 'processed', jsonb_build_object('isDispute', p_is_dispute), timezone('utc', now())
  )
  on conflict (stripe_event_id) do nothing;
  get diagnostics inserted_count = row_count;
  if inserted_count = 0 then
    return jsonb_build_object('status', 'duplicate');
  end if;
  if not p_signature_verified then
    update public.trade_donation_pool_stripe_events set status = 'mismatch'
    where stripe_event_id = p_stripe_event_id;
    return jsonb_build_object('status', 'mismatch');
  end if;

  select * into obligation_row
  from public.trade_donation_pool_obligations
  where id = p_obligation_id
  for update;
  if not found then
    return jsonb_build_object('status', 'ignored');
  end if;
  if p_amount_cents <> obligation_row.amount_cents or p_livemode <> obligation_row.stripe_livemode then
    update public.trade_donation_pool_obligations
    set status = 'needs_review', failure_code = 'refund_or_dispute_mismatch',
        failure_message = 'Stripe refund or dispute amount/environment did not match the obligation.'
    where id = obligation_row.id;
    return jsonb_build_object('status', 'mismatch');
  end if;

  if obligation_row.bundle_id is null and obligation_row.status in ('funded', 'refund_pending') then
    update public.trade_donation_pool_obligations
    set
      status = case when p_is_dispute then 'disputed' else 'refunded' end,
      refunded_at = case when p_is_dispute then refunded_at else timezone('utc', now()) end,
      failure_code = case when p_is_dispute then 'pre_settlement_dispute' else '' end,
      failure_message = left(coalesce(p_failure_message, ''), 500)
    where id = obligation_row.id
    returning * into obligation_row;

    if p_is_dispute then
      insert into public.trade_donation_pool_ledger_journals(
        event_key, journal_type, obligation_id, currency, status, description
      ) values (
        'stripe-dispute:' || p_stripe_event_id,
        'pre_settlement_chargeback',
        obligation_row.id,
        obligation_row.currency,
        'draft',
        'Participant payment disputed before pooled settlement.'
      )
      returning id into journal_id_value;
      insert into public.trade_donation_pool_ledger_lines(
        journal_id, account_code, entry_side, amount_cents, currency, profile_id, obligation_id
      ) values
        (journal_id_value, 'participant_settlement_liability', 'debit', obligation_row.amount_cents, obligation_row.currency, obligation_row.payer_user_id, obligation_row.id),
        (journal_id_value, 'platform_cash_asset', 'credit', obligation_row.amount_cents, obligation_row.currency, obligation_row.payer_user_id, obligation_row.id);
      update public.trade_donation_pool_ledger_journals
      set status = 'posted', posted_at = timezone('utc', now())
      where id = journal_id_value;
    else
      perform moral_trade_private.post_trade_donation_pool_refund_journal(
        obligation_row,
        'stripe-refund:' || p_stripe_event_id
      );
    end if;
    return jsonb_build_object('status', obligation_row.status);
  end if;

  if obligation_row.bundle_id is not null then
    select * into bundle_row
    from public.trade_donation_pool_bundles
    where id = obligation_row.bundle_id
    for update;

    update public.trade_donation_pool_obligations
    set
      status = 'disputed',
      failure_code = case when p_is_dispute then 'post_bundle_dispute' else 'post_bundle_refund' end,
      failure_message = left(coalesce(p_failure_message, 'Participant funds reversed after bundle freeze.'), 500)
    where id = obligation_row.id;

    update public.trade_donation_pool_bundles
    set
      status = 'needs_review',
      failure_code = case when p_is_dispute then 'component_dispute_after_bundle' else 'component_refund_after_bundle' end,
      failure_message = 'A participant contribution was reversed after the bundle became immutable.'
    where id = obligation_row.bundle_id
      and status in ('frozen', 'checkout_started', 'completed');

    if bundle_row.status = 'completed' then
      insert into public.trade_donation_pool_ledger_journals(
        event_key, journal_type, obligation_id, bundle_id, currency, status, description
      ) values (
        'stripe-post-settlement-loss:' || p_stripe_event_id,
        'post_settlement_chargeback',
        obligation_row.id,
        obligation_row.bundle_id,
        obligation_row.currency,
        'draft',
        'Participant funds reversed after the consolidated charitable gift was completed.'
      )
      returning id into journal_id_value;
      insert into public.trade_donation_pool_ledger_lines(
        journal_id, account_code, entry_side, amount_cents, currency, profile_id, obligation_id, bundle_id
      ) values
        (journal_id_value, 'chargeback_loss_expense', 'debit', obligation_row.amount_cents, obligation_row.currency, obligation_row.payer_user_id, obligation_row.id, obligation_row.bundle_id),
        (journal_id_value, 'platform_cash_asset', 'credit', obligation_row.amount_cents, obligation_row.currency, obligation_row.payer_user_id, obligation_row.id, obligation_row.bundle_id);
      update public.trade_donation_pool_ledger_journals
      set status = 'posted', posted_at = timezone('utc', now())
      where id = journal_id_value;
    end if;

    return jsonb_build_object('status', 'needs_review', 'bundleId', obligation_row.bundle_id);
  end if;

  return jsonb_build_object('status', 'ignored');
end;
$$;



CREATE FUNCTION public.record_trade_donation_pool_stripe_failure(p_stripe_event_id text, p_event_type text, p_livemode boolean, p_payload_hash text, p_signature_verified boolean, p_obligation_id uuid, p_failure_code text, p_failure_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  obligation_row public.trade_donation_pool_obligations%rowtype;
  next_status text;
  inserted_count integer := 0;
begin
  insert into public.trade_donation_pool_stripe_events(
    stripe_event_id, event_type, livemode, payload_hash, signature_verified,
    obligation_id, status, details, processed_at
  ) values (
    p_stripe_event_id, p_event_type, p_livemode, p_payload_hash, p_signature_verified,
    p_obligation_id, 'processed', jsonb_build_object('failureCode', p_failure_code), timezone('utc', now())
  )
  on conflict (stripe_event_id) do nothing;
  get diagnostics inserted_count = row_count;

  if inserted_count = 0 then
    return jsonb_build_object('status', 'duplicate');
  end if;
  if not p_signature_verified then
    update public.trade_donation_pool_stripe_events set status = 'mismatch'
    where stripe_event_id = p_stripe_event_id;
    return jsonb_build_object('status', 'mismatch');
  end if;

  select * into obligation_row
  from public.trade_donation_pool_obligations
  where id = p_obligation_id
  for update;
  if not found then
    return jsonb_build_object('status', 'ignored');
  end if;
  if obligation_row.status not in ('checkout_started', 'awaiting_funding', 'payment_failed', 'checkout_abandoned') then
    return jsonb_build_object('status', 'ignored');
  end if;

  next_status := case
    when p_failure_code = 'checkout_abandoned' then 'checkout_abandoned'
    else 'payment_failed'
  end;
  update public.trade_donation_pool_obligations
  set
    status = next_status,
    failure_code = left(coalesce(p_failure_code, 'stripe_payment_failed'), 120),
    failure_message = left(coalesce(p_failure_message, 'Stripe did not fund the pooled obligation.'), 500)
  where id = obligation_row.id;

  return jsonb_build_object('status', next_status);
end;
$$;



CREATE FUNCTION public.record_trade_donation_pool_stripe_success(p_stripe_event_id text, p_event_type text, p_livemode boolean, p_payload_hash text, p_signature_verified boolean, p_obligation_id uuid, p_checkout_session_id text, p_payment_intent_id text, p_charge_id_hash text, p_amount_cents integer, p_currency text, p_condition_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  obligation_row public.trade_donation_pool_obligations%rowtype;
  bundle_id_value uuid;
  inserted_count integer := 0;
begin
  insert into public.trade_donation_pool_stripe_events(
    stripe_event_id, event_type, livemode, payload_hash, signature_verified,
    obligation_id, status, details, processed_at
  ) values (
    p_stripe_event_id, p_event_type, p_livemode, p_payload_hash, p_signature_verified,
    p_obligation_id, 'processed', '{}'::jsonb, timezone('utc', now())
  )
  on conflict (stripe_event_id) do nothing;
  get diagnostics inserted_count = row_count;

  if inserted_count = 0 then
    return jsonb_build_object('status', 'duplicate', 'bundleId', null);
  end if;
  if not p_signature_verified then
    update public.trade_donation_pool_stripe_events
    set status = 'mismatch', details = jsonb_build_object('failureCode', 'signature_not_verified')
    where stripe_event_id = p_stripe_event_id;
    return jsonb_build_object('status', 'mismatch', 'bundleId', null);
  end if;

  select * into obligation_row
  from public.trade_donation_pool_obligations
  where id = p_obligation_id
  for update;

  if not found then
    update public.trade_donation_pool_stripe_events
    set status = 'mismatch', details = jsonb_build_object('failureCode', 'obligation_not_found')
    where stripe_event_id = p_stripe_event_id;
    return jsonb_build_object('status', 'mismatch', 'bundleId', null);
  end if;

  if obligation_row.status in ('funded', 'bundled', 'settled')
     and obligation_row.stripe_payment_intent_id = p_payment_intent_id then
    return jsonb_build_object('status', 'already_funded', 'bundleId', obligation_row.bundle_id);
  end if;

  if obligation_row.status not in ('checkout_started', 'awaiting_funding', 'payment_failed')
     or obligation_row.stripe_livemode <> p_livemode
     or obligation_row.stripe_checkout_session_id is distinct from p_checkout_session_id
     or obligation_row.amount_cents <> p_amount_cents
     or obligation_row.currency <> upper(p_currency)
     or obligation_row.condition_hash <> p_condition_hash
     or length(trim(coalesce(p_payment_intent_id, ''))) = 0
     or coalesce(p_charge_id_hash, '') !~ '^[0-9a-f]{64}$' then
    update public.trade_donation_pool_obligations
    set
      status = 'needs_review',
      failure_code = 'stripe_funding_mismatch',
      failure_message = 'The signed Stripe event did not match the frozen pooled obligation.',
      stripe_payload_hash = p_payload_hash
    where id = p_obligation_id;
    update public.trade_donation_pool_stripe_events
    set status = 'mismatch', details = jsonb_build_object('failureCode', 'stripe_funding_mismatch')
    where stripe_event_id = p_stripe_event_id;
    return jsonb_build_object('status', 'mismatch', 'bundleId', null);
  end if;

  update public.trade_donation_pool_obligations
  set
    status = 'funded',
    stripe_payment_intent_id = p_payment_intent_id,
    stripe_charge_id_hash = p_charge_id_hash,
    stripe_payload_hash = p_payload_hash,
    funded_at = coalesce(funded_at, timezone('utc', now())),
    failure_code = '',
    failure_message = ''
  where id = obligation_row.id
  returning * into obligation_row;

  perform moral_trade_private.post_trade_donation_pool_funding_journal(
    obligation_row,
    'stripe-funding:' || p_payment_intent_id
  );

  bundle_id_value := moral_trade_private.try_freeze_trade_donation_pool_bundle(
    obligation_row.environment,
    obligation_row.nonprofit_slug,
    obligation_row.nonprofit_ein,
    obligation_row.currency,
    obligation_row.frequency
  );

  insert into public.trade_donation_pool_audit_events(
    actor_kind, event_type, object_type, object_id, details
  ) values (
    'stripe',
    'participant_funding_verified',
    'obligation',
    obligation_row.id,
    jsonb_build_object('stripeEventId', p_stripe_event_id, 'bundleId', bundle_id_value)
  );

  return jsonb_build_object(
    'status', case when bundle_id_value is null then 'funded' else 'bundled' end,
    'bundleId', bundle_id_value
  );
end;
$_$;



CREATE FUNCTION public.refresh_profile_credibility(target_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  active_model public.credibility_model_versions%rowtype;
begin
  select *
  into active_model
  from public.credibility_model_versions
  where status = 'active'
  order by activated_at desc nulls last, created_at desc
  limit 1;

  if active_model.version is null then
    raise exception 'No active credibility model version';
  end if;

  delete from public.credibility_public_aggregates
  where profile_id = target_profile_id;

  insert into public.credibility_public_aggregates (
    profile_id,
    role,
    category,
    dimension,
    weighted_success,
    weighted_failure,
    effective_observations,
    event_count,
    independent_counterparties,
    last_event_at,
    as_of_at,
    model_version
  )
  with ranked as (
    select
      event_row.*,
      row_number() over (
        partition by event_row.profile_id,
          coalesce(event_row.counterparty_id::text, event_row.id::text),
          event_row.role,
          event_row.category,
          event_row.dimension
        order by event_row.occurred_at, event_row.id
      ) as counterparty_sequence
    from public.credibility_events event_row
    where event_row.profile_id = target_profile_id
      and event_row.eligible
  ), weighted as (
    select
      ranked.*,
      (
        exp(
          -ln(2::numeric)
          * greatest(0::numeric, extract(epoch from (now() - ranked.occurred_at))::numeric / 86400::numeric)
          / active_model.recency_half_life_days::numeric
        )
        * public.credibility_proof_weight(ranked.evidence_quality, active_model.proof_weights)
        * (1::numeric / sqrt(ranked.counterparty_sequence::numeric))
        * ranked.context_similarity
        * public.credibility_stake_weight(ranked.stake_units)
      ) as event_weight
    from ranked
  )
  select
    target_profile_id,
    weighted.role,
    weighted.category,
    weighted.dimension,
    sum(weighted.event_weight * weighted.outcome),
    sum(weighted.event_weight * (1::numeric - weighted.outcome)),
    sum(weighted.event_weight),
    count(*)::integer,
    count(distinct weighted.counterparty_id)::integer,
    max(weighted.occurred_at),
    now(),
    active_model.version
  from weighted
  group by weighted.role, weighted.category, weighted.dimension;
end;
$$;



CREATE FUNCTION public.refresh_profile_credibility_status(target_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  active_count integer;
  severe_count integer;
begin
  select
    count(*) filter (
      where restriction.status in ('active', 'reviewing')
        and restriction.starts_at <= now()
        and (restriction.ends_at is null or restriction.ends_at > now())
    )::integer,
    count(*) filter (
      where restriction.status = 'active'
        and restriction.restriction_type in ('account_compromise', 'identity_duplication', 'fraud', 'forged_evidence', 'coercion', 'threat')
        and restriction.starts_at <= now()
        and (restriction.ends_at is null or restriction.ends_at > now())
    )::integer
  into active_count, severe_count
  from public.credibility_restrictions restriction
  where restriction.profile_id = target_profile_id;

  insert into public.credibility_profile_status (
    profile_id,
    eligibility_state,
    active_restriction_count,
    updated_at
  )
  values (
    target_profile_id,
    case
      when severe_count > 0 then 'restricted'
      when active_count > 0 then 'review_required'
      else 'eligible'
    end,
    active_count,
    now()
  )
  on conflict (profile_id) do update set
    eligibility_state = excluded.eligibility_state,
    active_restriction_count = excluded.active_restriction_count,
    updated_at = excluded.updated_at;
end;
$$;



CREATE FUNCTION public.refresh_profile_rating_summary(target_profile_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  update public.profiles
  set
    rating_count = (
      select count(*)
      from public.agreement_ratings
      where rated_user_id = target_profile_id
    ),
    rating_avg = (
      select avg(score)::double precision
      from public.agreement_ratings
      where rated_user_id = target_profile_id
    )
  where id = target_profile_id;
end;
$$;



CREATE FUNCTION public.register_trade_evidence_v3(p_actor_id uuid, p_agreement_id uuid, p_submission_key text, p_evidence_type text, p_storage_path text DEFAULT ''::text, p_evidence_url text DEFAULT ''::text, p_attestation text DEFAULT ''::text, p_replaces_evidence_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  evidence_row public.trade_evidence_items%rowtype;
  prior_row public.trade_evidence_items%rowtype;
  counterpart_id uuid;
  normalized_key text := btrim(coalesce(p_submission_key, ''));
  normalized_type text := btrim(coalesce(p_evidence_type, ''));
  normalized_storage_path text := btrim(coalesce(p_storage_path, ''));
  normalized_url text := btrim(coalesce(p_evidence_url, ''));
  normalized_attestation text := btrim(coalesce(p_attestation, ''));
  remaining_challenges integer;
begin
  if p_actor_id is null or p_agreement_id is null then
    raise exception 'A signed-in agreement participant is required.';
  end if;
  if normalized_key = '' or length(normalized_key) > 200 then
    raise exception 'A bounded evidence submission key is required.';
  end if;
  if normalized_type not in ('file', 'link', 'attestation') then
    raise exception 'Unsupported evidence type.';
  end if;
  if length(normalized_storage_path) > 2000
     or length(normalized_url) > 2000
     or length(normalized_attestation) > 5000 then
    raise exception 'Evidence fields are too long.';
  end if;

  select * into evidence_row
  from public.trade_evidence_items
  where submitted_by = p_actor_id and submission_key = normalized_key
  limit 1;
  if evidence_row.id is not null then
    if evidence_row.agreement_id <> p_agreement_id then
      raise exception 'Evidence submission key belongs to another agreement.';
    end if;
    return jsonb_build_object(
      'evidenceId', evidence_row.id,
      'status', evidence_row.status,
      'created', false
    );
  end if;

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;
  if agreement_row.lifecycle_status not in ('active', 'evidence_due', 'disputed') then
    raise exception 'Evidence can be submitted only after bilateral activation.';
  end if;

  if normalized_type = 'file' then
    if normalized_storage_path = ''
       or split_part(normalized_storage_path, '/', 1) <> p_agreement_id::text
       or split_part(normalized_storage_path, '/', 2) <> p_actor_id::text
       or split_part(normalized_storage_path, '/', 3) <> 'private'
       or split_part(normalized_storage_path, '/', 4) = '' then
      raise exception 'Private evidence file path is invalid.';
    end if;
    if normalized_url <> '' or normalized_attestation <> '' then
      raise exception 'Submit one evidence source at a time.';
    end if;
  elsif normalized_type = 'link' then
    if normalized_url !~* '^https?://' then
      raise exception 'Evidence link must use http or https.';
    end if;
    if normalized_storage_path <> '' or normalized_attestation <> '' then
      raise exception 'Submit one evidence source at a time.';
    end if;
  else
    if normalized_attestation = '' then
      raise exception 'Write an attestation before submitting.';
    end if;
    if normalized_storage_path <> '' or normalized_url <> '' then
      raise exception 'Submit one evidence source at a time.';
    end if;
  end if;

  if p_replaces_evidence_id is not null then
    select * into prior_row
    from public.trade_evidence_items
    where id = p_replaces_evidence_id
    for update;
    if prior_row.id is null
       or prior_row.agreement_id <> p_agreement_id
       or prior_row.submitted_by <> p_actor_id
       or prior_row.status not in ('submitted', 'challenged') then
      raise exception 'Replacement evidence must reference an open item from the same submitter and agreement.';
    end if;
  end if;

  insert into public.trade_evidence_items(
    agreement_id,
    submitted_by,
    submission_key,
    evidence_type,
    storage_path,
    evidence_url,
    attestation,
    status,
    public_visibility,
    public_title,
    public_summary,
    public_url,
    public_storage_path,
    public_original_filename,
    public_mime_type,
    public_redaction_note,
    redaction_status,
    public_published_at,
    replaces_evidence_id,
    created_at
  ) values (
    p_agreement_id,
    p_actor_id,
    normalized_key,
    normalized_type,
    normalized_storage_path,
    normalized_url,
    normalized_attestation,
    'submitted',
    'private',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    'withheld',
    null,
    p_replaces_evidence_id,
    now()
  ) returning * into evidence_row;

  if prior_row.id is not null then
    update public.trade_evidence_items
    set status = 'replaced',
        replaced_at = now(),
        reviewed_at = now(),
        public_visibility = 'private',
        public_title = '',
        public_summary = '',
        public_url = '',
        public_storage_path = '',
        public_original_filename = '',
        public_mime_type = '',
        public_redaction_note = '',
        redaction_status = 'withheld',
        public_published_at = null
    where id = prior_row.id;
  end if;

  select count(*) into remaining_challenges
  from public.trade_evidence_items
  where agreement_id = p_agreement_id and status = 'challenged';

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set lifecycle_status = case when remaining_challenges > 0 then 'disputed' else 'evidence_due' end,
      status = 'active',
      public_evidence_enabled = exists (
        select 1
        from public.trade_evidence_items public_item
        where public_item.agreement_id = p_agreement_id
          and public_item.public_visibility = 'public'
          and public_item.public_published_at is not null
          and public_item.redaction_status in ('redacted', 'not_required')
          and public_item.status not in ('withdrawn', 'replaced')
      ),
      updated_at = now(),
      public_evidence_updated_at = now()
  where id = p_agreement_id;

  begin
    insert into public.core_loop_events(
      profile_id, event_type, entity_type, entity_id, idempotency_key, metadata, created_at
    ) values (
      p_actor_id,
      'evidence_submitted',
      'evidence',
      evidence_row.id,
      'evidence_submitted:' || p_actor_id::text || ':evidence:' || evidence_row.id::text,
      jsonb_build_object(
        'agreementId', p_agreement_id,
        'replacesEvidenceId', p_replaces_evidence_id,
        'visibility', 'private'
      ),
      now()
    )
    on conflict (idempotency_key) do nothing;
  exception when others then
    null;
  end;

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'evidence_submitted',
      'Private evidence submitted',
      case when prior_row.id is null
        then 'A participant submitted private evidence for your review.'
        else 'A participant replaced an evidence item. Review the new private evidence.'
      end,
      '/trade-agreements/' || p_agreement_id::text,
      'evidence_submitted:' || evidence_row.id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'evidenceId', evidence_row.id,
    'status', evidence_row.status,
    'replacedEvidenceId', prior_row.id,
    'visibility', 'private',
    'created', true
  );
end;
$$;



CREATE FUNCTION public.release_mpgf_pledge_impact_forecast(p_pool_public_key text, p_forecast_version text, p_model_version text, p_released_at timestamp with time zone, p_expires_at timestamp with time zone, p_forecast_json jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  live_pool_state jsonb;
  live_pool_state_sha256 text;
  pool_proposal_id_value uuid;
  content_value jsonb;
  content_sha256_value text;
  snapshot_id_value uuid;
  existing_snapshot record;
  event_payload_value jsonb;
begin
  if btrim(coalesce(p_forecast_version, '')) = ''
     or btrim(coalesce(p_model_version, '')) = '' then
    raise exception 'Forecast and model versions are required.'
      using errcode = '22023';
  end if;
  if p_released_at < timezone('utc', now()) - interval '15 minutes'
     or p_released_at > timezone('utc', now()) + interval '5 minutes'
     or p_expires_at <= p_released_at
     or p_expires_at > p_released_at + interval '2 hours' then
    raise exception 'Forecast release timestamps are stale, future-dated, or too long-lived.'
      using errcode = '22023';
  end if;

  live_pool_state := public.mpgf_pledge_impact_live_pool_state(
    p_pool_public_key,
    p_released_at
  );
  if live_pool_state is null then
    raise exception 'Pool is not an approved, active, publicly exact live MPGF proposal.'
      using errcode = '23514';
  end if;
  if not public.mpgf_pledge_impact_forecast_shape_valid(
    p_forecast_json,
    live_pool_state
  ) then
    raise exception 'Pledge-impact forecast payload failed validation.'
      using errcode = '22023';
  end if;

  pool_proposal_id_value := (live_pool_state ->> 'poolProposalId')::uuid;
  live_pool_state_sha256 := public.mpgf_pledge_impact_sha256(live_pool_state);
  content_value := jsonb_build_object(
    'poolPublicKey', p_pool_public_key,
    'poolProposalId', pool_proposal_id_value,
    'forecastVersion', p_forecast_version,
    'modelVersion', p_model_version,
    'releasedAt', p_released_at,
    'expiresAt', p_expires_at,
    'poolState', live_pool_state,
    'forecast', p_forecast_json
  );
  content_sha256_value := public.mpgf_pledge_impact_sha256(content_value);

  select id, content_sha256
  into existing_snapshot
  from public.mpgf_pledge_impact_forecast_snapshots
  where pool_public_key = p_pool_public_key
    and forecast_version = p_forecast_version;

  if found then
    if existing_snapshot.content_sha256 <> content_sha256_value then
      raise unique_violation using message =
        'Forecast version already exists with different content.';
    end if;
    return existing_snapshot.id;
  end if;

  insert into public.mpgf_pledge_impact_forecast_snapshots (
    pool_public_key,
    pool_proposal_id,
    forecast_version,
    model_version,
    released_at,
    expires_at,
    pool_state_json,
    pool_state_sha256,
    forecast_json,
    content_sha256
  ) values (
    p_pool_public_key,
    pool_proposal_id_value,
    p_forecast_version,
    p_model_version,
    p_released_at,
    p_expires_at,
    live_pool_state,
    live_pool_state_sha256,
    p_forecast_json,
    content_sha256_value
  ) returning id into snapshot_id_value;

  event_payload_value := jsonb_build_object(
    'snapshotId', snapshot_id_value,
    'poolPublicKey', p_pool_public_key,
    'poolProposalId', pool_proposal_id_value,
    'forecastVersion', p_forecast_version,
    'modelVersion', p_model_version,
    'releasedAt', p_released_at,
    'expiresAt', p_expires_at,
    'poolStateSha256', live_pool_state_sha256,
    'contentSha256', content_sha256_value
  );

  insert into public.mpgf_pledge_impact_forecast_audit_events (
    snapshot_id,
    event_type,
    event_payload,
    event_sha256
  ) values (
    snapshot_id_value,
    'forecast_released',
    event_payload_value,
    public.mpgf_pledge_impact_sha256(event_payload_value)
  );

  return snapshot_id_value;
end;
$$;



CREATE FUNCTION public.replace_agreement_reminder_configuration(p_agreement_id uuid, p_user_id uuid, p_preferences jsonb, p_rules jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1
    from public.agreements
    where id = p_agreement_id
      and (proposer_id = p_user_id or responder_id = p_user_id)
  ) then
    raise exception 'Agreement not found or reminder access denied.';
  end if;

  insert into public.agreement_reminder_preferences (
    agreement_id,
    user_id,
    timezone,
    quiet_hours_enabled,
    quiet_hours_start,
    quiet_hours_end,
    in_app_enabled,
    email_enabled,
    paused,
    updated_at
  )
  values (
    p_agreement_id,
    p_user_id,
    coalesce(nullif(p_preferences ->> 'timezone', ''), 'UTC'),
    coalesce((p_preferences ->> 'quietHoursEnabled')::boolean, true),
    coalesce(nullif(p_preferences ->> 'quietHoursStart', '')::time, time '22:00'),
    coalesce(nullif(p_preferences ->> 'quietHoursEnd', '')::time, time '07:00'),
    coalesce((p_preferences ->> 'inAppEnabled')::boolean, true),
    coalesce((p_preferences ->> 'emailEnabled')::boolean, false),
    coalesce((p_preferences ->> 'paused')::boolean, false),
    now()
  )
  on conflict (agreement_id, user_id)
  do update set
    timezone = excluded.timezone,
    quiet_hours_enabled = excluded.quiet_hours_enabled,
    quiet_hours_start = excluded.quiet_hours_start,
    quiet_hours_end = excluded.quiet_hours_end,
    in_app_enabled = excluded.in_app_enabled,
    email_enabled = excluded.email_enabled,
    paused = excluded.paused,
    updated_at = now();

  insert into public.agreement_reminder_rules (
    agreement_id,
    user_id,
    source,
    milestone_key,
    milestone_label,
    due_at,
    offset_minutes,
    remind_at,
    enabled,
    in_app_enabled,
    email_enabled,
    calendar_enabled,
    created_at,
    updated_at
  )
  select
    p_agreement_id,
    p_user_id,
    coalesce(nullif(rule.source, ''), 'agreement'),
    rule.milestone_key,
    rule.milestone_label,
    rule.due_at,
    rule.offset_minutes,
    rule.due_at + (rule.offset_minutes * interval '1 minute'),
    coalesce(rule.enabled, true),
    coalesce(rule.in_app_enabled, true),
    coalesce(rule.email_enabled, false),
    coalesce(rule.calendar_enabled, true),
    now(),
    now()
  from jsonb_to_recordset(coalesce(p_rules, '[]'::jsonb)) as rule(
    source text,
    milestone_key text,
    milestone_label text,
    due_at timestamp with time zone,
    offset_minutes integer,
    enabled boolean,
    in_app_enabled boolean,
    email_enabled boolean,
    calendar_enabled boolean
  )
  on conflict (agreement_id, user_id, milestone_key, offset_minutes)
  do update set
    source = excluded.source,
    milestone_label = excluded.milestone_label,
    due_at = excluded.due_at,
    enabled = excluded.enabled,
    in_app_enabled = excluded.in_app_enabled,
    email_enabled = excluded.email_enabled,
    calendar_enabled = excluded.calendar_enabled,
    updated_at = now();

  delete from public.agreement_reminder_rules existing
  where existing.agreement_id = p_agreement_id
    and existing.user_id = p_user_id
    and not exists (
      select 1
      from jsonb_to_recordset(coalesce(p_rules, '[]'::jsonb)) as incoming(
        source text,
        milestone_key text,
        milestone_label text,
        due_at timestamp with time zone,
        offset_minutes integer,
        enabled boolean,
        in_app_enabled boolean,
        email_enabled boolean,
        calendar_enabled boolean
      )
      where incoming.milestone_key = existing.milestone_key
        and incoming.offset_minutes = existing.offset_minutes
    );
end;
$$;



CREATE FUNCTION public.report_trade_external_payment_v1(p_payout_id uuid, p_provider text, p_provider_reference text, p_amount_cents bigint, p_currency text, p_paid_on date, p_receipt_storage_path text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  payout_row public.trade_milestone_payouts%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  prior_receipt public.trade_external_payment_receipts%rowtype;
  existing_receipt public.trade_external_payment_receipts%rowtype;
  normalized_provider text := btrim(coalesce(p_provider, ''));
  normalized_reference text := btrim(coalesce(p_provider_reference, ''));
  normalized_currency text := upper(btrim(coalesce(p_currency, '')));
  normalized_path text := btrim(coalesce(p_receipt_storage_path, ''));
  fingerprint text;
  payment_cycle_value integer;
  attempt_value smallint;
  receipt_kind_value text;
  receipt_id_value uuid;
begin
  fingerprint := encode(
    extensions.digest(
      convert_to(
        lower(normalized_provider) || chr(31) || normalized_reference,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = p_payout_id
  for update;

  select *
  into existing_receipt
  from public.trade_external_payment_receipts receipt
  where receipt.payout_id = p_payout_id
    and receipt.reference_fingerprint = fingerprint
  order by receipt.payment_cycle desc, receipt.attempt_number desc
  limit 1
  for update;

  if found then
    if existing_receipt.reported_by = actor_id
       and existing_receipt.provider = normalized_provider
       and existing_receipt.amount_cents = p_amount_cents
       and existing_receipt.currency = normalized_currency
       and existing_receipt.paid_on = p_paid_on
       and existing_receipt.receipt_storage_path = normalized_path
       and payout_row.status not in ('due', 'still_due', 'correction_due') then
      return existing_receipt.id;
    end if;
    raise exception 'That external transaction reference has already been used.';
  end if;

  if payout_row.status in ('due', 'still_due') then
    select coalesce(max(receipt.payment_cycle), 0) + 1
    into payment_cycle_value
    from public.trade_external_payment_receipts receipt
    where receipt.payout_id = p_payout_id;
    attempt_value := 1;
    receipt_kind_value := 'initial';
  elsif payout_row.status = 'correction_due' then
    select *
    into review_case
    from public.trade_payment_review_cases candidate
    where candidate.payout_id = payout_row.id
      and candidate.status = 'correction_due'
    order by candidate.payment_cycle desc
    limit 1
    for update;
    select *
    into prior_receipt
    from public.trade_external_payment_receipts receipt
    where receipt.id = review_case.initial_receipt_id
    for update;
    payment_cycle_value := review_case.payment_cycle;
    attempt_value := 2;
    receipt_kind_value := 'correction';
  else
    attempt_value := null;
  end if;

  if attempt_value is not null then
    select *
    into existing_receipt
    from public.trade_external_payment_receipts receipt
    where receipt.payout_id = p_payout_id
      and receipt.payment_cycle = payment_cycle_value
      and receipt.attempt_number = attempt_value
    for update;

    if found then
      if existing_receipt.reported_by = actor_id
         and existing_receipt.provider = normalized_provider
         and existing_receipt.reference_fingerprint = fingerprint
         and existing_receipt.amount_cents = p_amount_cents
         and existing_receipt.currency = normalized_currency
         and existing_receipt.paid_on = p_paid_on
         and existing_receipt.receipt_storage_path = normalized_path then
        return existing_receipt.id;
      end if;
      raise exception 'A different external payment report already exists for this attempt.';
    end if;
  end if;

  if actor_id is null
     or payout_row.id is null
     or attempt_value is null
     or payout_row.payer_id <> actor_id
     or not payout_row.is_final
     or p_amount_cents <> payout_row.amount_due_cents
     or normalized_currency <> payout_row.currency
     or p_paid_on is null
     or p_paid_on < payout_row.finalized_at::date
     or p_paid_on > current_date
     or length(normalized_provider) not between 1 and 120
     or length(normalized_reference) not between 1 and 500
     or length(normalized_path) > 1000
     or (
       normalized_path <> ''
       and normalized_path not like actor_id::text || '/%'
     ) then
    raise exception 'External payment must exactly match the final private amount due.';
  end if;

  if attempt_value = 2 then
    if review_case.id is null
       or review_case.status <> 'correction_due'
       or review_case.correction_permitted_at is null
       or review_case.corrected_receipt_id is not null
       or prior_receipt.id is null then
      raise exception 'The single corrected receipt is unavailable.';
    end if;
  end if;

  insert into public.trade_external_payment_receipts (
    payout_id,
    reported_by,
    provider,
    provider_reference,
    reference_fingerprint,
    amount_cents,
    currency,
    paid_on,
    receipt_storage_path,
    payment_cycle,
    attempt_number,
    receipt_kind,
    supersedes_receipt_id,
    response_deadline_at
  ) values (
    payout_row.id,
    actor_id,
    normalized_provider,
    normalized_reference,
    fingerprint,
    p_amount_cents,
    normalized_currency,
    p_paid_on,
    normalized_path,
    payment_cycle_value,
    attempt_value,
    receipt_kind_value,
    case when attempt_value = 2 then prior_receipt.id else null end,
    now() + interval '7 days'
  )
  returning id into receipt_id_value;

  if attempt_value = 2 then
    update public.trade_external_payment_receipts
    set status = 'superseded',
        updated_at = now()
    where id = prior_receipt.id;

    update public.trade_payment_review_cases
    set corrected_receipt_id = receipt_id_value,
        status = 'corrected_response',
        updated_at = now()
    where id = review_case.id;
  end if;

  update public.trade_milestone_payouts
  set status = case
        when attempt_value = 1 then 'reported_paid'
        else 'corrected_reported'
      end,
      updated_at = now()
  where id = payout_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    payout_row.payee_id,
    case
      when attempt_value = 1 then 'external_payment_reported'
      else 'external_payment_corrected'
    end,
    case
      when attempt_value = 1 then 'External payment reported'
      else 'Corrected payment receipt reported'
    end,
    'Review the private receipt within seven days and confirm or dispute it.',
    '/trade-agreements/' || milestone.agreement_id::text,
    'external_payment_reported:' || receipt_id_value::text,
    now()
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  on conflict (dedupe_key) do nothing;

  return receipt_id_value;
end;
$$;



CREATE FUNCTION public.request_trade_exit_v3(p_actor_id uuid, p_agreement_id uuid, p_request_type text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  agreement_row public.agreements%rowtype;
  request_row public.trade_exit_requests%rowtype;
  counterpart_id uuid;
  normalized_reason text := btrim(coalesce(p_reason, ''));
begin
  if p_actor_id is null or p_agreement_id is null then
    raise exception 'A signed-in agreement participant is required.';
  end if;
  if p_request_type not in ('mutual_cancel', 'unilateral_exit') then
    raise exception 'Choose mutual cancellation or unilateral exit.';
  end if;
  if normalized_reason = '' or length(normalized_reason) > 4000 then
    raise exception 'A bounded exit reason is required.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = p_agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;

  select * into request_row
  from public.trade_exit_requests
  where agreement_id = agreement_row.id
    and requested_by = p_actor_id
    and request_type = p_request_type
    and status in ('pending', 'executed')
  order by created_at desc
  limit 1;
  if request_row.id is not null then
    return jsonb_build_object(
      'requestId', request_row.id,
      'requestStatus', request_row.status,
      'lifecycleStatus', agreement_row.lifecycle_status,
      'created', false
    );
  end if;
  if agreement_row.lifecycle_status in ('completed', 'cancelled', 'expired') then
    raise exception 'This agreement is already final.';
  end if;

  insert into public.trade_exit_requests(
    agreement_id, requested_by, request_type, reason, status, created_at, resolved_at
  ) values (
    agreement_row.id,
    p_actor_id,
    p_request_type,
    normalized_reason,
    case when p_request_type = 'unilateral_exit' then 'executed' else 'pending' end,
    now(),
    case when p_request_type = 'unilateral_exit' then now() else null end
  ) returning * into request_row;

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;

  if p_request_type = 'unilateral_exit' then
    perform set_config('app.core_trade_internal', '1', true);
    update public.agreements
    set lifecycle_status = 'cancelled',
        status = 'cancelled',
        cancelled_at = coalesce(cancelled_at, now()),
        exit_requested_by = p_actor_id,
        exit_reason = normalized_reason,
        updated_at = now()
    where id = agreement_row.id;
    update public.trade_threads
    set status = 'closed', updated_at = now()
    where agreement_id = agreement_row.id;
  end if;

  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      case when p_request_type = 'unilateral_exit'
        then 'unilateral_exit'
        else 'mutual_cancel_requested'
      end,
      case when p_request_type = 'unilateral_exit'
        then 'Agreement exited'
        else 'Mutual cancellation requested'
      end,
      case when p_request_type = 'unilateral_exit'
        then 'The other participant used the published unilateral exit rule. Future obligations ended; completed periods remain recorded.'
        else 'The other participant requested mutual cancellation. Accept or decline in the agreement record.'
      end,
      '/trade-agreements/' || agreement_row.id::text,
      case when p_request_type = 'unilateral_exit'
        then 'unilateral_exit:' || request_row.id::text || ':' || counterpart_id::text
        else 'mutual_cancel:' || request_row.id::text || ':' || counterpart_id::text
      end,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'requestId', request_row.id,
    'requestStatus', request_row.status,
    'lifecycleStatus', case
      when p_request_type = 'unilateral_exit' then 'cancelled'
      else agreement_row.lifecycle_status
    end,
    'created', true
  );
end;
$$;



CREATE FUNCTION public.require_reciprocal_evidence_for_donation_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists (
    select 1
    from public.agreements a
    join public.trade_donation_terms t
      on t.agreement_version_id = a.current_version_id
    where a.id = new.agreement_id
  ) and not exists (
    select 1
    from public.trade_evidence_items e
    where e.agreement_id = new.agreement_id
      and e.status = 'accepted'
      and e.evidence_type <> 'provider_donation'
  ) then
    raise exception 'A provider donation activates the trade but does not prove the reciprocal action.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.reserve_background_candidate_exposure(target_candidate_profile_id uuid, target_purpose_code text, target_purpose_policy_version text, target_audience_scope text, target_cohort_scope_id text, target_surface_limit integer, target_window_days integer, target_budget_version text) RETURNS TABLE(allowed boolean, budget_state text, counter_id uuid, remaining integer, blocker_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  current_time_utc timestamptz := timezone('utc', now());
  normalized_cohort text := coalesce(nullif(target_cohort_scope_id, ''), '');
  normalized_window_days integer := greatest(1, least(coalesce(target_window_days, 30), 365));
  normalized_surface_limit integer := greatest(0, least(coalesce(target_surface_limit, 0), 1000));
  window_start_utc timestamptz := date_trunc('day', timezone('utc', now()));
  window_end_utc timestamptz;
  reserved_counter_id uuid;
  reserved_surface_count integer;
  reserved_budget_state text;
begin
  if target_candidate_profile_id is null or normalized_surface_limit <= 0 then
    allowed := false;
    budget_state := 'exhausted';
    counter_id := null;
    remaining := 0;
    blocker_code := 'candidate_budget_missing';
    return next;
    return;
  end if;

  window_end_utc := window_start_utc + make_interval(days => normalized_window_days);

  insert into public.background_candidate_exposure_counters (
    candidate_profile_id,
    purpose_code,
    purpose_policy_version,
    audience_scope,
    cohort_scope_id,
    window_start,
    window_end,
    candidate_inbound_budget_version_snapshot,
    retention_expires_at
  )
  values (
    target_candidate_profile_id,
    target_purpose_code,
    target_purpose_policy_version,
    target_audience_scope,
    normalized_cohort,
    window_start_utc,
    window_end_utc,
    coalesce(nullif(target_budget_version, ''), 'candidate-budget-v1'),
    window_end_utc + interval '45 days'
  )
  on conflict (candidate_profile_id, purpose_code, purpose_policy_version, audience_scope, cohort_scope_id, window_start)
  where counter_reference_state = 'active'
  do nothing;

  update public.background_candidate_exposure_counters
  set
    surface_count = surface_count + 1,
    budget_state = case
      when surface_count + 1 >= normalized_surface_limit then 'exhausted'
      when (surface_count + 1) * 5 >= normalized_surface_limit * 4 then 'near_limit'
      else 'clear'
    end,
    last_surface_at = current_time_utc,
    updated_at = current_time_utc
  where candidate_profile_id = target_candidate_profile_id
    and purpose_code = target_purpose_code
    and purpose_policy_version = target_purpose_policy_version
    and audience_scope = target_audience_scope
    and cohort_scope_id = normalized_cohort
    and window_start = window_start_utc
    and counter_reference_state = 'active'
    and budget_state <> 'cooloff'
    and surface_count < normalized_surface_limit
  returning id, surface_count, budget_state
  into reserved_counter_id, reserved_surface_count, reserved_budget_state;

  if reserved_counter_id is not null then
    allowed := true;
    budget_state := reserved_budget_state;
    counter_id := reserved_counter_id;
    remaining := greatest(0, normalized_surface_limit - reserved_surface_count);
    blocker_code := '';
    return next;
    return;
  end if;

  update public.background_candidate_exposure_counters
  set
    suppressed_for_budget_count = suppressed_for_budget_count + 1,
    budget_state = case when budget_state = 'cooloff' then 'cooloff' else 'exhausted' end,
    updated_at = current_time_utc
  where candidate_profile_id = target_candidate_profile_id
    and purpose_code = target_purpose_code
    and purpose_policy_version = target_purpose_policy_version
    and audience_scope = target_audience_scope
    and cohort_scope_id = normalized_cohort
    and window_start = window_start_utc
    and counter_reference_state = 'active'
  returning id, budget_state
  into reserved_counter_id, reserved_budget_state;

  allowed := false;
  budget_state := coalesce(reserved_budget_state, 'exhausted');
  counter_id := reserved_counter_id;
  remaining := 0;
  blocker_code := case when reserved_budget_state = 'cooloff' then 'candidate_cooloff' else 'candidate_budget_exhausted' end;
  return next;
end;
$$;



CREATE FUNCTION public.reserve_catalog_financial_commitment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  agreement_row public.agreements%rowtype;
  catalog_row public.offer_catalog_entries%rowtype;
  confirmation_count integer;
  pool_total integer;
  pool_reserved integer;
  pool_spent integer;
  available_cents integer;
  reservation_cents integer;
  inserted_count integer;
begin
  select agreement.*
  into agreement_row
  from public.agreements agreement
  where agreement.current_version_id = new.agreement_version_id;

  if not found then
    return new;
  end if;

  select catalog.*
  into catalog_row
  from public.offer_catalog_entries catalog
  where catalog.offer_id = agreement_row.offer_id
    and catalog.shared_financial_pool_key is not null;

  if not found then
    return new;
  end if;

  select count(*)
  into confirmation_count
  from public.trade_agreement_confirmations confirmation
  where confirmation.agreement_version_id = new.agreement_version_id;

  if confirmation_count < 2 then
    return new;
  end if;

  if exists (
    select 1
    from public.financial_commitment_reservations reservation
    where reservation.agreement_id = agreement_row.id
  ) then
    return new;
  end if;

  select pool.total_cents, pool.reserved_cents, pool.spent_cents
  into pool_total, pool_reserved, pool_spent
  from public.financial_commitment_pools pool
  where pool.pool_key = catalog_row.shared_financial_pool_key
  for update;

  if not found then
    raise exception 'The shared financial commitment pool is unavailable.';
  end if;

  available_cents := pool_total - pool_reserved - pool_spent;

  if catalog_row.reserve_all_remaining then
    reservation_cents := least(available_cents, 50000);
  else
    reservation_cents := catalog_row.financial_maximum_cents;
  end if;

  if reservation_cents is null or reservation_cents <= 0 then
    raise exception 'The shared $500 commitment pool has no unreserved capacity.';
  end if;

  if reservation_cents > available_cents then
    raise exception
      'The shared $500 commitment pool has only $% available; this agreement requires up to $%.',
      to_char(available_cents / 100.0, 'FM999999990.00'),
      to_char(reservation_cents / 100.0, 'FM999999990.00');
  end if;

  insert into public.financial_commitment_reservations (
    agreement_id,
    offer_id,
    pool_key,
    reserved_cents,
    status
  )
  values (
    agreement_row.id,
    agreement_row.offer_id,
    catalog_row.shared_financial_pool_key,
    reservation_cents,
    'reserved'
  )
  on conflict (agreement_id) do nothing;

  get diagnostics inserted_count = row_count;

  if inserted_count = 1 then
    update public.financial_commitment_pools
    set reserved_cents = reserved_cents + reservation_cents,
        updated_at = now()
    where pool_key = catalog_row.shared_financial_pool_key;
  end if;

  return new;
end;
$_$;



CREATE FUNCTION public.resolve_create_participants_v2(p_actor_profile_id uuid, p_profile_ids uuid[]) RETURNS TABLE(profile_id uuid, username text, display_name text, avatar_url text, account_type text, verification text, public_invitation_mentions_enabled boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_actor_profile_id is null then
    raise exception 'actor_profile_required' using errcode = '22023';
  end if;
  if p_profile_ids is null or coalesce(array_length(p_profile_ids, 1), 0) = 0 then
    return;
  end if;
  if array_length(p_profile_ids, 1) > 100 then
    raise exception 'too_many_profiles' using errcode = '22023';
  end if;
  return query
  with requested as (
    select request.profile_id, min(request.ordinality) as ordinality
    from unnest(p_profile_ids) with ordinality as request(profile_id, ordinality)
    where request.profile_id is not null
    group by request.profile_id
  )
  select
    profile.id,
    profile.username,
    public.safe_participant_display_name_v1(profile.display_name, profile.username),
    profile.avatar_url,
    profile.account_kind,
    case
      when exists (
        select 1 from public.profile_verification_badges badge
        where badge.profile_id = profile.id
          and badge.badge_type = case
            when profile.account_kind = 'organization' then 'organization_verified'
            else 'identity_verified'
          end
          and badge.status = 'verified'
          and (badge.expires_at is null or badge.expires_at > timezone('utc', now()))
      ) then case
        when profile.account_kind = 'organization' then 'organization-verified'
        else 'identity-verified'
      end
      else 'none'
    end,
    profile.public_invitation_mentions_enabled
  from requested
  join public.profiles profile on profile.id = requested.profile_id
  left join public.wish_profiles wish on wish.profile_id = profile.id
  where profile.username is not null
    and (profile.id = p_actor_profile_id or profile.accepts_group_invitations)
    and (profile.id = p_actor_profile_id or coalesce(wish.safety_status, 'clear') <> 'blocked')
    and (
      profile.id = p_actor_profile_id
      or not exists (
        select 1
        from public.trade_blocks block
        where (block.blocker_id = p_actor_profile_id and block.blocked_id = profile.id)
           or (block.blocker_id = profile.id and block.blocked_id = p_actor_profile_id)
      )
    )
  order by requested.ordinality;
end;
$$;



CREATE FUNCTION public.resolve_trade_milestone_appeal_v1(p_appeal_id uuid, p_completion_units numeric, p_confidence_band smallint, p_outcome text, p_private_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  appeal_row public.trade_milestone_appeals%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  base_review_row public.trade_milestone_reviews%rowtype;
  bundle_row public.trade_evidence_bundles%rowtype;
  completion_value numeric(20, 6);
  band_value smallint;
  final_outcome text;
  basis_points_value integer;
  amount_due_value bigint;
  appeal_review_id uuid;
  resume_seconds integer;
begin
  if not moral_trade_private.current_actor_has_trade_role('reviewer') then
    raise exception 'Appeal review requires an active profile role and AAL2.';
  end if;

  select *
  into appeal_row
  from public.trade_milestone_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = appeal_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select *
  into base_review_row
  from public.trade_milestone_reviews review
  where review.id = appeal_row.base_review_id
  for update;
  select *
  into bundle_row
  from public.trade_evidence_bundles bundle
  where bundle.id = base_review_row.bundle_id
  for update;

  if not found
     or appeal_row.status <> 'assigned'
     or appeal_row.assigned_reviewer_id <> actor_id
     or base_review_row.reviewer_id = actor_id
     or actor_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or p_outcome not in ('upheld', 'regraded', 'graded', 'rejected')
     or length(btrim(coalesce(p_private_reason, ''))) not between 1 and 4000 then
    raise exception 'This appeal cannot be resolved by the current reviewer.';
  end if;

  if p_outcome = 'upheld' then
    completion_value := base_review_row.completion_units;
    band_value := base_review_row.confidence_band;
    final_outcome := base_review_row.outcome;
  elsif p_outcome = 'rejected' then
    completion_value := 0;
    band_value := 0;
    final_outcome := 'rejected';
  else
    completion_value := p_completion_units;
    band_value := p_confidence_band;
    final_outcome := 'graded';
    if band_value not in (0, 25, 50, 75, 100)
       or completion_value is null
       or completion_value < 0
       or completion_value > milestone_row.units_total
       or (
         milestone_row.indivisible
         and completion_value not in (0, milestone_row.units_total)
       ) then
      raise exception 'Appeal grading must follow the frozen units and confidence bands.';
    end if;
  end if;

  select calculation.payout_basis_points, calculation.amount_due_cents
  into basis_points_value, amount_due_value
  from public.trade_milestone_payout_v1(
    milestone_row.maximum_amount_cents,
    completion_value,
    milestone_row.units_total,
    band_value
  ) calculation;

  insert into public.trade_milestone_reviews (
    milestone_id,
    bundle_id,
    reviewer_id,
    review_kind,
    base_review_id,
    outcome,
    completion_units,
    confidence_band,
    payout_basis_points,
    amount_due_cents,
    private_reason,
    appeal_deadline_at,
    is_final,
    finalized_at
  ) values (
    milestone_row.id,
    bundle_row.id,
    actor_id,
    'appeal',
    base_review_row.id,
    final_outcome,
    completion_value,
    band_value,
    basis_points_value,
    amount_due_value,
    btrim(p_private_reason),
    now(),
    true,
    now()
  )
  returning id into appeal_review_id;

  update public.trade_milestone_appeals
  set status = 'resolved',
      resolved_at = now()
  where id = appeal_row.id;

  update public.trade_evidence_bundles
  set status = case when final_outcome = 'rejected' then 'invalid' else 'accepted' end,
      reviewed_at = now()
  where id = bundle_row.id;

  update public.trade_milestone_payouts
  set review_id = appeal_review_id,
      completion_units = completion_value,
      confidence_band = band_value,
      payout_basis_points = basis_points_value,
      amount_due_cents = amount_due_value,
      is_final = true,
      status = case when amount_due_value = 0 then 'not_due' else 'due' end,
      finalized_at = now(),
      updated_at = now()
  where milestone_id = milestone_row.id;

  if final_outcome = 'rejected' then
    resume_seconds := case
      when exists (
        select 1
        from public.trade_evidence_bundles replacement
        where replacement.milestone_id = milestone_row.id
          and replacement.bundle_kind = 'replacement'
          and replacement.status <> 'draft'
      ) then 0
      else coalesce(appeal_row.replacement_seconds_remaining, 0)
    end;

    update public.trade_agreement_milestones
    set final_review_id = appeal_review_id,
        status = case when resume_seconds > 0 then 'replacement_due' else 'evidence_due' end,
        replacement_deadline_at = case
          when resume_seconds > 0 then now() + make_interval(secs => resume_seconds)
          else null
        end,
        replacement_seconds_remaining = case
          when resume_seconds > 0 then resume_seconds
          else null
        end,
        updated_at = now()
    where id = milestone_row.id;

    update public.agreements
    set lifecycle_status = 'evidence_due',
        future_obligations_paused_at = coalesce(future_obligations_paused_at, now()),
        future_obligations_pause_reason = 'Evidence rejection was upheld; unused replacement time resumed.',
        updated_at = now()
    where id = agreement_row.id;
  else
    update public.trade_agreement_milestones
    set final_review_id = appeal_review_id,
        status = 'graded',
        replacement_deadline_at = null,
        replacement_seconds_remaining = null,
        updated_at = now()
    where id = milestone_row.id;

    if not exists (
      select 1
      from public.trade_agreement_milestones other
      where other.agreement_id = agreement_row.id
        and other.id <> milestone_row.id
        and other.status in ('replacement_due', 'appeal_pending', 'evidence_due')
    ) then
      update public.agreements
      set lifecycle_status = case
            when lifecycle_status = 'evidence_due' then 'active'
            else lifecycle_status
          end,
          future_obligations_paused_at = null,
          future_obligations_pause_reason = '',
          updated_at = now()
      where id = agreement_row.id;
    end if;
  end if;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    participant_id,
    'milestone_appeal_resolved',
    'Milestone appeal resolved',
    'A different neutral reviewer recorded the final milestone decision.',
    '/trade-agreements/' || agreement_row.id::text,
    'milestone_appeal_resolved:' || appeal_row.id::text || ':' || participant_id::text,
    now()
  from unnest(
    array[agreement_row.proposer_id, agreement_row.responder_id]
  ) as participants(participant_id)
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'appealId', appeal_row.id,
    'reviewId', appeal_review_id,
    'milestoneId', milestone_row.id,
    'outcome', final_outcome,
    'completionUnits', completion_value,
    'confidenceBand', band_value,
    'payoutBasisPoints', basis_points_value,
    'amountDueCents', amount_due_value,
    'currency', milestone_row.currency,
    'isFinal', true
  );
end;
$$;



CREATE FUNCTION public.resolve_trade_payment_appeal_v1(p_appeal_id uuid, p_outcome text, p_private_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  appeal_row public.trade_payment_appeals%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  base_decision public.trade_payment_review_decisions%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  receipt_row public.trade_external_payment_receipts%rowtype;
  existing_decision public.trade_payment_review_decisions%rowtype;
  normalized_reason text := btrim(coalesce(p_private_reason, ''));
  appeal_decision_id uuid;
  payout_status_value text;
begin
  if not moral_trade_private.current_actor_has_trade_role('reviewer') then
    raise exception 'Payment appeal requires an active profile role and AAL2.';
  end if;

  select *
  into appeal_row
  from public.trade_payment_appeals appeal
  where appeal.id = p_appeal_id
  for update;
  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = appeal_row.case_id
  for update;
  select *
  into base_decision
  from public.trade_payment_review_decisions decision
  where decision.id = appeal_row.base_decision_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;
  select *
  into receipt_row
  from public.trade_external_payment_receipts receipt
  where receipt.id = base_decision.receipt_id
  for update;
  select *
  into existing_decision
  from public.trade_payment_review_decisions decision
  where decision.case_id = review_case.id
    and decision.decision_kind = 'appeal'
  for update;

  if existing_decision.id is not null then
    if existing_decision.reviewer_id = actor_id
       and existing_decision.outcome = p_outcome
       and existing_decision.private_reason = normalized_reason then
      return jsonb_build_object(
        'paymentAppealId', appeal_row.id,
        'decisionId', existing_decision.id,
        'outcome', existing_decision.outcome,
        'status', case
          when existing_decision.outcome = 'confirm_paid'
            then 'adjudicated_paid'
          else 'still_due'
        end,
        'isFinal', true
      );
    end if;
    raise exception 'A different final payment-appeal decision already exists.';
  end if;

  if appeal_row.status <> 'assigned'
     or review_case.status <> 'appeal_pending'
     or appeal_row.assigned_reviewer_id <> actor_id
     or base_decision.reviewer_id = actor_id
     or actor_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or p_outcome not in ('confirm_paid', 'still_due')
     or length(normalized_reason) not between 1 and 4000 then
    raise exception 'This payment appeal cannot be resolved by the current reviewer.';
  end if;

  insert into public.trade_payment_review_decisions (
    case_id,
    receipt_id,
    reviewer_id,
    decision_kind,
    base_decision_id,
    outcome,
    private_reason,
    appeal_deadline_at,
    is_final,
    finalized_at
  ) values (
    review_case.id,
    receipt_row.id,
    actor_id,
    'appeal',
    base_decision.id,
    p_outcome,
    normalized_reason,
    null,
    true,
    now()
  )
  returning id into appeal_decision_id;

  payout_status_value := case
    when p_outcome = 'confirm_paid' then 'adjudicated_paid'
    else 'still_due'
  end;

  update public.trade_payment_appeals
  set status = 'resolved',
      resolved_at = now()
  where id = appeal_row.id;
  update public.trade_payment_review_cases
  set status = 'resolved',
      final_decision_id = appeal_decision_id,
      updated_at = now()
  where id = review_case.id;
  update public.trade_external_payment_receipts
  set status = case
        when p_outcome = 'confirm_paid'
          then 'adjudicated_paid'
        else 'adjudicated_still_due'
      end,
      updated_at = now()
  where id = receipt_row.id;
  update public.trade_milestone_payouts
  set status = payout_status_value,
      updated_at = now()
  where id = payout_row.id;
  update public.trade_agreement_milestones
  set status = case
        when p_outcome = 'confirm_paid' then 'paid'
        else 'graded'
      end,
      updated_at = now()
  where id = milestone_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    participant_id,
    'payment_appeal_resolved',
    'External payment appeal resolved',
    'A different neutral reviewer recorded the final external-payment decision.',
    '/trade-agreements/' || agreement_row.id::text,
    'payment_appeal_resolved:' || appeal_row.id::text || ':' || participant_id::text,
    now()
  from unnest(
    array[agreement_row.proposer_id, agreement_row.responder_id]
  ) as participants(participant_id)
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'paymentAppealId', appeal_row.id,
    'decisionId', appeal_decision_id,
    'outcome', p_outcome,
    'status', payout_status_value,
    'isFinal', true
  );
end;
$$;



CREATE FUNCTION public.resolve_trade_payment_review_v1(p_case_id uuid, p_outcome text, p_private_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  review_case public.trade_payment_review_cases%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  agreement_row public.agreements%rowtype;
  receipt_row public.trade_external_payment_receipts%rowtype;
  decision_kind_value text;
  decision_id_value uuid;
  normalized_reason text := btrim(coalesce(p_private_reason, ''));
begin
  if not moral_trade_private.current_actor_has_trade_role('reviewer') then
    raise exception 'Payment review requires an active profile role and AAL2.';
  end if;

  select *
  into review_case
  from public.trade_payment_review_cases candidate
  where candidate.id = p_case_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = review_case.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;
  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = milestone_row.agreement_id
  for update;

  if review_case.corrected_receipt_id is not null then
    select *
    into receipt_row
    from public.trade_external_payment_receipts receipt
    where receipt.id = review_case.corrected_receipt_id
    for update;
    decision_kind_value := 'final';

    if review_case.status = 'corrected_response'
       and receipt_row.status = 'reported'
       and receipt_row.response_outcome = 'none'
       and receipt_row.response_deadline_at <= now() then
      update public.trade_external_payment_receipts
      set status = 'under_review',
          response_outcome = 'unanswered',
          responded_at = coalesce(responded_at, response_deadline_at),
          updated_at = now()
      where id = receipt_row.id;
      update public.trade_payment_review_cases
      set status = 'final_review',
          updated_at = now()
      where id = review_case.id;
      review_case.status := 'final_review';
      receipt_row.response_outcome := 'unanswered';
      receipt_row.status := 'under_review';
    end if;
  else
    select *
    into receipt_row
    from public.trade_external_payment_receipts receipt
    where receipt.id = review_case.initial_receipt_id
    for update;
    decision_kind_value := 'initial';
  end if;

  if review_case.assigned_reviewer_id <> actor_id
     or actor_id in (agreement_row.proposer_id, agreement_row.responder_id)
     or length(normalized_reason) not between 1 and 4000
     or (
       review_case.corrected_receipt_id is null
       and review_case.status <> 'assigned'
     )
     or (
       review_case.corrected_receipt_id is not null
       and review_case.status <> 'final_review'
     )
     or (
       review_case.corrected_receipt_id is not null
       and p_outcome = 'allow_correction'
     )
     or p_outcome not in (
       'confirm_paid', 'still_due', 'allow_correction'
     ) then
    raise exception 'This payment review decision is unavailable.';
  end if;

  insert into public.trade_payment_review_decisions (
    case_id,
    receipt_id,
    reviewer_id,
    decision_kind,
    outcome,
    private_reason,
    appeal_deadline_at
  ) values (
    review_case.id,
    receipt_row.id,
    actor_id,
    decision_kind_value,
    p_outcome,
    normalized_reason,
    case
      when p_outcome = 'allow_correction' then null
      else now() + interval '7 days'
    end
  )
  returning id into decision_id_value;

  if p_outcome = 'allow_correction' then
    update public.trade_external_payment_receipts
    set status = 'correction_requested',
        updated_at = now()
    where id = receipt_row.id;
    update public.trade_payment_review_cases
    set status = 'correction_due',
        correction_permitted_at = now(),
        updated_at = now()
    where id = review_case.id;
    update public.trade_milestone_payouts
    set status = 'correction_due',
        updated_at = now()
    where id = payout_row.id;
  else
    update public.trade_payment_review_cases
    set status = 'decision_pending',
        final_decision_id = decision_id_value,
        updated_at = now()
    where id = review_case.id;
    update public.trade_milestone_payouts
    set status = 'payment_decision_pending',
        updated_at = now()
    where id = payout_row.id;
  end if;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    participant_id,
    'payment_review_decided',
    case
      when p_outcome = 'allow_correction'
        then 'One corrected payment receipt permitted'
      else 'External payment review decided'
    end,
    case
      when p_outcome = 'allow_correction'
        then 'The payer may submit one corrected receipt. This permission is not an appealable final decision.'
      else 'The decision has a seven-day appeal window before it becomes final.'
    end,
    '/trade-agreements/' || agreement_row.id::text,
    'payment_review_decided:' || decision_id_value::text || ':' || participant_id::text,
    now()
  from unnest(
    array[agreement_row.proposer_id, agreement_row.responder_id]
  ) as participants(participant_id)
  on conflict (dedupe_key) do nothing;

  return jsonb_build_object(
    'paymentReviewCaseId', review_case.id,
    'decisionId', decision_id_value,
    'outcome', p_outcome,
    'status', case
      when p_outcome = 'allow_correction' then 'correction_due'
      else 'decision_pending'
    end
  );
end;
$$;



CREATE FUNCTION public.respond_trade_exit_v3(p_actor_id uuid, p_request_id uuid, p_decision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  request_row public.trade_exit_requests%rowtype;
  agreement_row public.agreements%rowtype;
  accepted boolean;
begin
  if p_actor_id is null or p_request_id is null then
    raise exception 'A signed-in counterparty and cancellation request are required.';
  end if;
  if p_decision not in ('accept', 'decline') then
    raise exception 'Choose accept or decline.';
  end if;

  select * into request_row
  from public.trade_exit_requests
  where id = p_request_id
  for update;
  if not found or request_row.request_type <> 'mutual_cancel' then
    raise exception 'Cancellation request is unavailable.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = request_row.agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found or p_actor_id = request_row.requested_by then
    raise exception 'Only the other participant may decide this request.';
  end if;

  accepted := p_decision = 'accept';
  if request_row.status <> 'pending' then
    if (accepted and request_row.status = 'accepted')
       or (not accepted and request_row.status = 'declined') then
      return jsonb_build_object(
        'requestId', request_row.id,
        'requestStatus', request_row.status,
        'lifecycleStatus', agreement_row.lifecycle_status,
        'idempotent', true
      );
    end if;
    raise exception 'This cancellation request was already decided.';
  end if;
  if agreement_row.lifecycle_status in ('completed', 'cancelled', 'expired') then
    raise exception 'The agreement is already final.';
  end if;

  update public.trade_exit_requests
  set status = case when accepted then 'accepted' else 'declined' end,
      resolved_at = now()
  where id = request_row.id;

  if accepted then
    perform set_config('app.core_trade_internal', '1', true);
    update public.agreements
    set lifecycle_status = 'cancelled',
        status = 'cancelled',
        cancelled_at = coalesce(cancelled_at, now()),
        exit_requested_by = request_row.requested_by,
        exit_reason = request_row.reason,
        updated_at = now()
    where id = agreement_row.id;
    update public.trade_threads
    set status = 'closed', updated_at = now()
    where agreement_id = agreement_row.id;
  end if;

  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      request_row.requested_by,
      case when accepted then 'mutual_cancel_accepted' else 'mutual_cancel_declined' end,
      case when accepted then 'Mutual cancellation accepted' else 'Mutual cancellation declined' end,
      case when accepted
        then 'Both participants agreed to cancel future obligations. Completed periods remain recorded.'
        else 'The mutual cancellation request was declined. The published unilateral exit rule remains available.'
      end,
      '/trade-agreements/' || agreement_row.id::text,
      'mutual_cancel_decision:' || request_row.id::text || ':' || p_decision,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'requestId', request_row.id,
    'requestStatus', case when accepted then 'accepted' else 'declined' end,
    'lifecycleStatus', case when accepted then 'cancelled' else agreement_row.lifecycle_status end,
    'idempotent', false
  );
end;
$$;



CREATE FUNCTION public.respond_trade_external_payment_v1(p_receipt_id uuid, p_response text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  receipt_row public.trade_external_payment_receipts%rowtype;
  payout_row public.trade_milestone_payouts%rowtype;
  review_case public.trade_payment_review_cases%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
  case_id_value uuid;
  normalized_note text := btrim(coalesce(p_note, ''));
begin
  select *
  into receipt_row
  from public.trade_external_payment_receipts receipt
  where receipt.id = p_receipt_id
  for update;
  select *
  into payout_row
  from public.trade_milestone_payouts payout
  where payout.id = receipt_row.payout_id
  for update;
  select *
  into milestone_row
  from public.trade_agreement_milestones milestone
  where milestone.id = payout_row.milestone_id
  for update;

  if actor_id is null
     or receipt_row.id is null
     or payout_row.payee_id <> actor_id
     or receipt_row.status <> 'reported'
     or receipt_row.response_outcome <> 'none'
     or receipt_row.response_deadline_at <= now()
     or (
       receipt_row.attempt_number = 1
       and payout_row.status <> 'reported_paid'
     )
     or (
       receipt_row.attempt_number = 2
       and payout_row.status <> 'corrected_reported'
     )
     or p_response not in ('confirm', 'dispute')
     or length(normalized_note) > 2000
     or (p_response = 'dispute' and normalized_note = '') then
    raise exception 'This external payment response is unavailable.';
  end if;

  if p_response = 'confirm' then
    update public.trade_external_payment_receipts
    set status = 'confirmed',
        response_outcome = 'confirmed',
        counterparty_note = normalized_note,
        responded_at = now(),
        updated_at = now()
    where id = receipt_row.id;

    update public.trade_milestone_payouts
    set status = 'confirmed',
        updated_at = now()
    where id = payout_row.id;

    update public.trade_agreement_milestones
    set status = 'paid',
        updated_at = now()
    where id = payout_row.milestone_id;

    update public.trade_payment_review_cases
    set status = 'resolved',
        updated_at = now()
    where payout_id = payout_row.id
      and status in ('correction_due', 'corrected_response', 'final_review');

    return jsonb_build_object(
      'receiptId', receipt_row.id,
      'payoutId', payout_row.id,
      'milestoneId', milestone_row.id,
      'status', 'confirmed'
    );
  end if;

  update public.trade_external_payment_receipts
  set status = 'under_review',
      response_outcome = 'disputed',
      counterparty_note = normalized_note,
      responded_at = now(),
      updated_at = now()
  where id = receipt_row.id;

  if receipt_row.attempt_number = 1 then
    case_id_value := moral_trade_private.ensure_trade_payment_review_case(
      payout_row.id
    );
  else
    select *
    into review_case
    from public.trade_payment_review_cases candidate
    where candidate.payout_id = payout_row.id
      and candidate.corrected_receipt_id = receipt_row.id
    for update;
    if review_case.id is null
       or review_case.corrected_receipt_id <> receipt_row.id
       or review_case.assigned_reviewer_id is null
       or review_case.status <> 'corrected_response' then
      raise exception 'The corrected receipt cannot enter final review.';
    end if;
    update public.trade_payment_review_cases
    set status = 'final_review',
        updated_at = now()
    where id = review_case.id;
    update public.trade_milestone_payouts
    set status = 'payment_review_pending',
        updated_at = now()
    where id = payout_row.id;
    case_id_value := review_case.id;
  end if;

  return jsonb_build_object(
    'receiptId', receipt_row.id,
    'payoutId', payout_row.id,
    'milestoneId', milestone_row.id,
    'paymentReviewCaseId', case_id_value,
    'status', 'payment_review_pending'
  );
end;
$$;



CREATE FUNCTION public.respond_trade_invitation_v2(p_actor_id uuid, p_token_hash text, p_decision text, p_message text, p_proposed_action text, p_requested_action text, p_duration text, p_start_date date, p_evidence_rule text, p_evidence_due_date date, p_exit_conditions text, p_maximum_burden text, p_privacy_scope text, p_no_trade_baseline text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.respond_trade_invitation_v2_unbound_legacy(
    p_actor_id, p_token_hash, p_decision, p_message, p_proposed_action,
    p_requested_action, p_duration, p_start_date, p_evidence_rule,
    p_evidence_due_date, p_exit_conditions, p_maximum_burden,
    p_privacy_scope, p_no_trade_baseline
  );
end;
$$;



CREATE FUNCTION public.respond_trade_invitation_v2_unbound_legacy(p_actor_id uuid, p_token_hash text, p_decision text, p_message text, p_proposed_action text, p_requested_action text, p_duration text, p_start_date date, p_evidence_rule text, p_evidence_due_date date, p_exit_conditions text, p_maximum_burden text, p_privacy_scope text, p_no_trade_baseline text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  invitation_row public.trade_invitations%rowtype;
  offer_row public.offers%rowtype;
  actor_email text;
  actor_email_confirmed timestamptz;
  thread_row public.trade_threads%rowtype;
  proposal_id_value uuid;
  proposal_version integer;
  proposal_terms_hash text;
  agreement_id_value uuid;
  agreement_version_id uuid;
  actor_name text;
begin
  if p_actor_id is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'A signed-in recipient and secure invitation are required.';
  end if;
  if p_decision not in ('accept', 'counter', 'decline') then
    raise exception 'Choose accept, counter, or decline.';
  end if;
  if length(btrim(coalesce(p_message, ''))) > 4000 then
    raise exception 'Response notes must be 4,000 characters or fewer.';
  end if;

  select * into invitation_row
  from public.trade_invitations
  where token_hash = p_token_hash;

  if not found
     or not moral_trade_private.invitation_status_is_usable(invitation_row.status) then
    raise exception 'Invitation is unavailable or was already answered.';
  end if;
  if invitation_row.sender_id = p_actor_id then
    raise exception 'The sender cannot answer their own invitation.';
  end if;

  select lower(u.email), u.email_confirmed_at
  into actor_email, actor_email_confirmed
  from auth.users u
  where u.id = p_actor_id;

  if actor_email_confirmed is null then
    raise exception 'Confirm your email address before answering an invitation.';
  end if;

  perform moral_trade_private.lock_pair(invitation_row.sender_id, p_actor_id);

  select * into offer_row
  from public.offers
  where id = invitation_row.offer_id
  for update;

  if not found then
    raise exception 'The reviewed proposal is no longer available.';
  end if;

  perform moral_trade_private.lock_invitation_delivery(invitation_row.id);
  select * into invitation_row
  from public.trade_invitations
  where id = invitation_row.id
    and token_hash = p_token_hash
  for update;

  if not found
     or not moral_trade_private.invitation_status_is_usable(invitation_row.status) then
    raise exception 'Invitation is unavailable or was already answered.';
  end if;
  if invitation_row.expires_at <= now() then
    update public.trade_invitations
    set status = 'expired', revoked_at = now(),
        revocation_reason = 'Invitation expired after 14 days.', updated_at = now()
    where id = invitation_row.id;
    perform moral_trade_private.suppress_invitation_email(
      invitation_row.id,
      'Invitation expired before response.'
    );
    raise exception 'Invitation expired.';
  end if;
  if invitation_row.sender_id = p_actor_id then
    raise exception 'The sender cannot answer their own invitation.';
  end if;

  if invitation_row.recipient_user_id is not null
     and invitation_row.recipient_user_id <> p_actor_id then
    raise exception 'This invitation is bound to a different account.';
  end if;
  if invitation_row.delivery_kind = 'email'
     and invitation_row.recipient_user_id is null
     and lower(invitation_row.recipient_email) <> actor_email then
    raise exception 'Sign in with the confirmed email address that received this invitation.';
  end if;

  if offer_row.id <> invitation_row.offer_id
     or offer_row.owner_id <> invitation_row.sender_id
     or not moral_trade_private.offer_is_invitable(offer_row.id)
     or invitation_row.terms_version <> offer_row.terms_version
     or invitation_row.terms_hash <> public.core_trade_terms_hash(
       offer_row.offer_action,
       offer_row.request_action,
       offer_row.duration,
       offer_row.start_date,
       offer_row.verification,
       offer_row.evidence_due_date,
       offer_row.exit_conditions,
       offer_row.maximum_burden,
       offer_row.privacy_scope,
       offer_row.no_trade_baseline
     ) then
    raise exception 'The reviewed proposal changed or is no longer eligible.';
  end if;

  if moral_trade_private.pair_is_blocked(invitation_row.sender_id, p_actor_id) then
    raise exception 'This interaction is blocked.';
  end if;

  update public.trade_invitations
  set
    recipient_user_id = p_actor_id,
    claimed_by = p_actor_id,
    claimed_at = coalesce(claimed_at, now()),
    updated_at = now()
  where id = invitation_row.id;

  if p_decision = 'decline' then
    update public.trade_invitations
    set status = 'declined', responded_at = now(), updated_at = now()
    where id = invitation_row.id;
    perform moral_trade_private.suppress_invitation_email(
      invitation_row.id,
      'Invitation was declined.'
    );
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      invitation_row.sender_id,
      'invitation_declined',
      'Invitation declined',
      'The invited participant declined. No agreement was created.',
      '/trades/' || invitation_row.offer_id::text || '/invite',
      'invitation_declined:' || invitation_row.id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
    return jsonb_build_object('status', 'declined');
  end if;

  select * into thread_row
  from public.trade_threads t
  where t.offer_id = offer_row.id
    and t.status <> 'closed'
    and (
      (t.participant_a = invitation_row.sender_id and t.participant_b = p_actor_id)
      or
      (t.participant_b = invitation_row.sender_id and t.participant_a = p_actor_id)
    )
  for update;

  if not found then
    insert into public.trade_threads(
      offer_id,
      invitation_id,
      participant_a,
      participant_b,
      status,
      last_message_at,
      created_at,
      updated_at
    ) values (
      offer_row.id,
      invitation_row.id,
      invitation_row.sender_id,
      p_actor_id,
      'active',
      now(),
      now(),
      now()
    )
    returning * into thread_row;
  end if;

  if thread_row.status <> 'active' then
    raise exception 'The private thread is not active.';
  end if;
  if thread_row.agreement_id is not null
     or exists (
       select 1
       from public.agreements a
       where a.offer_id = offer_row.id
         and (
           (a.proposer_id = invitation_row.sender_id and a.responder_id = p_actor_id)
           or
           (a.proposer_id = p_actor_id and a.responder_id = invitation_row.sender_id)
         )
         and a.lifecycle_status not in ('cancelled', 'expired')
     ) then
    raise exception 'An agreement already exists for this proposal and participant pair.';
  end if;

  select coalesce(max(cp.version), 0) + 1
  into proposal_version
  from public.trade_counterproposals cp
  where cp.thread_id = thread_row.id;

  update public.trade_counterproposals
  set status = 'superseded', responded_at = now()
  where thread_id = thread_row.id
    and status = 'proposed';

  if p_decision = 'accept' then
    proposal_terms_hash := public.core_trade_terms_hash(
      offer_row.offer_action,
      offer_row.request_action,
      offer_row.duration,
      offer_row.start_date,
      offer_row.verification,
      offer_row.evidence_due_date,
      offer_row.exit_conditions,
      offer_row.maximum_burden,
      offer_row.privacy_scope,
      offer_row.no_trade_baseline
    );

    insert into public.trade_counterproposals(
      thread_id, offer_id, proposer_id, version, status,
      proposed_action, requested_action, duration, start_date,
      evidence_rule, evidence_due_date, exit_conditions, maximum_burden,
      privacy_scope, no_trade_baseline, terms_hash, created_at, responded_at
    ) values (
      thread_row.id, offer_row.id, invitation_row.sender_id, proposal_version, 'proposed',
      offer_row.offer_action, offer_row.request_action, offer_row.duration, offer_row.start_date,
      offer_row.verification, offer_row.evidence_due_date, offer_row.exit_conditions,
      offer_row.maximum_burden, offer_row.privacy_scope, offer_row.no_trade_baseline,
      proposal_terms_hash, now(), null
    )
    returning id into proposal_id_value;

    perform set_config('app.core_trade_accepting', '1', true);
    update public.trade_counterproposals
    set status = 'accepted', responded_at = now()
    where id = proposal_id_value;

    insert into public.agreements(
      offer_id,
      interest_id,
      proposer_id,
      responder_id,
      status,
      lifecycle_status,
      notes,
      evidence_due_at,
      created_at,
      updated_at
    ) values (
      offer_row.id,
      null,
      invitation_row.sender_id,
      p_actor_id,
      'proposed',
      'proposed',
      'Created from an accepted structured counterproposal. Both parties must confirm the same immutable version.',
      offer_row.evidence_due_date,
      now(),
      now()
    )
    returning id into agreement_id_value;

    perform set_config('app.core_trade_linking_agreement', '1', true);
    insert into public.trade_agreement_versions(
      agreement_id, version, proposed_by, proposed_action, requested_action,
      duration, start_date, evidence_rule, evidence_due_date, exit_conditions,
      maximum_burden, privacy_scope, no_trade_baseline, terms_hash, created_at
    ) values (
      agreement_id_value, 1, invitation_row.sender_id,
      offer_row.offer_action, offer_row.request_action, offer_row.duration,
      offer_row.start_date, offer_row.verification, offer_row.evidence_due_date,
      offer_row.exit_conditions, offer_row.maximum_burden, offer_row.privacy_scope,
      offer_row.no_trade_baseline, proposal_terms_hash, now()
    )
    returning id into agreement_version_id;

    perform set_config('app.core_trade_internal', '1', true);
    update public.agreements
    set
      current_version_id = agreement_version_id,
      evidence_due_at = offer_row.evidence_due_date,
      status = 'proposed',
      lifecycle_status = 'proposed',
      updated_at = now()
    where id = agreement_id_value;

    update public.trade_threads
    set agreement_id = agreement_id_value, updated_at = now(), last_message_at = now()
    where id = thread_row.id;

    update public.trade_invitations
    set status = 'accepted', responded_at = now(), updated_at = now()
    where id = invitation_row.id;

    insert into public.trade_messages(
      thread_id, sender_id, message_type, body, metadata, created_at
    ) values (
      thread_row.id,
      null,
      'system',
      'The recipient accepted the reviewed terms. The agreement remains proposed until both participants confirm the same frozen version.',
      jsonb_build_object(
        'invitationId', invitation_row.id,
        'agreementId', agreement_id_value,
        'agreementVersionId', agreement_version_id
      ),
      now()
    );

    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values
      (
        invitation_row.sender_id,
        'final_confirmation_required',
        'Invitation accepted — confirm terms',
        'Review the frozen agreement version. It is not active until both participants confirm it.',
        '/trade-agreements/' || agreement_id_value::text,
        'invite_confirmation:' || agreement_id_value::text || ':' || invitation_row.sender_id::text,
        now()
      ),
      (
        p_actor_id,
        'final_confirmation_required',
        'Confirm the accepted terms',
        'Review the frozen agreement version. It is not active until both participants confirm it.',
        '/trade-agreements/' || agreement_id_value::text,
        'invite_confirmation:' || agreement_id_value::text || ':' || p_actor_id::text,
        now()
      )
    on conflict (dedupe_key) do nothing;

    perform moral_trade_private.suppress_invitation_email(
      invitation_row.id,
      'Invitation was accepted.'
    );
    return jsonb_build_object(
      'status', 'accepted',
      'threadId', thread_row.id,
      'agreementId', agreement_id_value,
      'agreementVersionId', agreement_version_id
    );
  end if;

  if greatest(
    length(btrim(coalesce(p_proposed_action, ''))),
    length(btrim(coalesce(p_requested_action, ''))),
    length(btrim(coalesce(p_duration, ''))),
    length(btrim(coalesce(p_evidence_rule, ''))),
    length(btrim(coalesce(p_exit_conditions, ''))),
    length(btrim(coalesce(p_maximum_burden, ''))),
    length(btrim(coalesce(p_privacy_scope, ''))),
    length(btrim(coalesce(p_no_trade_baseline, '')))
  ) > 5000 then
    raise exception 'Counterproposal terms must be 5,000 characters or fewer per field.';
  end if;
  if btrim(coalesce(p_proposed_action, '')) = ''
     or btrim(coalesce(p_requested_action, '')) = ''
     or btrim(coalesce(p_duration, '')) = ''
     or btrim(coalesce(p_evidence_rule, '')) = ''
     or btrim(coalesce(p_exit_conditions, '')) = ''
     or btrim(coalesce(p_maximum_burden, '')) = ''
     or btrim(coalesce(p_privacy_scope, '')) = ''
     or btrim(coalesce(p_no_trade_baseline, '')) = '' then
    raise exception 'Complete every bounded counterproposal term.';
  end if;

  proposal_terms_hash := public.core_trade_terms_hash(
    btrim(p_proposed_action),
    btrim(p_requested_action),
    btrim(p_duration),
    p_start_date,
    btrim(p_evidence_rule),
    p_evidence_due_date,
    btrim(p_exit_conditions),
    btrim(p_maximum_burden),
    btrim(p_privacy_scope),
    btrim(p_no_trade_baseline)
  );

  insert into public.trade_counterproposals(
    thread_id, offer_id, proposer_id, version, status,
    proposed_action, requested_action, duration, start_date,
    evidence_rule, evidence_due_date, exit_conditions, maximum_burden,
    privacy_scope, no_trade_baseline, terms_hash, created_at
  ) values (
    thread_row.id, offer_row.id, p_actor_id, proposal_version, 'proposed',
    btrim(p_proposed_action), btrim(p_requested_action), btrim(p_duration), p_start_date,
    btrim(p_evidence_rule), p_evidence_due_date, btrim(p_exit_conditions),
    btrim(p_maximum_burden), btrim(p_privacy_scope), btrim(p_no_trade_baseline),
    proposal_terms_hash, now()
  )
  returning id into proposal_id_value;

  select coalesce(nullif(p.display_name, ''), 'The invited participant')
  into actor_name
  from public.profiles p
  where p.id = p_actor_id;

  update public.trade_invitations
  set status = 'countered', responded_at = now(), updated_at = now()
  where id = invitation_row.id;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, created_at
  ) values (
    thread_row.id,
    null,
    'system',
    coalesce(actor_name, 'The invited participant') || ' sent a counterproposal.',
    jsonb_build_object(
      'invitationId', invitation_row.id,
      'counterproposalId', proposal_id_value,
      'version', proposal_version
    ),
    now()
  );

  insert into public.trade_notifications(
    user_id, notification_type, title, body, href, dedupe_key, created_at
  ) values (
    invitation_row.sender_id,
    'counterproposal_sent',
    'Invitation counterproposal received',
    'The invited participant proposed a new immutable version of the terms.',
    '/messages/' || thread_row.id::text,
    'invite_counter:' || proposal_id_value::text || ':' || invitation_row.sender_id::text,
    now()
  )
  on conflict (dedupe_key) do nothing;

  perform moral_trade_private.suppress_invitation_email(
    invitation_row.id,
    'Invitation received a counterproposal.'
  );
  return jsonb_build_object(
    'status', 'countered',
    'threadId', thread_row.id,
    'counterproposalId', proposal_id_value
  );
end;
$_$;



CREATE FUNCTION public.retry_email_outbox_v2(p_email_id uuid, p_worker_token uuid, p_error text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  next_status text;
begin
  update public.email_outbox
  set
    status = case when attempt_count >= 5 then 'failed' else 'retry' end,
    available_at = case
      when attempt_count >= 5 then available_at
      else now() + make_interval(mins => power(2, least(attempt_count, 6))::integer)
    end,
    last_error = left(coalesce(p_error, 'Unknown email delivery failure.'), 500),
    locked_at = null,
    lock_token = null
  where id = p_email_id
    and status = 'processing'
    and lock_token = p_worker_token
  returning status into next_status;
  return next_status;
end;
$$;



CREATE FUNCTION public.review_conditional_payment_destination_request(p_actor_profile_id uuid, p_request_id uuid, p_decision text, p_notes text, p_stripe_connected_account_id text, p_capabilities_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  request_row public.conditional_payment_destination_requests%rowtype;
  destination_row public.conditional_payment_destinations%rowtype;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Decision must be approved or rejected.';
  end if;
  if not exists (select 1 from public.profiles where id = p_actor_profile_id) then
    raise exception 'The reviewing profile does not exist.';
  end if;

  select * into request_row
  from public.conditional_payment_destination_requests
  where id = p_request_id
  for update;
  if not found then
    raise exception 'Destination request not found.';
  end if;
  if request_row.status <> 'pending' then
    return to_jsonb(request_row);
  end if;

  if p_decision = 'approved' then
    if trim(coalesce(p_stripe_connected_account_id, '')) !~ '^acct_[A-Za-z0-9_]+$' then
      raise exception 'Approval requires a verified Stripe connected-account identifier.';
    end if;
    if p_capabilities_snapshot is null or jsonb_typeof(p_capabilities_snapshot) <> 'object' then
      raise exception 'Approval requires a structured capabilities snapshot.';
    end if;
    if request_row.environment = 'live' and not (
      coalesce((p_capabilities_snapshot->>'chargesEnabled')::boolean, false)
      and coalesce((p_capabilities_snapshot->>'payoutsEnabled')::boolean, false)
      and coalesce((p_capabilities_snapshot->>'detailsSubmitted')::boolean, false)
    ) then
      raise exception 'A live destination must have verified charges, payouts, and submitted details.';
    end if;

    insert into public.conditional_payment_destinations(
      registered_charity_id,
      display_name,
      stripe_connected_account_id,
      livemode,
      status,
      capabilities_snapshot,
      test_only,
      reviewed_by,
      reviewed_at
    ) values (
      null,
      request_row.display_name,
      trim(p_stripe_connected_account_id),
      request_row.environment = 'live',
      'active',
      p_capabilities_snapshot || jsonb_build_object(
        'provider', request_row.provider,
        'providerNonprofitId', request_row.provider_nonprofit_id,
        'nonprofitSlug', request_row.nonprofit_slug,
        'nonprofitEin', request_row.nonprofit_ein,
        'countryCode', request_row.country_code,
        'websiteUrl', request_row.website_url,
        'identityHash', request_row.identity_hash,
        'destinationRequestId', request_row.id
      ),
      request_row.environment = 'test',
      p_actor_profile_id,
      timezone('utc', now())
    )
    returning * into destination_row;

    update public.conditional_payment_destination_requests
    set status = 'approved', reviewed_by = p_actor_profile_id,
        reviewed_at = timezone('utc', now()), review_notes = left(coalesce(p_notes, ''), 1000),
        destination_id = destination_row.id
    where id = request_row.id
    returning * into request_row;
  else
    update public.conditional_payment_destination_requests
    set status = 'rejected', reviewed_by = p_actor_profile_id,
        reviewed_at = timezone('utc', now()), review_notes = left(coalesce(p_notes, ''), 1000),
        destination_id = null
    where id = request_row.id
    returning * into request_row;
  end if;

  insert into public.conditional_payment_destination_review_events(
    request_id, actor_profile_id, decision, identity_hash, notes
  ) values (
    request_row.id,
    p_actor_profile_id,
    p_decision,
    request_row.identity_hash,
    left(coalesce(p_notes, ''), 1000)
  );

  return to_jsonb(request_row);
end;
$_$;



CREATE FUNCTION public.review_trade_donation_pool_gate(p_actor_profile_id uuid, p_environment text, p_gate_key text, p_status text, p_notes text, p_accountable_owner_name text, p_accountable_owner_role text, p_accountable_owner_email text, p_evidence_url text, p_evidence_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  gate_row public.trade_donation_pool_gate_status%rowtype;
begin
  if p_environment not in ('test', 'live') then
    raise exception 'Invalid gate environment.';
  end if;
  if p_status not in ('passed', 'pending', 'blocked') then
    raise exception 'Invalid gate status.';
  end if;
  if not exists (select 1 from public.profiles where id = p_actor_profile_id) then
    raise exception 'The reviewing profile does not exist.';
  end if;
  if p_status = 'passed' and (
    length(trim(coalesce(p_accountable_owner_name, ''))) < 2
    or length(trim(coalesce(p_accountable_owner_role, ''))) < 2
    or trim(coalesce(p_accountable_owner_email, '')) !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    or trim(coalesce(p_evidence_url, '')) !~ '^https://'
    or trim(coalesce(p_evidence_sha256, '')) !~ '^[0-9a-f]{64}$'
  ) then
    raise exception 'Passing a gate requires named ownership, role, email, HTTPS evidence, and an exact SHA-256.';
  end if;

  update public.trade_donation_pool_gate_status
  set status = p_status,
      notes = left(coalesce(p_notes, ''), 2000),
      approved_by = case when p_status = 'passed' then p_actor_profile_id else null end,
      approved_at = case when p_status = 'passed' then timezone('utc', now()) else null end,
      accountable_owner_name = case when p_status = 'passed' then trim(p_accountable_owner_name) else '' end,
      accountable_owner_role = case when p_status = 'passed' then trim(p_accountable_owner_role) else '' end,
      accountable_owner_email = case when p_status = 'passed' then lower(trim(p_accountable_owner_email)) else '' end,
      evidence_url = case when p_status = 'passed' then trim(p_evidence_url) else '' end,
      evidence_sha256 = case when p_status = 'passed' then lower(trim(p_evidence_sha256)) else '' end,
      evidence_recorded_at = case when p_status = 'passed' then timezone('utc', now()) else null end,
      updated_at = timezone('utc', now())
  where environment = p_environment and gate_key = p_gate_key
  returning * into gate_row;

  if not found then
    raise exception 'Payment gate not found.';
  end if;

  insert into public.trade_donation_pool_audit_events(
    actor_profile_id, actor_kind, event_type, object_type, object_id, details
  ) values (
    p_actor_profile_id,
    'operator',
    'gate_reviewed',
    'gate',
    null,
    jsonb_build_object(
      'environment', p_environment,
      'gateKey', p_gate_key,
      'status', p_status,
      'evidenceSha256', case when p_status = 'passed' then lower(trim(p_evidence_sha256)) else null end
    )
  );

  return to_jsonb(gate_row);
end;
$_$;



CREATE FUNCTION public.review_trade_evidence_v3(p_actor_id uuid, p_evidence_id uuid, p_decision text, p_challenge_reason text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  evidence_row public.trade_evidence_items%rowtype;
  agreement_row public.agreements%rowtype;
  remaining_challenges integer;
  normalized_reason text := btrim(coalesce(p_challenge_reason, ''));
begin
  if p_actor_id is null or p_evidence_id is null then
    raise exception 'A signed-in counterparty is required.';
  end if;
  if p_decision not in ('accept', 'challenge') then
    raise exception 'Choose accept or challenge.';
  end if;
  if length(normalized_reason) > 4000 then
    raise exception 'Challenge reason must be 4,000 characters or fewer.';
  end if;

  select * into evidence_row
  from public.trade_evidence_items
  where id = p_evidence_id
  for update;
  if not found then
    raise exception 'Evidence item is unavailable.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = evidence_row.agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found or p_actor_id = evidence_row.submitted_by then
    raise exception 'Only the counterparty may review submitted evidence.';
  end if;

  if (p_decision = 'accept' and evidence_row.status = 'accepted')
     or (p_decision = 'challenge' and evidence_row.status = 'challenged') then
    return jsonb_build_object(
      'evidenceId', evidence_row.id,
      'status', evidence_row.status,
      'idempotent', true
    );
  end if;
  if evidence_row.status <> 'submitted' then
    raise exception 'Evidence is no longer awaiting review.';
  end if;

  if p_decision = 'challenge' then
    if evidence_row.challenge_window_ends_at <= now() then
      raise exception 'The challenge window for this evidence item has closed.';
    end if;
    if normalized_reason = '' then
      raise exception 'State the factual or scope issue being challenged.';
    end if;
    update public.trade_evidence_items
    set status = 'challenged',
        challenge_reason = normalized_reason,
        reviewed_at = now()
    where id = evidence_row.id;

    perform set_config('app.core_trade_internal', '1', true);
    update public.agreements
    set lifecycle_status = 'disputed',
        status = 'active',
        updated_at = now()
    where id = agreement_row.id;
  else
    update public.trade_evidence_items
    set status = 'accepted',
        challenge_reason = '',
        reviewed_at = now()
    where id = evidence_row.id;

    select count(*) into remaining_challenges
    from public.trade_evidence_items
    where agreement_id = agreement_row.id and status = 'challenged';
    if agreement_row.lifecycle_status = 'disputed' and remaining_challenges = 0 then
      perform set_config('app.core_trade_internal', '1', true);
      update public.agreements
      set lifecycle_status = 'evidence_due',
          status = 'active',
          updated_at = now()
      where id = agreement_row.id;
    end if;
  end if;

  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      evidence_row.submitted_by,
      case when p_decision = 'accept' then 'evidence_accepted' else 'evidence_challenged' end,
      case when p_decision = 'accept' then 'Evidence accepted' else 'Evidence challenged' end,
      case when p_decision = 'accept'
        then 'The counterparty accepted the submitted evidence.'
        else 'The counterparty challenged an evidence item. Review the stated reason in the agreement record.'
      end,
      '/trade-agreements/' || agreement_row.id::text,
      case when p_decision = 'accept'
        then 'evidence_accepted:' || evidence_row.id::text
        else 'evidence_challenged:' || evidence_row.id::text
      end,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'evidenceId', evidence_row.id,
    'status', case when p_decision = 'accept' then 'accepted' else 'challenged' end,
    'idempotent', false
  );
end;
$$;



CREATE FUNCTION public.revoke_trade_invitation_v2(p_actor_id uuid, p_invitation_id uuid, p_offer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform moral_trade_private.require_bound_trade_actor(p_actor_id);
  return public.revoke_trade_invitation_v2_unbound_legacy(
    p_actor_id, p_invitation_id, p_offer_id
  );
end;
$$;



CREATE FUNCTION public.revoke_trade_invitation_v2_unbound_legacy(p_actor_id uuid, p_invitation_id uuid, p_offer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  invitation_row public.trade_invitations%rowtype;
  offer_row public.offers%rowtype;
begin
  select * into offer_row
  from public.offers
  where id = p_offer_id
  for update;

  if not found or offer_row.owner_id <> p_actor_id then
    raise exception 'Offer not found or access denied.';
  end if;

  perform moral_trade_private.lock_invitation_delivery(p_invitation_id);
  select * into invitation_row
  from public.trade_invitations
  where id = p_invitation_id
    and offer_id = p_offer_id
    and sender_id = p_actor_id
  for update;

  if not found then
    raise exception 'Invitation not found or access denied.';
  end if;
  if not moral_trade_private.invitation_status_is_usable(invitation_row.status) then
    raise exception 'Only an open invitation can be revoked.';
  end if;
  if exists (
    select 1
    from public.email_outbox e
    where e.source_kind = 'trade_invitation'
      and e.source_id = p_invitation_id::text
      and e.status = 'processing'
      and e.locked_at >= now() - interval '10 minutes'
  ) then
    raise exception 'Invitation email delivery is in progress. Retry shortly.';
  end if;

  update public.trade_invitations
  set
    status = 'revoked',
    revoked_at = now(),
    revocation_reason = 'Revoked by sender.',
    updated_at = now()
  where id = p_invitation_id;
  perform moral_trade_private.suppress_invitation_email(
    p_invitation_id,
    'Invitation revoked by sender before delivery.'
  );
  return true;
end;
$$;



CREATE FUNCTION public.revoke_trade_invitations_after_offer_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  terms_changed boolean;
begin
  terms_changed :=
    new.offered_cause is distinct from old.offered_cause
    or new.requested_cause is distinct from old.requested_cause
    or new.offer_action is distinct from old.offer_action
    or new.request_action is distinct from old.request_action
    or new.verification is distinct from old.verification
    or new.duration is distinct from old.duration
    or new.no_trade_baseline is distinct from old.no_trade_baseline
    or new.start_date is distinct from old.start_date
    or new.exit_conditions is distinct from old.exit_conditions
    or new.maximum_burden is distinct from old.maximum_burden
    or new.privacy_scope is distinct from old.privacy_scope
    or new.evidence_due_date is distinct from old.evidence_due_date
    or new.terms_version is distinct from old.terms_version;

  if terms_changed
     or new.workflow_status <> 'published'
     or new.status::text <> 'open' then
    perform moral_trade_private.revoke_offer_invitations(
      new.id,
      case
        when terms_changed then 'The offer terms changed.'
        else 'The offer is no longer published and open.'
      end
    );
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.route_profile_ciphertexts_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  entry record;
  ciphertext text;
begin
  if value is null
     or jsonb_typeof(value) <> 'object'
     or octet_length(value::text) > 50000
  then
    return false;
  end if;

  for entry in select item.key, item.value from jsonb_each(value) as item
  loop
    if entry.key <> all (array[
      'route_recommendation_profiles.goal',
      'route_recommendation_profiles.cause_priorities',
      'route_recommendation_profiles.otherwise_baseline'
    ])
       or jsonb_typeof(entry.value) <> 'string'
    then
      return false;
    end if;

    ciphertext := entry.value #>> '{}';
    if octet_length(ciphertext) > 12000
       or ciphertext !~ '^bgenc:v(1|2):'
    then
      return false;
    end if;
  end loop;

  return true;
exception when others then
  return false;
end;
$$;



CREATE FUNCTION public.route_profile_interview_answers_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if value is null
     or jsonb_typeof(value) <> 'object'
     or octet_length(value::text) > 1000
     or value - array['confirmed', 'version', 'confirmedAt'] <> '{}'::jsonb
  then
    return false;
  end if;

  if value = '{}'::jsonb then
    return true;
  end if;

  if jsonb_typeof(value -> 'confirmed') is distinct from 'boolean'
     or jsonb_typeof(value -> 'version') is distinct from 'string'
     or jsonb_typeof(value -> 'confirmedAt') is distinct from 'string'
  then
    return false;
  end if;

  return (value ->> 'confirmed')::boolean = true
    and (value ->> 'version') = 'guided-route-interview-v1'
    and char_length(value ->> 'confirmedAt') <= 40;
exception when others then
  return false;
end;
$$;



CREATE FUNCTION public.route_profile_pairwise_answers_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  entry record;
  answer jsonb;
  left_format text;
  right_format text;
  answer_choice text;
  canonical_key text;
  unordered_pair text;
  seen_pairs text[] := '{}'::text[];
  answer_count integer := 0;
begin
  if value is null
     or jsonb_typeof(value) <> 'object'
     or octet_length(value::text) > 30000
  then
    return false;
  end if;

  for entry in select item.key, item.value from jsonb_each(value) as item
  loop
    answer_count := answer_count + 1;
    if answer_count > 10 or jsonb_typeof(entry.value) <> 'object' then
      return false;
    end if;

    answer := entry.value;
    if answer - array['choice', 'leftFormat', 'rightFormat', 'answeredAt'] <> '{}'::jsonb then
      return false;
    end if;
    if jsonb_typeof(answer -> 'leftFormat') is distinct from 'string'
       or jsonb_typeof(answer -> 'rightFormat') is distinct from 'string'
       or jsonb_typeof(answer -> 'choice') is distinct from 'string'
       or jsonb_typeof(answer -> 'answeredAt') is distinct from 'string'
    then
      return false;
    end if;

    left_format := answer ->> 'leftFormat';
    right_format := answer ->> 'rightFormat';
    answer_choice := answer ->> 'choice';
    canonical_key := 'route-format:' || left_format || ':' || right_format;
    unordered_pair := least(left_format, right_format) || ':' || greatest(left_format, right_format);

    if left_format not in ('direct', 'threshold', 'redirect', 'personal', 'coalition')
       or right_format not in ('direct', 'threshold', 'redirect', 'personal', 'coalition')
       or left_format = right_format
       or answer_choice not in ('left', 'right', 'equal', 'neither', 'unsure')
       or entry.key <> canonical_key
       or unordered_pair = any (seen_pairs)
       or char_length(answer ->> 'answeredAt') > 40
    then
      return false;
    end if;

    seen_pairs := array_append(seen_pairs, unordered_pair);
  end loop;

  return true;
exception when others then
  return false;
end;
$$;



CREATE FUNCTION public.safe_participant_display_name_v1(p_display_name text, p_username text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  with cleaned as (
    select btrim(regexp_replace(regexp_replace(coalesce(p_display_name, ''), '[[:cntrl:]]', '', 'g'), '[[:space:]]+', ' ', 'g')) as value
  )
  select case
    when nullif(cleaned.value, '') is null then '@' || p_username
    when strpos(cleaned.value, '@') > 0 then '@' || p_username
    when cleaned.value ~* '(https?://|www\.)' then '@' || p_username
    when char_length(regexp_replace(cleaned.value, '[^0-9]', '', 'g')) >= 7
      and cleaned.value ~ '^[+0-9() .-]+$' then '@' || p_username
    else left(cleaned.value, 120)
  end
  from cleaned;
$_$;



CREATE FUNCTION public.search_create_participants_v2(p_actor_profile_id uuid, p_query text, p_limit integer DEFAULT 12) RETURNS TABLE(profile_id uuid, username text, display_name text, avatar_url text, account_type text, verification text, public_invitation_mentions_enabled boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth', 'extensions'
    AS $$
declare
  normalized_query text := lower(regexp_replace(regexp_replace(btrim(coalesce(p_query, '')), '^@+', ''), '[[:space:]]+', ' ', 'g'));
  bounded_limit integer := least(12, greatest(1, coalesce(p_limit, 12)));
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_actor_profile_id is null then
    raise exception 'actor_profile_required' using errcode = '22023';
  end if;
  if char_length(normalized_query) < 2 or char_length(normalized_query) > 80 then
    return;
  end if;
  return query
  with candidate as (
    select
      profile.id,
      profile.username,
      public.safe_participant_display_name_v1(profile.display_name, profile.username) as display_name,
      profile.avatar_url,
      profile.account_kind,
      profile.public_invitation_mentions_enabled,
      case
        when lower(profile.username) = normalized_query then 0
        when lower(public.safe_participant_display_name_v1(profile.display_name, profile.username)) = normalized_query then 1
        when left(lower(profile.username), char_length(normalized_query)) = normalized_query then 2
        when left(lower(public.safe_participant_display_name_v1(profile.display_name, profile.username)), char_length(normalized_query)) = normalized_query then 3
        when strpos(lower(profile.username), normalized_query) > 0 then 4
        when strpos(lower(public.safe_participant_display_name_v1(profile.display_name, profile.username)), normalized_query) > 0 then 5
        when greatest(
          extensions.similarity(lower(profile.username), normalized_query),
          extensions.similarity(lower(public.safe_participant_display_name_v1(profile.display_name, profile.username)), normalized_query)
        ) >= 0.28 then 6
        else 100
      end as match_rank
    from public.profiles profile
    left join public.wish_profiles wish on wish.profile_id = profile.id
    where profile.id <> p_actor_profile_id
      and profile.username is not null
      and profile.accepts_group_invitations
      and coalesce(wish.safety_status, 'clear') <> 'blocked'
      and not exists (
        select 1
        from public.trade_blocks block
        where (block.blocker_id = p_actor_profile_id and block.blocked_id = profile.id)
           or (block.blocker_id = profile.id and block.blocked_id = p_actor_profile_id)
      )
  )
  select
    candidate.id,
    candidate.username,
    candidate.display_name,
    candidate.avatar_url,
    candidate.account_kind,
    case
      when exists (
        select 1 from public.profile_verification_badges badge
        where badge.profile_id = candidate.id
          and badge.badge_type = case
            when candidate.account_kind = 'organization' then 'organization_verified'
            else 'identity_verified'
          end
          and badge.status = 'verified'
          and (badge.expires_at is null or badge.expires_at > timezone('utc', now()))
      ) then case
        when candidate.account_kind = 'organization' then 'organization-verified'
        else 'identity-verified'
      end
      else 'none'
    end,
    candidate.public_invitation_mentions_enabled
  from candidate
  where candidate.match_rank < 100
  order by candidate.match_rank, lower(candidate.username), candidate.id
  limit bounded_limit;
end;
$$;



CREATE FUNCTION public.seed_donation_offset_redirect_plans() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  initial_charity_id text;
begin
  select donation_offset_offers.compromise_charity_id
  into initial_charity_id
  from public.donation_offset_offers
  where donation_offset_offers.offer_id = new.offer_id;

  if initial_charity_id is null then
    return new;
  end if;

  insert into public.donation_offset_redirect_plans (
    match_id,
    participant_role,
    participant_profile_id,
    registered_charity_id
  )
  values (
    new.id,
    'owner',
    new.owner_profile_id,
    initial_charity_id
  )
  on conflict (match_id, participant_role) do nothing;

  if new.counterparty_profile_id is not null then
    insert into public.donation_offset_redirect_plans (
      match_id,
      participant_role,
      participant_profile_id,
      registered_charity_id
    )
    values (
      new.id,
      'counterparty',
      new.counterparty_profile_id,
      initial_charity_id
    )
    on conflict (match_id, participant_role) do nothing;
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.send_trade_message_v3(p_actor_id uuid, p_thread_id uuid, p_body text, p_submission_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
  existing_id uuid;
  message_id_value uuid;
  counterpart_id uuid;
  normalized_body text := btrim(coalesce(p_body, ''));
  normalized_key text := btrim(coalesce(p_submission_key, ''));
begin
  if p_actor_id is null or p_thread_id is null then
    raise exception 'A signed-in participant and thread are required.';
  end if;
  if normalized_body = '' or length(normalized_body) > 4000 then
    raise exception 'Messages must be between 1 and 4,000 characters.';
  end if;
  if normalized_key = '' or length(normalized_key) > 200 then
    raise exception 'A bounded message submission key is required.';
  end if;

  select id into existing_id
  from public.trade_messages
  where sender_id = p_actor_id and submission_key = normalized_key
  limit 1;
  if existing_id is not null then
    return jsonb_build_object('messageId', existing_id, 'created', false);
  end if;

  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b);
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;

  perform moral_trade_private.lock_pair(thread_row.participant_a, thread_row.participant_b);
  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b)
  for update;
  if not found or thread_row.status <> 'active' then
    raise exception 'This private thread is not active.';
  end if;
  if moral_trade_private.pair_is_blocked(thread_row.participant_a, thread_row.participant_b) then
    raise exception 'This interaction is blocked.';
  end if;

  insert into public.trade_messages(
    thread_id, sender_id, message_type, body, metadata, submission_key, created_at
  ) values (
    thread_row.id, p_actor_id, 'user', normalized_body, '{}'::jsonb, normalized_key, now()
  )
  returning id into message_id_value;

  update public.trade_threads
  set last_message_at = now(), updated_at = now()
  where id = thread_row.id;

  counterpart_id := case
    when thread_row.participant_a = p_actor_id then thread_row.participant_b
    else thread_row.participant_a
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'message_received',
      'New private message',
      'A participant sent a message in your private Moral Trade thread.',
      '/messages/' || thread_row.id::text,
      'message_received:' || message_id_value::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object('messageId', message_id_value, 'created', true);
end;
$$;



CREATE FUNCTION public.set_agreement_reminder_occurrence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.remind_at := new.due_at + (new.offset_minutes * interval '1 minute');
  return new;
end;
$$;



CREATE FUNCTION public.set_conditional_destination_request_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$$;



CREATE FUNCTION public.set_trade_donation_pool_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$$;



