CREATE FUNCTION public.settle_catalog_financial_commitment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  reservation_row public.financial_commitment_reservations%rowtype;
begin
  if new.lifecycle_status is not distinct from old.lifecycle_status then
    return new;
  end if;

  select reservation.*
  into reservation_row
  from public.financial_commitment_reservations reservation
  where reservation.agreement_id = new.id
    and reservation.status = 'reserved'
  for update;

  if not found then
    return new;
  end if;

  if new.lifecycle_status = 'completed' then
    update public.financial_commitment_pools
    set reserved_cents = reserved_cents - reservation_row.reserved_cents,
        spent_cents = spent_cents + reservation_row.reserved_cents,
        updated_at = now()
    where pool_key = reservation_row.pool_key
      and reserved_cents >= reservation_row.reserved_cents;

    update public.financial_commitment_reservations
    set status = 'spent',
        updated_at = now()
    where agreement_id = new.id;
  elsif new.lifecycle_status in ('cancelled','expired') then
    update public.financial_commitment_pools
    set reserved_cents = reserved_cents - reservation_row.reserved_cents,
        updated_at = now()
    where pool_key = reservation_row.pool_key
      and reserved_cents >= reservation_row.reserved_cents;

    update public.financial_commitment_reservations
    set status = 'released',
        updated_at = now()
    where agreement_id = new.id;
  end if;

  return new;
end;
$$;



CREATE TABLE public.trade_donation_intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    donation_term_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    agreement_version_id uuid NOT NULL,
    payer_user_id uuid NOT NULL,
    provider text DEFAULT 'every_org'::text NOT NULL,
    partner_donation_id text NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    expected_target_id text NOT NULL,
    expected_target_name text NOT NULL,
    expected_nonprofit_slug text NOT NULL,
    expected_nonprofit_ein text DEFAULT ''::text NOT NULL,
    expected_amount_cents integer NOT NULL,
    expected_currency text DEFAULT 'USD'::text NOT NULL,
    expected_frequency text DEFAULT 'ONCE'::text NOT NULL,
    provider_charge_id_hash text DEFAULT ''::text NOT NULL,
    provider_payload_hash text DEFAULT ''::text NOT NULL,
    provider_amount_cents integer,
    provider_currency text DEFAULT ''::text NOT NULL,
    provider_nonprofit_slug text DEFAULT ''::text NOT NULL,
    provider_nonprofit_ein text DEFAULT ''::text NOT NULL,
    provider_donation_date timestamp with time zone,
    provider_payment_method text DEFAULT ''::text NOT NULL,
    failure_code text DEFAULT ''::text NOT NULL,
    failure_message text DEFAULT ''::text NOT NULL,
    checkout_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT trade_donation_intents_expected_amount_cents_check CHECK (((expected_amount_cents >= 100) AND (expected_amount_cents <= 50000))),
    CONSTRAINT trade_donation_intents_expected_currency_check CHECK ((expected_currency = 'USD'::text)),
    CONSTRAINT trade_donation_intents_expected_frequency_check CHECK ((expected_frequency = 'ONCE'::text)),
    CONSTRAINT trade_donation_intents_provider_check CHECK ((provider = 'every_org'::text)),
    CONSTRAINT trade_donation_intents_status_check CHECK ((status = ANY (ARRAY['created'::text, 'checkout_started'::text, 'completed'::text, 'needs_review'::text, 'cancelled'::text])))
);



CREATE FUNCTION public.start_trade_donation_checkout(p_agreement_id uuid, p_actor_id uuid, p_partner_donation_id text) RETURNS public.trade_donation_intents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  current_agreement public.agreements%rowtype;
  current_term public.trade_donation_terms%rowtype;
  current_intent public.trade_donation_intents%rowtype;
  payer_id uuid;
begin
  select a.*
  into current_agreement
  from public.agreements a
  where a.id = p_agreement_id
  for update;

  if not found then
    raise exception 'Agreement not found.';
  end if;
  if current_agreement.lifecycle_status <> 'awaiting_donation' then
    raise exception 'Both participants must confirm the frozen terms before donation checkout.';
  end if;

  select t.*
  into current_term
  from public.trade_donation_terms t
  where t.agreement_id = current_agreement.id
    and t.agreement_version_id = current_agreement.current_version_id;

  if not found then
    raise exception 'Frozen donation terms not found.';
  end if;
  if current_term.amount_cents < 1000 then
    raise exception 'Every.org requires at least $10. Sub-$10 obligations must use pooled settlement.';
  end if;

  payer_id := case
    when current_term.payer_role = 'proposer' then current_agreement.proposer_id
    else current_agreement.responder_id
  end;
  if p_actor_id <> payer_id then
    raise exception 'Only the named payer can start the donation checkout.';
  end if;

  select i.*
  into current_intent
  from public.trade_donation_intents i
  where i.donation_term_id = current_term.id
  for update;

  if found then
    if current_intent.status = 'completed' then
      return current_intent;
    end if;
    if current_intent.status = 'needs_review' then
      raise exception 'This donation requires operator review before another checkout can start.';
    end if;
    if current_intent.status = 'cancelled' then
      raise exception 'This donation checkout was cancelled and cannot be reopened.';
    end if;
    update public.trade_donation_intents
    set status = 'checkout_started', checkout_started_at = coalesce(checkout_started_at, timezone('utc', now()))
    where id = current_intent.id
    returning * into current_intent;
    return current_intent;
  end if;

  insert into public.trade_donation_intents(
    donation_term_id,
    agreement_id,
    agreement_version_id,
    payer_user_id,
    provider,
    partner_donation_id,
    status,
    expected_target_id,
    expected_target_name,
    expected_nonprofit_slug,
    expected_nonprofit_ein,
    expected_amount_cents,
    expected_currency,
    expected_frequency,
    checkout_started_at
  ) values (
    current_term.id,
    current_agreement.id,
    current_term.agreement_version_id,
    payer_id,
    'every_org',
    p_partner_donation_id,
    'checkout_started',
    current_term.target_id,
    current_term.target_name,
    current_term.nonprofit_slug,
    current_term.nonprofit_ein,
    current_term.amount_cents,
    current_term.currency,
    current_term.frequency,
    timezone('utc', now())
  )
  returning * into current_intent;

  return current_intent;
end;
$_$;



CREATE FUNCTION public.start_trade_donation_pool_bundle_checkout(p_actor_id uuid, p_bundle_id uuid, p_partner_donation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  bundle_row public.trade_donation_pool_bundles%rowtype;
  invalid_component_count integer;
begin
  if length(trim(coalesce(p_partner_donation_id, ''))) = 0 then
    raise exception 'A unique partner donation ID is required.';
  end if;

  select * into bundle_row
  from public.trade_donation_pool_bundles
  where id = p_bundle_id
  for update;
  if not found then
    raise exception 'Pooled-settlement bundle not found.';
  end if;
  if bundle_row.status = 'checkout_started' and bundle_row.partner_donation_id = p_partner_donation_id then
    return to_jsonb(bundle_row);
  end if;
  if bundle_row.status <> 'frozen' then
    raise exception 'Only a frozen bundle can start provider checkout.';
  end if;

  select count(*) into invalid_component_count
  from public.trade_donation_pool_bundle_items i
  join public.trade_donation_pool_obligations o on o.id = i.obligation_id
  join public.agreements a on a.id = i.agreement_id
  join public.trade_donation_terms t on t.id = i.donation_term_id
  where i.bundle_id = bundle_row.id
    and (
      o.status <> 'bundled'
      or o.bundle_id <> bundle_row.id
      or a.lifecycle_status <> 'awaiting_donation'
      or a.current_version_id <> i.agreement_version_id
      or t.agreement_version_id <> i.agreement_version_id
      or t.amount_cents <> i.allocation_cents
      or t.nonprofit_slug <> bundle_row.nonprofit_slug
      or t.currency <> bundle_row.currency
      or t.frequency <> bundle_row.frequency
    );
  if invalid_component_count > 0 then
    update public.trade_donation_pool_bundles
    set status = 'needs_review', failure_code = 'component_invalid_before_checkout',
        failure_message = 'One or more component obligations changed before provider checkout.'
    where id = bundle_row.id;
    raise exception 'The bundle contains a stale or invalid component.';
  end if;

  update public.trade_donation_pool_bundles
  set
    status = 'checkout_started',
    partner_donation_id = p_partner_donation_id,
    checkout_started_at = timezone('utc', now()),
    failure_code = '',
    failure_message = ''
  where id = bundle_row.id
  returning * into bundle_row;

  insert into public.trade_donation_pool_audit_events(
    actor_profile_id, actor_kind, event_type, object_type, object_id, details
  ) values (
    p_actor_id,
    'operator',
    'every_org_bundle_checkout_started',
    'bundle',
    bundle_row.id,
    jsonb_build_object('manifestHash', bundle_row.manifest_hash)
  );

  return to_jsonb(bundle_row);
end;
$$;



CREATE FUNCTION public.start_trade_milestone_amendment_v1(p_agreement_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  agreement_row public.agreements%rowtype;
  current_version public.trade_agreement_versions%rowtype;
  next_version_number integer;
  next_version_id uuid;
begin
  if actor_id is null then
    raise exception 'Sign in before proposing amended milestone terms.';
  end if;

  select *
  into agreement_row
  from public.agreements agreement
  where agreement.id = p_agreement_id
  for update;

  if not found
     or actor_id not in (agreement_row.proposer_id, agreement_row.responder_id)
     or agreement_row.lifecycle_status <> 'proposed'
     or agreement_row.current_version_id is null then
    raise exception 'Only a participant may amend an unactivated proposed agreement.';
  end if;

  select *
  into current_version
  from public.trade_agreement_versions version
  where version.id = agreement_row.current_version_id
    and version.agreement_id = agreement_row.id
  for update;

  if not found then
    raise exception 'The current frozen agreement version is unavailable.';
  end if;
  if current_version.milestone_manifest_hash is null
     and not exists (
       select 1
       from public.trade_agreement_confirmations confirmation
       where confirmation.agreement_version_id = current_version.id
     ) then
    raise exception 'The current milestone draft is still editable; amend it before finalizing.';
  end if;

  select coalesce(max(version.version), 0) + 1
  into next_version_number
  from public.trade_agreement_versions version
  where version.agreement_id = agreement_row.id;

  insert into public.trade_agreement_versions (
    agreement_id,
    version,
    proposed_by,
    proposed_action,
    requested_action,
    duration,
    start_date,
    evidence_rule,
    evidence_due_date,
    exit_conditions,
    maximum_burden,
    privacy_scope,
    no_trade_baseline,
    terms_hash,
    requires_milestone_manifest,
    milestone_manifest_hash,
    complete_terms_hash,
    created_at
  ) values (
    agreement_row.id,
    next_version_number,
    actor_id,
    current_version.proposed_action,
    current_version.requested_action,
    current_version.duration,
    current_version.start_date,
    current_version.evidence_rule,
    current_version.evidence_due_date,
    current_version.exit_conditions,
    current_version.maximum_burden,
    current_version.privacy_scope,
    current_version.no_trade_baseline,
    current_version.terms_hash,
    true,
    null,
    null,
    now()
  )
  returning id into next_version_id;

  update public.agreements
  set current_version_id = next_version_id,
      status = 'proposed',
      lifecycle_status = 'proposed',
      evidence_due_at = current_version.evidence_due_date,
      updated_at = now()
  where id = agreement_row.id;

  insert into public.trade_notifications (
    user_id, notification_type, title, body, href, dedupe_key, created_at
  )
  select
    participant_id,
    'milestone_amendment_started',
    'Milestone amendment started',
    'A new proposed version is ready for milestone terms. Earlier confirmations do not apply.',
    '/trade-agreements/' || agreement_row.id::text,
    'milestone_amendment:' || next_version_id::text || ':' || participant_id::text,
    now()
  from unnest(
    array[agreement_row.proposer_id, agreement_row.responder_id]
  ) as participants(participant_id)
  on conflict (dedupe_key) do nothing;

  return next_version_id;
end;
$$;



CREATE FUNCTION public.submit_conditional_payment_destination_request(p_requester_profile_id uuid, p_environment text, p_provider_nonprofit_id text, p_nonprofit_slug text, p_display_name text, p_nonprofit_ein text, p_country_code text, p_website_url text, p_identity_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  normalized_identity jsonb;
  identity_hash_value text;
  request_row public.conditional_payment_destination_requests%rowtype;
begin
  if p_environment not in ('test', 'live') then
    raise exception 'Invalid destination-request environment.';
  end if;
  if not exists (select 1 from public.profiles where id = p_requester_profile_id) then
    raise exception 'The requesting profile does not exist.';
  end if;
  if length(trim(coalesce(p_provider_nonprofit_id, ''))) < 2
     or length(trim(coalesce(p_nonprofit_slug, ''))) < 2
     or length(trim(coalesce(p_display_name, ''))) < 2 then
    raise exception 'Provider ID, nonprofit slug, and display name are required.';
  end if;
  if trim(coalesce(p_website_url, '')) !~ '^https://' then
    raise exception 'An HTTPS nonprofit profile or official website is required.';
  end if;
  if p_identity_snapshot is null or jsonb_typeof(p_identity_snapshot) <> 'object' then
    raise exception 'A structured identity snapshot is required.';
  end if;

  normalized_identity := jsonb_build_object(
    'schemaVersion', 'conditional-payment-destination-identity-v1',
    'provider', 'every_org',
    'providerNonprofitId', lower(trim(p_provider_nonprofit_id)),
    'nonprofitSlug', lower(trim(p_nonprofit_slug)),
    'displayName', trim(p_display_name),
    'nonprofitEin', regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    'countryCode', upper(left(trim(coalesce(p_country_code, '')), 2)),
    'websiteUrl', trim(p_website_url),
    'sourceSnapshot', p_identity_snapshot
  );
  identity_hash_value := encode(
    extensions.digest(convert_to(normalized_identity::text, 'UTF8'), 'sha256'),
    'hex'
  );

  select * into request_row
  from public.conditional_payment_destination_requests
  where environment = p_environment
    and provider = 'every_org'
    and provider_nonprofit_id = lower(trim(p_provider_nonprofit_id))
  for update;

  if found then
    if request_row.identity_hash <> identity_hash_value then
      raise exception 'This provider nonprofit already has a request with different frozen identity data.';
    end if;
    return to_jsonb(request_row);
  end if;

  insert into public.conditional_payment_destination_requests(
    requester_profile_id,
    environment,
    provider,
    provider_nonprofit_id,
    nonprofit_slug,
    display_name,
    nonprofit_ein,
    country_code,
    website_url,
    identity_snapshot,
    identity_hash
  ) values (
    p_requester_profile_id,
    p_environment,
    'every_org',
    lower(trim(p_provider_nonprofit_id)),
    lower(trim(p_nonprofit_slug)),
    trim(p_display_name),
    regexp_replace(coalesce(p_nonprofit_ein, ''), '[^0-9]', '', 'g'),
    upper(left(trim(coalesce(p_country_code, '')), 2)),
    trim(p_website_url),
    normalized_identity,
    identity_hash_value
  ) returning * into request_row;

  insert into public.conditional_payment_destination_review_events(
    request_id, actor_profile_id, decision, identity_hash, notes
  ) values (
    request_row.id,
    p_requester_profile_id,
    'submitted',
    request_row.identity_hash,
    'User requested review of a provider-listed fallback charity.'
  );

  return to_jsonb(request_row);
end;
$$;



CREATE FUNCTION public.submit_mpgf_phase_one_ballot(p_round_id uuid, p_project_ids uuid[], p_idempotency_key text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select private.submit_mpgf_phase_one_ballot($1, $2, $3);
$_$;



CREATE FUNCTION public.submit_trade_evidence_bundle_v1(p_bundle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  bundle_row public.trade_evidence_bundles%rowtype;
  milestone_row public.trade_agreement_milestones%rowtype;
begin
  select *
  into bundle_row
  from public.trade_evidence_bundles b
  where b.id = p_bundle_id;
  if actor_id is null
     or not found
     or bundle_row.submitted_by <> actor_id
     or bundle_row.status <> 'draft' then
    raise exception 'This evidence packet cannot be submitted.';
  end if;

  select *
  into milestone_row
  from public.trade_agreement_milestones m
  where m.id = bundle_row.milestone_id
  for update;

  select *
  into bundle_row
  from public.trade_evidence_bundles b
  where b.id = p_bundle_id
    and b.milestone_id = milestone_row.id
  for update;
  if not found
     or bundle_row.submitted_by <> actor_id
     or bundle_row.status <> 'draft' then
    raise exception 'This evidence packet cannot be submitted.';
  end if;

  if not exists (
    select 1
    from public.trade_evidence_bundle_items item
    where item.bundle_id = bundle_row.id
  ) then
    raise exception 'Add at least one evidence item.';
  end if;
  if bundle_row.bundle_kind = 'replacement'
     and (
       milestone_row.replacement_deadline_at is null
       or milestone_row.replacement_deadline_at <= now()
     ) then
    raise exception 'The replacement window has expired or is paused.';
  end if;

  update public.trade_evidence_bundles
  set status = 'submitted',
      submitted_at = now()
  where id = bundle_row.id;

  update public.trade_agreement_milestones
  set current_bundle_id = bundle_row.id,
      status = 'under_review',
      reviewer_selection_opened_at = coalesce(reviewer_selection_opened_at, now()),
      updated_at = now()
  where id = milestone_row.id;

  if milestone_row.assigned_reviewer_id is not null then
    insert into public.trade_notifications (
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      milestone_row.assigned_reviewer_id,
      'milestone_evidence_review',
      'Milestone evidence is ready',
      'A private evidence packet is ready for neutral review.',
      '/trade-review/' || milestone_row.id::text,
      'milestone_review:' || bundle_row.id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  end if;

  return jsonb_build_object(
    'bundleId', bundle_row.id,
    'milestoneId', milestone_row.id,
    'status', 'under_review'
  );
end;
$$;



CREATE FUNCTION public.suppress_email_outbox_v2(p_email_id uuid, p_worker_token uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  update public.email_outbox
  set
    status = 'suppressed',
    provider = 'resend_safety_gate',
    body = case
      when source_kind = 'trade_invitation' then '[private invitation link removed]'
      else body
    end,
    last_error = left(coalesce(p_reason, 'Suppressed by email safety gate.'), 500),
    suppressed_at = now(),
    locked_at = null,
    lock_token = null
  where id = p_email_id
    and status = 'processing'
    and lock_token = p_worker_token;
  return found;
end;
$$;



CREATE FUNCTION public.sync_wish_profile_public_preview() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_profile_id uuid;
begin
  if tg_op = 'DELETE' then
    delete from public.wish_profile_public_previews where profile_id = old.profile_id;
    return old;
  end if;

  target_profile_id := new.profile_id;
  if new.is_discoverable is true
     and new.share_public_preview is true
     and new.safety_status = 'clear' then
    insert into public.wish_profile_public_previews(
      profile_id,
      participant_kind,
      collective_name,
      causes,
      public_preview,
      location_city,
      location_region,
      openness_to_payment,
      openness_to_pledges,
      background_search_enabled,
      privacy_stage,
      updated_at
    ) values (
      new.profile_id,
      new.participant_kind,
      new.collective_name,
      new.causes,
      new.public_preview,
      case when new.share_location then new.location_city else null end,
      case when new.share_location then new.location_region else null end,
      new.openness_to_payment,
      new.openness_to_pledges,
      new.background_search_enabled,
      new.privacy_stage,
      new.updated_at
    )
    on conflict (profile_id) do update set
      participant_kind = excluded.participant_kind,
      collective_name = excluded.collective_name,
      causes = excluded.causes,
      public_preview = excluded.public_preview,
      location_city = excluded.location_city,
      location_region = excluded.location_region,
      openness_to_payment = excluded.openness_to_payment,
      openness_to_pledges = excluded.openness_to_pledges,
      background_search_enabled = excluded.background_search_enabled,
      privacy_stage = excluded.privacy_stage,
      updated_at = excluded.updated_at;
  else
    delete from public.wish_profile_public_previews where profile_id = target_profile_id;
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.touch_core_thread_from_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.trade_threads
  set last_message_at = new.created_at, updated_at = new.created_at
  where id = new.thread_id;
  return new;
end;
$$;



CREATE FUNCTION public.touch_public_evidence_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_agreement_id uuid;
begin
  target_agreement_id := case when tg_op = 'DELETE' then old.agreement_id else new.agreement_id end;

  update public.agreements a
  set
    public_evidence_enabled = exists (
      select 1
      from public.trade_evidence_items e
      where e.agreement_id = target_agreement_id
        and e.public_visibility = 'public'
        and e.public_published_at is not null
        and e.status not in ('withdrawn', 'replaced')
        and e.redaction_status <> 'withheld'
    ),
    public_evidence_updated_at = now()
  where a.id = target_agreement_id;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;



CREATE FUNCTION public.trade_milestone_manifest_hash_v1(p_agreement_version_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select encode(
    extensions.digest(
      convert_to(
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'position', m.position,
              'performerId', m.performer_id,
              'payerId', m.payer_id,
              'actionCategory', btrim(m.action_category),
              'description', btrim(m.description),
              'unitLabel', btrim(m.unit_label),
              'unitsTotal', m.units_total,
              'indivisible', m.indivisible,
              'maximumAmountCents', m.maximum_amount_cents,
              'currency', m.currency,
              'evidenceRule', btrim(m.evidence_rule),
              'confidenceBands', jsonb_build_array(100, 75, 50, 25, 0),
              'replacementWindowDays', 7,
              'appealWindowDays', 7,
              'payoutRounding', 'floor_to_cent'
            )
            order by m.position
          ),
          '[]'::jsonb
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
  from public.trade_agreement_milestones m
  where m.agreement_version_id = p_agreement_version_id;
$$;



CREATE FUNCTION public.trade_milestone_payout_v1(p_maximum_amount_cents bigint, p_completion_units numeric, p_units_total numeric, p_confidence_band smallint) RETURNS TABLE(payout_basis_points integer, amount_due_cents bigint)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    floor(
      least(greatest(p_completion_units, 0), p_units_total)
      / p_units_total
      * p_confidence_band
      * 100
    )::integer,
    floor(
      p_maximum_amount_cents::numeric
      * least(greatest(p_completion_units, 0), p_units_total)
      / p_units_total
      * p_confidence_band
      / 100
    )::bigint
  where p_maximum_amount_cents >= 0
    and p_units_total > 0
    and p_confidence_band in (0, 25, 50, 75, 100);
$$;



CREATE FUNCTION public.upsert_match_suggestion(target_profile_a_id uuid, target_profile_b_id uuid, target_profile_a_entry_id uuid, target_profile_b_entry_id uuid, target_reason_for_a text, target_reason_for_b text, target_score smallint, target_dedupe_key text, target_match_basis text[] DEFAULT '{}'::text[], target_shared_causes text[] DEFAULT '{}'::text[], target_suggested_first_step text DEFAULT ''::text, target_risk_notes text DEFAULT ''::text, target_generated_by text DEFAULT 'rule-based'::text) RETURNS TABLE(match_id uuid, was_created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  existing_match_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if auth.uid() <> target_profile_a_id and auth.uid() <> target_profile_b_id then
    raise exception 'You can only create match suggestions involving your own profile.';
  end if;

  if target_profile_a_id = target_profile_b_id then
    raise exception 'A match suggestion requires two different profiles.';
  end if;

  if (
    select count(*)
    from public.wish_profiles
    where profile_id in (target_profile_a_id, target_profile_b_id)
      and is_discoverable = true
      and safety_status = 'clear'
  ) <> 2 then
    raise exception 'Both profiles must be discoverable and clear safety review.';
  end if;

  select id into existing_match_id
  from public.match_suggestions
  where dedupe_key = target_dedupe_key;

  insert into public.match_suggestions (
    profile_a_id,
    profile_b_id,
    profile_a_entry_id,
    profile_b_entry_id,
    reason_for_a,
    reason_for_b,
    score,
    match_basis,
    shared_causes,
    suggested_first_step,
    risk_notes,
    generated_by,
    status,
    dedupe_key,
    last_scored_at
  )
  values (
    target_profile_a_id,
    target_profile_b_id,
    target_profile_a_entry_id,
    target_profile_b_entry_id,
    target_reason_for_a,
    target_reason_for_b,
    least(100, greatest(0, target_score)),
    coalesce(target_match_basis, '{}'),
    coalesce(target_shared_causes, '{}'),
    coalesce(target_suggested_first_step, ''),
    coalesce(target_risk_notes, ''),
    coalesce(nullif(target_generated_by, ''), 'rule-based'),
    'suggested',
    target_dedupe_key,
    timezone('utc', now())
  )
  on conflict (dedupe_key) do update
    set reason_for_a = excluded.reason_for_a,
        reason_for_b = excluded.reason_for_b,
        score = excluded.score,
        match_basis = excluded.match_basis,
        shared_causes = excluded.shared_causes,
        suggested_first_step = excluded.suggested_first_step,
        risk_notes = excluded.risk_notes,
        generated_by = excluded.generated_by,
        last_scored_at = excluded.last_scored_at,
        status = case
          when public.match_suggestions.status = 'dismissed' then public.match_suggestions.status
          else excluded.status
        end
  returning id into match_id;

  was_created := existing_match_id is null;
  return next;
end;
$$;



CREATE FUNCTION public.validate_donation_offset_redirect_plan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  expected_profile_id uuid;
  charity_is_eligible boolean;
begin
  select case
    when new.participant_role = 'owner' then donation_offset_matches.owner_profile_id
    else donation_offset_matches.counterparty_profile_id
  end
  into expected_profile_id
  from public.donation_offset_matches
  where donation_offset_matches.id = new.match_id;

  if expected_profile_id is null or expected_profile_id <> new.participant_profile_id then
    raise exception 'Redirect-plan participant does not match the donation-offset role.';
  end if;

  select
    registered_charities.is_active
    and registered_charities.selectable
    and not registered_charities.is_political_campaign
  into charity_is_eligible
  from public.registered_charities
  where registered_charities.id = new.registered_charity_id;

  if coalesce(charity_is_eligible, false) is not true then
    raise exception 'Redirect-plan destination is not an eligible registered charity.';
  end if;

  if tg_op = 'UPDATE'
    and new.registered_charity_id is distinct from old.registered_charity_id
    and new.plan_version <= old.plan_version then
    raise exception 'Changing a redirect destination requires a newer plan version.';
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.validate_public_donation_redirect_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.public_receipt_enabled
    and not old.public_receipt_enabled
    and (
      new.purpose <> 'donation_offset'
      or new.subject_type <> 'donation_offset_match'
      or not new.livemode
      or new.status <> 'transferred'
      or coalesce(new.condition_snapshot ->> 'schemaVersion', '')
        <> 'donation-offset-payment-condition-v2'
    ) then
    raise exception 'Only a transferred live v2 donation redirect can publish a receipt.';
  end if;

  if not new.public_receipt_enabled then
    new.public_receipt_enabled_at := null;
    new.public_receipt_enabled_by := null;
  elsif not old.public_receipt_enabled then
    new.public_receipt_enabled_at := timezone('utc', now());
  end if;

  return new;
end;
$$;



CREATE FUNCTION public.validate_trade_donation_term_agreement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  version_agreement_id uuid;
begin
  select v.agreement_id
  into version_agreement_id
  from public.trade_agreement_versions v
  where v.id = new.agreement_version_id;

  if version_agreement_id is null or version_agreement_id <> new.agreement_id then
    raise exception 'Donation terms must reference a version of the same agreement.';
  end if;
  return new;
end;
$$;



CREATE FUNCTION public.viewer_can_access_collective(target_collective_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select
    auth.uid() is not null
    and (
      exists (
        select 1
        from public.collectives
        where id = target_collective_id
          and owner_id = auth.uid()
      )
      or exists (
        select 1
        from public.collective_members
        where collective_id = target_collective_id
          and profile_id = auth.uid()
          and status = 'active'
      )
    );
$$;



CREATE FUNCTION public.viewer_can_see_match_identity(target_match_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select
    public.viewer_participates_in_match(target_match_id)
    and exists (
      select 1
      from public.match_suggestions
      where id = target_match_id
        and (
          identity_revealed = true
          or (
            exists (
              select 1
              from public.match_consents
              where match_id = target_match_id
                and profile_id = profile_a_id
            )
            and exists (
              select 1
              from public.match_consents
              where match_id = target_match_id
                and profile_id = profile_b_id
            )
          )
        )
    );
$$;



CREATE FUNCTION public.viewer_consent_to_match(target_match_id uuid, consent_note text DEFAULT ''::text) RETURNS TABLE(counterparty_id uuid, both_consented boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  viewer_id uuid := auth.uid();
  profile_a uuid;
  profile_b uuid;
begin
  if viewer_id is null then
    raise exception 'Authentication required.';
  end if;

  select profile_a_id, profile_b_id
  into profile_a, profile_b
  from public.match_suggestions
  where id = target_match_id
    and status <> 'dismissed';

  if profile_a is null or profile_b is null then
    raise exception 'Match suggestion not found.';
  end if;

  if viewer_id <> profile_a and viewer_id <> profile_b then
    raise exception 'You can only consent to your own match suggestions.';
  end if;

  counterparty_id := case when viewer_id = profile_a then profile_b else profile_a end;

  insert into public.match_consents (match_id, profile_id, note, consented_at)
  values (target_match_id, viewer_id, coalesce(consent_note, ''), timezone('utc', now()))
  on conflict (match_id, profile_id) do update
    set note = excluded.note,
        consented_at = excluded.consented_at;

  both_consented := exists (
    select 1
    from public.match_consents
    where match_id = target_match_id
      and profile_id = profile_a
  ) and exists (
    select 1
    from public.match_consents
    where match_id = target_match_id
      and profile_id = profile_b
  );

  if both_consented then
    update public.match_suggestions
    set identity_revealed = true,
        status = 'introduced'
    where id = target_match_id;
  end if;

  return next;
end;
$$;



CREATE FUNCTION public.viewer_has_interest_for_offer(target_offer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select
    auth.uid() is not null
    and exists (
      select 1
      from public.interests
      where interests.offer_id = target_offer_id
        and interests.user_id = auth.uid()
    );
$$;



CREATE FUNCTION public.viewer_has_offer_in_cart(target_offer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select
    auth.uid() is not null
    and exists (
      select 1
      from public.offer_carts
      where offer_carts.offer_id = target_offer_id
        and offer_carts.user_id = auth.uid()
    );
$$;



CREATE FUNCTION public.viewer_participates_in_match(target_match_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select
    auth.uid() is not null
    and exists (
      select 1
      from public.match_suggestions
      where id = target_match_id
        and (
          profile_a_id = auth.uid()
          or profile_b_id = auth.uid()
        )
    );
$$;



CREATE FUNCTION public.wish_profile_is_previewable(target_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  select exists (
    select 1
    from public.wish_profiles
    where profile_id = target_profile_id
      and is_discoverable = true
