$$;



CREATE FUNCTION public.withdraw_trade_evidence_v3(p_actor_id uuid, p_evidence_id uuid, p_reason text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  evidence_row public.trade_evidence_items%rowtype;
  agreement_row public.agreements%rowtype;
  counterpart_id uuid;
  remaining_challenges integer;
  remaining_open_or_accepted integer;
  next_lifecycle text;
  normalized_reason text := btrim(coalesce(p_reason, ''));
begin
  if p_actor_id is null or p_evidence_id is null then
    raise exception 'A signed-in evidence submitter is required.';
  end if;
  if length(normalized_reason) > 4000 then
    raise exception 'Withdrawal reason must be 4,000 characters or fewer.';
  end if;

  select * into evidence_row
  from public.trade_evidence_items
  where id = p_evidence_id
  for update;
  if not found then
    raise exception 'Evidence item is unavailable.';
  end if;
  if evidence_row.status = 'withdrawn' then
    return jsonb_build_object(
      'evidenceId', evidence_row.id,
      'status', 'withdrawn',
      'idempotent', true
    );
  end if;
  if evidence_row.submitted_by <> p_actor_id
     or evidence_row.status not in ('submitted', 'challenged') then
    raise exception 'Only the submitter may withdraw open evidence.';
  end if;

  select * into agreement_row
  from public.agreements
  where id = evidence_row.agreement_id
    and p_actor_id in (proposer_id, responder_id)
  for update;
  if not found then
    raise exception 'Agreement not found or access denied.';
  end if;

  update public.trade_evidence_items
  set status = 'withdrawn',
      withdrawn_at = now(),
      withdrawal_reason = normalized_reason,
      reviewed_at = now(),
      public_visibility = 'private',
      public_title = '',
      public_summary = '',
      public_url = '',
      public_storage_path = '',
      public_original_filename = '',
      public_mime_type = '',
      public_redaction_note = '',
      redaction_status = 'withheld',
      public_published_at = null
  where id = evidence_row.id;

  select count(*) into remaining_challenges
  from public.trade_evidence_items
  where agreement_id = agreement_row.id and status = 'challenged';
  select count(*) into remaining_open_or_accepted
  from public.trade_evidence_items
  where agreement_id = agreement_row.id
    and status in ('submitted', 'accepted', 'challenged');
  next_lifecycle := case
    when remaining_challenges > 0 then 'disputed'
    when remaining_open_or_accepted > 0 then 'evidence_due'
    else 'active'
  end;

  perform set_config('app.core_trade_internal', '1', true);
  update public.agreements
  set lifecycle_status = next_lifecycle,
      status = 'active',
      public_evidence_enabled = exists (
        select 1
        from public.trade_evidence_items public_item
        where public_item.agreement_id = agreement_row.id
          and public_item.public_visibility = 'public'
          and public_item.public_published_at is not null
          and public_item.redaction_status in ('redacted', 'not_required')
          and public_item.status not in ('withdrawn', 'replaced')
      ),
      updated_at = now(),
      public_evidence_updated_at = now()
  where id = agreement_row.id;

  counterpart_id := case
    when agreement_row.proposer_id = p_actor_id then agreement_row.responder_id
    else agreement_row.proposer_id
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'evidence_withdrawn',
      'Evidence withdrawn',
      'The submitting participant withdrew an open evidence item. The durable activity record remains available.',
      '/trade-agreements/' || agreement_row.id::text,
      'evidence_withdrawn:' || evidence_row.id::text || ':' || counterpart_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'evidenceId', evidence_row.id,
    'status', 'withdrawn',
    'idempotent', false
  );
end;
$$;



CREATE FUNCTION public.withdraw_trade_response_v3(p_actor_id uuid, p_thread_id uuid, p_interest_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  thread_row public.trade_threads%rowtype;
  counterpart_id uuid;
begin
  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b);
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;
  perform moral_trade_private.lock_pair(thread_row.participant_a, thread_row.participant_b);
  select * into thread_row
  from public.trade_threads
  where id = p_thread_id
    and p_actor_id in (participant_a, participant_b)
  for update;
  if not found then
    raise exception 'Thread not found or access denied.';
  end if;
  if thread_row.agreement_id is not null then
    raise exception 'Use the agreement exit workflow after agreement formation.';
  end if;
  if thread_row.status = 'closed' then
    return jsonb_build_object('threadId', thread_row.id, 'status', 'closed', 'idempotent', true);
  end if;

  if p_interest_id is not null then
    update public.interests
    set status = 'withdrawn', updated_at = now()
    where id = p_interest_id
      and offer_id = thread_row.offer_id
      and user_id = p_actor_id;
    if not found then
      raise exception 'Response not found or access denied.';
    end if;
  else
    update public.interests
    set status = 'withdrawn', updated_at = now()
    where offer_id = thread_row.offer_id
      and user_id = p_actor_id
      and status <> 'accepted';
  end if;

  update public.trade_counterproposals
  set status = 'withdrawn', responded_at = now()
  where thread_id = thread_row.id
    and proposer_id = p_actor_id
    and status = 'proposed';
  update public.trade_threads
  set status = 'closed', updated_at = now()
  where id = thread_row.id;

  counterpart_id := case
    when thread_row.participant_a = p_actor_id then thread_row.participant_b
    else thread_row.participant_a
  end;
  begin
    insert into public.trade_notifications(
      user_id, notification_type, title, body, href, dedupe_key, created_at
    ) values (
      counterpart_id,
      'response_withdrawn',
      'Response withdrawn',
      'The counterparty withdrew before agreement formation. No obligation was created.',
      '/messages/' || thread_row.id::text,
      'response_withdrawn:' || thread_row.id::text || ':' || p_actor_id::text,
      now()
    )
    on conflict (dedupe_key) do nothing;
  exception when others then
    null;
  end;

  return jsonb_build_object('threadId', thread_row.id, 'status', 'closed', 'idempotent', false);
end;
$$;



CREATE TABLE public.acquisition_prospects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    campaign text DEFAULT 'july17_2026'::text NOT NULL,
    tracking_slug text NOT NULL,
    name text NOT NULL,
    email text NOT NULL,
    organization text DEFAULT ''::text NOT NULL,
    role text DEFAULT ''::text NOT NULL,
    qualification_note text DEFAULT ''::text NOT NULL,
    channel text DEFAULT 'email'::text NOT NULL,
    contacted_at timestamp with time zone,
    responded_at timestamp with time zone,
    response_outcome text DEFAULT ''::text NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acquisition_prospects_channel_allowed CHECK ((channel = ANY (ARRAY['email'::text, 'introduction'::text, 'community'::text, 'other'::text]))),
    CONSTRAINT acquisition_prospects_email_not_blank CHECK ((btrim(email) <> ''::text)),
    CONSTRAINT acquisition_prospects_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT acquisition_prospects_tracking_slug_not_blank CHECK ((btrim(tracking_slug) <> ''::text))
);



CREATE TABLE public.impact_contributions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    contribution_kind text DEFAULT 'donation'::text NOT NULL,
    cause_area text DEFAULT ''::text NOT NULL,
    action_label text DEFAULT ''::text NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    occurred_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    evidence_url text DEFAULT ''::text NOT NULL,
    evidence_note text DEFAULT ''::text NOT NULL,
    verification_status text DEFAULT 'self_reported'::text NOT NULL,
    source_label text DEFAULT 'manual'::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT impact_contributions_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT impact_contributions_contribution_kind_check CHECK ((contribution_kind = ANY (ARRAY['donation'::text, 'money_equivalent'::text]))),
    CONSTRAINT impact_contributions_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text)),
    CONSTRAINT impact_contributions_verification_status_check CHECK ((verification_status = ANY (ARRAY['self_reported'::text, 'verified'::text, 'imported'::text])))
);



CREATE TABLE public.network_invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    target_label text NOT NULL,
    target_context text DEFAULT ''::text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    target_kind text DEFAULT 'person'::text NOT NULL,
    target_url text DEFAULT ''::text NOT NULL,
    desired_capability text DEFAULT ''::text NOT NULL,
    suggested_message text DEFAULT ''::text NOT NULL,
    priority smallint DEFAULT 3 NOT NULL,
    CONSTRAINT network_invites_priority_check CHECK (((priority >= 1) AND (priority <= 5))),
    CONSTRAINT network_invites_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'dismissed'::text]))),
    CONSTRAINT network_invites_target_kind_check CHECK ((target_kind = ANY (ARRAY['person'::text, 'collective'::text, 'institution'::text, 'community'::text, 'public_call'::text])))
);



CREATE TABLE public.offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    owner_alias text NOT NULL,
    mode public.offer_mode NOT NULL,
    offered_cause text NOT NULL,
    requested_cause text NOT NULL,
    offer_action text NOT NULL,
    request_action text NOT NULL,
    compromise_cause text DEFAULT 'Not needed'::text NOT NULL,
    offer_impact smallint NOT NULL,
    min_counterparty_impact smallint NOT NULL,
    verification text NOT NULL,
    duration text NOT NULL,
    trust_level smallint NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    discount_note text DEFAULT ''::text NOT NULL,
    status public.offer_status DEFAULT 'open'::public.offer_status NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    payment_interval_value integer,
    payment_interval_unit text,
    workflow_status text DEFAULT 'draft'::text NOT NULL,
    moderation_reason text DEFAULT ''::text NOT NULL,
    submission_key text DEFAULT ''::text NOT NULL,
    fingerprint text DEFAULT ''::text NOT NULL,
    no_trade_baseline text DEFAULT ''::text NOT NULL,
    start_date date,
    exit_conditions text DEFAULT ''::text NOT NULL,
    maximum_burden text DEFAULT ''::text NOT NULL,
    privacy_scope text DEFAULT 'Participants and operator only'::text NOT NULL,
    evidence_due_date date,
    submitted_at timestamp with time zone,
    published_at timestamp with time zone,
    closed_at timestamp with time zone,
    deleted_at timestamp with time zone,
    terms_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT offers_min_counterparty_impact_check CHECK (((min_counterparty_impact >= 1) AND (min_counterparty_impact <= 10))),
