    CONSTRAINT offers_payment_interval_unit_check CHECK (((payment_interval_unit IS NULL) OR (payment_interval_unit = ANY (ARRAY['day'::text, 'month'::text, 'year'::text])))),
    CONSTRAINT offers_payment_interval_value_check CHECK (((payment_interval_value IS NULL) OR (payment_interval_value > 0))),
    CONSTRAINT offers_terms_version_positive CHECK ((terms_version > 0)),
    CONSTRAINT offers_trust_level_check CHECK (((trust_level >= 1) AND (trust_level <= 5))),
    CONSTRAINT offers_workflow_status_check CHECK ((workflow_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'published'::text, 'changes_requested'::text, 'rejected'::text, 'paused'::text, 'closed'::text, 'deleted'::text])))
