CREATE VIEW public.acquisition_funnel_v1 WITH (security_invoker='true') AS
 SELECT ap.id,
    ap.campaign,
    ap.tracking_slug,
    ap.name,
    ap.email,
    ap.organization,
    ap.role,
    ap.qualification_note,
    ap.channel,
    ap.contacted_at,
    ap.responded_at,
    ap.response_outcome,
    ap.notes,
    matched_profile.id AS registered_profile_id,
    matched_profile.created_at AS registered_at,
    first_action.action_type AS meaningful_action_type,
    first_action.action_at AS meaningful_action_at,
    (ap.contacted_at IS NOT NULL) AS contacted,
    (ap.responded_at IS NOT NULL) AS responded,
    (matched_profile.id IS NOT NULL) AS registered,
    (first_action.action_at IS NOT NULL) AS meaningful_action,
    ((matched_profile.id IS NOT NULL) AND (first_action.action_at IS NOT NULL)) AS acquired,
        CASE
            WHEN ((matched_profile.id IS NOT NULL) AND (first_action.action_at IS NOT NULL)) THEN 'acquired'::text
            WHEN (matched_profile.id IS NOT NULL) THEN 'registered'::text
            WHEN (ap.responded_at IS NOT NULL) THEN 'responded'::text
            WHEN (ap.contacted_at IS NOT NULL) THEN 'contacted'::text
            ELSE 'queued'::text
        END AS stage,
    ap.created_at,
    ap.updated_at
   FROM ((public.acquisition_prospects ap
     LEFT JOIN LATERAL ( SELECT p.id,
            p.created_at
           FROM public.profiles p
          WHERE (lower(btrim(p.email)) = lower(btrim(ap.email)))
          ORDER BY p.created_at
         LIMIT 1) matched_profile ON (true))
     LEFT JOIN LATERAL ( SELECT actions.action_type,
            actions.action_at
           FROM ( SELECT 'offer_saved'::text AS action_type,
                    o.created_at AS action_at
                   FROM public.offers o
                  WHERE (o.owner_id = matched_profile.id)
                UNION ALL
                 SELECT 'wish_profile_saved'::text AS action_type,
                    wp.created_at AS action_at
                   FROM public.wish_profiles wp
                  WHERE (wp.profile_id = matched_profile.id)
                UNION ALL
                 SELECT 'counterparty_invite_saved'::text AS action_type,
                    ni.created_at AS action_at
                   FROM public.network_invites ni
                  WHERE (ni.profile_id = matched_profile.id)
                UNION ALL
                 SELECT 'public_good_action_logged'::text AS action_type,
                    ic.created_at AS action_at
                   FROM public.impact_contributions ic
                  WHERE (ic.profile_id = matched_profile.id)) actions
          WHERE (actions.action_at >= matched_profile.created_at)
          ORDER BY actions.action_at, actions.action_type
         LIMIT 1) first_action ON (true));



CREATE VIEW public.acquisition_funnel_summary_v1 WITH (security_invoker='true') AS
 SELECT campaign,
    count(*) AS prospects,
    count(*) FILTER (WHERE contacted) AS contacted,
    count(*) FILTER (WHERE responded) AS responded,
    count(*) FILTER (WHERE registered) AS registered,
    count(*) FILTER (WHERE acquired) AS acquired
   FROM public.acquisition_funnel_v1
  GROUP BY campaign;



