    CONSTRAINT background_subject_identity_automation_shape_check CHECK ((((subject_kind = ANY (ARRAY['automated_agent'::text, 'service_account'::text])) AND (automation_disclosure_state = 'disclosed_broadly'::text)) OR (subject_kind <> ALL (ARRAY['automated_agent'::text, 'service_account'::text])))),
    CONSTRAINT background_subject_identity_individual_shape_check CHECK ((((subject_kind = 'individual'::text) AND (sanitized_subject_label = 'individual'::text) AND (human_accountable_owner_id IS NULL) AND (representative_authority_state = 'not_required'::text) AND (representative_authority_scope = '{}'::jsonb) AND (automation_disclosure_state = 'not_automated'::text) AND (authority_expires_at IS NULL)) OR ((subject_kind <> 'individual'::text) AND (human_accountable_owner_id IS NOT NULL) AND (representative_authority_state <> 'not_required'::text) AND (representative_authority_scope ? 'purposeCodes'::text) AND (representative_authority_scope ? 'surfaces'::text) AND (authority_expires_at IS NOT NULL)))),
    CONSTRAINT background_subject_identity_p_automation_disclosure_state_check CHECK ((automation_disclosure_state = ANY (ARRAY['not_automated'::text, 'disclosed_broadly'::text, 'pending_review'::text, 'blocked'::text]))),
    CONSTRAINT background_subject_identity_profi_sanitized_subject_label_check CHECK ((sanitized_subject_label = ANY (ARRAY['individual'::text, 'organisation'::text, 'collective'::text, 'automated helper'::text, 'service account'::text, 'partner/operator seat'::text]))),
    CONSTRAINT background_subject_identity_profiles_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['individual'::text, 'organisation'::text, 'collective'::text, 'automated_agent'::text, 'service_account'::text, 'partner_operator'::text])))
);



