    CONSTRAINT command_tool_calls_execution_mode_check CHECK ((execution_mode = ANY (ARRAY['immediate'::text, 'private_handoff'::text, 'confirmed_handoff'::text, 'strong_confirmed_handoff'::text, 'blocked'::text]))),
    CONSTRAINT command_tool_calls_permission_tier_check CHECK ((permission_tier = ANY (ARRAY['read_only'::text, 'private_reversible'::text, 'external_consequential'::text, 'financial_strong_confirmation'::text, 'prohibited'::text]))),
    CONSTRAINT command_tool_calls_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'ready'::text, 'awaiting_confirmation'::text, 'confirmed'::text, 'completed'::text, 'blocked'::text, 'failed'::text])))
);



CREATE TABLE public.comment_votes (
    comment_id uuid NOT NULL,
    user_id uuid NOT NULL,
    value smallint NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT comment_votes_value_check CHECK ((value = ANY (ARRAY['-1'::integer, 1])))
);



CREATE TABLE public.conditional_payment_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    mandate_id uuid NOT NULL,
    settlement_batch_id uuid,
    attempt_number integer NOT NULL,
    idempotency_key text NOT NULL,
    stripe_payment_intent_id text,
    stripe_charge_id text,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    receipt_url text,
    failure_code text,
    decline_code text,
    failure_message text,
    refunded_amount_cents integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    authorization_consented_at timestamp with time zone,
    CONSTRAINT conditional_payment_attempts_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT conditional_payment_attempts_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT conditional_payment_attempts_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text)),
    CONSTRAINT conditional_payment_attempts_refunded_amount_cents_check CHECK ((refunded_amount_cents >= 0)),
    CONSTRAINT conditional_payment_attempts_status_check CHECK ((status = ANY (ARRAY['created'::text, 'processing'::text, 'requires_action'::text, 'succeeded'::text, 'failed'::text, 'refunded'::text, 'disputed'::text])))
);



CREATE TABLE public.conditional_payment_audit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_profile_id uuid,
    actor_kind text DEFAULT 'system'::text NOT NULL,
