    CONSTRAINT conditional_payment_audit_events_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['participant'::text, 'operator'::text, 'system'::text, 'stripe'::text])))
);



CREATE TABLE public.conditional_payment_customers (
    profile_id uuid NOT NULL,
    stripe_customer_id text NOT NULL,
    stripe_default_payment_method_id text,
    livemode boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);



CREATE TABLE public.conditional_payment_destination_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requester_profile_id uuid NOT NULL,
    environment text NOT NULL,
    provider text DEFAULT 'every_org'::text NOT NULL,
    provider_nonprofit_id text NOT NULL,
    nonprofit_slug text NOT NULL,
    display_name text NOT NULL,
    nonprofit_ein text DEFAULT ''::text NOT NULL,
    country_code text DEFAULT ''::text NOT NULL,
    website_url text NOT NULL,
    identity_snapshot jsonb NOT NULL,
    identity_hash text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text DEFAULT ''::text NOT NULL,
    destination_id uuid,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_payment_destination_requests_check CHECK ((((status = 'pending'::text) AND (reviewed_by IS NULL) AND (reviewed_at IS NULL) AND (destination_id IS NULL)) OR ((status = 'approved'::text) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (destination_id IS NOT NULL)) OR ((status = 'rejected'::text) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (destination_id IS NULL)))),
    CONSTRAINT conditional_payment_destination_requests_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'live'::text]))),
    CONSTRAINT conditional_payment_destination_requests_identity_hash_check CHECK ((identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_payment_destination_requests_provider_check CHECK ((provider = 'every_org'::text)),
    CONSTRAINT conditional_payment_destination_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT conditional_payment_destination_requests_website_url_check CHECK ((website_url ~ '^https://'::text))
);



CREATE TABLE public.conditional_payment_destination_review_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
