    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_payment_destination_review_even_identity_hash_check CHECK ((identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_payment_destination_review_events_decision_check CHECK ((decision = ANY (ARRAY['submitted'::text, 'approved'::text, 'rejected'::text])))
);



CREATE TABLE public.conditional_payment_destinations (
