    CONSTRAINT conditional_payment_destinations_check CHECK (((NOT livemode) OR (NOT test_only))),
    CONSTRAINT conditional_payment_destinations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'blocked'::text])))
);



CREATE TABLE public.conditional_payment_gate_status (
