CREATE TABLE public.conditional_payment_mandates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    purpose text NOT NULL,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    participant_role text NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    condition_snapshot jsonb NOT NULL,
    condition_hash text NOT NULL,
    livemode boolean DEFAULT false NOT NULL,
    status text DEFAULT 'setup_pending'::text NOT NULL,
    stripe_customer_id text,
    stripe_checkout_session_id text,
    stripe_setup_intent_id text,
    stripe_payment_method_id text,
    consent_terms_version text NOT NULL,
    consented_at timestamp with time zone NOT NULL,
    ready_at timestamp with time zone,
    expires_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    failure_code text,
    failure_message text,
    superseded_by uuid,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_payment_mandates_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT conditional_payment_mandates_condition_hash_check CHECK ((condition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_payment_mandates_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text)),
    CONSTRAINT conditional_payment_mandates_participant_role_check CHECK ((participant_role = ANY (ARRAY['owner'::text, 'counterparty'::text, 'pledger'::text, 'creator'::text, 'matcher'::text]))),
    CONSTRAINT conditional_payment_mandates_purpose_check CHECK ((purpose = ANY (ARRAY['donation_offset'::text, 'public_goods_pool'::text, 'conditional_redirect'::text]))),
    CONSTRAINT conditional_payment_mandates_status_check CHECK ((status = ANY (ARRAY['setup_pending'::text, 'ready'::text, 'charge_pending'::text, 'requires_action'::text, 'charged'::text, 'failed'::text, 'cancelled'::text, 'refunded'::text, 'disputed'::text]))),
    CONSTRAINT conditional_payment_mandates_subject_type_check CHECK ((subject_type = ANY (ARRAY['donation_offset_match'::text, 'donation_offset_pool'::text, 'mpgf_campaign'::text, 'conditional_redirect_offer'::text])))
);



