    processed_at timestamp with time zone,
    CONSTRAINT conditional_payment_webhook_events_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_payment_webhook_events_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'processed'::text, 'ignored'::text, 'failed'::text])))
);



CREATE TABLE public.conditional_redirect_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    offer_id uuid NOT NULL,
    matcher_profile_id uuid NOT NULL,
    mandate_id uuid NOT NULL,
    setup_succeeded_at timestamp with time zone,
    stripe_event_created_at timestamp with time zone,
    stripe_event_id text,
    status text DEFAULT 'setup_pending'::text NOT NULL,
    recovery_ends_at timestamp with time zone,
    recovery_attempts integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_redirect_candidates_check CHECK ((((setup_succeeded_at IS NULL) AND (stripe_event_created_at IS NULL) AND (stripe_event_id IS NULL)) OR ((setup_succeeded_at IS NOT NULL) AND (stripe_event_created_at IS NOT NULL) AND (stripe_event_id IS NOT NULL)))),
    CONSTRAINT conditional_redirect_candidates_recovery_attempts_check CHECK (((recovery_attempts >= 0) AND (recovery_attempts <= 1))),
    CONSTRAINT conditional_redirect_candidates_status_check CHECK ((status = ANY (ARRAY['setup_pending'::text, 'eligible'::text, 'winner'::text, 'backup'::text, 'recovery'::text, 'promoted'::text, 'charged'::text, 'declined'::text, 'requires_action'::text, 'expired'::text, 'cancelled'::text])))
);



CREATE TABLE public.conditional_redirect_offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    creator_profile_id uuid NOT NULL,
    creator_amount_cents integer NOT NULL,
    matcher_amount_cents integer NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    fallback_destination_id uuid NOT NULL,
    matched_destination_id uuid NOT NULL,
    offer_kind text GENERATED ALWAYS AS (
CASE
    WHEN (fallback_destination_id = matched_destination_id) THEN 'matching_donation'::text
    ELSE 'redirection'::text
END) STORED,
    deadline_at timestamp with time zone NOT NULL,
    arbitration_closes_at timestamp with time zone NOT NULL,
    creator_mandate_id uuid,
    winning_candidate_id uuid,
    status text DEFAULT 'pending_creator_authorization'::text NOT NULL,
    terms_version text NOT NULL,
    condition_hash text NOT NULL,
    livemode boolean DEFAULT false NOT NULL,
    recovery_ends_at timestamp with time zone,
    creator_recovery_attempts integer DEFAULT 0 NOT NULL,
    settlement_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancellation_reason text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_redirect_offers_check CHECK ((deadline_at >= (created_at + '00:30:00'::interval))),
    CONSTRAINT conditional_redirect_offers_check1 CHECK ((deadline_at <= (created_at + '30 days'::interval))),
    CONSTRAINT conditional_redirect_offers_check2 CHECK ((arbitration_closes_at = (deadline_at + '00:15:00'::interval))),
    CONSTRAINT conditional_redirect_offers_condition_hash_check CHECK ((condition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_redirect_offers_creator_amount_cents_check CHECK ((creator_amount_cents > 0)),
    CONSTRAINT conditional_redirect_offers_creator_recovery_attempts_check CHECK (((creator_recovery_attempts >= 0) AND (creator_recovery_attempts <= 1))),
    CONSTRAINT conditional_redirect_offers_currency_check CHECK ((currency = 'usd'::text)),
    CONSTRAINT conditional_redirect_offers_matcher_amount_cents_check CHECK ((matcher_amount_cents > 0)),
    CONSTRAINT conditional_redirect_offers_status_check CHECK ((status = ANY (ARRAY['pending_creator_authorization'::text, 'open'::text, 'arbitrating'::text, 'matcher_recovery'::text, 'creator_recovery'::text, 'matched_settling'::text, 'fallback_settling'::text, 'matched_transferred'::text, 'fallback_transferred'::text, 'cancelled'::text, 'operator_review'::text])))
);



CREATE TABLE public.conditional_redirect_settlement_legs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
