    CONSTRAINT conditional_redirect_settlement_legs_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT conditional_redirect_settlement_legs_participant_role_check CHECK ((participant_role = ANY (ARRAY['creator'::text, 'matcher'::text]))),
    CONSTRAINT conditional_redirect_settlement_legs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'charging'::text, 'requires_action'::text, 'charged'::text, 'transferring'::text, 'transferred'::text, 'refunding'::text, 'refunded'::text, 'failed'::text, 'operator_review'::text])))
);



CREATE TABLE public.conditional_settlement_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    purpose text NOT NULL,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    condition_hash text NOT NULL,
    condition_snapshot jsonb NOT NULL,
    destination_id uuid NOT NULL,
    livemode boolean DEFAULT false NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    total_amount_cents integer NOT NULL,
    expected_mandate_count integer DEFAULT 2 NOT NULL,
    transfer_group text NOT NULL,
    status text DEFAULT 'pending_authorizations'::text NOT NULL,
    processing_token uuid,
    processing_started_at timestamp with time zone,
    next_retry_at timestamp with time zone,
    failure_code text,
    failure_message text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    owner_destination_id uuid,
    counterparty_destination_id uuid,
    public_receipt_token uuid DEFAULT gen_random_uuid() NOT NULL,
    public_receipt_enabled boolean DEFAULT false NOT NULL,
    public_receipt_enabled_at timestamp with time zone,
    public_receipt_enabled_by uuid,
    CONSTRAINT conditional_settlement_batches_condition_hash_check CHECK ((condition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conditional_settlement_batches_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text)),
    CONSTRAINT conditional_settlement_batches_expected_mandate_count_check CHECK ((expected_mandate_count > 0)),
    CONSTRAINT conditional_settlement_batches_purpose_check CHECK ((purpose = ANY (ARRAY['donation_offset'::text, 'public_goods_pool'::text, 'conditional_redirect'::text]))),
    CONSTRAINT conditional_settlement_batches_status_check CHECK ((status = ANY (ARRAY['pending_authorizations'::text, 'ready'::text, 'charging'::text, 'requires_action'::text, 'charged'::text, 'transferring'::text, 'transferred'::text, 'failed'::text, 'refunding'::text, 'refunded'::text, 'disputed'::text, 'cancelled'::text]))),
    CONSTRAINT conditional_settlement_batches_subject_type_check CHECK ((subject_type = ANY (ARRAY['donation_offset_match'::text, 'donation_offset_pool'::text, 'mpgf_campaign'::text, 'conditional_redirect_offer'::text]))),
    CONSTRAINT conditional_settlement_batches_total_amount_cents_check CHECK ((total_amount_cents > 0))
);



CREATE TABLE public.conditional_settlement_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    settlement_batch_id uuid NOT NULL,
    mandate_id uuid NOT NULL,
    payment_attempt_id uuid NOT NULL,
    destination_id uuid NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    idempotency_key text NOT NULL,
    stripe_transfer_id text,
    stripe_transfer_reversal_id text,
    status text DEFAULT 'created'::text NOT NULL,
    failure_code text,
    failure_message text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT conditional_settlement_transfers_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT conditional_settlement_transfers_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text)),
    CONSTRAINT conditional_settlement_transfers_status_check CHECK ((status = ANY (ARRAY['created'::text, 'transferred'::text, 'failed'::text, 'reversing'::text, 'reversed'::text])))
);



CREATE TABLE public.core_loop_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid,
    event_type text NOT NULL,
    entity_type text DEFAULT ''::text NOT NULL,
    entity_id uuid,
    idempotency_key text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT core_loop_events_event_type_check CHECK ((event_type = ANY (ARRAY['signup_completed'::text, 'onboarding_completed'::text, 'offer_draft_saved'::text, 'offer_submitted'::text, 'offer_published'::text, 'invitation_sent'::text, 'response_sent'::text, 'counterproposal_sent'::text, 'agreement_confirmed_by_both'::text, 'evidence_submitted'::text, 'agreement_completed'::text])))
);



CREATE VIEW public.core_loop_funnel_summary WITH (security_invoker='true') AS
 SELECT event_type,
    count(*) AS event_count,
    count(DISTINCT profile_id) AS unique_users,
    min(created_at) AS first_seen_at,
    max(created_at) AS last_seen_at
   FROM public.core_loop_events
  GROUP BY event_type;



CREATE TABLE public.credibility_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    agreement_id uuid,
    counterparty_id uuid,
    role text NOT NULL,
    category text NOT NULL,
    dimension text NOT NULL,
    outcome numeric NOT NULL,
    evidence_quality text DEFAULT 'platform_verified'::text NOT NULL,
    context_similarity numeric DEFAULT 1 NOT NULL,
    stake_units numeric DEFAULT 0 NOT NULL,
    source_type text NOT NULL,
    source_id text,
    reason_code text DEFAULT ''::text NOT NULL,
    eligible boolean DEFAULT true NOT NULL,
    exclusion_reason text DEFAULT ''::text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    verified_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT credibility_event_category_check CHECK ((category = ANY (ARRAY['donation'::text, 'behavioral_pledge'::text, 'paid_action'::text, 'service'::text, 'group_purchase'::text, 'recurring_commitment'::text, 'other'::text]))),
    CONSTRAINT credibility_event_context_similarity_check CHECK (((context_similarity >= (0)::numeric) AND (context_similarity <= (1)::numeric))),
    CONSTRAINT credibility_event_dimension_check CHECK ((dimension = ANY (ARRAY['fulfilment'::text, 'evidence_integrity'::text, 'settlement'::text, 'dispute_conduct'::text, 'responsiveness'::text]))),
    CONSTRAINT credibility_event_evidence_quality_check CHECK ((evidence_quality = ANY (ARRAY['platform_verified'::text, 'independent'::text, 'adjudicated'::text, 'bilateral'::text, 'self_reported'::text]))),
    CONSTRAINT credibility_event_metadata_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT credibility_event_no_self_counterparty CHECK (((counterparty_id IS NULL) OR (counterparty_id <> profile_id))),
    CONSTRAINT credibility_event_outcome_check CHECK (((outcome >= (0)::numeric) AND (outcome <= (1)::numeric))),
    CONSTRAINT credibility_event_role_check CHECK ((role = ANY (ARRAY['committer'::text, 'funder'::text, 'verifier'::text, 'recipient'::text, 'counterparty'::text]))),
    CONSTRAINT credibility_event_stake_units_check CHECK ((stake_units >= (0)::numeric))
);



CREATE TABLE public.credibility_model_versions (
    version text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    prior_success numeric DEFAULT 4 NOT NULL,
    prior_failure numeric DEFAULT 1 NOT NULL,
    lower_quantile numeric DEFAULT 0.10 NOT NULL,
    minimum_effective_observations numeric DEFAULT 3 NOT NULL,
    recency_half_life_days integer DEFAULT 365 NOT NULL,
    dimension_weights jsonb DEFAULT '{"fulfilment": 0.45, "settlement": 0.15, "responsiveness": 0.05, "dispute_conduct": 0.10, "evidence_integrity": 0.25}'::jsonb NOT NULL,
    proof_weights jsonb DEFAULT '{"bilateral": 0.6, "adjudicated": 1.0, "independent": 1.0, "self_reported": 0.2, "platform_verified": 1.0}'::jsonb NOT NULL,
    context_weights jsonb DEFAULT '{"exact": 1.0, "same_role": 0.7, "unrelated": 0.25, "same_category": 0.6}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    CONSTRAINT credibility_model_context_weights_object CHECK ((jsonb_typeof(context_weights) = 'object'::text)),
    CONSTRAINT credibility_model_dimension_weights_object CHECK ((jsonb_typeof(dimension_weights) = 'object'::text)),
    CONSTRAINT credibility_model_half_life_check CHECK (((recency_half_life_days >= 30) AND (recency_half_life_days <= 3650))),
    CONSTRAINT credibility_model_lower_quantile_check CHECK (((lower_quantile > (0)::numeric) AND (lower_quantile < 0.5))),
    CONSTRAINT credibility_model_minimum_observations_check CHECK ((minimum_effective_observations >= (0)::numeric)),
    CONSTRAINT credibility_model_prior_failure_check CHECK ((prior_failure > (0)::numeric)),
    CONSTRAINT credibility_model_prior_success_check CHECK ((prior_success > (0)::numeric)),
    CONSTRAINT credibility_model_proof_weights_object CHECK ((jsonb_typeof(proof_weights) = 'object'::text)),
    CONSTRAINT credibility_model_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'retired'::text])))
);



CREATE TABLE public.credibility_profile_status (
    profile_id uuid NOT NULL,
    eligibility_state text DEFAULT 'eligible'::text NOT NULL,
    active_restriction_count integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT credibility_profile_status_count_check CHECK ((active_restriction_count >= 0)),
    CONSTRAINT credibility_profile_status_state_check CHECK ((eligibility_state = ANY (ARRAY['eligible'::text, 'review_required'::text, 'restricted'::text])))
);



CREATE TABLE public.credibility_public_aggregates (
    profile_id uuid NOT NULL,
    role text NOT NULL,
    category text NOT NULL,
    dimension text NOT NULL,
    weighted_success numeric DEFAULT 0 NOT NULL,
    weighted_failure numeric DEFAULT 0 NOT NULL,
    effective_observations numeric DEFAULT 0 NOT NULL,
    event_count integer DEFAULT 0 NOT NULL,
    independent_counterparties integer DEFAULT 0 NOT NULL,
    last_event_at timestamp with time zone,
    as_of_at timestamp with time zone DEFAULT now() NOT NULL,
    model_version text NOT NULL,
    CONSTRAINT credibility_public_aggregate_category_check CHECK ((category = ANY (ARRAY['donation'::text, 'behavioral_pledge'::text, 'paid_action'::text, 'service'::text, 'group_purchase'::text, 'recurring_commitment'::text, 'other'::text]))),
    CONSTRAINT credibility_public_aggregate_dimension_check CHECK ((dimension = ANY (ARRAY['fulfilment'::text, 'evidence_integrity'::text, 'settlement'::text, 'dispute_conduct'::text, 'responsiveness'::text]))),
    CONSTRAINT credibility_public_aggregate_nonnegative_check CHECK (((weighted_success >= (0)::numeric) AND (weighted_failure >= (0)::numeric) AND (effective_observations >= (0)::numeric) AND (event_count >= 0) AND (independent_counterparties >= 0))),
    CONSTRAINT credibility_public_aggregate_role_check CHECK ((role = ANY (ARRAY['committer'::text, 'funder'::text, 'verifier'::text, 'recipient'::text, 'counterparty'::text])))
);



