    CONSTRAINT credibility_restriction_role_check CHECK (((scope_role IS NULL) OR (scope_role = ANY (ARRAY['committer'::text, 'funder'::text, 'verifier'::text, 'recipient'::text, 'counterparty'::text])))),
    CONSTRAINT credibility_restriction_status_check CHECK ((status = ANY (ARRAY['reviewing'::text, 'active'::text, 'resolved'::text, 'overturned'::text]))),
    CONSTRAINT credibility_restriction_type_check CHECK ((restriction_type = ANY (ARRAY['account_compromise'::text, 'identity_duplication'::text, 'fraud'::text, 'forged_evidence'::text, 'coercion'::text, 'threat'::text, 'safety_review'::text, 'other'::text]))),
    CONSTRAINT credibility_restriction_window_check CHECK (((ends_at IS NULL) OR (ends_at > starts_at)))
);



