    CONSTRAINT fallback_livestream_evidence_routes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'armed'::text, 'cancelled_trade_cleared'::text, 'due'::text, 'live_window'::text, 'recording_due'::text, 'submitted'::text, 'reviewed_observed'::text, 'reviewed_unclear'::text, 'missed'::text, 'cancelled'::text]))),
