    CONSTRAINT match_introduction_tasks_sort_order_check CHECK (((sort_order >= 1) AND (sort_order <= 20))),
    CONSTRAINT match_introduction_tasks_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'done'::text, 'skipped'::text])))
);



