    CONSTRAINT match_reports_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewed'::text, 'dismissed'::text])))
);



CREATE TABLE public.match_suggestions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_a_id uuid NOT NULL,
