    profile_b_entry_id uuid,
    reason_for_a text NOT NULL,
    reason_for_b text NOT NULL,
    score smallint DEFAULT 50 NOT NULL,
    match_basis text[] DEFAULT '{}'::text[] NOT NULL,
    shared_causes text[] DEFAULT '{}'::text[] NOT NULL,
    suggested_first_step text DEFAULT ''::text NOT NULL,
    risk_notes text DEFAULT ''::text NOT NULL,
    generated_by text DEFAULT 'rule-based'::text NOT NULL,
    status public.match_suggestion_status DEFAULT 'suggested'::public.match_suggestion_status NOT NULL,
    dedupe_key text DEFAULT (gen_random_uuid())::text NOT NULL,
    identity_revealed boolean DEFAULT false NOT NULL,
    last_scored_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    background_owner_profile_id uuid,
    CONSTRAINT match_suggestions_check CHECK ((profile_a_id <> profile_b_id)),
    CONSTRAINT match_suggestions_score_check CHECK (((score >= 0) AND (score <= 100)))
);



CREATE TABLE public.wish_profile_public_previews (
    profile_id uuid NOT NULL,
    participant_kind text DEFAULT 'individual'::text NOT NULL,
    collective_name text DEFAULT ''::text NOT NULL,
    causes text[] DEFAULT '{}'::text[] NOT NULL,
    public_preview text DEFAULT ''::text NOT NULL,
    location_city text,
    location_region text,
    openness_to_payment boolean DEFAULT false NOT NULL,
    openness_to_pledges boolean DEFAULT true NOT NULL,
    background_search_enabled boolean DEFAULT true NOT NULL,
    privacy_stage text DEFAULT 'broad'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);



CREATE VIEW public.wish_profile_previews WITH (security_invoker='true') AS
 SELECT profile_id,
    participant_kind,
    collective_name,
    causes,
    public_preview,
    location_city,
    location_region,
    openness_to_payment,
    openness_to_pledges,
    background_search_enabled,
    privacy_stage,
    updated_at
   FROM public.wish_profile_public_previews;



CREATE VIEW public.match_suggestion_previews WITH (security_invoker='true') AS
 SELECT match_suggestions.id,
        CASE
            WHEN public.viewer_can_see_match_identity(match_suggestions.id) THEN
            CASE
                WHEN (match_suggestions.profile_a_id = auth.uid()) THEN match_suggestions.profile_b_id
                ELSE match_suggestions.profile_a_id
            END
            ELSE NULL::uuid
        END AS counterparty_profile_id,
    COALESCE(counterparty_preview.public_preview, ''::text) AS counterparty_public_preview,
    COALESCE(counterparty_preview.causes, '{}'::text[]) AS counterparty_causes,
    counterparty_preview.location_city AS counterparty_location_city,
    counterparty_preview.location_region AS counterparty_location_region,
    COALESCE(counterparty_preview.openness_to_payment, false) AS counterparty_openness_to_payment,
    COALESCE(counterparty_preview.openness_to_pledges, false) AS counterparty_openness_to_pledges,
        CASE
            WHEN (match_suggestions.profile_a_id = auth.uid()) THEN match_suggestions.reason_for_a
            ELSE match_suggestions.reason_for_b
        END AS viewer_reason,
        CASE
            WHEN public.viewer_can_see_match_identity(match_suggestions.id) THEN
            CASE
                WHEN (match_suggestions.profile_a_id = auth.uid()) THEN match_suggestions.reason_for_b
                ELSE match_suggestions.reason_for_a
            END
            ELSE ''::text
        END AS counterparty_reason,
    match_suggestions.score,
    match_suggestions.match_basis,
    match_suggestions.shared_causes,
    match_suggestions.suggested_first_step,
    match_suggestions.risk_notes,
    match_suggestions.generated_by,
    match_suggestions.status,
    match_suggestions.identity_revealed,
    (EXISTS ( SELECT 1
           FROM public.match_consents
          WHERE ((match_consents.match_id = match_suggestions.id) AND (match_consents.profile_id = auth.uid())))) AS viewer_consented,
    (EXISTS ( SELECT 1
           FROM public.match_consents
          WHERE ((match_consents.match_id = match_suggestions.id) AND (match_consents.profile_id =
                CASE
                    WHEN (match_suggestions.profile_a_id = auth.uid()) THEN match_suggestions.profile_b_id
                    ELSE match_suggestions.profile_a_id
                END)))) AS counterparty_consented,
    public.viewer_can_see_match_identity(match_suggestions.id) AS can_reveal_identity,
    match_suggestions.last_scored_at,
    match_suggestions.created_at,
    match_suggestions.updated_at
   FROM (public.match_suggestions
     LEFT JOIN public.wish_profile_previews counterparty_preview ON ((counterparty_preview.profile_id =
        CASE
            WHEN (match_suggestions.profile_a_id = auth.uid()) THEN match_suggestions.profile_b_id
            ELSE match_suggestions.profile_a_id
        END)))
  WHERE ((auth.uid() IS NOT NULL) AND ((match_suggestions.profile_a_id = auth.uid()) OR (match_suggestions.profile_b_id = auth.uid())) AND ((match_suggestions.background_owner_profile_id IS NULL) OR (match_suggestions.background_owner_profile_id = auth.uid()) OR public.viewer_can_see_match_identity(match_suggestions.id)) AND (match_suggestions.status <> 'dismissed'::public.match_suggestion_status));



CREATE TABLE public.moral_trade_create_offer_terms (
