    CONSTRAINT moral_trade_create_pool_term_failure_bonus_timing_terms_j_check CHECK ((jsonb_typeof(failure_bonus_timing_terms_json) = 'object'::text)),
    CONSTRAINT moral_trade_create_pool_term_moral_trade_failure_bonus_sh_check CHECK (((moral_trade_failure_bonus_share_bps >= 0) AND (moral_trade_failure_bonus_share_bps <= 10000))),
    CONSTRAINT moral_trade_create_pool_term_threshold_amounts_cents_jso_check1 CHECK (((jsonb_array_length(threshold_amounts_cents_json) >= 1) AND (jsonb_array_length(threshold_amounts_cents_json) <= 10))),
