    CONSTRAINT moral_trade_create_pool_terms_check CHECK ((((failure_bonus_timing_mode = 'formula'::text) AND (formula_source IS NOT NULL) AND (formula_ast_json IS NOT NULL) AND (formula_language_version = 'moral_trade_timing_formula_v1'::text) AND (formula_hash ~ '^[0-9a-f]{64}$'::text) AND (jsonb_typeof(formula_variables_json) = 'array'::text)) OR ((failure_bonus_timing_mode <> 'formula'::text) AND (formula_source IS NULL) AND (formula_ast_json IS NULL) AND (formula_language_version IS NULL) AND (formula_hash IS NULL) AND (formula_variables_json IS NULL)))),
    CONSTRAINT moral_trade_create_pool_terms_continuation_mode_check CHECK ((continuation_mode = ANY (ARRAY['stop'::text, 'continue'::text]))),
    CONSTRAINT moral_trade_create_pool_terms_failure_bonus_base_type_check CHECK ((failure_bonus_base_type = ANY (ARRAY['none'::text, 'fixed'::text, 'percentage'::text, 'function'::text]))),
    CONSTRAINT moral_trade_create_pool_terms_failure_bonus_timing_mode_check CHECK ((failure_bonus_timing_mode = ANY (ARRAY['all'::text, 'cutoff'::text, 'firstPercent'::text, 'preset'::text, 'piecewise'::text, 'formula'::text]))),
    CONSTRAINT moral_trade_create_pool_terms_reserve_quote_status_check CHECK ((reserve_quote_status = ANY (ARRAY['not_applicable'::text, 'pending_underwriting'::text, 'quoted'::text, 'approved'::text, 'revision_required'::text, 'rejected'::text]))),
    CONSTRAINT moral_trade_create_pool_terms_review_status_check CHECK ((review_status = ANY (ARRAY['pending_review'::text, 'approved'::text, 'revision_required'::text, 'rejected'::text])))
);



