    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_dac_campaign_outcomes_eligible_amount_nonnegative CHECK ((eligible_amount_cents >= 0)),
    CONSTRAINT mpgf_dac_campaign_outcomes_eligible_supporters_nonnegative CHECK ((eligible_supporter_count >= 0)),
