    CONSTRAINT mpgf_dac_campaign_outcomes_object CHECK ((jsonb_typeof(outcome_json) = 'object'::text)),
    CONSTRAINT mpgf_dac_campaign_outcomes_reason_required CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT mpgf_dac_campaign_outcomes_status_valid CHECK ((outcome_status = ANY (ARRAY['succeeded'::text, 'lapsed'::text]))),
    CONSTRAINT mpgf_dac_campaign_outcomes_terms_hash_format CHECK ((terms_sha256 ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_campaign_outcomes_terms_version_positive CHECK ((terms_version > 0)),
    CONSTRAINT mpgf_dac_campaign_outcomes_threshold_amount_positive CHECK ((threshold_amount_cents > 0)),
    CONSTRAINT mpgf_dac_campaign_outcomes_threshold_result_valid CHECK ((((outcome_status = 'succeeded'::text) AND (eligible_amount_cents >= threshold_amount_cents) AND (eligible_supporter_count >= threshold_supporters)) OR ((outcome_status = 'lapsed'::text) AND (evaluated_at >= deadline_at) AND ((eligible_amount_cents < threshold_amount_cents) OR (eligible_supporter_count < threshold_supporters))))),
    CONSTRAINT mpgf_dac_campaign_outcomes_threshold_supporters_positive CHECK ((threshold_supporters > 0))
);



CREATE TABLE public.mpgf_dac_pledge_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pledge_intent_id uuid NOT NULL,
    pledge_id uuid NOT NULL,
    campaign_id text NOT NULL,
    pool_proposal_id uuid NOT NULL,
    profile_id uuid NOT NULL,
    event_type text NOT NULL,
    terms_version integer NOT NULL,
    terms_sha256 text NOT NULL,
    amount_cents bigint NOT NULL,
    currency text NOT NULL,
    event_json jsonb NOT NULL,
    event_sha256 text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_dac_pledge_events_amount_positive CHECK ((amount_cents > 0)),
    CONSTRAINT mpgf_dac_pledge_events_currency_usd CHECK ((currency = 'usd'::text)),
    CONSTRAINT mpgf_dac_pledge_events_event_hash_format CHECK ((event_sha256 ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_pledge_events_event_object CHECK ((jsonb_typeof(event_json) = 'object'::text)),
    CONSTRAINT mpgf_dac_pledge_events_terms_hash_format CHECK ((terms_sha256 ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_pledge_events_terms_version_positive CHECK ((terms_version > 0)),
    CONSTRAINT mpgf_dac_pledge_events_type_valid CHECK ((event_type = ANY (ARRAY['pledge_created'::text, 'eligibility_reviewed'::text, 'pledge_expired'::text])))
);



CREATE TABLE public.mpgf_dac_pledge_intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
