    supporter_reason text,
    consent_json jsonb NOT NULL,
    consent_sha256 text NOT NULL,
    accepted_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_dac_pledge_intents_amount_positive CHECK ((amount_cents > 0)),
    CONSTRAINT mpgf_dac_pledge_intents_consent_hash_format CHECK ((consent_sha256 ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_pledge_intents_consent_object CHECK ((jsonb_typeof(consent_json) = 'object'::text)),
    CONSTRAINT mpgf_dac_pledge_intents_currency_usd CHECK ((currency = 'usd'::text)),
    CONSTRAINT mpgf_dac_pledge_intents_idempotency_hash_format CHECK ((idempotency_key_hash ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_pledge_intents_supporter_reason_length CHECK (((supporter_reason IS NULL) OR (char_length(supporter_reason) <= 500))),
    CONSTRAINT mpgf_dac_pledge_intents_terms_hash_format CHECK ((terms_sha256 ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT mpgf_dac_pledge_intents_terms_version_positive CHECK ((terms_version > 0)),
    CONSTRAINT mpgf_dac_pledge_intents_visibility_valid CHECK ((visibility_mode = ANY (ARRAY['private_amount'::text, 'public_supporter'::text, 'public_reason'::text])))
);



CREATE TABLE public.mpgf_failure_bonus_premium_quotes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reserve_id uuid NOT NULL,
    pool_proposal_id uuid NOT NULL,
    threshold_id text NOT NULL,
    threshold_index integer NOT NULL,
    cumulative_net_recipient_threshold_cents bigint NOT NULL,
    incremental_net_recipient_cents bigint NOT NULL,
    premium_rate_bps integer NOT NULL,
    success_premium_cents bigint NOT NULL,
    cumulative_success_premium_cents bigint NOT NULL,
    gross_success_requirement_cents bigint NOT NULL,
    premium_payer text NOT NULL,
    premium_included_in_net_recipient_threshold boolean DEFAULT false NOT NULL,
    pricing_mode text DEFAULT 'experience_rated'::text NOT NULL,
    pricing_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    policy_version text NOT NULL,
    provisional boolean DEFAULT true NOT NULL,
    rationale text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'pending_review'::text NOT NULL,
    quote_hash text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    failure_bonus_rate_bps integer NOT NULL,
    incremental_failure_bonus_exposure_cents bigint NOT NULL,
    maximum_failure_bonus_exposure_cents bigint NOT NULL,
    eligibility_json jsonb NOT NULL,
    max_participants integer NOT NULL,
    max_bonus_per_participant_cents bigint NOT NULL,
    CONSTRAINT mpgf_failure_bonus_premium_q_cumulative_net_recipient_thr_check CHECK ((cumulative_net_recipient_threshold_cents > 0)),
    CONSTRAINT mpgf_failure_bonus_premium_q_cumulative_success_premium_c_check CHECK ((cumulative_success_premium_cents > 0)),
    CONSTRAINT mpgf_failure_bonus_premium_q_gross_success_requirement_ce_check CHECK ((gross_success_requirement_cents > 0)),
    CONSTRAINT mpgf_failure_bonus_premium_q_incremental_net_recipient_ce_check CHECK ((incremental_net_recipient_cents > 0)),
    CONSTRAINT mpgf_failure_bonus_premium_q_premium_included_in_net_reci_check CHECK ((premium_included_in_net_recipient_threshold = false)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_approval_complete CHECK ((((status <> 'approved'::text) AND (approved_at IS NULL) AND (approved_by IS NULL)) OR ((status = 'approved'::text) AND (provisional = false) AND (approved_at IS NOT NULL) AND (approved_by IS NOT NULL)))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_cumulative_single_threshold CHECK (((threshold_index <> 1) OR ((cumulative_net_recipient_threshold_cents = incremental_net_recipient_cents) AND (cumulative_success_premium_cents = success_premium_cents)))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_eligibility_valid CHECK (public.mpgf_failure_bonus_eligibility_policy_valid(eligibility_json, max_participants, max_bonus_per_participant_cents)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_exposure_valid CHECK (((incremental_failure_bonus_exposure_cents >= 0) AND (maximum_failure_bonus_exposure_cents >= incremental_failure_bonus_exposure_cents) AND (maximum_failure_bonus_exposure_cents = LEAST((((cumulative_net_recipient_threshold_cents * (failure_bonus_rate_bps)::bigint) + 9999) / 10000), ((max_participants)::bigint * max_bonus_per_participant_cents))))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_failure_bonus_rate_valid CHECK (((failure_bonus_rate_bps >= 1) AND (failure_bonus_rate_bps <= 10000))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_gross_exact CHECK ((gross_success_requirement_cents = (cumulative_net_recipient_threshold_cents + cumulative_success_premium_cents))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_increment_exact CHECK ((success_premium_cents = (((incremental_net_recipient_cents * (premium_rate_bps)::bigint) + 9999) / 10000))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_policy_version_check CHECK (((policy_version = btrim(policy_version)) AND (policy_version <> ''::text))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_premium_payer_check CHECK ((premium_payer = ANY (ARRAY['pool_creator_or_sponsor'::text, 'contributors_pro_rata'::text]))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_premium_rate_bps_check CHECK (((premium_rate_bps >= 1) AND (premium_rate_bps <= 1000000))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_pricing_json_check CHECK ((jsonb_typeof(pricing_json) = 'object'::text)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_pricing_mode_check CHECK ((pricing_mode = ANY (ARRAY['experience_rated'::text, 'operator_override'::text]))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_pricing_valid CHECK (public.mpgf_failure_bonus_provisional_pricing_valid(pricing_json, failure_bonus_rate_bps, premium_rate_bps)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_quote_hash_check CHECK ((quote_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_status_check CHECK ((status = ANY (ARRAY['pending_review'::text, 'approved'::text, 'superseded'::text, 'voided'::text]))),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_success_premium_cents_check CHECK ((success_premium_cents > 0)),
    CONSTRAINT mpgf_failure_bonus_premium_quotes_threshold_index_check CHECK (((threshold_index >= 1) AND (threshold_index <= 10)))
);



CREATE TABLE public.mpgf_failure_bonus_reserve_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reserve_id uuid NOT NULL,
    pool_proposal_id uuid,
    premium_quote_id uuid,
    threshold_index integer,
    event_type text NOT NULL,
    cash_delta_cents bigint DEFAULT 0 NOT NULL,
    exposure_delta_cents bigint DEFAULT 0 NOT NULL,
    currency text DEFAULT 'usd'::text NOT NULL,
    status text DEFAULT 'pending_review'::text NOT NULL,
    idempotency_key text NOT NULL,
    source_ref_hash text NOT NULL,
    event_hash text NOT NULL,
    public_memo text DEFAULT ''::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_failure_bonus_reserve_entries_currency_check CHECK ((currency = 'usd'::text)),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_effect_valid CHECK ((((event_type = ANY (ARRAY['anchor_capital_credit'::text, 'success_premium_credit'::text])) AND (cash_delta_cents > 0) AND (exposure_delta_cents = 0)) OR ((event_type = 'failure_bonus_debit'::text) AND (cash_delta_cents < 0) AND (exposure_delta_cents = cash_delta_cents)) OR ((event_type = 'reserve_expense_debit'::text) AND (cash_delta_cents < 0) AND (exposure_delta_cents = 0)) OR ((event_type = 'bonus_exposure_allocation'::text) AND (cash_delta_cents = 0) AND (exposure_delta_cents > 0)) OR ((event_type = 'bonus_exposure_release'::text) AND (cash_delta_cents = 0) AND (exposure_delta_cents < 0)))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_event_hash_check CHECK ((event_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_event_type_check CHECK ((event_type = ANY (ARRAY['anchor_capital_credit'::text, 'success_premium_credit'::text, 'failure_bonus_debit'::text, 'reserve_expense_debit'::text, 'bonus_exposure_allocation'::text, 'bonus_exposure_release'::text]))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_pool_scope_required CHECK (((event_type <> ALL (ARRAY['failure_bonus_debit'::text, 'reserve_expense_debit'::text, 'bonus_exposure_allocation'::text, 'bonus_exposure_release'::text])) OR ((pool_proposal_id IS NOT NULL) AND (threshold_index IS NOT NULL)))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_posted_approval CHECK ((((status <> 'posted'::text) AND (approved_at IS NULL) AND (approved_by IS NULL)) OR ((status = 'posted'::text) AND (approved_at IS NOT NULL) AND (approved_by IS NOT NULL)))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_premium_quote_required CHECK (((event_type <> 'success_premium_credit'::text) OR ((premium_quote_id IS NOT NULL) AND (pool_proposal_id IS NOT NULL) AND (threshold_index IS NOT NULL)))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_source_ref_hash_check CHECK ((source_ref_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_status_check CHECK ((status = ANY (ARRAY['pending_review'::text, 'posted'::text, 'voided'::text]))),
    CONSTRAINT mpgf_failure_bonus_reserve_entries_threshold_index_check CHECK (((threshold_index >= 1) AND (threshold_index <= 10)))
);



CREATE VIEW public.mpgf_failure_bonus_reserve_public_summary AS
SELECT
    NULL::uuid AS id,
    NULL::text AS reserve_key,
    NULL::text AS display_name,
    NULL::text AS currency,
    NULL::text AS status,
    NULL::text AS policy_version,
    NULL::text AS custody_mode,
    NULL::text AS public_description,
    NULL::bigint AS posted_cash_balance_cents,
    NULL::bigint AS open_bonus_exposure_cents,
    NULL::bigint AS available_backing_cents,
    NULL::bigint AS success_premiums_credited_cents,
    NULL::bigint AS failure_bonuses_paid_cents,
    NULL::bigint AS reserve_expenses_paid_cents,
    NULL::bigint AS posted_entry_count,
    NULL::timestamp with time zone AS updated_at;



