    public_review_summary text DEFAULT ''::text NOT NULL,
    approved_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_phase_one_project_approval_timestamp CHECK (((status <> 'approved'::text) OR (approved_at IS NOT NULL))),
    CONSTRAINT mpgf_phase_one_projects_action_category_check CHECK ((action_category ~ '^[a-z0-9_]{2,80}$'::text)),
    CONSTRAINT mpgf_phase_one_projects_external_checkout_url_check CHECK (((external_checkout_url ~ '^https://'::text) AND (char_length(external_checkout_url) <= 2000))),
    CONSTRAINT mpgf_phase_one_projects_public_review_summary_check CHECK ((char_length(public_review_summary) <= 2000)),
    CONSTRAINT mpgf_phase_one_projects_recipient_name_check CHECK (((char_length(recipient_name) >= 2) AND (char_length(recipient_name) <= 200))),
    CONSTRAINT mpgf_phase_one_projects_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
    CONSTRAINT mpgf_phase_one_projects_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'under_review'::text, 'approved'::text, 'paused'::text, 'rejected'::text, 'retired'::text]))),
    CONSTRAINT mpgf_phase_one_projects_summary_check CHECK (((char_length(summary) >= 20) AND (char_length(summary) <= 2000))),
    CONSTRAINT mpgf_phase_one_projects_title_check CHECK (((char_length(title) >= 3) AND (char_length(title) <= 200)))
);



CREATE TABLE public.mpgf_phase_one_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    pledge_opens_at timestamp with time zone,
    pledge_closes_at timestamp with time zone,
    ballot_opens_at timestamp with time zone,
    ballot_closes_at timestamp with time zone,
    quorum_bps integer DEFAULT 5000 NOT NULL,
    ballot_policy text DEFAULT 'equal_credit_approval_split_v1'::text NOT NULL,
    result_effect text DEFAULT 'advisory_external_checkout_confirmation_required'::text NOT NULL,
    terms_version text DEFAULT 'mpgf-phase-one-terms-v1'::text NOT NULL,
    result_hash text,
    quorum_met boolean DEFAULT false NOT NULL,
    results_published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT mpgf_phase_one_round_windows_ordered CHECK ((((pledge_opens_at IS NULL) OR (pledge_closes_at IS NULL) OR (pledge_opens_at < pledge_closes_at)) AND ((ballot_opens_at IS NULL) OR (ballot_closes_at IS NULL) OR (ballot_opens_at < ballot_closes_at)) AND ((pledge_closes_at IS NULL) OR (ballot_opens_at IS NULL) OR (pledge_closes_at <= ballot_opens_at)))),
    CONSTRAINT mpgf_phase_one_rounds_ballot_policy_check CHECK ((ballot_policy = 'equal_credit_approval_split_v1'::text)),
    CONSTRAINT mpgf_phase_one_rounds_quorum_bps_check CHECK ((quorum_bps = 5000)),
    CONSTRAINT mpgf_phase_one_rounds_result_effect_check CHECK ((result_effect = 'advisory_external_checkout_confirmation_required'::text)),
    CONSTRAINT mpgf_phase_one_rounds_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
