    CONSTRAINT mpgf_pool_proposals_success_premium_complete CHECK ((((public_goods_failure_bonus_enabled = false) AND (public_goods_failure_bonus_rate_bps IS NULL) AND (public_goods_threshold_schedule_json IS NULL) AND (public_goods_failure_bonus_eligibility_json IS NULL) AND (public_goods_failure_bonus_max_participants IS NULL) AND (public_goods_failure_bonus_max_per_participant_cents IS NULL) AND (public_goods_failure_bonus_schedule_status IS NULL) AND (public_goods_success_premium_rate_bps IS NULL) AND (public_goods_success_premium_cents IS NULL) AND (public_goods_success_premium_payer IS NULL) AND (public_goods_success_premium_policy_version IS NULL) AND (public_goods_success_premium_provisional IS NULL) AND (public_goods_gross_success_requirement_cents IS NULL) AND (public_goods_success_premium_pricing_json IS NULL)) OR ((public_goods_failure_bonus_enabled = true) AND (public_goods_threshold_amount_cents IS NOT NULL) AND (public_goods_threshold_amount_cents > 0) AND (public_goods_threshold_supporters IS NOT NULL) AND (public_goods_threshold_supporters > 0) AND ((public_goods_failure_bonus_rate_bps >= 1) AND (public_goods_failure_bonus_rate_bps <= 10000)) AND (public_goods_threshold_schedule_json IS NOT NULL) AND (public_goods_failure_bonus_eligibility_json IS NOT NULL) AND (public_goods_failure_bonus_max_participants IS NOT NULL) AND (public_goods_failure_bonus_max_per_participant_cents IS NOT NULL) AND (public_goods_failure_bonus_schedule_status = ANY (ARRAY['pending_review'::text, 'approved'::text])) AND (public_goods_success_premium_rate_bps IS NOT NULL) AND (public_goods_success_premium_cents IS NOT NULL) AND (public_goods_success_premium_cents > 0) AND (public_goods_success_premium_payer = 'pool_creator_or_sponsor'::text) AND (public_goods_success_premium_policy_version = 'mpgf_failure_bonus_success_premium_v0_1'::text) AND (public_goods_success_premium_provisional = (public_goods_failure_bonus_schedule_status = 'pending_review'::text)) AND (public_goods_gross_success_requirement_cents IS NOT NULL) AND (public_goods_success_premium_pricing_json IS NOT NULL) AND public.mpgf_failure_bonus_threshold_schedule_valid(public_goods_threshold_schedule_json, public_goods_failure_bonus_eligibility_json, public_goods_failure_bonus_schedule_status, public_goods_failure_bonus_rate_bps, public_goods_threshold_amount_cents, public_goods_success_premium_rate_bps, public_goods_success_premium_cents, public_goods_gross_success_requirement_cents, public_goods_success_premium_pricing_json, requested_maximum_funding_cents, public_goods_threshold_supporters, public_goods_failure_bonus_max_participants, public_goods_failure_bonus_max_per_participant_cents)))),
    CONSTRAINT mpgf_pool_proposals_success_premium_outside_threshold CHECK ((public_goods_success_premium_included_in_net_threshold = false)),
    CONSTRAINT mpgf_pool_proposals_success_premium_payer_valid CHECK (((public_goods_success_premium_payer IS NULL) OR (public_goods_success_premium_payer = ANY (ARRAY['pool_creator_or_sponsor'::text, 'contributors_pro_rata'::text])))),
    CONSTRAINT mpgf_pool_proposals_success_premium_rate_valid CHECK (((public_goods_success_premium_rate_bps IS NULL) OR ((public_goods_success_premium_rate_bps >= 1) AND (public_goods_success_premium_rate_bps <= 1000000)))),
    CONSTRAINT mpgf_pool_proposals_terms_hash_valid CHECK (((operative_terms_sha256 IS NULL) OR (operative_terms_sha256 ~ '^sha256:[a-f0-9]{64}$'::text))),
