    CONSTRAINT mpgf_public_goods_pledges_capture_mode_check CHECK ((capture_mode = ANY (ARRAY['external_handoff'::text, 'stored_payment_method'::text, 'signed_intent'::text]))),
    CONSTRAINT mpgf_public_goods_pledges_currency_check CHECK ((currency = 'usd'::text)),
    CONSTRAINT mpgf_public_goods_pledges_dac_binding_complete CHECK ((((pledge_intent_id IS NULL) AND (pool_proposal_id IS NULL) AND (terms_version IS NULL) AND (terms_sha256 IS NULL) AND (accepted_at IS NULL) AND (expires_at IS NULL)) OR ((pledge_intent_id IS NOT NULL) AND (pool_proposal_id IS NOT NULL) AND (terms_version IS NOT NULL) AND (terms_version > 0) AND (terms_sha256 ~ '^sha256:[a-f0-9]{64}$'::text) AND (accepted_at IS NOT NULL) AND (expires_at IS NOT NULL) AND (expires_at > accepted_at) AND (capture_mode = 'signed_intent'::text) AND (is_recurring = false)))),
    CONSTRAINT mpgf_public_goods_pledges_eligibility_state_check CHECK ((eligibility_state = ANY (ARRAY['eligible'::text, 'pending_review'::text, 'duplicate_identity'::text, 'below_minimum'::text, 'blocked'::text]))),
    CONSTRAINT mpgf_public_goods_pledges_human_score_bps_check CHECK (((human_score_bps >= 0) AND (human_score_bps <= 10000))),
    CONSTRAINT mpgf_public_goods_pledges_status_check CHECK ((status = ANY (ARRAY['pledged'::text, 'captured'::text, 'voided'::text, 'expired'::text]))),
    CONSTRAINT mpgf_public_goods_pledges_visibility_mode_check CHECK ((visibility_mode = ANY (ARRAY['private_amount'::text, 'public_supporter'::text, 'public_reason'::text])))
);



