    CONSTRAINT performance_bonds_status_check CHECK ((status = ANY (ARRAY['not_enabled'::text, 'draft'::text, 'awaiting_funding'::text, 'funded'::text, 'active'::text, 'evidence_due'::text, 'evidence_submitted'::text, 'challenge_window_open'::text, 'accepted_by_counterparty'::text, 'auto_refund_pending'::text, 'refunded'::text, 'challenged'::text, 'under_review'::text, 'accepted_after_review'::text, 'rejected_after_review'::text, 'forfeited'::text, 'split_disbursed'::text, 'cancelled'::text, 'expired'::text])))
);



