CREATE TABLE public.profile_username_claims (
    username text NOT NULL,
    profile_id uuid NOT NULL,
    is_current boolean DEFAULT true NOT NULL,
    claimed_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    superseded_at timestamp with time zone,
    CONSTRAINT profile_username_claims_state_check CHECK (((is_current AND (superseded_at IS NULL)) OR ((NOT is_current) AND (superseded_at IS NOT NULL)))),
    CONSTRAINT profile_username_claims_username_valid CHECK (((username = public.normalize_profile_username_v1(username)) AND ((char_length(username) >= 2) AND (char_length(username) <= 32)) AND (username ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$'::text) AND (username !~ '--'::text) AND (NOT public.profile_username_is_reserved_v1(username))))
);



