CREATE VIEW public.public_profile_cards_v1 WITH (security_barrier='true') AS
 SELECT id,
    display_name,
    bio,
    follower_count,
    following_count,
    karma,
    comment_count,
    rating_avg,
    rating_count,
    offer_count,
    created_at,
    public_location_granularity,
        CASE
            WHEN (public_location_granularity = 'city'::text) THEN city
            ELSE NULL::text
        END AS city,
        CASE
            WHEN (public_location_granularity = ANY (ARRAY['city'::text, 'region'::text])) THEN region
            ELSE NULL::text
        END AS region,
        CASE
            WHEN (public_location_granularity <> 'hidden'::text) THEN country
            ELSE NULL::text
        END AS country
   FROM public.profiles profile;



