    time_budget_minutes integer DEFAULT 0 NOT NULL,
    action_budget_count integer DEFAULT 0 NOT NULL,
    horizon text DEFAULT 'month'::text NOT NULL,
    route_formats text[] DEFAULT ARRAY['direct'::text] NOT NULL,
    evidence_preference text DEFAULT 'high'::text NOT NULL,
    uncertainty_preference text DEFAULT 'balanced'::text NOT NULL,
    interaction_preference text DEFAULT 'open'::text NOT NULL,
    privacy_preference text DEFAULT 'private'::text NOT NULL,
    planned_donation_baseline boolean,
    planned_donation_cents integer DEFAULT 0 NOT NULL,
    otherwise_baseline text DEFAULT ''::text NOT NULL,
    pairwise_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    interview_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    sensitive_ciphertexts jsonb DEFAULT '{}'::jsonb NOT NULL,
    sensitive_encryption_version text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT route_profiles_baseline_ciphertext_shape CHECK ((((otherwise_baseline = ''::text) AND (NOT (sensitive_ciphertexts ? 'route_recommendation_profiles.otherwise_baseline'::text))) OR ((otherwise_baseline = '[encrypted private field]'::text) AND (sensitive_ciphertexts ? 'route_recommendation_profiles.otherwise_baseline'::text)))),
    CONSTRAINT route_profiles_cause_ciphertext_shape CHECK ((cause_priorities = '{}'::text[])),
    CONSTRAINT route_profiles_ciphertexts_valid CHECK (public.route_profile_ciphertexts_valid(sensitive_ciphertexts)),
    CONSTRAINT route_profiles_encryption_version_valid CHECK ((((sensitive_ciphertexts = '{}'::jsonb) AND (sensitive_encryption_version = ''::text)) OR ((sensitive_ciphertexts <> '{}'::jsonb) AND (sensitive_encryption_version = ANY (ARRAY['bg-field-v1'::text, 'bg-field-v2'::text]))))),
    CONSTRAINT route_profiles_goal_ciphertext_shape CHECK ((((goal = ''::text) AND (NOT (sensitive_ciphertexts ? 'route_recommendation_profiles.goal'::text))) OR ((goal = '[encrypted private field]'::text) AND (sensitive_ciphertexts ? 'route_recommendation_profiles.goal'::text)))),
    CONSTRAINT route_profiles_interview_answers_valid CHECK (public.route_profile_interview_answers_valid(interview_answers)),
    CONSTRAINT route_profiles_pairwise_answers_valid CHECK (public.route_profile_pairwise_answers_valid(pairwise_answers)),
    CONSTRAINT route_profiles_planned_donation_state_valid CHECK (((planned_donation_baseline IS TRUE) OR (planned_donation_cents = 0))),
    CONSTRAINT route_recommendation_profiles_action_budget_count_check CHECK (((action_budget_count >= 0) AND (action_budget_count <= 1000))),
    CONSTRAINT route_recommendation_profiles_cause_priorities_check CHECK ((cardinality(cause_priorities) <= 16)),
    CONSTRAINT route_recommendation_profiles_check CHECK ((planned_donation_baseline OR (planned_donation_cents = 0))),
    CONSTRAINT route_recommendation_profiles_evidence_preference_check CHECK ((evidence_preference = ANY (ARRAY['standard'::text, 'high'::text, 'connected'::text]))),
    CONSTRAINT route_recommendation_profiles_goal_check CHECK ((char_length(goal) <= 180)),
    CONSTRAINT route_recommendation_profiles_horizon_check CHECK ((horizon = ANY (ARRAY['day'::text, 'week'::text, 'month'::text, 'quarter'::text, 'year'::text]))),
    CONSTRAINT route_recommendation_profiles_interaction_preference_check CHECK ((interaction_preference = ANY (ARRAY['solo'::text, 'open'::text, 'invite'::text]))),
    CONSTRAINT route_recommendation_profiles_interview_answers_check CHECK ((jsonb_typeof(interview_answers) = 'object'::text)),
    CONSTRAINT route_recommendation_profiles_money_budget_cents_check CHECK (((money_budget_cents >= 0) AND (money_budget_cents <= 100000000))),
    CONSTRAINT route_recommendation_profiles_otherwise_baseline_check CHECK ((char_length(otherwise_baseline) <= 700)),
    CONSTRAINT route_recommendation_profiles_pairwise_answers_check CHECK ((jsonb_typeof(pairwise_answers) = 'object'::text)),
    CONSTRAINT route_recommendation_profiles_planned_donation_cents_check CHECK (((planned_donation_cents >= 0) AND (planned_donation_cents <= 100000000))),
    CONSTRAINT route_recommendation_profiles_privacy_preference_check CHECK ((privacy_preference = ANY (ARRAY['private'::text, 'public-safe'::text, 'public'::text]))),
    CONSTRAINT route_recommendation_profiles_route_formats_check CHECK ((((cardinality(route_formats) >= 1) AND (cardinality(route_formats) <= 5)) AND (route_formats <@ ARRAY['direct'::text, 'threshold'::text, 'redirect'::text, 'personal'::text, 'coalition'::text]))),
    CONSTRAINT route_recommendation_profiles_sensitive_ciphertexts_check CHECK ((jsonb_typeof(sensitive_ciphertexts) = 'object'::text)),
    CONSTRAINT route_recommendation_profiles_time_budget_minutes_check CHECK (((time_budget_minutes >= 0) AND (time_budget_minutes <= 100000))),
    CONSTRAINT route_recommendation_profiles_uncertainty_preference_check CHECK ((uncertainty_preference = ANY (ARRAY['conservative'::text, 'balanced'::text, 'exploratory'::text])))
);



