    payer_id uuid NOT NULL,
    action_category text NOT NULL,
    description text NOT NULL,
    unit_label text NOT NULL,
    units_total numeric(20,6) NOT NULL,
    indivisible boolean DEFAULT true NOT NULL,
    maximum_amount_cents bigint NOT NULL,
    currency text NOT NULL,
    evidence_rule text NOT NULL,
    status text DEFAULT 'terms'::text NOT NULL,
    reviewer_selection_opened_at timestamp with time zone,
    assigned_reviewer_id uuid,
    current_bundle_id uuid,
    final_review_id uuid,
    replacement_packet_used boolean DEFAULT false NOT NULL,
    replacement_deadline_at timestamp with time zone,
    replacement_seconds_remaining integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trade_agreement_milestones_action_category_check CHECK ((action_category = ANY (ARRAY['donation'::text, 'service'::text, 'advocacy'::text, 'research'::text, 'lifestyle'::text, 'other'::text]))),
    CONSTRAINT trade_agreement_milestones_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT trade_agreement_milestones_description_check CHECK (((length(btrim(description)) >= 1) AND (length(btrim(description)) <= 5000))),
    CONSTRAINT trade_agreement_milestones_distinct_roles_check CHECK ((performer_id <> payer_id)),
    CONSTRAINT trade_agreement_milestones_evidence_rule_check CHECK (((length(btrim(evidence_rule)) >= 1) AND (length(btrim(evidence_rule)) <= 5000))),
    CONSTRAINT trade_agreement_milestones_indivisible_units_check CHECK (((NOT indivisible) OR (units_total = (1)::numeric))),
    CONSTRAINT trade_agreement_milestones_maximum_amount_cents_check CHECK (((maximum_amount_cents >= 0) AND (maximum_amount_cents <= '9007199254740991'::bigint))),
    CONSTRAINT trade_agreement_milestones_position_check CHECK ((("position" >= 1) AND ("position" <= 100))),
    CONSTRAINT trade_agreement_milestones_replacement_seconds_remaining_check CHECK (((replacement_seconds_remaining IS NULL) OR ((replacement_seconds_remaining >= 0) AND (replacement_seconds_remaining <= 604800)))),
    CONSTRAINT trade_agreement_milestones_status_check CHECK ((status = ANY (ARRAY['terms'::text, 'evidence_due'::text, 'under_review'::text, 'replacement_due'::text, 'appeal_pending'::text, 'graded'::text, 'paid'::text, 'cancelled'::text]))),
    CONSTRAINT trade_agreement_milestones_unit_label_check CHECK (((length(btrim(unit_label)) >= 1) AND (length(btrim(unit_label)) <= 120))),
    CONSTRAINT trade_agreement_milestones_units_total_check CHECK ((units_total > (0)::numeric))
);



