    CONSTRAINT trade_donation_pool_gate_status_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'live'::text]))),
    CONSTRAINT trade_donation_pool_gate_status_status_check CHECK ((status = ANY (ARRAY['passed'::text, 'pending'::text, 'blocked'::text])))
);



