    CONSTRAINT trade_evidence_items_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'accepted'::text, 'challenged'::text, 'withdrawn'::text, 'replaced'::text])))
);



CREATE TABLE public.trade_exit_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    agreement_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    request_type text NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT trade_exit_requests_request_type_check CHECK ((request_type = ANY (ARRAY['mutual_cancel'::text, 'unilateral_exit'::text]))),
    CONSTRAINT trade_exit_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text, 'executed'::text])))
);



CREATE TABLE public.trade_external_payment_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payout_id uuid NOT NULL,
    reported_by uuid NOT NULL,
    provider text NOT NULL,
    provider_reference text NOT NULL,
    reference_fingerprint text NOT NULL,
    amount_cents bigint NOT NULL,
    currency text NOT NULL,
    paid_on date NOT NULL,
    receipt_storage_path text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'reported'::text NOT NULL,
    counterparty_note text DEFAULT ''::text NOT NULL,
    reported_at timestamp with time zone DEFAULT now() NOT NULL,
    responded_at timestamp with time zone,
    payment_cycle integer DEFAULT 1 NOT NULL,
    attempt_number smallint DEFAULT 1 NOT NULL,
    receipt_kind text DEFAULT 'initial'::text NOT NULL,
    supersedes_receipt_id uuid,
    response_deadline_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    response_outcome text DEFAULT 'none'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trade_external_payment_receipts_amount_cents_check CHECK ((amount_cents >= 0)),
    CONSTRAINT trade_external_payment_receipts_attempt_check CHECK (((payment_cycle >= 1) AND (((attempt_number = 1) AND (receipt_kind = 'initial'::text) AND (supersedes_receipt_id IS NULL)) OR ((attempt_number = 2) AND (receipt_kind = 'correction'::text) AND (supersedes_receipt_id IS NOT NULL))))),
    CONSTRAINT trade_external_payment_receipts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT trade_external_payment_receipts_provider_check CHECK (((length(btrim(provider)) >= 1) AND (length(btrim(provider)) <= 120))),
    CONSTRAINT trade_external_payment_receipts_provider_reference_check CHECK (((length(btrim(provider_reference)) >= 1) AND (length(btrim(provider_reference)) <= 500))),
    CONSTRAINT trade_external_payment_receipts_reference_fingerprint_check CHECK ((reference_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT trade_external_payment_receipts_response_outcome_check CHECK ((response_outcome = ANY (ARRAY['none'::text, 'confirmed'::text, 'disputed'::text, 'unanswered'::text]))),
    CONSTRAINT trade_external_payment_receipts_status_check CHECK ((status = ANY (ARRAY['reported'::text, 'confirmed'::text, 'under_review'::text, 'correction_requested'::text, 'superseded'::text, 'adjudicated_paid'::text, 'adjudicated_still_due'::text])))
);



CREATE TABLE public.trade_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    offer_id uuid NOT NULL,
    sender_id uuid NOT NULL,
    recipient_user_id uuid,
    recipient_email text DEFAULT ''::text NOT NULL,
    token text,
    message text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'drafted'::text NOT NULL,
    opened_at timestamp with time zone,
    responded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    token_hash text,
    token_ciphertext text DEFAULT ''::text NOT NULL,
    delivery_kind text DEFAULT 'share_link'::text NOT NULL,
    terms_version integer DEFAULT 1 NOT NULL,
    terms_hash text DEFAULT ''::text NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '14 days'::interval) NOT NULL,
    claimed_at timestamp with time zone,
    claimed_by uuid,
    revoked_at timestamp with time zone,
    revocation_reason text DEFAULT ''::text NOT NULL,
    CONSTRAINT trade_invitations_delivery_kind_check CHECK ((delivery_kind = ANY (ARRAY['email'::text, 'share_link'::text]))),
    CONSTRAINT trade_invitations_secure_active_check CHECK (((status <> ALL (ARRAY['drafted'::text, 'sent'::text, 'opened'::text])) OR ((token_hash ~ '^[0-9a-f]{64}$'::text) AND (length(token_ciphertext) >= 40) AND (terms_version > 0) AND (terms_hash ~ '^[0-9a-f]{64}$'::text) AND (expires_at > created_at)))),
    CONSTRAINT trade_invitations_status_check CHECK ((status = ANY (ARRAY['drafted'::text, 'sent'::text, 'opened'::text, 'responded'::text, 'accepted'::text, 'countered'::text, 'declined'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT trade_invitations_token_must_be_null CHECK ((token IS NULL))
);



