    CONSTRAINT trade_messages_message_type_check CHECK ((message_type = ANY (ARRAY['user'::text, 'system'::text])))
);



CREATE TABLE public.trade_milestone_appeals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    milestone_id uuid NOT NULL,
    base_review_id uuid NOT NULL,
    opened_by uuid NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'reviewer_selection'::text NOT NULL,
    assigned_reviewer_id uuid,
    reviewer_selection_deadline_at timestamp with time zone NOT NULL,
    replacement_seconds_remaining integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT trade_milestone_appeals_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 4000))),
    CONSTRAINT trade_milestone_appeals_replacement_seconds_remaining_check CHECK (((replacement_seconds_remaining IS NULL) OR ((replacement_seconds_remaining >= 0) AND (replacement_seconds_remaining <= 604800)))),
    CONSTRAINT trade_milestone_appeals_resolved_state_check CHECK ((((status = 'resolved'::text) AND (resolved_at IS NOT NULL)) OR ((status <> 'resolved'::text) AND (resolved_at IS NULL)))),
    CONSTRAINT trade_milestone_appeals_status_check CHECK ((status = ANY (ARRAY['reviewer_selection'::text, 'assigned'::text, 'resolved'::text])))
);



CREATE TABLE public.trade_milestone_payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    milestone_id uuid NOT NULL,
    review_id uuid NOT NULL,
    payer_id uuid NOT NULL,
    payee_id uuid NOT NULL,
    maximum_amount_cents bigint NOT NULL,
    completion_units numeric(20,6) NOT NULL,
    units_total numeric(20,6) NOT NULL,
    confidence_band smallint NOT NULL,
    payout_basis_points integer NOT NULL,
    amount_due_cents bigint NOT NULL,
    currency text NOT NULL,
    is_final boolean DEFAULT false NOT NULL,
    status text DEFAULT 'provisional'::text NOT NULL,
    finalized_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trade_milestone_payouts_check CHECK (((amount_due_cents >= 0) AND (amount_due_cents <= maximum_amount_cents))),
    CONSTRAINT trade_milestone_payouts_completion_units_check CHECK ((completion_units >= (0)::numeric)),
    CONSTRAINT trade_milestone_payouts_confidence_band_check CHECK ((confidence_band = ANY (ARRAY[0, 25, 50, 75, 100]))),
    CONSTRAINT trade_milestone_payouts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT trade_milestone_payouts_final_state_check CHECK ((((NOT is_final) AND (status = 'provisional'::text) AND (finalized_at IS NULL)) OR (is_final AND (status <> 'provisional'::text) AND (finalized_at IS NOT NULL)))),
    CONSTRAINT trade_milestone_payouts_maximum_amount_cents_check CHECK ((maximum_amount_cents >= 0)),
    CONSTRAINT trade_milestone_payouts_payout_basis_points_check CHECK (((payout_basis_points >= 0) AND (payout_basis_points <= 10000))),
    CONSTRAINT trade_milestone_payouts_status_check CHECK ((status = ANY (ARRAY['provisional'::text, 'not_due'::text, 'due'::text, 'reported_paid'::text, 'payment_review_pending'::text, 'correction_due'::text, 'corrected_reported'::text, 'payment_decision_pending'::text, 'payment_appeal_pending'::text, 'confirmed'::text, 'adjudicated_paid'::text, 'still_due'::text]))),
    CONSTRAINT trade_milestone_payouts_units_total_check CHECK ((units_total > (0)::numeric))
);



CREATE TABLE public.trade_milestone_reviewer_nominations (
