CREATE TABLE public.trade_milestone_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    milestone_id uuid NOT NULL,
    bundle_id uuid NOT NULL,
    reviewer_id uuid NOT NULL,
    review_kind text NOT NULL,
    base_review_id uuid,
    outcome text NOT NULL,
    completion_units numeric(20,6) NOT NULL,
    confidence_band smallint NOT NULL,
    payout_basis_points integer NOT NULL,
    amount_due_cents bigint NOT NULL,
    private_reason text NOT NULL,
    appeal_deadline_at timestamp with time zone NOT NULL,
    is_final boolean DEFAULT false NOT NULL,
    finalized_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trade_milestone_reviews_amount_due_cents_check CHECK ((amount_due_cents >= 0)),
    CONSTRAINT trade_milestone_reviews_appeal_link_check CHECK ((((review_kind = 'appeal'::text) AND (base_review_id IS NOT NULL)) OR ((review_kind <> 'appeal'::text) AND (base_review_id IS NULL)))),
    CONSTRAINT trade_milestone_reviews_completion_units_check CHECK ((completion_units >= (0)::numeric)),
    CONSTRAINT trade_milestone_reviews_confidence_band_check CHECK ((confidence_band = ANY (ARRAY[0, 25, 50, 75, 100]))),
    CONSTRAINT trade_milestone_reviews_final_state_check CHECK (((is_final AND (finalized_at IS NOT NULL)) OR ((NOT is_final) AND (finalized_at IS NULL)))),
    CONSTRAINT trade_milestone_reviews_outcome_check CHECK ((outcome = ANY (ARRAY['graded'::text, 'rejected'::text]))),
    CONSTRAINT trade_milestone_reviews_payout_basis_points_check CHECK (((payout_basis_points >= 0) AND (payout_basis_points <= 10000))),
    CONSTRAINT trade_milestone_reviews_private_reason_check CHECK (((length(btrim(private_reason)) >= 1) AND (length(btrim(private_reason)) <= 4000))),
    CONSTRAINT trade_milestone_reviews_rejected_values_check CHECK ((((outcome = 'rejected'::text) AND (completion_units = (0)::numeric) AND (confidence_band = 0) AND (payout_basis_points = 0) AND (amount_due_cents = 0)) OR (outcome = 'graded'::text))),
    CONSTRAINT trade_milestone_reviews_review_kind_check CHECK ((review_kind = ANY (ARRAY['initial'::text, 'replacement'::text, 'appeal'::text])))
);



