    CONSTRAINT trade_payment_review_cases_status_check CHECK ((status = ANY (ARRAY['reviewer_selection'::text, 'assigned'::text, 'correction_due'::text, 'corrected_response'::text, 'final_review'::text, 'decision_pending'::text, 'appeal_pending'::text, 'resolved'::text])))
);



CREATE TABLE public.trade_payment_review_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
