    appeal_deadline_at timestamp with time zone,
    is_final boolean DEFAULT false NOT NULL,
    finalized_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trade_payment_review_decisions_correction_check CHECK ((((outcome = 'allow_correction'::text) AND (decision_kind = 'initial'::text) AND (appeal_deadline_at IS NULL) AND (NOT is_final) AND (finalized_at IS NULL)) OR (outcome <> 'allow_correction'::text))),
    CONSTRAINT trade_payment_review_decisions_decision_kind_check CHECK ((decision_kind = ANY (ARRAY['initial'::text, 'final'::text, 'appeal'::text]))),
    CONSTRAINT trade_payment_review_decisions_finality_check CHECK (((is_final AND (finalized_at IS NOT NULL)) OR ((NOT is_final) AND (finalized_at IS NULL)))),
    CONSTRAINT trade_payment_review_decisions_kind_check CHECK ((((decision_kind = 'appeal'::text) AND (base_decision_id IS NOT NULL)) OR ((decision_kind <> 'appeal'::text) AND (base_decision_id IS NULL)))),
    CONSTRAINT trade_payment_review_decisions_outcome_check CHECK ((outcome = ANY (ARRAY['confirm_paid'::text, 'still_due'::text, 'allow_correction'::text]))),
    CONSTRAINT trade_payment_review_decisions_private_reason_check CHECK (((length(btrim(private_reason)) >= 1) AND (length(btrim(private_reason)) <= 4000)))
);



