CREATE INDEX wish_profiles_broad_preview_causes_gin_idx ON public.wish_profiles USING gin (causes) WHERE ((is_discoverable = true) AND (share_public_preview = true) AND (background_search_enabled = true) AND (safety_status = 'clear'::text));



CREATE INDEX wish_profiles_broad_preview_text_search_idx ON public.wish_profiles USING gin (to_tsvector('english'::regconfig, ((((((COALESCE(public_preview, ''::text) || ' '::text) || COALESCE(collective_name, ''::text)) || ' '::text) || COALESCE(participant_kind, ''::text)) || ' '::text) ||
CASE
    WHEN share_location THEN ((COALESCE(location_city, ''::text) || ' '::text) || COALESCE(location_region, ''::text))
    ELSE ''::text
END))) WHERE ((is_discoverable = true) AND (share_public_preview = true) AND (background_search_enabled = true) AND (safety_status = 'clear'::text));



