CREATE OR REPLACE VIEW public.mpgf_failure_bonus_reserve_public_summary WITH (security_barrier='true') AS
 SELECT reserve.id,
    reserve.reserve_key,
    reserve.display_name,
    reserve.currency,
    reserve.status,
    reserve.policy_version,
    reserve.custody_mode,
    reserve.public_description,
    (COALESCE(sum(entry.cash_delta_cents) FILTER (WHERE (entry.status = 'posted'::text)), (0)::numeric))::bigint AS posted_cash_balance_cents,
    (COALESCE(sum(entry.exposure_delta_cents) FILTER (WHERE (entry.status = 'posted'::text)), (0)::numeric))::bigint AS open_bonus_exposure_cents,
    ((COALESCE(sum(entry.cash_delta_cents) FILTER (WHERE (entry.status = 'posted'::text)), (0)::numeric) - COALESCE(sum(entry.exposure_delta_cents) FILTER (WHERE (entry.status = 'posted'::text)), (0)::numeric)))::bigint AS available_backing_cents,
    (COALESCE(sum(entry.cash_delta_cents) FILTER (WHERE ((entry.status = 'posted'::text) AND (entry.event_type = 'success_premium_credit'::text))), (0)::numeric))::bigint AS success_premiums_credited_cents,
    (abs(COALESCE(sum(entry.cash_delta_cents) FILTER (WHERE ((entry.status = 'posted'::text) AND (entry.event_type = 'failure_bonus_debit'::text))), (0)::numeric)))::bigint AS failure_bonuses_paid_cents,
    (abs(COALESCE(sum(entry.cash_delta_cents) FILTER (WHERE ((entry.status = 'posted'::text) AND (entry.event_type = 'reserve_expense_debit'::text))), (0)::numeric)))::bigint AS reserve_expenses_paid_cents,
    count(entry.id) FILTER (WHERE (entry.status = 'posted'::text)) AS posted_entry_count,
    reserve.updated_at
   FROM (public.mpgf_failure_bonus_reserves reserve
     LEFT JOIN public.mpgf_failure_bonus_reserve_entries entry ON ((entry.reserve_id = reserve.id)))
  GROUP BY reserve.id;



