CREATE POLICY "Owners can read their financial pool" ON public.financial_commitment_pools FOR SELECT USING ((owner_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY "Participants can read financial reservations" ON public.financial_commitment_reservations FOR SELECT USING (((EXISTS ( SELECT 1
   FROM public.financial_commitment_pools pool
  WHERE ((pool.pool_key = financial_commitment_reservations.pool_key) AND (pool.owner_id = ( SELECT auth.uid() AS uid))))) OR (EXISTS ( SELECT 1
   FROM public.agreements agreement
  WHERE ((agreement.id = financial_commitment_reservations.agreement_id) AND ((( SELECT auth.uid() AS uid) = agreement.proposer_id) OR (( SELECT auth.uid() AS uid) = agreement.responder_id)))))));



CREATE POLICY "Public can read catalog metadata" ON public.offer_catalog_entries FOR SELECT USING (true);



ALTER TABLE public.acquisition_prospects ENABLE ROW LEVEL SECURITY;


ALTER TABLE public.agreement_events ENABLE ROW LEVEL SECURITY;


CREATE POLICY agreement_events_insert_participants ON public.agreement_events FOR INSERT TO authenticated WITH CHECK (((actor_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.agreements
  WHERE ((agreements.id = agreement_events.agreement_id) AND ((agreements.proposer_id = ( SELECT auth.uid() AS uid)) OR (agreements.responder_id = ( SELECT auth.uid() AS uid))))))));



CREATE POLICY agreement_events_select_participants ON public.agreement_events FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.agreements
  WHERE ((agreements.id = agreement_events.agreement_id) AND ((agreements.proposer_id = ( SELECT auth.uid() AS uid)) OR (agreements.responder_id = ( SELECT auth.uid() AS uid)))))));



ALTER TABLE public.agreement_payment_schedules ENABLE ROW LEVEL SECURITY;


CREATE POLICY agreement_payment_schedules_insert_participants ON public.agreement_payment_schedules FOR INSERT TO authenticated WITH CHECK (((payer_id = ( SELECT auth.uid() AS uid)) OR (payee_id = ( SELECT auth.uid() AS uid))));



CREATE POLICY agreement_payment_schedules_select_participants ON public.agreement_payment_schedules FOR SELECT TO authenticated USING (((payer_id = ( SELECT auth.uid() AS uid)) OR (payee_id = ( SELECT auth.uid() AS uid))));



CREATE POLICY agreement_payment_schedules_update_participants ON public.agreement_payment_schedules FOR UPDATE TO authenticated USING (((payer_id = ( SELECT auth.uid() AS uid)) OR (payee_id = ( SELECT auth.uid() AS uid)))) WITH CHECK (((payer_id = ( SELECT auth.uid() AS uid)) OR (payee_id = ( SELECT auth.uid() AS uid))));



ALTER TABLE public.agreement_payments ENABLE ROW LEVEL SECURITY;


CREATE POLICY agreement_payments_select_participants ON public.agreement_payments FOR SELECT TO authenticated USING (((payer_id = ( SELECT auth.uid() AS uid)) OR (payee_id = ( SELECT auth.uid() AS uid))));



ALTER TABLE public.agreement_ratings ENABLE ROW LEVEL SECURITY;


CREATE POLICY agreement_ratings_insert_own ON public.agreement_ratings FOR INSERT TO authenticated WITH CHECK (((rater_id = ( SELECT auth.uid() AS uid)) AND (rated_user_id <> ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
