ALTER TABLE public.trade_payment_review_cases ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_payment_review_cases_authorized_select ON public.trade_payment_review_cases FOR SELECT TO authenticated USING (moral_trade_private.can_read_trade_payment_case_v1(id, ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_payment_review_decisions ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_payment_review_decisions_authorized_select ON public.trade_payment_review_decisions FOR SELECT TO authenticated USING (moral_trade_private.can_read_trade_payment_decision_v1(id, ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_payment_reviewer_nominations ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_payment_reviewer_nominations_participant_select ON public.trade_payment_reviewer_nominations FOR SELECT TO authenticated USING (moral_trade_private.is_trade_payment_case_participant_v1(case_id, ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_reports ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_reports_reporter_select ON public.trade_reports FOR SELECT TO authenticated USING ((reporter_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_review_events ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_review_events_owner_insert ON public.trade_review_events FOR INSERT TO authenticated WITH CHECK (((reviewer_id IS NULL) AND (action = ANY (ARRAY['submitted'::text, 'duplicate_flagged'::text])) AND (EXISTS ( SELECT 1
   FROM public.offers offer
  WHERE ((offer.id = trade_review_events.offer_id) AND (offer.owner_id = ( SELECT auth.uid() AS uid)))))));



CREATE POLICY trade_review_events_owner_select ON public.trade_review_events FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.offers o
  WHERE ((o.id = trade_review_events.offer_id) AND (o.owner_id = ( SELECT auth.uid() AS uid))))));



ALTER TABLE public.trade_review_role_grants ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_review_role_grants_self_select ON public.trade_review_role_grants FOR SELECT TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_thread_reads ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_thread_reads_self_all ON public.trade_thread_reads TO authenticated USING ((user_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.trade_threads ENABLE ROW LEVEL SECURITY;


CREATE POLICY trade_threads_participant_select ON public.trade_threads FOR SELECT TO authenticated USING (((participant_a = ( SELECT auth.uid() AS uid)) OR (participant_b = ( SELECT auth.uid() AS uid))));



ALTER TABLE public.transparency_receipts ENABLE ROW LEVEL SECURITY;


CREATE POLICY transparency_receipts_insert_own_actor_scope ON public.transparency_receipts FOR INSERT TO authenticated WITH CHECK ((actor_scope = ('profile:'::text || (( SELECT auth.uid() AS uid))::text)));



CREATE POLICY transparency_receipts_select_own_actor_scope ON public.transparency_receipts FOR SELECT TO authenticated USING ((actor_scope = ('profile:'::text || (( SELECT auth.uid() AS uid))::text)));



ALTER TABLE public.user_follows ENABLE ROW LEVEL SECURITY;


CREATE POLICY "verified profile badges are public" ON public.profile_verification_badges FOR SELECT TO authenticated, anon USING (((status = 'verified'::text) AND ((expires_at IS NULL) OR (expires_at > now()))));



ALTER TABLE public.webinar_rsvps ENABLE ROW LEVEL SECURITY;


CREATE POLICY webinar_rsvps_insert_public ON public.webinar_rsvps FOR INSERT TO authenticated, anon WITH CHECK ((((profile_id IS NULL) OR (profile_id = ( SELECT auth.uid() AS uid))) AND ((char_length(email) >= 3) AND (char_length(email) <= 320)) AND (jsonb_typeof(attribution) = 'object'::text)));



CREATE POLICY webinar_rsvps_select_own ON public.webinar_rsvps FOR SELECT TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.wish_entries ENABLE ROW LEVEL SECURITY;


CREATE POLICY wish_entries_delete_own ON public.wish_entries FOR DELETE TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY wish_entries_insert_own ON public.wish_entries FOR INSERT TO authenticated WITH CHECK ((profile_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY wish_entries_select_own_or_preview ON public.wish_entries FOR SELECT TO authenticated USING (((profile_id = ( SELECT auth.uid() AS uid)) OR ((visibility = 'preview'::text) AND (safety_status = 'clear'::text) AND public.wish_profile_is_previewable(profile_id))));



CREATE POLICY wish_entries_update_own ON public.wish_entries FOR UPDATE TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((profile_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.wish_notifications ENABLE ROW LEVEL SECURITY;


CREATE POLICY wish_notifications_insert_relevant ON public.wish_notifications FOR INSERT TO authenticated WITH CHECK (((profile_id = ( SELECT auth.uid() AS uid)) OR ((match_id IS NOT NULL) AND public.viewer_participates_in_match(match_id) AND public.profile_participates_in_match(match_id, profile_id))));



CREATE POLICY wish_notifications_select_own ON public.wish_notifications FOR SELECT TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY wish_notifications_update_own ON public.wish_notifications FOR UPDATE TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((profile_id = ( SELECT auth.uid() AS uid)));



ALTER TABLE public.wish_profile_public_previews ENABLE ROW LEVEL SECURITY;


CREATE POLICY wish_profile_public_previews_read ON public.wish_profile_public_previews FOR SELECT TO authenticated, anon USING (true);



ALTER TABLE public.wish_profiles ENABLE ROW LEVEL SECURITY;


CREATE POLICY wish_profiles_insert_own ON public.wish_profiles FOR INSERT TO authenticated WITH CHECK ((profile_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY wish_profiles_select_own ON public.wish_profiles FOR SELECT TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid)));



CREATE POLICY wish_profiles_update_own ON public.wish_profiles FOR UPDATE TO authenticated USING ((profile_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((profile_id = ( SELECT auth.uid() AS uid)));



